var PATH_BOOK_CHN = {"subject": "语文", "book": "必修上册", "version": "统编版", "chapters": [{"no": "第一单元", "title": "青春激扬", "units": ["u_chn_1", "u_chn_2", "u_chn_3"]}, {"no": "第二单元", "title": "劳动光荣", "units": ["u_chn_4", "u_chn_5", "u_chn_6"]}, {"no": "第三单元", "title": "生命的诗意", "units": ["u_chn_7", "u_chn_8", "u_chn_9"]}, {"no": "第四单元", "title": "家乡文化生活", "units": ["u_chn_10"]}, {"no": "第五单元", "title": "乡土的中国", "units": ["u_chn_11"]}, {"no": "第六单元", "title": "学习之道", "units": ["u_chn_12", "u_chn_13", "u_chn_14", "u_chn_15"]}, {"no": "第七单元", "title": "自然情怀", "units": ["u_chn_16", "u_chn_17", "u_chn_18"]}, {"no": "第八单元", "title": "语言家园", "units": ["u_chn_19"]}, {"no": "古诗词诵读", "title": "古诗词诵读", "units": ["u_chn_20"]}], "order": ["u_chn_1", "u_chn_2", "u_chn_3", "u_chn_4", "u_chn_5", "u_chn_6", "u_chn_7", "u_chn_8", "u_chn_9", "u_chn_10", "u_chn_11", "u_chn_12", "u_chn_13", "u_chn_14", "u_chn_15", "u_chn_16", "u_chn_17", "u_chn_18", "u_chn_19", "u_chn_20"], "nodes": {"chn_c001": {"name": "沁园春·长沙", "sec": 1, "secTitle": "第1课 沁园春·长沙", "page": 2, "desc": "词的上阕写景、下阕抒情；「竞自由」「谁主沉浮」是全词的魂，默写易错字最集中。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《沁园春·长沙》中写水面场景的句子「____，____」（船与飞舟）。", "answer": "百舸争流；到中流击水，浪遏飞舟（注意「舸」读 gě、「遏」读 è）"}, "pre": [], "next": ["chn_c002", "chn_c009"], "content": {"advance": {"a": "共同点：都一反悲秋传统，把秋天写得生机勃勃、催人奋进。刘禹锡明说「秋日胜春朝」，以议论翻出新意；毛泽东则不直说，靠竞自由的意象群和指点江山的群像，让昂扬从画面里自己长出来。一为说理，一为造境，态度一致。", "kind": "self", "q": "传统诗词多「悲秋」，本词写秋却昂扬。结合刘禹锡《秋词》「自古逢秋悲寂寥，我言秋日胜春朝」，说说两首作品对待秋的态度有何共同点。"}, "apply": [{"ans": 1, "opts": ["只是写鹰和鱼的动作，没有深意", "「击」「翔」写出鹰的矫健、鱼的自由，与下文「竞自由」呼应，景中见生机与力量", "两个字互换位置效果更好", "主要起押韵作用"], "q": "「鹰击长空，鱼翔浅底」中「击」「翔」二字的效果，分析最恰当的一项是（ ）", "why": "炼字题要答两层：字面动作＋情感指向。「击」写矫健有力，「翔」写悠然自由，共同指向万物竞自由的昂扬基调。"}, {"ans": 2, "opts": ["纯粹是对自然现象的疑问", "表达对人生短暂的感伤", "由眼前景引发对国家民族命运的关切，含蓄地表达了以天下为己任的担当", "感叹自己怀才不遇"], "q": "对「怅寥廓，问苍茫大地，谁主沉浮」的理解，正确的一项是（ ）", "why": "这是全词题眼：景—问—怀的转折点，问的对象是「苍茫大地」，指向的是谁主宰国家命运的时代命题。"}], "basics": [{"ans": 0, "opts": ["词牌是「沁园春」，词题是「长沙」", "词牌是「长沙」，词题是「沁园春」", "词牌、词题都是「沁园春」", "这首词没有词牌"], "q": "《沁园春·长沙》的词牌和词题分别是（ ）", "why": "「沁园春」是词牌名，规定格律；「长沙」是题目，交代写作地点。"}, {"ans": 1, "opts": ["上阕抒情，下阕写景", "上阕写景设问，下阕追忆抒情", "通篇都在写景", "通篇都在议论时局"], "q": "下列对本词结构判断正确的是（ ）", "why": "上阕写橘子洲秋景并发出「谁主沉浮」之问，下阕追忆峥嵘岁月、抒发抱负。"}], "case": {"a": "填空：层林尽染；百舸争流。色彩上，「红遍」「碧透」一红一碧、冷暖相衬，色彩浓烈明快，一扫传统秋景的萧瑟，奠定全词昂扬乐观的基调。", "q": "默写填空：看万山红遍， ______；漫江碧透， ______。并说明这两句在色彩运用上的特点。", "title": "案例：名句默写与手法"}, "intro": "1925 年，毛泽东重游长沙，独立橘子洲头写下这首词。==上阕写景、下阕抒情，「问苍茫大地，谁主沉浮」是全词的题眼。==这一课抓两件事：**意象**群怎样层层铺开，抒情主人公的形象怎样立起来。", "learn": [{"h": "背景与词牌", "p": "1925 年，毛泽东离开韶山前往广州主持农民运动讲习所，途经长沙，重游橘子洲、岳麓山，追忆学生时代的革命生活，写下此词。「沁园春」是**词牌**名，不是题目；这类词共 114 字，上阕以写景为主，下阕以抒情、追忆为主。判断一首词的内容结构，先看上下阕的分工。"}, {"h": "上阕：意象群的铺展", "p": "落笔先定立点「独立寒秋，湘江北去，橘子洲头」，再层层推出意象：**万山红遍、层林尽染、漫江碧透、百舸争流、鹰击长空、鱼翔浅底**，末句「万类霜天竞自由」总收。==赏析这类写景，先抓意象的排列：由远及近、由高到低、由静到动。==再抠动词：**击、翔、竞**三字把秋天写成了生命的竞技场，这是本词不悲秋的第一处证据。"}, {"h": "下阕：群像与作答", "p": "「携来百侣曾游」把镜头转回往昔：**恰同学少年，风华正茂；书生意气，挥斥方遒。指点江山，激扬文字，粪土当年万户侯。**写的是青年群体的意气。结尾「曾记否，到中流击水，浪遏飞舟」用回忆中的行动，回答了上阕「谁主沉浮」的设问——答案不在句中，在这群人的身上。"}], "pitfalls": ["把「沁园春」当成词的题目，它是词牌名，与内容无关。", "默写错字：「百舸争流」的「舸」误作「舵」；「浪遏飞舟」的「遏」误作「竭」。", "赏析写景只说「景色优美」，不点意象的排列顺序和动词的锤炼。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 1, "t": "沁园春·长沙", "dur": "26:47", "from": "名师课堂", "vtop": ["“独立”不能改成“站立”：倒装前置强调“独立”，写出诗人身处险境仍坦荡从容、胸怀天下的中流砥柱气概。", "意象是融入作者主观情感的客观物象，上片“看”字领起万山、层林、漫江、百舸、鹰、鱼，远近高低多角度写秋景。", "下片首句“携来百侣曾游”是过片，承上启下；“中流击水，浪遏飞舟”回答了上片“谁主沉浮”：主宰国家命运的是以天下为己任的青年革命者。"], "vsum": "本课学毛泽东青年时代写的词《沁园春·长沙》。开场先看毛泽东年少时写的两首诗，感受他一往无前的斗争精神和天下有我的伟人情怀：一首是《七绝·改西乡隆盛诗赠父亲》，“孩儿立志出乡关，学不成名誓不还。埋骨何须桑梓地，人生无处不青山”；另一首是《七绝·咏蛙》，“独坐池塘如虎踞，绿荫树下养精神。春来我不先开口，哪个虫儿敢作声”。这就是奋斗的青春该有的样子。这首词写于**1925年**，当时革命运动正蓬勃发展，五卅运动和省港大罢工相继爆发，毛泽东直接领导了湖南的农民运动；同时国共两党的统一战线已经确立，国民革命政府已在广州正式成立。这年深秋，毛泽东去广州主持农民运动讲习所，在长沙停留期间重游橘子洲，面对湘江上的自然秋景，联想到当时的革命形势，便写下了这首词。赏析诗词从三个方面入手：一从**内容**方面入手，读懂这首词写了什么；二从**写作手法**入手，明确这首词是如何写的，写作手法一般包含描写手法、修辞手法和抒情方式三方面；三从**情感**入手，读懂作者为什么写这首词、要表达什么情感。先赏上片，上片主要写景。首句“**独立寒秋，湘江北去，橘子洲头**”，正常语序应该是“寒秋独立橘子洲头，湘江北去”，分别点明了时间、地点和特定环境。“独立寒秋”从语法上看采用了**倒装**，倒装的目的在于强调“独立”。“独立”这个词能不能改成“站立”呢？显然不能。当时湖南军阀赵恒惕命令湘潭县团防局逮捕毛泽东就地正法，毛泽东得到消息后趁着月色扮成乡下郎中，坐轿子回到了韶山，秘密来到了赵恒惕的眼皮底下长沙。诗人身处险境，却能独立寒秋，表现了他的坦荡和从容，更有迎风独立、俯视天下、胸怀大志的形象，体现了诗人充当中流砥柱、顶天立地的气概。同时把“独立”前置增强了表现力：用一个特写镜头把人物从景中推出，凸显了抒情主人公卓然而立的形象，激发了读者的联想与想象。柳宗元“独钓寒江雪”表达了被贬的落寞与独善其身的清高，与革命伟人胸怀天下的傲岸不群是不可同日而语的。欣赏完“独立寒秋图”，继续欣赏“湘江秋景图”。欣赏之前先学一个重要概念——**意象**：意象指诗歌中融入了作者主观情感的客观物象，是作者内在的思想情感与外在的客观物象的统一。这幅图景由“**看**”字领起，“看”字统领的意象有远山、层林、漫江、百舸、鹰击长空的鹰、畅游水中的鱼。先看远景：作者远眺群山，“**万山红遍**”，写出了群山起伏叠嶂之态，气象雄阔、视野开阔、大气磅礴；“遍”写出了红之广，一个数词一个副词，虽不是什么华丽的词藻，却通过红叶写出了秋天的壮观，红色枫叶在秋阳的照耀下红得似火、辉煌灿烂，突出了壮阔之美。“**层林尽染**”：“层”写出了树木随山势起伏而远近上下变化的形态；“尽”形容秋天的树叶全部变红，具有很强的画面感；“**染**”运用**拟人**的手法，写出了枫叶的颜色由淡变深的动态，且充满了意趣。王实甫在《西厢记》中有“**晓来谁染霜林醉，总是离人泪**”的名句，一个“染”字就把一片枫林仿佛人工染成的一样的壮美景色描绘出来。南宋的张炎在《疏影·咏红叶》中写红叶，寄寓着作为南宋遗民在南宋灭亡后面对异族的残暴统治依然保持爱国赤诚忠贞之心，彰显了亡国遗民蔑视卑躬屈膝的新贵的高尚气节。同样面对黑暗的社会现实，张炎展现了不卑不亢的民族气节，而毛泽东则通过壮丽之景透露出自信乐观的豪情。随着镜头的拉近，作者静观“**漫江碧透**”：“漫”是满的意思，不是取一朵浪花、一轮涟漪，而是放眼湘江整体，写出了江水漫溢之状；“透”写出了江水的清澈；“碧”是青绿色，既写出了江水的清澈，又赋予生命的力度，勃发着生命的光彩。“漫山红遍，漫江碧透”，红碧两色都赋予生命的力度，勃发着生命的光彩，一派勃然生机、欣欣向荣；而且红碧两色的对比度很强，红在碧的映衬下愈显其红，碧在红的映衬下愈显其绿，红枫绿水、交相辉映、色彩流光、鲜艳夺目。古代诗人的写景诗中也非常注意景色颜色的搭配，杜甫诗句“山青花欲燃”也是以青红二色描写出青山的壮美。“**百舸争流**”：“百”写出了船只的众多；“争”写出了江面上千帆竞发、争先恐后的热闹场面，不仅是数量多、热闹，且写出一种生机活力，与整体诗意相合。老师把这句与屈原《九歌》里同样写千帆竞渡的句子进行对比：屈原那句为纪念我国第一位爱国诗人屈原，用竞渡来消解心中的愁绪，多一份悲壮，蕴含着人们对他的无限缅怀；毛泽东的诗中却张扬着不甘人后的竞争气势。随着镜头的变幻，作者仰观应天、俯瞰于地：“**鹰击长空**”这句中“击”是否可以改为“飞”？是不行的。“击”本来应该是人发出的动作，有搏击的意味，更能把雄鹰振翅奋飞、迅猛有力地搏击长空的矫健勇猛的雄姿描绘出来，写出雄鹰振翅翱翔的自由，如此有力、如此傲然，天地之间只见这一只只雄鹰。“**鱼翔浅底**”：“翔”一般用来形容鸟儿，鱼儿在水中应该是游动的，为什么用“翔”呢？“浅底”并非真的水浅，而是清澈见底、水浅得看得见底，蓝天倒映在碧水中，看上去鱼好像在天空中游动，好像飞翔一样，不用扇动翅膀而飞，生动地写出了鱼在水中自由自在、轻松自如的神态。“翔”使整个画面活化了。再深入一层，还可理解为：鱼在水中游是眼前之景，在空中翔可以理解为心中之景，因为比海洋还辽阔的是天空，在天空翱翔的鱼更加自由。这句词是在化用《诗经·大雅·旱麓》“鸢飞戾天，鱼跃于渊”的基础上进行的不着痕迹的化用，赋予了客观事物强烈的感情色彩，更好地表现了那种彻底追求自由的状态。“**万类霜天竞自由**”由眼前景扩展到世间万物，并做了哲理性升华，“竞”有力地突出了在寒秋严霜下万物蓬勃旺盛的生命力，让读者感受到诗人对大自然的无限热爱和由衷赞美。既然世间万物都在秋光中过着自由自在的生活，在秋光中获得了自由生存，那么作为万物之灵的人类，特别是被压迫被剥削的人民，不是更应该竞自由吗？这实际上是对被压迫人民的号召和呼唤。秋天是草木变衰的季节，也是一般人容易伤怀的时候。刘禹锡《秋词》说“**自古逢秋悲寂寥，我言秋日胜春朝**”，自从宋玉悲秋，历代文人皆生悲意，秋天落在纸面上只是一颗凄清的泪滴而已。然而秋天又是守成与革新的试金石：秋天对旧有之物进行否定，对新生之物加以肯定，大凡守成恋旧的人常会因秋气扫除旧物而感慨盛世变衰，而立志改造社会的革命者对秋天的除旧布新予以热烈的欢呼。毛泽东是伟大的革命家，他所进行的改变中国几千年历史的革命是一场划时代的大革命，他热爱秋天，在所有的词作中多次欢呼秋天、赞美秋天，如“**一年一度秋风劲，不似春光，胜似春光**”“**万木霜天红烂漫**”“**六盘山上高峰，红旗漫卷西风**”。在本词中，诗人呈现在我们眼前的是一幅绚丽蓬勃、充满生机的瑰丽图景，诗人对秋天的礼赞更是达到了如火如荼的地步。品读上片最后一句“**怅寥廓，问苍茫大地，谁主沉浮**”：“怅”是诗意不畅、怅惘，这里用来表达由深思而引发的激昂慷慨的心绪；词人面对生机勃勃的大自然和广阔的宇宙，面对着在大自然和宇宙中竞自由的万物，思绪万千、深沉地思索。他想到了祖国的命运和革命的未来，禁不住向苍茫大地发问，谁来主宰国家的命运、掌握民族的前途，提出革命领导权的问题。“问”有力发千钧之势，是屈原笔下的《天问》，意在告诉我们天将降大任于斯人也，直接表现了诗人博大的胸襟和气魄。上片作者独立湘江，描绘了一幅生机盎然、色彩绚丽壮美的秋景图，并借景抒情，发出了“谁主沉浮”的感叹，直接表现了诗人博大的胸襟和气魄。面对上片提出的问题，下片是如何回答的呢？下面一起分析下片。首先具体研习“峥嵘岁月图”：“**携来百侣曾游，忆往昔峥嵘岁月稠**”在全文的结构中起什么样的作用呢？一般分上下两片的词，其下片首句又称**过片**，在词中起承接过渡的作用，因此填词时非常注意过片。本词上片写独立寒秋、故地重游而看到了景色，自然而然地想到以前同学携手来游的情景，于是过渡到对往昔生活及同学少年的回忆中，在此过渡非常自然，衔接也是非常巧妙。上片讲到“百舸争流”，数词“百”写出了船之众多，同样这里的“百侣”突出同学少年的人数之多、气势之大；“携”有带领的意思，彰显领导本色。橘子洲是青年毛泽东与同学战友常来游览的旧地，旧地重游，回忆浮现。“峥嵘”原指山势险峻，这里是不平凡、不寻常的意思；“稠”指多，“峥嵘岁月稠”指不寻常的日子很多。毛泽东在长沙生活、学习、从事革命期间，国内外发生了许多重大事件：辛亥革命、第一次世界大战、俄国十月革命、五四运动、中国共产党的成立等，都是影响世界形势的巨大变革，这样的岁月如历史群山中耸立的一座又一座的峥嵘的高峰。“**恰同学少年，风华正茂；书生意气，挥斥方遒**”四句，激昂顿挫、节奏鲜明，活化出一群青年革命家的英姿俊彩：正值青春年少的同学们意气风发、才华横溢、激情奔放、革命斗志昂扬。1914年，毛泽东进入湖南省第一师范读书，结识了一批胸怀革命大志的学友，经常在湘江岸边、岳麓山中、橘子洲头聚会，在蓬勃发展的革命形势的激励下，他们纵谈革命理想、满腔热情，正如汹涌的湘江浪涛奔腾无阻。“**指点江山，激扬文字，粪土当年万户侯**”艺术地概括了这群青年革命家的实践活动：毛泽东曾在长沙组织起湖南学生联合会和新民学会，开办了工人夜校，宣传革命真理；他们评论国家大事，写出了一篇篇激扬文字。毛泽东在《湘江评论》中豪迈地宣称：军阀不要怕，官僚不要怕，资本家不要怕，把军阀官僚看得同粪土一般。“粪土”在这里是**意动用法**，是“以……为粪土”的意思；“万户侯”本指十万户的封侯者，这里借指大军阀大官僚。回忆峥嵘岁月，流露出对往事的无限怀念，表现了他和革命战友们以天下为己任、蔑视反动派、改造旧世界的革命战斗豪情，同时也说明年轻的革命家完全可以主宰中国的命运，完全有能力打碎旧的国家机器，创造一个崭新的世界。现在继续学习“中流击水图”：“**曾记否，到中流击水，浪遏飞舟**”。当年，作者曾和蔡和森等数十名战友同学，在上水和下水的时候到湘江游泳，坚持不懈，直到隆冬季节，以此来锤炼自己的意志和胆识。现在，作者独立于橘子洲头，回忆起当时的情景，不禁向同学和战友亲切发问。这一句既写出了当时的情景，其中又暗含了勉励之意。“遏”传神之极，掷地可作金石之声，使我们仿佛看到了他们激昂的神态，好似听到了他们的豪言壮语，形象地表达了一代革命青年的凌云壮志。关于“中流击水，浪遏飞舟”，有两种不同的理解：一种解释为“击水”为游泳，在激流中奋力划水，掀起了浪花，甚至阻挡了飞速前进的船舶；另一种解释为“中流击水”即中流砥柱的转化，祖逖中流击楫而誓曰“祖逖不能清中原而复济者，有如大江”，后来“中流击楫”就成了立志复兴祖国的代名词，在这里表示诗人要在时代的潮流里乘风破浪、勇往直前、立志振兴中华的豪情壮志。无论是“到中流击水”还是“中流击楫”，本身都是带有抗争的意味，它实际上是青年革命家峥嵘岁月的艺术缩影。如果把中国革命看作是一条长河，那么这群中流击水者正是长河中的弄潮儿，他们的大无畏精神激起了震天动地的湘江浪涛。这些青年是真正的风流人物，这样的人不主沉浮，谁又能主宰沉浮呢？诗人巧妙地借用“中流击水，浪遏飞舟”的图景，回答了“谁主沉浮”的问题，形象地表达了诗人以天下为己任、蔑视反动统治者、改造旧中国的壮志豪情。这首词上片描绘了一幅多姿多彩、生机勃勃的湘江秋景图，并借景抒情，提出了“苍茫大地，谁主沉浮”的问题；下片回忆了往昔的峥嵘岁月，表现了诗人和战友们为了改造旧中国英勇无畏的革命精神和壮志豪情，形象含蓄地给出了“谁主沉浮”的答案：主宰国家命运的，是以天下为己任、蔑视反动统治者、敢于改造旧世界的青年革命者。全词气势豪迈、激情奔放，洋溢着诗人的青春热情，体现了诗人的伟大抱负。这首词的豪迈气势从何而来？作者是如何表现的呢？首先是**意象美**：由于立意昂扬向上，所以所选取的意象也是生机勃勃的景物，选取的意象广大高远；其次在景物的摄取上采用**多方观照、广角摄影**的手法，多角度、多层面地展示秋光：万山层林是远景，漫江百舸是近景，鹰击仰视、鱼翔俯视，远近高低一览无余；其三在景物的着色上注重**色彩的映衬**搭配，选取红、碧二色；其次是语言极富有表现力，精选**动词**形象入化，数词“万”“百”凸显豪放诗风，“万”“百”突出了宏大壮阔、力学上的崇高美感，给人以强烈的视觉震撼，彰显诗人豁达的胸襟，在毛泽东的其他诗词中用“万”“千”“百”等数词营造一种豪放开阔的氛围已成为他的风格，例如“红军不怕远征难，万水千山只等闲”“北国风光，千里冰封，万里雪飘”；形容词和副词的使用准确到位；其五在景物状态的描写上**动静结合**：山红水绿是静态美，鹰是搏击长空、鱼是漫游浅底、船是竞相争流、水是滔滔北去，体现了动态美，在作者的笔下，秋天不再是生命渐趋衰弱，恰恰相反，那是一个充满了生机的辉煌世界；其六是**景中含情、情景交融**：作者以情驭景，依据自己的主观情志去选择驾驭景物，词中的景物是作者主观能动化了的景物，融入了作者的感情色彩和思想意识，透过这幅壮丽飞动的秋景图，我们读到了它博大的胸襟、崇高的风范。上片写景，景中有情，无论是树叶经霜变红、似染过的万山，还是湘江水中百舸争流的场面，或是搏击长空的雄鹰和水中自在来往的游鱼，都是融入作者情感的景物；下片有叙述、有议论，也结合着抒情，在作者回忆往昔生活的时候，注入颂扬当代英雄的斗志豪情。通过这首词的学习，我们不仅感受到了青年时期的毛泽东以天下为己任、改造旧世界、创造新天地的战斗精神，也学习了鉴赏诗词的方法。练习：比较《沁园春·长沙》和马致远的《天净沙·秋思》“枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯”在意象的选取和表达的情感上有何不同。意象选取不同：《沁园春·长沙》选取远山、层林、漫江、百舸、搏击长空的鹰、畅游水中的鱼等具有壮丽特点的意象；《天净沙·秋思》选取枯藤、老树、昏鸦、西风等具有凄清悲凉特点的意象。表达情感的不同：《沁园春·长沙》表现革命青年以天下为己任、改造旧世界、创造新天地的精神；《天净沙·秋思》充分表现了断肠人浪迹天涯的浓烈的思乡之情。课后作业：再读《沁园春·长沙》，以“诗歌里的青春”为主题，撰写读后感。毛泽东创作这首词时正当而立之年，正是这青年时代树立的雄心壮志和百折不挠、乐观奋进的精神气概成就了一代伟人。青春是什么？青春是生命力最旺盛的年代，充满着豪情，洋溢着乐观，朝气蓬勃，意气风发，斗志昂扬。无奋斗，不青春。老师衷心地希望同学们在自己的青春岁月中都能自觉地磨练意志，塑造完善的人格，像当年的毛泽东那样，到中流击水，浪遏飞舟，书写出壮阔的人生篇章。", "vtech": [["“独立”与倒装：强调什么", "正常语序是“寒秋独立橘子洲头”，把“独立”前置是倒装，目的在强调“独立”；“独立”不能换成“站立”：诗人当时正被军阀下令逮捕，身处险境仍独立寒秋，写出坦荡从容、胸怀天下的中流砥柱气概；对比柳宗元“独钓寒江雪”的被贬落寞与独善其身的清高。"], ["意象与“看”字领起", "意象是融入作者主观情感的客观物象；上片“看”字统领万山、层林、漫江、百舸、鹰、鱼六组意象；做题信号：先找领字，再按远近高低列意象，最后说意象背后的情感，别只罗列景物。"], ["动词最见功力：染、击、翔、遏", "“染”是拟人，写枫叶颜色由淡变深的动态；“击”不能换“飞”，“击”有搏击的意味，写出雄鹰振翅奋飞的矫健勇猛；“翔”本写鸟，写鱼显得轻松自如、如在空中飞翔；“遏”传神之极，写浪花阻住飞舟，掷地可作金石之声。"], ["过片与“谁主沉浮”的回答", "下片首句“携来百侣曾游”是过片，承接上片写景、过渡到回忆往昔；“中流击水，浪遏飞舟”有两种理解（击水游泳／中流击楫立志复兴），都含抗争意味，是对上片“谁主沉浮”的回答：主宰国家命运的是以天下为己任的青年革命者。"]], "vgaokao": []}}, "chn_c002": {"name": "立在地球边上放号·红烛", "sec": 2, "secTitle": "第2课 诗歌四首", "page": 4, "desc": "郭沫若的爆发式咏叹与闻一多的红烛自喻：两种现代诗的抒情方式。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c001"], "next": ["chn_c003"], "content": {"advance": {"a": "五四时期是思想解放、反帝反封建的浪潮期。诗中的洪涛既是自然伟力，也是摧毁旧秩序、涤荡旧世界的时代力量象征；诗人礼赞洪涛，就是礼赞创造新世界的革命精神。", "kind": "self", "q": "《立在地球边上放号》写于五四时期。结合时代背景，说说诗中「洪涛」意象的时代含义。"}, "apply": [{"ans": 1, "opts": ["使诗歌显得啰嗦", "形成喷涌而出的节奏，强化对自然伟力与创造精神的礼赞", "是诗人词穷的表现", "主要为了凑齐篇幅"], "q": "《立在地球边上放号》反复出现感叹与呼告句式，其作用分析正确的一项是（ ）", "why": "形式服务情感：反复与呼告把情绪推向高潮，与「力的美学」的主题正相配。"}, {"ans": 2, "opts": ["两首都是托物言志", "两首都是借景抒情", "郭诗以咏叹自然伟力直抒胸臆，闻诗以红烛自喻托物言志", "两首都没有抒情主人公"], "q": "下列对两首诗抒情方式的判断，正确的一项是（ ）", "why": "对比题抓差异：一个情感向外喷发，一个向内收束、自喻自勉。"}], "basics": [{"ans": 1, "opts": ["闻一多", "郭沫若", "徐志摩", "艾青"], "q": "诗集《女神》的作者是（ ）", "why": "《女神》1921 年出版，是郭沫若的代表作，五四新诗的奠基之作。"}, {"ans": 1, "opts": ["喜庆吉祥的气氛", "诗人以烛自喻，象征燃烧自己、照亮别人的奉献精神", "对童年生活的怀念", "对爱情的向往"], "q": "《红烛》中「红烛」的象征意义是（ ）", "why": "闻一多以红烛自况：烧成灰也要发光发热，是知识分子的自我期许。"}], "case": {"a": "由惊叹（这样红的烛）到追问（红烛的来历与使命），再到自誓（愿学红烛、吐出心来）——情感从对象身上收回到诗人自己身上，完成自喻。", "q": "用一句话概括《红烛》抒情主人公情感的变化过程。", "title": "案例：抓情感升温线"}, "intro": "第 2 课四首诗，先看两首中国现代诗：**郭沫若**的《立在地球边上放号》是向外的爆发，**闻一多**的《红烛》是向内的自誓。==现代诗鉴赏抓一条线：抒情主人公的情感是怎样一步步升温的。==", "learn": [{"h": "立在地球边上放号：力的美学", "p": "出自诗集《女神》（1921），写于五四时期。诗人想象自己站在地球边上，看太平洋的潮水、白云、怒涌的海水。核心句式是反复咏叹「啊啊！我眼前来了的滚滚的洪涛哟」式的**呼告**与**反复**，节奏短促、情绪喷涌。==这首诗的考点是「力的追求」：诗人赞美的是摧毁旧世界、创造新世界的力量。==意象只有两组：地球与洪涛，简单而巨大。"}, {"h": "红烛：以烛自喻", "p": "闻一多诗集《红烛》的序诗。诗人把红烛当作对话者：「红烛啊！这样红的烛！」红烛燃烧自己、照亮别人，诗人由此自喻：愿把自己烧成灰，也要给世界留下光和热。结构上是**设问—咏叹—自誓**：先问红烛何来，再赞它的红，最后落到「诗人啊，吐出你的心来比比，可是一般颜色」的自勉。"}, {"h": "两首诗的对比读法", "p": "郭诗向外：情感指向自然伟力与时代浪潮，抒情主人公是「放号者」；闻诗向内：情感指向自我牺牲，抒情主人公就是红烛本身。高考诗歌比较题常问抒情方式差异，答案模板：一个**借景抒情、直抒胸臆相混**，一个**托物言志、借物自喻**。"}], "pitfalls": ["《立在地球边上放号》把「放号」理解成放哨，它是吹响号角、发出呼喊之意。", "《红烛》只答「赞美蜡烛」，丢掉「以烛自喻、燃己照人」这一层。", "作者记混：《女神》是郭沫若，《红烛》是闻一多。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 2, "t": "诗歌四首", "dur": "25:40", "from": "名师课堂", "vtop": ["《立在地球边上放号》里“力”的特点是壮丽、伟大、不可阻挡，破坏一切又创造一切，充满艺术之美，象征五四时代狂飙突进的精神。", "《峨日朵雪峰之侧》的张力有五个方面：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义，再加上抒情的节制。", "雄鹰、雪豹象征力量、自由、英雄，蜘蛛象征弱小卑微；能坚守高度的不是强大而是弱小——这是《峨日朵雪峰之侧》的主旨。"], "vsum": "本课学第二课的两首现代诗：《立在地球边上放号》和《峨日朵雪峰之侧》。通过比较分析，了解现代诗语言的发展和变化，体会现代诗的诗歌艺术。先学郭沫若的《立在地球边上放号》。作者郭沫若，原名郭开真，四川乐山人，现代文学家、诗人、历史学家。1919年五四运动爆发，他投身新文化运动；1921年发表第一本新诗集《女神》，洋溢着强烈的浪漫主义气息，是中国新诗的奠基之作，郭沫若也因此成为中国新诗的重要奠基人之一；同年他又与郁达夫等人一同创立创造社，成为文学革命的主要阵地；他后来还是中国科学院首任院长。这首诗写于五四新文学时期：当时在思想启蒙的时代主题下倡导文学革命，主张平易抒情、新鲜活泼、明了通俗的国民文学；语言形式上扬弃文言文、提倡白话文写作——1917年《新青年》先刊出胡适的八首白话诗，后来又发表刘半农、沈尹默的白话诗；1918年《新青年》发表鲁迅的白话小说《狂人日记》；稍后郭沫若发表《女神》中的大量诗篇，这些都是这场革命的最初业绩。《立在地球边上放号》就发表于这一时期，诗歌以澎湃的激情赞颂了大自然的神力，洋溢着破旧立新的勇猛革命精神。郭沫若自己说：“个人的郁积，民族的郁积，在这时找到喷火口，也找到喷火的方式。我在那时差不多是狂了。”这些五四初期的新诗，在意象、语言、表现手法上都和古典诗歌迥然不同，虽然还显得生涩、平实，但要知道，打破两千年的文言文传统、第一次用白话文写诗，在当时需要多么勇敢的尝试。赏析这首诗从三个方面入手。一是新奇而主观化的意象：诗中的云海、北冰洋、太平洋、洪涛，展现了大自然宏伟壮丽的图景，是古典诗歌中从未出现的；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作和自然意象融合，使得意象成为生命的化身，渗透着诗人强烈的主观精神，所以称之为主观化的意象，这与古典诗歌的意象是不同的。二是狂飙突进的精神：诗中用雄奇、瑰丽、气势磅礴的意象，最终指向一种“力”。这种力有什么特点？从天空的云海到最极端的北冰洋，是壮丽的；竟然能把地球推倒，是前所未有而伟大的；滚滚而来，不可阻挡；破坏一切，又能创造一切；还能创造艺术之美，表现在形态、声响、韵律这些方面。这种力象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明，表现出一种积极进取、勇敢创造的昂扬精神，和热烈追求、摧毁旧世界的勇气与坚定。这种精神是古典诗歌中不曾出现的。三是自由的语言形式：句式上不再有字数限制，而是灵活多变，随着情感变化而变化，使得诗作显得自由奔放；自由的句式不意味着随意搭配，现代诗也讲究内在的韵律——本首诗的长句子由三个韵律单位构成，形成了诗歌的韵律感，读起来有音乐感，这是诗歌区别于散文必不可少的要素之一；“不断的毁坏，不断的创造，不断的努力”这些短句子由动词短语或名词短语排比组成，排比句式增强了诗歌的节奏感和气势；用词方面，白话文口语化的用词通俗易懂、适合传播，在动词、形容词、副词的使用上改变了文言文大多使用单音节词的特点，广泛使用双音节词，符合白话汉语的表达习惯；同时本首诗增加了语气词的使用，“啊”“哟”这些语气词直接抒情，如同词语间的粘合剂，加上后表达感情的效果更强烈。以上这些语言的变化表明，现代诗采用白话文，在句式、词语、抒情等方面都对文言文是一种突破，发展了汉语言的形式，为汉语表达开拓了新的维度。经过了六七十年，到当代，现代诗在语言上愈发取得明显的发展：诗歌文本容量增大，语言技巧性增强，给人以更多的玩味和思考。下面以本课另外一首诗《峨日朵雪峰之侧》为例，谈谈当代诗歌的特点。先了解诗人昌耀：原名王昌耀，湖南桃源人，诗人；1950年参军，曾参加抗美援朝；1955年去青海工作，后调任作协青海分会专业作家。昌耀在苦难深重的生活重压之下，将感悟和激情融于凝重、壮美的意象之中，诗歌中体现了饱经沧桑的情怀、古老开阔的西部人文背景和博大的生命意识，在当代中国诗坛具有重要的地位。峨日朵雪峰是祁连山脉的一座无名山，山顶终年积雪；这首诗写于特殊的年代，诗人遭受了不公正的待遇，但是坎坷的命运与艰苦的生活磨练了诗人的意志，更砥砺了诗人的思想。赏析这首诗主要从诗歌张力的角度入手。所谓张力，是现代诗分析绕不过去的术语。罗吉·福勒说：一般而论，凡是存在着对立而又相互联系的力量、冲动或意义的地方，都存在着张力。在现代诗中，一切相互对峙而又相互作用的意象、情感、修辞、语词，都可产生张力，使得诗歌形成一个有机统一体。简单说，张力就是现代诗中那些矛盾又融合的因素。在古典诗歌中，王籍《入若耶溪》“蝉噪林逾静，鸟鸣山更幽”就是张力诗学的典范：蝉噪、鸟鸣是动，林静、山幽是静，动静之间语意背离、形成两极，但两极间的相互作用却相反相成，营造出一个动中有静的新意境；清代诗论家吴乔由此进一步发挥，动中有静正是诗的绝诣所在。在《峨日朵雪峰之侧》中，张力体现在五个方面。第一，语言的跳跃性。诗歌的第一句“这是我此刻仅能征服的高度了”，凝练而突兀。现代诗的语言和散文截然不同，不需要层层渲染铺垫，只展示最核心的意识的一刹那，体现了语言的非连续性和跳跃性，给人想象的空间。“此刻”这个时间词具有暗示性：此前是否已经尽力陆续征服了很多高度，此后会不会有新的高度，我的目标是不是不停地征服新的高度——这些问题带来了稳稳丰富的解读空间。这就是现代诗的语言，凝练集中但绝不缺少丰富，词语表面的意义和内涵的意义之间存在一种张力。第二，词语的张力。“我小心地探出前额，惊异于薄壁那边，朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海”——这里太阳的“彷徨许久”与“决然跃入”形成一组矛盾；“我的指关节，楔钉一样，楔入巨石的罅隙。血滴，从撕裂的千层掌鞋底渗出”——人物的动作“楔入”与“撕裂”形成对比，对比的效果是打破了语言的静止状态，形成一幅动态的画面。第三，意象对比带来的张力。落日、滑坡的山体，是一组下坠的力量；而此时的攀登者，指关节楔入石缝，是一个坚守者、占据者，这构成一组矛盾，让人联想到现实中有很多让人下滑的力量，但坚守者自有自己的高度要坚持，哪怕这高度是自己仅能达到的，也要用尽全力，体现了人在自然和生活面前的尊严。小小的指关节和巨石、血滴和千层岩，这是渺小与巨大的对比，让人联想到每一寸的坚持要付出多么巨大的努力，甚至牺牲。现代诗的意象之间构成矛盾与对比，目的是让读者由外在形象思考精神内涵，给予读者开阔的想象空间。古典诗歌也有意象的对比，例如杜甫“无边落木萧萧下，不尽长江滚滚来”，落叶的渺小与长江的无穷、落叶飘落的细微声与长江奔涌的浪涛声都构成对比；但是传统诗歌意象的对比是平面的，目的是构成一幅有机的画面，以对自然景色绘声绘色的描摹、渲染意境为目的；而现代诗意象的对比是立体的、由外而内，目的是形成丰富的想象空间和内涵层次，不仅从自然，还深入到人生、精神、哲理角度给人启发。第四，意象叠加与减少带来的张力。“朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海。山体不时滑坡，引动棕色深渊自上而下的一派消融，响着向远方远去的喊杀声”——这里突出雪山严酷特点的意象，太阳、山海、深渊不停叠加，而消融、喊杀声的声音也在叠加，意象与音响的叠加构成一组外部的力量；而对“我”的刻画则做了减法，只定格在指关节、血滴这样触目惊心的意象上，显示出内部力量的痛苦。内外力量都在拉扯着攀登者下滑，但他却仍在坚守，体现了攀登者的坚毅。意象的组合方式，在古典诗歌甚至早期新诗中，大多是并列的形式，如“枯藤老树昏鸦，小桥流水人家”，再如《立在地球边上放号》中太平洋、北冰洋、云海等意象的并列；还有一种组合方式是从不同角度进行排列，如杜甫“风急天高猿啸哀，渚清沙白鸟飞回”，融合了动静、远近、高低、视听等不同的描写角度；这种传统的意象组合都是线性的，而现代诗通过对意象的叠加和减少，使得诗歌的文本展现出立体般的层次，拓展了语言的维度。第五，比喻带来的暗示意义形成张力。“真渴望有一只雄鹰或雪豹与我为伍”——在陡峭的岩壁上，攀登者渴望成为雪山的雄鹰或雪豹，但“但有一只小得可怜的蜘蛛，与我一同默想着这大自然赐予的快慰”。雄鹰和雪豹是力量、速度、自由、英雄、王者的象征，而蜘蛛象征着弱小、卑微、平凡。人们总是渴望在现实中拥有自由、无拘束、潇洒伶俐的状态，但真正的情况是我们不过是一个卑微弱小的存在，这就带来了反讽的效果，是诗人的自嘲——这一层是比喻带来的表面含义。仔细再读诗歌最后几句：在陡峭的岩壁上，唯一能领略自然之美的是谁呢？只有我和这只弱小的蜘蛛，也就象征着坚守高度的不是强大、不是自由、不是速度，甚至不是英雄和王者，而是弱小。这是比喻带来的暗示意义，也是诗人想传达的诗歌主旨。寒冷陡峭的雪山之侧，光明的太阳落山了，山体正在无法阻挡地下滑；而攀登者忍受着痛苦，如楔钉一样楔入石缝，冷静而坚持。在巨大的雪山背景上，它的渺小就如同一只小小的蜘蛛，这幅画面正象征着在现实的巨浪中，能坚守自持的恰恰是卑微而平凡的人。在理智的叙说与冷静的描述中，有诗人对坚守者的歌颂与赞美。古典诗歌的比喻，本体和喻体之间的距离愈远，想象空间愈广；而现代诗歌不应停留在从本体到喻体的线性描述，而应该产生第三种暗示意义。例如辛弃疾“马作的卢飞快，弓如霹雳弦惊”，霹雳用来形容发弓射箭的速度之快之准，从弓到快准的特点、再到喻体霹雳，比喻是这样线性的表达；而《峨日朵雪峰之侧》也有线性比喻，从坚守者到弱小、平凡的特点、再到蜘蛛，但还有内在的暗示意义：尽管弱小而平凡，却在坚守高度——这一哲理性思考。再看诗人情感发生了怎样的变化。诗歌开头“我小心地探出前额”，紧张而小心翼翼；在不停下滑的深渊面前，“我”坚守住岩壁，指关节楔入石缝，给人一种紧绷之感；而后来觉察到愿望落空，只有蜘蛛陪伴自己，流露出幽默和自嘲；到最后与蜘蛛一同默想大自然赐予的快慰，这里体现了冷静、认同和默契，也体现了诗人达到自己的高度后豁达的心智和洒脱的情怀。古典诗歌“诗言志”的传统决定了抒情是古典诗的主要目的，或者借景抒情，或者直抒胸臆，或者情景交融，情是古诗的内核；而现代诗的抒情是节制的，表面的冷静叙述之下，内在流动着巨大的情感激流，这种情感的变化和流动不是喷涌而出，而是通过语言的技巧和意象的组合实现——这就是情感之流要规范进语言形式的河道之中。通过以上分析可以发现，当代诗歌在意象的组合方式、词语的跳跃性和对比、比喻的多重含义、抒情的节制等方面，都体现了现代诗语言的张力。经过汉语几十年的发展，相较五四时期的新诗，现代诗的语言不断寻找新的表现方式、不断尝试新的手法和技巧，经历了从情感的书写到哲理的思索，这些都表现出现代汉语语言形式的发展；现代诗作为一种独立的文学样式，也渐渐发展出对其进行研究的现代诗学。课堂反馈有两道题：第一题，诗中表现的五四时期狂飙突进的精神具体为一种“力”，这种力有什么特点？答案是这种力是壮丽的、伟大的、不可阻挡的，破坏一切又创造一切，充满艺术之美。第二题，《峨日朵雪峰之侧》体现出来的现代诗的张力特点有哪些方面？答案是现代诗的张力主要表现在意象的组合方式（包括意象对比、意象叠加或减少）、词语的跳跃性和对比、比喻的多重含义，以及抒情的节制。课后作业：请同学们在以下现代诗中任选一首，从词语、意象组合、情感等方面试作赏析。", "vtech": [["主观化的意象：新诗与古典诗的分水岭", "云海、北冰洋、太平洋、洪涛是古典诗歌中从未出现的新意象；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作与自然意象融合，意象成为生命的化身，渗透着诗人强烈的主观精神；做题信号：问新诗与古典诗意象有何不同，先答意象新、再答意象主观化。"], ["“力”的特点与象征：五四狂飙突进的精神", "这种力是壮丽的、伟大的、不可阻挡的，破坏一切又能创造一切，还能创造艺术之美（形态、声响、韵律）；它象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明；答题时五个特点要答全，别只写“破坏旧世界”。"], ["张力的五个方面", "《峨日朵雪峰之侧》的张力体现在：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义；再加抒情的节制；问“张力体现在哪些方面”就按这五点答，别把古典的“动中有静”当成现代诗的张力。"], ["比喻要读出第三种暗示意义", "雄鹰、雪豹象征力量、速度、自由、英雄、王者，蜘蛛象征弱小、卑微、平凡；表面含义是诗人的自嘲，暗示意义是：能坚守高度的不是强大而是弱小；古典比喻是从本体到喻体的线性描述，现代诗的比喻还要读出内在的暗示意义，别只停在“蜘蛛像攀登者一样弱小”这一层。"]], "vgaokao": []}}, "chn_c003": {"name": "峨日朵雪峰之侧·致云雀", "sec": 2, "secTitle": "第2课 诗歌四首", "page": 6, "desc": "昌耀的雪峰意象与雪莱笔下的云雀：自读篇目，抓意象与象征即可。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c002"], "next": [], "content": {"advance": {"a": "与文化传统和诗人的精神追求有关：意象本身没有固定含义，是诗人在特定文化语境与创作意图中赋予它的。鉴赏时不能套固定象征表，必须回到文本细节推断。", "kind": "self", "q": "雪莱说云雀是「欢乐的精灵」，而中国古代诗中写鸟多寄托归隐或思乡（如「鸟倦飞而知还」）。这种差异说明意象象征义与什么有关？"}, "apply": [{"ans": 1, "opts": ["显示诗人词汇量大", "云雀只闻其声、难以直写，多侧面比喻能层层逼近它欢乐、自由、光明的本质", "为了押韵", "为了拉长诗篇"], "q": "《致云雀》连用多个比喻写云雀，这样写的好处是（ ）", "why": "手法题答「为什么不用直写」：对象不可见，比喻群是逼近本质的手段，最终指向象征义。"}, {"ans": 1, "opts": ["都写爱情", "都借自然意象寄托精神追求，意象都有明确的象征义", "都是叙事诗", "都用了重章叠句"], "q": "把两首诗放在一起看，共同之处是（ ）", "why": "比较题先找共性框架：借物（景）寄情、意象象征，是两首诗的共同写法。"}], "basics": [{"ans": 1, "opts": ["拜伦", "雪莱", "济慈", "华兹华斯"], "q": "《致云雀》的作者是（ ）", "why": "雪莱是英国浪漫主义诗人，《致云雀》《西风颂》都是他的名作；《夜莺颂》是济慈。"}, {"ans": 1, "opts": ["旅途的障碍", "崇高、坚韧的精神品格与理想追求", "寒冷与死亡", "对故乡的思念"], "q": "《峨日朵雪峰之侧》中雪峰的象征意义是（ ）", "why": "诗人借雪峰的巍峨沉默自况心境，象征不屈的人格与崇高的理想。"}], "case": {"a": "雪峰象征崇高坚韧的人格——细节：雪峰沉默巍峨却孕育雄鹰与江河，静默中自有力量。云雀象征自由欢乐的精灵——细节：它高飞高唱、只闻其声不见其形，诗人愿向它学习歌唱。", "q": "填写对照：雪峰象征 ______；云雀象征 ______。各用诗中一个细节支撑你的判断。", "title": "案例：意象—象征对照"}, "intro": "后两首是自读篇目：**昌耀**的《峨日朵雪峰之侧》写雪峰的崇高与生命力，**雪莱**的《致云雀》把云雀写成欢乐与光明的精灵。==自读篇目抓两点就够：核心意象是什么、象征什么。==", "learn": [{"h": "峨日朵雪峰之侧", "p": "昌耀 1962 年所作（发表较晚）。峨日朵是青海的一座雪峰。诗中雪峰巍峨、沉默，却孕育着雄鹰、雪豹与江河之源。诗人用「这是我此刻的心情吗」的设问，把雪峰的高洁、坚韧与自己的精神追求合为一体。考点：**意象的象征义**——雪峰象征崇高理想与不屈的人格。"}, {"h": "致云雀", "p": "英国浪漫主义诗人雪莱的名作。云雀只闻其声、不见其形，诗人一连串用比喻去逼近它：像诗人、像少女、像萤火虫、像玫瑰——最后得出结论，云雀是「欢乐的精灵」。==雪莱的云雀与中国诗中的禽鸟不同：它不寄托闲适，而是象征自由、欢乐与光明的诗人精神。==结尾诗人祈求云雀把歌唱的本领教给自己，是全诗的落点。"}, {"h": "自读篇目的答题边界", "p": "自读课文在考试中一般不单独命题，但会作为比较阅读的材料出现。高频问法：两篇（首）作品意象象征义的异同。答题时把两边的意象—象征对应写全：雪峰—崇高坚韧的人格；云雀—自由欢乐的精灵。"}], "pitfalls": ["把《致云雀》的作者记成济慈，云雀是雪莱，夜莺才是济慈。", "《峨日朵雪峰之侧》只答「写雪景很美」，丢掉象征层。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 2, "t": "诗歌四首", "dur": "25:40", "from": "名师课堂", "vtop": ["《立在地球边上放号》里“力”的特点是壮丽、伟大、不可阻挡，破坏一切又创造一切，充满艺术之美，象征五四时代狂飙突进的精神。", "《峨日朵雪峰之侧》的张力有五个方面：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义，再加上抒情的节制。", "雄鹰、雪豹象征力量、自由、英雄，蜘蛛象征弱小卑微；能坚守高度的不是强大而是弱小——这是《峨日朵雪峰之侧》的主旨。"], "vsum": "本课学第二课的两首现代诗：《立在地球边上放号》和《峨日朵雪峰之侧》。通过比较分析，了解现代诗语言的发展和变化，体会现代诗的诗歌艺术。先学郭沫若的《立在地球边上放号》。作者郭沫若，原名郭开真，四川乐山人，现代文学家、诗人、历史学家。1919年五四运动爆发，他投身新文化运动；1921年发表第一本新诗集《女神》，洋溢着强烈的浪漫主义气息，是中国新诗的奠基之作，郭沫若也因此成为中国新诗的重要奠基人之一；同年他又与郁达夫等人一同创立创造社，成为文学革命的主要阵地；他后来还是中国科学院首任院长。这首诗写于五四新文学时期：当时在思想启蒙的时代主题下倡导文学革命，主张平易抒情、新鲜活泼、明了通俗的国民文学；语言形式上扬弃文言文、提倡白话文写作——1917年《新青年》先刊出胡适的八首白话诗，后来又发表刘半农、沈尹默的白话诗；1918年《新青年》发表鲁迅的白话小说《狂人日记》；稍后郭沫若发表《女神》中的大量诗篇，这些都是这场革命的最初业绩。《立在地球边上放号》就发表于这一时期，诗歌以澎湃的激情赞颂了大自然的神力，洋溢着破旧立新的勇猛革命精神。郭沫若自己说：“个人的郁积，民族的郁积，在这时找到喷火口，也找到喷火的方式。我在那时差不多是狂了。”这些五四初期的新诗，在意象、语言、表现手法上都和古典诗歌迥然不同，虽然还显得生涩、平实，但要知道，打破两千年的文言文传统、第一次用白话文写诗，在当时需要多么勇敢的尝试。赏析这首诗从三个方面入手。一是新奇而主观化的意象：诗中的云海、北冰洋、太平洋、洪涛，展现了大自然宏伟壮丽的图景，是古典诗歌中从未出现的；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作和自然意象融合，使得意象成为生命的化身，渗透着诗人强烈的主观精神，所以称之为主观化的意象，这与古典诗歌的意象是不同的。二是狂飙突进的精神：诗中用雄奇、瑰丽、气势磅礴的意象，最终指向一种“力”。这种力有什么特点？从天空的云海到最极端的北冰洋，是壮丽的；竟然能把地球推倒，是前所未有而伟大的；滚滚而来，不可阻挡；破坏一切，又能创造一切；还能创造艺术之美，表现在形态、声响、韵律这些方面。这种力象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明，表现出一种积极进取、勇敢创造的昂扬精神，和热烈追求、摧毁旧世界的勇气与坚定。这种精神是古典诗歌中不曾出现的。三是自由的语言形式：句式上不再有字数限制，而是灵活多变，随着情感变化而变化，使得诗作显得自由奔放；自由的句式不意味着随意搭配，现代诗也讲究内在的韵律——本首诗的长句子由三个韵律单位构成，形成了诗歌的韵律感，读起来有音乐感，这是诗歌区别于散文必不可少的要素之一；“不断的毁坏，不断的创造，不断的努力”这些短句子由动词短语或名词短语排比组成，排比句式增强了诗歌的节奏感和气势；用词方面，白话文口语化的用词通俗易懂、适合传播，在动词、形容词、副词的使用上改变了文言文大多使用单音节词的特点，广泛使用双音节词，符合白话汉语的表达习惯；同时本首诗增加了语气词的使用，“啊”“哟”这些语气词直接抒情，如同词语间的粘合剂，加上后表达感情的效果更强烈。以上这些语言的变化表明，现代诗采用白话文，在句式、词语、抒情等方面都对文言文是一种突破，发展了汉语言的形式，为汉语表达开拓了新的维度。经过了六七十年，到当代，现代诗在语言上愈发取得明显的发展：诗歌文本容量增大，语言技巧性增强，给人以更多的玩味和思考。下面以本课另外一首诗《峨日朵雪峰之侧》为例，谈谈当代诗歌的特点。先了解诗人昌耀：原名王昌耀，湖南桃源人，诗人；1950年参军，曾参加抗美援朝；1955年去青海工作，后调任作协青海分会专业作家。昌耀在苦难深重的生活重压之下，将感悟和激情融于凝重、壮美的意象之中，诗歌中体现了饱经沧桑的情怀、古老开阔的西部人文背景和博大的生命意识，在当代中国诗坛具有重要的地位。峨日朵雪峰是祁连山脉的一座无名山，山顶终年积雪；这首诗写于特殊的年代，诗人遭受了不公正的待遇，但是坎坷的命运与艰苦的生活磨练了诗人的意志，更砥砺了诗人的思想。赏析这首诗主要从诗歌张力的角度入手。所谓张力，是现代诗分析绕不过去的术语。罗吉·福勒说：一般而论，凡是存在着对立而又相互联系的力量、冲动或意义的地方，都存在着张力。在现代诗中，一切相互对峙而又相互作用的意象、情感、修辞、语词，都可产生张力，使得诗歌形成一个有机统一体。简单说，张力就是现代诗中那些矛盾又融合的因素。在古典诗歌中，王籍《入若耶溪》“蝉噪林逾静，鸟鸣山更幽”就是张力诗学的典范：蝉噪、鸟鸣是动，林静、山幽是静，动静之间语意背离、形成两极，但两极间的相互作用却相反相成，营造出一个动中有静的新意境；清代诗论家吴乔由此进一步发挥，动中有静正是诗的绝诣所在。在《峨日朵雪峰之侧》中，张力体现在五个方面。第一，语言的跳跃性。诗歌的第一句“这是我此刻仅能征服的高度了”，凝练而突兀。现代诗的语言和散文截然不同，不需要层层渲染铺垫，只展示最核心的意识的一刹那，体现了语言的非连续性和跳跃性，给人想象的空间。“此刻”这个时间词具有暗示性：此前是否已经尽力陆续征服了很多高度，此后会不会有新的高度，我的目标是不是不停地征服新的高度——这些问题带来了稳稳丰富的解读空间。这就是现代诗的语言，凝练集中但绝不缺少丰富，词语表面的意义和内涵的意义之间存在一种张力。第二，词语的张力。“我小心地探出前额，惊异于薄壁那边，朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海”——这里太阳的“彷徨许久”与“决然跃入”形成一组矛盾；“我的指关节，楔钉一样，楔入巨石的罅隙。血滴，从撕裂的千层掌鞋底渗出”——人物的动作“楔入”与“撕裂”形成对比，对比的效果是打破了语言的静止状态，形成一幅动态的画面。第三，意象对比带来的张力。落日、滑坡的山体，是一组下坠的力量；而此时的攀登者，指关节楔入石缝，是一个坚守者、占据者，这构成一组矛盾，让人联想到现实中有很多让人下滑的力量，但坚守者自有自己的高度要坚持，哪怕这高度是自己仅能达到的，也要用尽全力，体现了人在自然和生活面前的尊严。小小的指关节和巨石、血滴和千层岩，这是渺小与巨大的对比，让人联想到每一寸的坚持要付出多么巨大的努力，甚至牺牲。现代诗的意象之间构成矛盾与对比，目的是让读者由外在形象思考精神内涵，给予读者开阔的想象空间。古典诗歌也有意象的对比，例如杜甫“无边落木萧萧下，不尽长江滚滚来”，落叶的渺小与长江的无穷、落叶飘落的细微声与长江奔涌的浪涛声都构成对比；但是传统诗歌意象的对比是平面的，目的是构成一幅有机的画面，以对自然景色绘声绘色的描摹、渲染意境为目的；而现代诗意象的对比是立体的、由外而内，目的是形成丰富的想象空间和内涵层次，不仅从自然，还深入到人生、精神、哲理角度给人启发。第四，意象叠加与减少带来的张力。“朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海。山体不时滑坡，引动棕色深渊自上而下的一派消融，响着向远方远去的喊杀声”——这里突出雪山严酷特点的意象，太阳、山海、深渊不停叠加，而消融、喊杀声的声音也在叠加，意象与音响的叠加构成一组外部的力量；而对“我”的刻画则做了减法，只定格在指关节、血滴这样触目惊心的意象上，显示出内部力量的痛苦。内外力量都在拉扯着攀登者下滑，但他却仍在坚守，体现了攀登者的坚毅。意象的组合方式，在古典诗歌甚至早期新诗中，大多是并列的形式，如“枯藤老树昏鸦，小桥流水人家”，再如《立在地球边上放号》中太平洋、北冰洋、云海等意象的并列；还有一种组合方式是从不同角度进行排列，如杜甫“风急天高猿啸哀，渚清沙白鸟飞回”，融合了动静、远近、高低、视听等不同的描写角度；这种传统的意象组合都是线性的，而现代诗通过对意象的叠加和减少，使得诗歌的文本展现出立体般的层次，拓展了语言的维度。第五，比喻带来的暗示意义形成张力。“真渴望有一只雄鹰或雪豹与我为伍”——在陡峭的岩壁上，攀登者渴望成为雪山的雄鹰或雪豹，但“但有一只小得可怜的蜘蛛，与我一同默想着这大自然赐予的快慰”。雄鹰和雪豹是力量、速度、自由、英雄、王者的象征，而蜘蛛象征着弱小、卑微、平凡。人们总是渴望在现实中拥有自由、无拘束、潇洒伶俐的状态，但真正的情况是我们不过是一个卑微弱小的存在，这就带来了反讽的效果，是诗人的自嘲——这一层是比喻带来的表面含义。仔细再读诗歌最后几句：在陡峭的岩壁上，唯一能领略自然之美的是谁呢？只有我和这只弱小的蜘蛛，也就象征着坚守高度的不是强大、不是自由、不是速度，甚至不是英雄和王者，而是弱小。这是比喻带来的暗示意义，也是诗人想传达的诗歌主旨。寒冷陡峭的雪山之侧，光明的太阳落山了，山体正在无法阻挡地下滑；而攀登者忍受着痛苦，如楔钉一样楔入石缝，冷静而坚持。在巨大的雪山背景上，它的渺小就如同一只小小的蜘蛛，这幅画面正象征着在现实的巨浪中，能坚守自持的恰恰是卑微而平凡的人。在理智的叙说与冷静的描述中，有诗人对坚守者的歌颂与赞美。古典诗歌的比喻，本体和喻体之间的距离愈远，想象空间愈广；而现代诗歌不应停留在从本体到喻体的线性描述，而应该产生第三种暗示意义。例如辛弃疾“马作的卢飞快，弓如霹雳弦惊”，霹雳用来形容发弓射箭的速度之快之准，从弓到快准的特点、再到喻体霹雳，比喻是这样线性的表达；而《峨日朵雪峰之侧》也有线性比喻，从坚守者到弱小、平凡的特点、再到蜘蛛，但还有内在的暗示意义：尽管弱小而平凡，却在坚守高度——这一哲理性思考。再看诗人情感发生了怎样的变化。诗歌开头“我小心地探出前额”，紧张而小心翼翼；在不停下滑的深渊面前，“我”坚守住岩壁，指关节楔入石缝，给人一种紧绷之感；而后来觉察到愿望落空，只有蜘蛛陪伴自己，流露出幽默和自嘲；到最后与蜘蛛一同默想大自然赐予的快慰，这里体现了冷静、认同和默契，也体现了诗人达到自己的高度后豁达的心智和洒脱的情怀。古典诗歌“诗言志”的传统决定了抒情是古典诗的主要目的，或者借景抒情，或者直抒胸臆，或者情景交融，情是古诗的内核；而现代诗的抒情是节制的，表面的冷静叙述之下，内在流动着巨大的情感激流，这种情感的变化和流动不是喷涌而出，而是通过语言的技巧和意象的组合实现——这就是情感之流要规范进语言形式的河道之中。通过以上分析可以发现，当代诗歌在意象的组合方式、词语的跳跃性和对比、比喻的多重含义、抒情的节制等方面，都体现了现代诗语言的张力。经过汉语几十年的发展，相较五四时期的新诗，现代诗的语言不断寻找新的表现方式、不断尝试新的手法和技巧，经历了从情感的书写到哲理的思索，这些都表现出现代汉语语言形式的发展；现代诗作为一种独立的文学样式，也渐渐发展出对其进行研究的现代诗学。课堂反馈有两道题：第一题，诗中表现的五四时期狂飙突进的精神具体为一种“力”，这种力有什么特点？答案是这种力是壮丽的、伟大的、不可阻挡的，破坏一切又创造一切，充满艺术之美。第二题，《峨日朵雪峰之侧》体现出来的现代诗的张力特点有哪些方面？答案是现代诗的张力主要表现在意象的组合方式（包括意象对比、意象叠加或减少）、词语的跳跃性和对比、比喻的多重含义，以及抒情的节制。课后作业：请同学们在以下现代诗中任选一首，从词语、意象组合、情感等方面试作赏析。", "vtech": [["主观化的意象：新诗与古典诗的分水岭", "云海、北冰洋、太平洋、洪涛是古典诗歌中从未出现的新意象；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作与自然意象融合，意象成为生命的化身，渗透着诗人强烈的主观精神；做题信号：问新诗与古典诗意象有何不同，先答意象新、再答意象主观化。"], ["“力”的特点与象征：五四狂飙突进的精神", "这种力是壮丽的、伟大的、不可阻挡的，破坏一切又能创造一切，还能创造艺术之美（形态、声响、韵律）；它象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明；答题时五个特点要答全，别只写“破坏旧世界”。"], ["张力的五个方面", "《峨日朵雪峰之侧》的张力体现在：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义；再加抒情的节制；问“张力体现在哪些方面”就按这五点答，别把古典的“动中有静”当成现代诗的张力。"], ["比喻要读出第三种暗示意义", "雄鹰、雪豹象征力量、速度、自由、英雄、王者，蜘蛛象征弱小、卑微、平凡；表面含义是诗人的自嘲，暗示意义是：能坚守高度的不是强大而是弱小；古典比喻是从本体到喻体的线性描述，现代诗的比喻还要读出内在的暗示意义，别只停在“蜘蛛像攀登者一样弱小”这一层。"]], "vgaokao": []}}, "chn_c004": {"name": "百合花", "sec": 3, "secTitle": "第3课 小说两篇", "page": 12, "desc": "茹志鹃的战争小说不写战场写被面：细节、视角与「百合花」的象征。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《百合花》中百合花图案的被面象征什么？", "answer": "象征纯洁美好的人性与军民之间圣洁的情感。"}, "pre": [], "next": ["chn_c005"], "content": {"advance": {"a": "避开正面战场，把笔墨放在后方的人情细节上：战争的残酷只用牺牲一笔带过，人性的温暖却写得饱满。这样处理使主题从「战争胜利」转向「人性美好」，在同类题材中独树一帜，也让悲剧结尾的情感冲击更克制、更持久。", "kind": "self", "q": "有人说《百合花》写战争却没有硝烟味。请结合文本说说这种写法的效果。"}, "apply": [{"ans": 1, "opts": ["说明新媳妇很富有", "以行动完成人物转变：从护着嫁妆的羞涩新妇，到敬重烈士的普通百姓，情感升华无声而有力", "为了引出下文", "纯粹交代被子的下落"], "q": "通讯员牺牲后，新媳妇把新被子盖在他身上。这一情节在人物塑造上的作用是（ ）", "why": "情节题要答人物弧线：盖被一个动作完成了转变与升华，比任何议论都有力。"}, {"ans": 1, "opts": ["可以随便发表议论", "见证者视角限制叙事范围，使故事更真实可信，也便于抒发「我」的敬意与感动", "节省篇幅", "避免描写心理活动"], "q": "小说以「我」为叙述者，这样安排的好处是（ ）", "why": "视角题答三点：限制范围、增强真实感、承载抒情。"}], "basics": [{"ans": 1, "opts": ["铁凝", "茹志鹃", "丁玲", "萧红"], "q": "《百合花》的作者是（ ）", "why": "茹志鹃以《百合花》成名；铁凝是《哦，香雪》的作者。"}, {"ans": 3, "opts": ["作为线索贯穿全文", "象征纯洁美好的人性与军民之情", "推动新媳妇的情感转变", "描写战场战斗的激烈"], "q": "小说中百合花被面的作用不包括（ ）", "why": "小说刻意避开正面战场描写，被面的作用在人物与主题，不在战斗。"}], "case": {"a": "说明他纯朴、体贴、善良：年纪小、职位低，却处处照顾别人。作者不用形容词，把性格藏进一连串小动作里——这正是《百合花》细节描写的标志性手法。", "q": "文中通讯员把馒头垫在「我」的肩上、把枣子塞给「我」。这类细节共同说明他怎样的性格？", "title": "案例：找细节读人物"}, "intro": "《百合花》写战争，却几乎不写战场：一床绣着**百合花**的被面，串起通讯员、新媳妇和「我」。==小说考点抓三样：细节描写、叙述视角、标题的象征义。==", "learn": [{"h": "故事与结构", "p": "茹志鹃 1958 年发表的短篇小说，背景是解放战争。通讯员带「我」去包扎所，路上向新媳妇借被子被拒绝；战斗中通讯员为救担架员牺牲，新媳妇把自己结婚时唯一的嫁妆——绣着百合花的新被子——盖在了他的遗体上。情节极简，靠**细节**推进：带路、借被、送鸡蛋、盖被，每个细节都是人物情感的刻度。"}, {"h": "人物与细节描写", "p": "通讯员：十九岁，腼腆、纯朴，从枪筒里挑出的一颗枣、给「我」肩上垫的馒头，都是他的体贴。新媳妇：从「扭捏借被被拒」到「主动盖被」，转变全靠动作与神态完成，没有一句喊口号。==小说塑造人物，最高级的办法是让细节自己说话；答题时找到细节，就找到了分析入口。==「我」是见证者视角，限制视角反而让情感更可信。"}, {"h": "标题与主题", "p": "百合花被面是全文的**线索**，也是象征：百合花象征纯洁，借指通讯员与新媳妇纯洁高尚的心灵，以及军民之间圣洁深厚的情谊。主题不是歌颂战争本身，而是歌颂战争年代里普通人的人性美与人情美——这是茹志鹃区别于一般战争小说的地方。"}], "pitfalls": ["答主题只说「歌颂解放军英勇作战」，漏掉人性美、军民情这一核心。", "把新媳妇前后态度变化说成「思想觉悟突然提高」，其实是细节铺垫下的自然转变。", "作者记错：茹志鹃，不是茹志鹃的其他同音字。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 4, "t": "小说两篇（百合花/哦，香雪）", "dur": "26:14", "from": "名师课堂", "vtop": ["《百合花》以小见大：不写大战场面，只写借被子、缝破洞、献被子三个生活片段，表现纯洁深厚的军民之情和战友之情。", "衣服上的破洞四次出现是全篇最重要的细节：34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞，串联情节、刻画人物、升华主题。", "百合花被子是象征：百合花清丽、纯洁、淡雅，既是新媳妇也是小通讯员高尚纯洁心灵的象征，军民之情和战友之情都像百合花一样纯洁美好。"], "vsum": "先说清楚一点：这节 P4 的视频只讲了第一篇《百合花》，第二篇《哦，香雪》这节课里一个字都没讲到——按选片登记，《哦，香雪》在合集的 P5，另有讲解。下面是这节课实际讲的内容，全部是《百合花》。\n\n开场先说战争在大家印象里是什么样：不是双方对垒的刀光剑影，就是战后的断壁残垣。但有的作家能抛开战争的血泪，从别样的角度凸显生命的美好，《百合花》就是这样一部作品。\n\n先介绍作者**茹志娟**，当代著名女作家，创作以短篇小说见长，笔调**清新俊逸**，情节单纯明了，细节丰富传神，善于从较小的角度反映时代本质。1950年起陆续在报刊发表短篇小说和特写，后来出版了《高高的白杨树》《静静的产院》《百合花》等短篇集。文学评论家**茅盾**称赞说，《百合花》风格清新俊逸，是一篇**结构谨严、没有闲笔**的短篇小说，同时又富于抒情诗的风味，是他最近读过的几十篇小说中最使他满意、最使他感动的一篇。\n\n再看写作背景：小说里的人物和事件并非来自真人真事，但描写的战斗以及战斗的时间、地点是真实的。1946年中秋节，战斗打响，茹志娟在前线包扎所做战勤工作，第一个工作就是去借被子；战斗开始后，她负责记录牺牲战士的姓名、单位，在这个过程中不禁设想他们的家庭亲友、生前的愿望、心中的秘密，当时的情景和想法她一直没有忘记。\n\n常见的战争题材作品有两种类型：一种以塑造人物形象为主，通过战争事件、战役过程和战斗场面的描写，着重刻画人物的思想性格；另一种以反映战争事件为主，通过人物和故事情节的描写，形象地阐释某一重大军事行动、军事思想、军事原则和战略战术。而《百合花》**另辟蹊径**，描写战争状态下的生活片段，格外让人心动。\n\n还要先弄清小说这种文体：小说以**塑造人物形象为中心**，通过故事情节的叙述和环境的描写，反映社会与个人生活。一篇优秀的小说往往必须具备三个要素：**生动的人物形象**、**完整的故事情节**和**人物活动的具体环境**，其中人物形象又是主要因素。\n\n进入文章，先梳理情节。主要人物有三个：小说中的“我”、**小通讯员**、**新媳妇**。情节分四段：**开端**是第1段到第23段，通讯员送我去前沿包扎所；**发展**是第24段到第43段，我和通讯员到百姓家借被子；**高潮**是第44段到第57段，新媳妇为通讯员缝衣服；**结局**是第58段到第59段，新媳妇把百合花被子献出来、盖在通讯员的遗体上。\n\n本篇小说最重要的手法是**细节描写**。细节是指人物、景物、事件等表现对象富有特色的细小环节，细节描写只抓住生活中的细微而又具体的典型情节，加以生动细致的描绘，具体渗透在对人物、景物或场面的描写之中。课文里最典型的是通讯员衣服上的破洞，先后写了四次：第34段，借被子出门，衣服挂在门钩上，肩膀处撕下一片布，“口子撕得不小”；第43段，通讯员回部队，人已走远，还看见肩上撕挂下来的布片在风里一飘一飘；第53段，通讯员牺牲后，军装的肩头上露着那个大洞，一片布还挂在那里；第56段，新媳妇拿着针，“细细地，密密地缝着那个破洞”。四次破洞的作用要从三个角度答：结构上，第一次做铺垫、照应后文缝破洞，第二次承上启下、为后文埋下伏笔，第三次把情节推向高潮、印证牺牲，第四次照应前文、与在新媳妇家划破衣服相映衬；人物上，写出通讯员的朴实、腼腆、执拗和新媳妇的友善、热情，也写出通讯员的天真质朴和回部队时的乐观；主题上，体现**军民鱼水情**，使革命情义得到升华。\n\n小说塑造人物主要运用了哪些描写手法、表现了人物什么性格特征，要分人物记。写“我”，主要运用**心理描写**、**语言描写**、**动作描写**：比如我打趣通讯员“人家走路都没出一滴汗”，“为了我跟他说话，却害他出了这一头大汗”，“这都怪我了”，写出我的幽默、爱开玩笑；面对伤员，“我不能解除他们任何痛苦”，只能带着妇女们给伤员擦洗、喂饭，写出我的细心与无奈。写小通讯员，主要运用**细节描写**、**动作描写**、**神态描写**、**语言描写**：枪筒里稀疏地插了几根树枝，表现他对生活的热爱；借了被子“却高低不肯，撂下被子就走”，表现他的执拗；“他飞红了脸，更加扭怩起来，两只手不停地数摸着皮腰带上的扣眼”，表现他的腼腆；听到要把被子送回去，“他突然站住脚，呆了一会儿说：那，那我们送回去吧”，表现他的憨厚朴实；临走摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说：给你开饭了，说完就脚不点地地走了”，表现他关爱同志。写新媳妇，主要运用**肖像描写**、**动作描写**、**神态描写**：“这媳妇长得很好看，高高的鼻梁，弯弯的眉，而且一头蓬松松的刘海”，凸显其美丽；“好像在掂量我刚才那些话的分量”，转身进去抱被子了，体现其善良和对小战士朴素浓烈的阶级感情；“那媳妇一面笑着，一面赶忙找针拿线，要给他缝上”，表现其友善热情；“依然拿着针，细细地，密密地缝着那个破洞”，“低下头还是一针一针地缝”，表现出品德高尚、勇敢坚强。\n\n除了三位主要人物，小说还刻画了**担架员**的形象，用的手法是**侧面描写**。文章结尾第53到54段，担架员把通讯员抬上门板，还围在床边不肯走；这时通讯员叫大家快趴下，自己一下子扑在了那个东西上。通过担架员的语言，侧面烘托出通讯员英勇无畏的英雄壮举，显出其革命精神的伟大。\n\n把人物刻画的方法总结一下：**正面描写**又称直接描写，指描写人物的语言、行动、肖像、神态、心理来表现人物性格特征，包括概括介绍、肖像描写、神态描写、语言描写、动作描写、细节描写、心理描写；**侧面描写**又称间接描写，即通过其他人物的言行间接写主人公。\n\n再看本文的语言和手法。《百合花》的语言，不论叙述、描写还是对话，都给人一种自然、**清新**、柔和优美的感觉，把一个流血牺牲的战斗故事写得充满诗意，特别是人物语言个性鲜明、生动传神。赏析句子要会抓点：比如“我眼前出现了一片绿雾似的竹海中间，一条窄窄的石级山道，盘旋而上，一个肩膀宽宽的小伙，肩上垫了一块老蓝布，扛了几只青竹，竹梢长长地拖在他后面，挂打着石级哗哗作响”——这句既有环境描写，又有人物的细节描写，既有蓝绿之色，又有哗哗之音，**视听结合**，描绘出竹海中小通讯员劳作的场景。再比如我和小通讯员的对话：“你多大了？”“十九。”“参加革命几年了？”“一年。”“你怎么参加革命的？”“大军北撤时，我自己跟来的。”这段话介绍了通讯员的出身、年龄，又揭示了他舍己救人的阶级基础和思想基础，表现了他的思想觉悟和自觉的革命要求。\n\n本文还突出使用**对比手法**，有两处必会：一是能射出杀人子弹的枪筒里，插着象征自然与和平的树枝与野菊花，这本身就是一个鲜明的对比，让我们在无言中感受**战争与和平的剧烈冲突**——战争是残酷的，但生活是美好的，战争中不可避免会有流血，但在小通讯员身上却能看到生活的一抹亮色；二是通讯员牺牲后，新媳妇与医生、我的态度不同：借被子时的腼腆与局促、临走时的狼狈模样还记忆犹新，舍己救人的英勇无畏又挽在眼前，新媳妇的情感由原先的疼爱变为当下的痛惜，医生和我还能够用理性的眼光去看待小通讯员的死亡，但新媳妇不能——她劈手夺下被子，一针一线，密密地缝着破洞，这是情感与理智的鲜明对比，是**情感对死亡的战胜**。\n\n再看行文构思。小说情节的叙述方式主要有五种：**顺序**，按时间、空间顺序来写，情节发展脉络分明、层次清晰；**倒叙**，不按时间先后顺序，而是把某些发生在后的情节或结局先行提出，然后再按顺序叙述下去，造成悬念、引人入胜；**插叙**，在叙述主要事件的过程中，插入另一与之有关的事件，然后再接上原来的事件写，对主要情节或中心事件做必要补充说明，使情节更加完整、结构更加严密、内容更加充实丰满；**补叙**，在叙述主要事件的过程中插入另一与之有关的事件，然后再接上原来的事件写，对上文内容加以补充解释，对下文做某些交代，照应上下文；**平叙**，只叙述两件或多件同时发生的事，使头绪清楚、照应得体。《百合花》全文以时间为顺序，以**“我”的所见所闻为线索**展开情节，以“我”为视点娓娓动听地叙述故事、栩栩如生地描绘人物，并从“我”的感情变化中逐步完成人物性格的塑造，使故事显得更为真实。\n\n最后看文章的主题，也就是百合花被子的象征意义。大自然中的百合花具备**清丽、纯洁、淡雅**的特点，小说中的白色百合最为常见，其花语为纯洁、清新，对应着文中的军民鱼水情。与百合花被子相关的情节主要有两处：第一处在第26段到第41段，通讯员和我去借被子，在我的帮助下，从新媳妇家借来了百合花被子；第二处在第58段到第59段，新媳妇把被子盖在通讯员的遗体上。这两处情节在结构上推动小说情节的发展，使得结构严谨；为刻画人物性格服务，照应人性之美，暗示人物心灵的纯洁与精神的高尚，表现出革命军民鱼水情。再说百合花和新媳妇之间的关系：新媳妇娴静、淳朴、善良、纯真，具有如百合花一样美丽的**人性美**，所以百合花正是人物纯真、美好心灵的象征。而百合花不仅仅是新媳妇心灵和性格的象征，也象征着小通讯员高贵的品格。百合花作为文章情感的载体，象征着人物的高贵品格，不仅仅是两位主人公，从小说中的“我”到文章中的担架员、医生、卫生员、通讯干部、村中妇女等等，处处表现出人民群众对革命的理解与支持。题目“百合花”本身也有讲究：百合花色泽文雅、香气清幽、白净纯洁，题目用的手法是**借代**，借印有百合花的被子来指代；更重要的是，作者赋予了它丰富的象征意义——小通讯员和新媳妇都有百合花一样高尚纯洁美好的心灵，军民之间的感情也像百合花一样纯洁、高尚、美好，战士和战士之间的情感也像百合花一样纯洁、高尚、美好。一句话，百合花象征着**人性美**、**性格美**，百合花是一首青春赞歌。\n\n课的最后总结选材特点：作者没有直接描绘战争场面，而是通过生活场景切入战争时代；作者通过连姓名都没有的三个人物之间的关系，谱写了一曲“**没有爱情的爱情牧歌**”——在通讯员和“我”之间，作者让我对通讯员建立起一种比同志、同乡更为亲切的感情；维系在通讯员和新媳妇之间的关系纽带，同样也是一种圣洁美好的感情，正如被子的百合花图案一样纯洁。这是一种青春的气息，一份革命的情意。常见的战争题材文章都是描绘战争场景，但本文选材上却从小处着眼、**以小见大**，表现主题：小说选取了革命战争时期人民斗争生活中的一朵小小的浪花，刻画了有着和百合花一样纯洁高尚、美好心灵的小通讯员和新媳妇形象，表现了纯洁深厚的**军民之情**和**战友之情**，传达了高尚的人情美和人性美。\n\n课后的反馈与评价也值得过一遍：小说主要刻画了小通讯员和新媳妇这两个人物形象，运用了细节描写、语言描写、肖像描写、神态描写和动作描写，分别表现了小通讯员热爱生活、执拗、腼腆、朴实、关爱同志的性格特点，和新媳妇美丽、善良、友善、热情、品德高尚、勇敢坚强的性格特点。练习题里有四道：一是字音字形，根据拼音写汉字：破毡帽、扭怩、踌躇、幼稚；二是刻画人物手法，“我”劝新媳妇不要缝了，她却瞟了我一眼，“还是一针一针地缝”，点拨要从新媳妇对通讯员的崇敬和愧疚上考虑——新媳妇是在缝进她的一片深情，瞟我一眼，是对我不理解她的内心表示不满；三是动作描写，“劈手”一词表现了新媳妇怎样的态度——先理解词的意思，再放在语境中考虑：劈手写出了新媳妇用自己的新被子为通讯员入殓时的果断、坚毅、不容商量的态度；四是细节描写，小说中两次写到馒头，第42段通讯员摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说，给你开饭了”，第57段通讯员牺牲后，我无意中摸到身边两个干硬的馒头——结构上前后照应，第一次为后文通讯员牺牲时身上带着干硬的馒头埋下伏笔，第二次照应前文；人物上突出了通讯员关爱同志的性格特点，烘托了他高尚的人格情操和与我深厚的革命情谊；主题上突出了我当时内心的伤痛和不舍，使文章的悲剧性更加突出，使读者产生强烈的共鸣，突出通讯员的献身精神。课后作业有三项：复习刻画人物的手法，了解手法的作用；体悟《百合花》中感人至深的青春情怀和人性之美；新媳妇将自己的新被子盖在牺牲的通讯员身上时没有说话，揣摩其心理，写一段话，写出此时她的心理所想。", "vtech": [["细节描写：破洞四次，作用分三层", "课文先后四次写通讯员衣服上的破洞（34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞）。考试要从结构、人物、主题三方面答：结构上铺垫、照应、承上启下、推向高潮；人物上写出通讯员的朴实腼腆执拗和新媳妇的友善热情；主题上升华军民鱼水情。只答“刻画人物”不完整。"], ["正面描写 vs 侧面描写", "正面（直接）描写：语言、行动、肖像、神态、心理、细节，如写新媳妇的肖像、写通讯员的神态。侧面（间接）描写：通过其他人物的言行间接写主人公，如担架员的语言侧面烘托通讯员英勇无畏。看到“通过别人写主人公”就认侧面描写，别写成正面。"], ["对比手法两处必会", "一是枪筒里插树枝野菊花，对比能射出杀人子弹的枪筒——战争与和平的剧烈冲突，战争残酷但生活美好；二是通讯员牺牲后新媳妇“劈手夺下被子、一针一线密密地缝”，对比医生和我的理性克制——情感对死亡的战胜。"], ["叙述顺序与线索", "全文以时间为顺序，以“我”的所见所闻为线索，以“我”为视点叙述。叙述方式有顺序、倒叙、插叙、补叙、平叙五种，别把插叙和补叙混了：插叙是插入另一有关事件再接回原文，对主要情节做必要补充；补叙是对上文补充解释、对下文做交代、照应上下文。"]], "vgaokao": []}}, "chn_c005": {"name": "哦，香雪", "sec": 3, "secTitle": "第3课 小说两篇", "page": 19, "desc": "铁凝的抒情小说：一分钟的火车、40 个鸡蛋换来的铅笔盒。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c004"], "next": [], "content": {"advance": {"a": "同：都是贯穿全文的线索兼象征，情节围绕物件展开，主题由物件点出。异：被面在人与人之间流转，象征的是已经存在的美好人性与军民之情；铅笔盒是香雪主动追求的目标，象征尚未抵达的文明与未来。一个回望人情之美，一个眺望文明之光。", "kind": "self", "q": "《百合花》与《哦，香雪》都靠一个核心物件组织全篇。比较两篇中物件（被面、铅笔盒）的异同。"}, "apply": [{"ans": 1, "opts": ["增加热闹气氛", "形成对照：凤娇的向往偏于物质与热闹，香雪的向往指向知识与文明，衬托香雪形象的纯洁与深刻", "凤娇是反面人物", "没有特别用意"], "q": "小说为什么安排凤娇这个人物与香雪并列（ ）", "why": "对照是这篇小说的基本结构，答题要说清对照的两极各指向什么。"}, {"ans": 1, "opts": ["故事的结局交代", "以呼唤式抒情收束全篇，把对香雪的赞美与祝福推向高潮，呼应标题", "引出新人物", "单纯的语气词填充"], "q": "结尾「哦，香雪！香雪！」一句的作用是（ ）", "why": "抒情小说常以呼唤收尾：点题、抒情、余韵，一句三得。"}], "basics": [{"ans": 2, "opts": ["十个", "二十个", "四十个", "一百个"], "q": "香雪用多少个鸡蛋换来了铅笔盒（ ）", "why": "40 个鸡蛋是她能拿出的全部积蓄，数字本身就是向往之重的度量。"}, {"ans": 1, "opts": ["财富与地位", "知识、现代文明与走出大山的向往", "同学之间的友谊", "火车的速度"], "q": "《哦，香雪》中铅笔盒象征（ ）", "why": "铅笔盒是女学生的用品，在香雪眼里就是文明与知识的化身。"}], "case": {"a": "出现：女学生的自动铅笔盒让香雪看呆，它与山村的木头铅笔盒完全不同。变化：香雪用 40 个鸡蛋换得它，又为它走 30 里夜路。指向：它已不是文具，而是知识与现代文明的象征，凝结着山村少女走出大山、改变命运的渴望。", "q": "铅笔盒在文中出现了多次。请按「出现—变化—指向」三步，简述它的象征意义形成过程。", "title": "案例：物件象征三问"}, "intro": "《哦，香雪》是铁凝的**抒情小说**：山村每天只停一分钟的火车，搅动了台儿沟姑娘们的心。==考点抓两样：铅笔盒这一核心物件的象征义、抒情笔法与小说语言的诗化。==香雪用 40 个鸡蛋换铅笔盒，是全篇的高光。", "learn": [{"h": "故事与人物", "p": "台儿沟封闭落后，火车的到来是姑娘们一天中最热闹的时刻。香雪与凤娇性格对照：凤娇泼辣外向，盼着火车带来外面的世界；香雪安静内秀，目光落在女学生的**铅笔盒**上——那只带磁铁扣、自动合上的铅笔盒，成了她心中现代文明的化身。她用攒下的 40 个鸡蛋换来铅笔盒，独自走了 30 里夜路回家。"}, {"h": "核心物件：铅笔盒", "p": "铅笔盒在文中反复出现，是典型的**象征性细节**：它象征知识、现代文明与山村少女对新生活的向往。香雪换的不是文具，是走出大山的愿望。与之对照的是凤娇们看重的手表、发卡——同样向往，层次不同。==小说题遇到反复出现的物件，先问三句：出现几次？在谁手里变化？指向什么主题？==本篇的答案指向「文明的叩门」。"}, {"h": "抒情笔法", "p": "这篇小说淡化情节、强化抒情：月光下的台儿沟、香雪夜行时的心理独白，都写得像散文诗。结尾「哦，香雪！香雪！」的呼唤把情感推向高潮。主题落点：改革开放初期，封闭山村被现代文明轻轻叩门的瞬间，一代青年对新生活的纯真渴望。"}], "pitfalls": ["把香雪换铅笔盒理解成虚荣攀比，丢掉了「对知识与文明的向往」这一层。", "忽略凤娇与香雪的对照关系，只复述情节。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 4, "t": "小说两篇（百合花/哦，香雪）", "dur": "26:14", "from": "名师课堂", "vtop": ["《百合花》以小见大：不写大战场面，只写借被子、缝破洞、献被子三个生活片段，表现纯洁深厚的军民之情和战友之情。", "衣服上的破洞四次出现是全篇最重要的细节：34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞，串联情节、刻画人物、升华主题。", "百合花被子是象征：百合花清丽、纯洁、淡雅，既是新媳妇也是小通讯员高尚纯洁心灵的象征，军民之情和战友之情都像百合花一样纯洁美好。"], "vsum": "先说清楚一点：这节 P4 的视频只讲了第一篇《百合花》，第二篇《哦，香雪》这节课里一个字都没讲到——按选片登记，《哦，香雪》在合集的 P5，另有讲解。下面是这节课实际讲的内容，全部是《百合花》。\n\n开场先说战争在大家印象里是什么样：不是双方对垒的刀光剑影，就是战后的断壁残垣。但有的作家能抛开战争的血泪，从别样的角度凸显生命的美好，《百合花》就是这样一部作品。\n\n先介绍作者**茹志娟**，当代著名女作家，创作以短篇小说见长，笔调**清新俊逸**，情节单纯明了，细节丰富传神，善于从较小的角度反映时代本质。1950年起陆续在报刊发表短篇小说和特写，后来出版了《高高的白杨树》《静静的产院》《百合花》等短篇集。文学评论家**茅盾**称赞说，《百合花》风格清新俊逸，是一篇**结构谨严、没有闲笔**的短篇小说，同时又富于抒情诗的风味，是他最近读过的几十篇小说中最使他满意、最使他感动的一篇。\n\n再看写作背景：小说里的人物和事件并非来自真人真事，但描写的战斗以及战斗的时间、地点是真实的。1946年中秋节，战斗打响，茹志娟在前线包扎所做战勤工作，第一个工作就是去借被子；战斗开始后，她负责记录牺牲战士的姓名、单位，在这个过程中不禁设想他们的家庭亲友、生前的愿望、心中的秘密，当时的情景和想法她一直没有忘记。\n\n常见的战争题材作品有两种类型：一种以塑造人物形象为主，通过战争事件、战役过程和战斗场面的描写，着重刻画人物的思想性格；另一种以反映战争事件为主，通过人物和故事情节的描写，形象地阐释某一重大军事行动、军事思想、军事原则和战略战术。而《百合花》**另辟蹊径**，描写战争状态下的生活片段，格外让人心动。\n\n还要先弄清小说这种文体：小说以**塑造人物形象为中心**，通过故事情节的叙述和环境的描写，反映社会与个人生活。一篇优秀的小说往往必须具备三个要素：**生动的人物形象**、**完整的故事情节**和**人物活动的具体环境**，其中人物形象又是主要因素。\n\n进入文章，先梳理情节。主要人物有三个：小说中的“我”、**小通讯员**、**新媳妇**。情节分四段：**开端**是第1段到第23段，通讯员送我去前沿包扎所；**发展**是第24段到第43段，我和通讯员到百姓家借被子；**高潮**是第44段到第57段，新媳妇为通讯员缝衣服；**结局**是第58段到第59段，新媳妇把百合花被子献出来、盖在通讯员的遗体上。\n\n本篇小说最重要的手法是**细节描写**。细节是指人物、景物、事件等表现对象富有特色的细小环节，细节描写只抓住生活中的细微而又具体的典型情节，加以生动细致的描绘，具体渗透在对人物、景物或场面的描写之中。课文里最典型的是通讯员衣服上的破洞，先后写了四次：第34段，借被子出门，衣服挂在门钩上，肩膀处撕下一片布，“口子撕得不小”；第43段，通讯员回部队，人已走远，还看见肩上撕挂下来的布片在风里一飘一飘；第53段，通讯员牺牲后，军装的肩头上露着那个大洞，一片布还挂在那里；第56段，新媳妇拿着针，“细细地，密密地缝着那个破洞”。四次破洞的作用要从三个角度答：结构上，第一次做铺垫、照应后文缝破洞，第二次承上启下、为后文埋下伏笔，第三次把情节推向高潮、印证牺牲，第四次照应前文、与在新媳妇家划破衣服相映衬；人物上，写出通讯员的朴实、腼腆、执拗和新媳妇的友善、热情，也写出通讯员的天真质朴和回部队时的乐观；主题上，体现**军民鱼水情**，使革命情义得到升华。\n\n小说塑造人物主要运用了哪些描写手法、表现了人物什么性格特征，要分人物记。写“我”，主要运用**心理描写**、**语言描写**、**动作描写**：比如我打趣通讯员“人家走路都没出一滴汗”，“为了我跟他说话，却害他出了这一头大汗”，“这都怪我了”，写出我的幽默、爱开玩笑；面对伤员，“我不能解除他们任何痛苦”，只能带着妇女们给伤员擦洗、喂饭，写出我的细心与无奈。写小通讯员，主要运用**细节描写**、**动作描写**、**神态描写**、**语言描写**：枪筒里稀疏地插了几根树枝，表现他对生活的热爱；借了被子“却高低不肯，撂下被子就走”，表现他的执拗；“他飞红了脸，更加扭怩起来，两只手不停地数摸着皮腰带上的扣眼”，表现他的腼腆；听到要把被子送回去，“他突然站住脚，呆了一会儿说：那，那我们送回去吧”，表现他的憨厚朴实；临走摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说：给你开饭了，说完就脚不点地地走了”，表现他关爱同志。写新媳妇，主要运用**肖像描写**、**动作描写**、**神态描写**：“这媳妇长得很好看，高高的鼻梁，弯弯的眉，而且一头蓬松松的刘海”，凸显其美丽；“好像在掂量我刚才那些话的分量”，转身进去抱被子了，体现其善良和对小战士朴素浓烈的阶级感情；“那媳妇一面笑着，一面赶忙找针拿线，要给他缝上”，表现其友善热情；“依然拿着针，细细地，密密地缝着那个破洞”，“低下头还是一针一针地缝”，表现出品德高尚、勇敢坚强。\n\n除了三位主要人物，小说还刻画了**担架员**的形象，用的手法是**侧面描写**。文章结尾第53到54段，担架员把通讯员抬上门板，还围在床边不肯走；这时通讯员叫大家快趴下，自己一下子扑在了那个东西上。通过担架员的语言，侧面烘托出通讯员英勇无畏的英雄壮举，显出其革命精神的伟大。\n\n把人物刻画的方法总结一下：**正面描写**又称直接描写，指描写人物的语言、行动、肖像、神态、心理来表现人物性格特征，包括概括介绍、肖像描写、神态描写、语言描写、动作描写、细节描写、心理描写；**侧面描写**又称间接描写，即通过其他人物的言行间接写主人公。\n\n再看本文的语言和手法。《百合花》的语言，不论叙述、描写还是对话，都给人一种自然、**清新**、柔和优美的感觉，把一个流血牺牲的战斗故事写得充满诗意，特别是人物语言个性鲜明、生动传神。赏析句子要会抓点：比如“我眼前出现了一片绿雾似的竹海中间，一条窄窄的石级山道，盘旋而上，一个肩膀宽宽的小伙，肩上垫了一块老蓝布，扛了几只青竹，竹梢长长地拖在他后面，挂打着石级哗哗作响”——这句既有环境描写，又有人物的细节描写，既有蓝绿之色，又有哗哗之音，**视听结合**，描绘出竹海中小通讯员劳作的场景。再比如我和小通讯员的对话：“你多大了？”“十九。”“参加革命几年了？”“一年。”“你怎么参加革命的？”“大军北撤时，我自己跟来的。”这段话介绍了通讯员的出身、年龄，又揭示了他舍己救人的阶级基础和思想基础，表现了他的思想觉悟和自觉的革命要求。\n\n本文还突出使用**对比手法**，有两处必会：一是能射出杀人子弹的枪筒里，插着象征自然与和平的树枝与野菊花，这本身就是一个鲜明的对比，让我们在无言中感受**战争与和平的剧烈冲突**——战争是残酷的，但生活是美好的，战争中不可避免会有流血，但在小通讯员身上却能看到生活的一抹亮色；二是通讯员牺牲后，新媳妇与医生、我的态度不同：借被子时的腼腆与局促、临走时的狼狈模样还记忆犹新，舍己救人的英勇无畏又挽在眼前，新媳妇的情感由原先的疼爱变为当下的痛惜，医生和我还能够用理性的眼光去看待小通讯员的死亡，但新媳妇不能——她劈手夺下被子，一针一线，密密地缝着破洞，这是情感与理智的鲜明对比，是**情感对死亡的战胜**。\n\n再看行文构思。小说情节的叙述方式主要有五种：**顺序**，按时间、空间顺序来写，情节发展脉络分明、层次清晰；**倒叙**，不按时间先后顺序，而是把某些发生在后的情节或结局先行提出，然后再按顺序叙述下去，造成悬念、引人入胜；**插叙**，在叙述主要事件的过程中，插入另一与之有关的事件，然后再接上原来的事件写，对主要情节或中心事件做必要补充说明，使情节更加完整、结构更加严密、内容更加充实丰满；**补叙**，在叙述主要事件的过程中插入另一与之有关的事件，然后再接上原来的事件写，对上文内容加以补充解释，对下文做某些交代，照应上下文；**平叙**，只叙述两件或多件同时发生的事，使头绪清楚、照应得体。《百合花》全文以时间为顺序，以**“我”的所见所闻为线索**展开情节，以“我”为视点娓娓动听地叙述故事、栩栩如生地描绘人物，并从“我”的感情变化中逐步完成人物性格的塑造，使故事显得更为真实。\n\n最后看文章的主题，也就是百合花被子的象征意义。大自然中的百合花具备**清丽、纯洁、淡雅**的特点，小说中的白色百合最为常见，其花语为纯洁、清新，对应着文中的军民鱼水情。与百合花被子相关的情节主要有两处：第一处在第26段到第41段，通讯员和我去借被子，在我的帮助下，从新媳妇家借来了百合花被子；第二处在第58段到第59段，新媳妇把被子盖在通讯员的遗体上。这两处情节在结构上推动小说情节的发展，使得结构严谨；为刻画人物性格服务，照应人性之美，暗示人物心灵的纯洁与精神的高尚，表现出革命军民鱼水情。再说百合花和新媳妇之间的关系：新媳妇娴静、淳朴、善良、纯真，具有如百合花一样美丽的**人性美**，所以百合花正是人物纯真、美好心灵的象征。而百合花不仅仅是新媳妇心灵和性格的象征，也象征着小通讯员高贵的品格。百合花作为文章情感的载体，象征着人物的高贵品格，不仅仅是两位主人公，从小说中的“我”到文章中的担架员、医生、卫生员、通讯干部、村中妇女等等，处处表现出人民群众对革命的理解与支持。题目“百合花”本身也有讲究：百合花色泽文雅、香气清幽、白净纯洁，题目用的手法是**借代**，借印有百合花的被子来指代；更重要的是，作者赋予了它丰富的象征意义——小通讯员和新媳妇都有百合花一样高尚纯洁美好的心灵，军民之间的感情也像百合花一样纯洁、高尚、美好，战士和战士之间的情感也像百合花一样纯洁、高尚、美好。一句话，百合花象征着**人性美**、**性格美**，百合花是一首青春赞歌。\n\n课的最后总结选材特点：作者没有直接描绘战争场面，而是通过生活场景切入战争时代；作者通过连姓名都没有的三个人物之间的关系，谱写了一曲“**没有爱情的爱情牧歌**”——在通讯员和“我”之间，作者让我对通讯员建立起一种比同志、同乡更为亲切的感情；维系在通讯员和新媳妇之间的关系纽带，同样也是一种圣洁美好的感情，正如被子的百合花图案一样纯洁。这是一种青春的气息，一份革命的情意。常见的战争题材文章都是描绘战争场景，但本文选材上却从小处着眼、**以小见大**，表现主题：小说选取了革命战争时期人民斗争生活中的一朵小小的浪花，刻画了有着和百合花一样纯洁高尚、美好心灵的小通讯员和新媳妇形象，表现了纯洁深厚的**军民之情**和**战友之情**，传达了高尚的人情美和人性美。\n\n课后的反馈与评价也值得过一遍：小说主要刻画了小通讯员和新媳妇这两个人物形象，运用了细节描写、语言描写、肖像描写、神态描写和动作描写，分别表现了小通讯员热爱生活、执拗、腼腆、朴实、关爱同志的性格特点，和新媳妇美丽、善良、友善、热情、品德高尚、勇敢坚强的性格特点。练习题里有四道：一是字音字形，根据拼音写汉字：破毡帽、扭怩、踌躇、幼稚；二是刻画人物手法，“我”劝新媳妇不要缝了，她却瞟了我一眼，“还是一针一针地缝”，点拨要从新媳妇对通讯员的崇敬和愧疚上考虑——新媳妇是在缝进她的一片深情，瞟我一眼，是对我不理解她的内心表示不满；三是动作描写，“劈手”一词表现了新媳妇怎样的态度——先理解词的意思，再放在语境中考虑：劈手写出了新媳妇用自己的新被子为通讯员入殓时的果断、坚毅、不容商量的态度；四是细节描写，小说中两次写到馒头，第42段通讯员摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说，给你开饭了”，第57段通讯员牺牲后，我无意中摸到身边两个干硬的馒头——结构上前后照应，第一次为后文通讯员牺牲时身上带着干硬的馒头埋下伏笔，第二次照应前文；人物上突出了通讯员关爱同志的性格特点，烘托了他高尚的人格情操和与我深厚的革命情谊；主题上突出了我当时内心的伤痛和不舍，使文章的悲剧性更加突出，使读者产生强烈的共鸣，突出通讯员的献身精神。课后作业有三项：复习刻画人物的手法，了解手法的作用；体悟《百合花》中感人至深的青春情怀和人性之美；新媳妇将自己的新被子盖在牺牲的通讯员身上时没有说话，揣摩其心理，写一段话，写出此时她的心理所想。", "vtech": [["细节描写：破洞四次，作用分三层", "课文先后四次写通讯员衣服上的破洞（34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞）。考试要从结构、人物、主题三方面答：结构上铺垫、照应、承上启下、推向高潮；人物上写出通讯员的朴实腼腆执拗和新媳妇的友善热情；主题上升华军民鱼水情。只答“刻画人物”不完整。"], ["正面描写 vs 侧面描写", "正面（直接）描写：语言、行动、肖像、神态、心理、细节，如写新媳妇的肖像、写通讯员的神态。侧面（间接）描写：通过其他人物的言行间接写主人公，如担架员的语言侧面烘托通讯员英勇无畏。看到“通过别人写主人公”就认侧面描写，别写成正面。"], ["对比手法两处必会", "一是枪筒里插树枝野菊花，对比能射出杀人子弹的枪筒——战争与和平的剧烈冲突，战争残酷但生活美好；二是通讯员牺牲后新媳妇“劈手夺下被子、一针一线密密地缝”，对比医生和我的理性克制——情感对死亡的战胜。"], ["叙述顺序与线索", "全文以时间为顺序，以“我”的所见所闻为线索，以“我”为视点叙述。叙述方式有顺序、倒叙、插叙、补叙、平叙五种，别把插叙和补叙混了：插叙是插入另一有关事件再接回原文，对主要情节做必要补充；补叙是对上文补充解释、对下文做交代、照应上下文。"]], "vgaokao": []}}, "chn_c006": {"name": "喜看稻菽千重浪", "sec": 1, "secTitle": "第4课 新闻三篇", "page": 32, "desc": "人物通讯的范本：用细节和场景写袁隆平，不用空洞的颂词。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "通讯与消息的根本区别是什么？", "answer": "消息重在迅速报道事实；通讯重在具体形象地报道人物或事件，有细节、有情节、有描写。"}, "pre": [], "next": ["chn_c007", "chn_c008"], "content": {"advance": {"a": "标题化用古诗《悯农》「喜看稻菽千重浪」一句，既直接点出袁隆平与水稻的主题，又比直说「袁隆平的贡献」多了文采与画面感。此类标题在新闻标题制作题中是高分范例：既含信息（写谁、写什么），又有文学性（借用与画面）。", "kind": "self", "q": "标题以「喜看稻菽千重浪」入题，好在哪里？从新闻标题的要求谈谈。"}, "apply": [{"ans": 1, "opts": ["堆砌辞藻", "用人物自己的语言与具体经历说话，成就感与挫败感都落在实处，形象可信", "可以虚构情节", "主要靠作者评论拔高"], "q": "文中写袁隆平谈「超级稻」的挫折与梦想，语言平实。这体现通讯写作的什么特点（ ）", "why": "通讯的真实性优先：人物语言越平实，形象越可信；评论拔高反而减分。"}, {"ans": 2, "opts": ["靠抒情结尾", "靠编造对话", "靠细节、数字与场景的支撑", "靠标题吸引人"], "q": "通讯要把人物写活，本文主要靠（ ）", "why": "细节、数字、场景是通讯的三大支柱，缺了它们人物就只剩下履历。"}], "basics": [{"ans": 1, "opts": ["消息", "通讯", "评论", "特写"], "q": "《喜看稻菽千重浪》属于新闻文体的哪一种（ ）", "why": "它是人物通讯：完整生动地报道典型人物的事迹，不同于只报事实的消息。"}, {"ans": 1, "opts": ["杂交水稻", "青蒿素", "电子计算机", "原子弹"], "q": "袁隆平被誉为「杂交水稻之父」，其主要贡献领域是（ ）", "why": "袁隆平团队培育杂交水稻，大幅提升粮食产量；青蒿素属屠呦呦团队。"}], "case": {"a": "要点：写清发现的年份与地点；写清当时的质疑与困难；写出「天然雄性不育株」是杂交水稻研究的关键起点这层意义。写法：不堆术语，用「一株稻子改变一个国家粮食命运」的悬念收尾。", "q": "任选文中一处细节（如发现天然雄性不育株），用两三句话改写成一则简短的人物新闻导语，要求保留关键细节。", "title": "案例：细节改写导语"}, "intro": "第 4 课是三篇**通讯**：《喜看稻菽千重浪》写科学家袁隆平。==学通讯抓一个问题：它和消息有什么不同？答案是——通讯用细节与场景把人物写活。==", "learn": [{"h": "文体：人物通讯", "p": "通讯是比消息更完整、更生动的新闻文体，讲究**典型细节、场景再现与人物语言**。本篇是人物通讯：按袁隆平发现天然雄性不育株、攻克杂交水稻难关、推广超级稻的轨迹选材，不平铺履历，而是挑最能显出品格的片段。考试中辨别文体：标题带文学性、篇幅长、有描写和细节——多半是通讯。"}, {"h": "选材：用细节写精神", "p": "作者写的不是「袁隆平贡献巨大」这种结论，而是他蹲在田埂上的样子、一次次失败后不改的执着、对「禾下乘凉梦」的讲述。==通讯的写作公式：精神不靠形容词，靠细节累积。==答题时把「朴实、执着、心怀天下」这类评价逐一对应回文中的细节，评价才站得住。"}, {"h": "结构：纵贯一生的轨迹", "p": "全文以时间为线，又以「稻菽」意象收束首尾：标题化用《悯农》的诗句，既点出水稻主题，又让新闻有了文学的温度。结尾再回稻田，人物形象与主题同时完成。这种写法与一般新闻的倒金字塔不同，是通讯独有的叙事型结构。"}], "pitfalls": ["把通讯与消息混为一谈：消息以简明迅速、报道事实为主，通讯重在形象生动。", "答精神品质时只贴标签，不回扣文中细节。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 7, "t": "新闻三篇（喜看稻菽千重浪）", "dur": "27:10", "from": "名师课堂", "vtop": ["人物通讯以人物的新近行动为新闻，重在表现人物的品质、性格和精神面貌，通过个别显示一般、通过平凡突出伟大，达到揭示时代特征、感染教育读者的目的。", "《喜看稻菽千重浪》四部分四个小标题：曾记否，到中流击水（1961年发现天然杂交稻株）／创新是科学家的灵魂和本质／事实是科学家的空气／饥饿的威胁在退却——小标题就是语段的核心内容。", "读人物通讯抓四点：吸引人的故事、打动人的细节、个性化的语言、影响人的思想线；过程线是经历与事件，思想线是作者提炼的中心思想。"], "vsum": "本课讲第二单元“劳动光荣”里的《喜看稻菽千重浪》。先说清楚：这节视频只细讲这一篇人物通讯，单元里另外两篇自读通讯《探界者钟扬》和《心有一团火，温暖众人心》课上只布置了自读填表和细节分析的任务，没有逐篇细讲。\n\n开场先交代篇目：《喜看稻菽千重浪》是沈英甲写的人物通讯，发表在《科技日报》2001年2月22日，写的是首届**国家最高科学技术奖**获得者**袁隆平**。本课的学习目标有三条：一是学会阅读人物通讯，把握报道的立场，提升**媒介素养**；二是学会分析通讯的**报道角度**，理解**事实与观点**的关系；三是深入体会**劳动最光荣、劳动最伟大**的思想，培养创新的意识与勇气，形成正确的劳动观念。老师先引了一句普利策新闻奖作品序言里的话：新闻之所以重要，那就是人——写人、影响人。人物通讯在通讯家族里数量占比比较大，研究并掌握它的写作方法，是时代赋予新闻记者的神圣使命。\n\n先明晰概念：**人物通讯以人物的新近行动为新闻**，重在表现人物的品质、性格和精神面貌，**通过个别显示一般，通过平凡突出伟大**，达到揭示时代特征、感染并且教育读者的目的。人物通讯肩负着反映社会主流价值观和国家宣传导向、传播文化与价值的责任。\n\n接下来从题目入手分析。主标题“喜看稻菽千重浪”出自毛泽东的《七律·到韶山》：“喜看稻菽千重浪，遍地英雄下夕烟”。这首诗回顾韶山人民的革命历史，描绘人民公社社员通过热情劳动喜获丰收，赞扬革命人民艰苦卓绝的战斗精神。作者借用诗句为袁隆平作记：一个“喜”字，写出了袁隆平通过不断探索、收获良田稻香的喜悦；“稻”指的是**天然杂交水稻**，“千重浪”营造了开阔意境，既有风吹稻浪的滚滚金黄，又有一望无际的辽阔千里，也让人联想起袁隆平在田间地头育种耕耘的汗水。题目精准生动、富有诗意。副标题“首届国家最高科学技术奖获得者袁隆平”明确交代了人物通讯的写作对象，补充说明主标题的内容。\n\n正文一共分为四个部分，分别由四个小标题引领：**“曾记否，到中流击水”“创新是科学家的灵魂和本质”“事实是科学家的空气”“饥饿的威胁在退却”**。小标题既是语段的标题，同样也是语段的核心内容，拿到文章要对它们足够重视。\n\n第一部分“曾记否，到中流击水”出自毛泽东《沁园春·长沙》“曾记否，到中流击水，浪遏飞舟”，作者用这样有气魄的句子回顾袁隆平的研究历程。这部分是对过去时间段生活内容的回顾：1961年，31岁的袁隆平发现了**天然杂交稻株**，那份激动与喜悦以及这一发现的重大意义。文章不仅写了杂交水稻研究起始阶段的欣喜、期待、失望、思索及发现，还以中国人“**民以食为天**”的观念以及当年普遍发生的饥饿作为社会背景，写了青年袁隆平作为科学工作者要用农业科技战胜饥饿的使命感和责任心，凸显他在研究过程中表现出的**敏于发现、勇于探索**的科学素养。结构上，以“袁隆平的发现注定要成为世界农业上的经典事例”收束，强调这一发现的重大意义，也揭示科研探索过程的艰辛，并引起下文——袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战。\n\n第二部分“创新是科学家的灵魂和本质”揭示这部分内容的主旨：主要写袁隆平面对水稻杂种优势利用这道世界性难题所表现出的敢于挑战的勇气和信心，突出他作为科学家**勇于创新**的精神品格。值得注意的是，这部分里作者写道，袁隆平“从而拉开了我国水稻杂种优势利用的序幕，开创了水稻研究的新纪元”，对袁隆平的成果给予了高度评价；并通过写袁隆平对“中国有中国的有利条件”的分析，显示了他对祖国的热爱以及对制度、道路和文化的自信。\n\n第三部分“事实是科学家的空气”开头先以典型细节写袁隆平对中国亿万农民的深厚感情及为农民造福的追求；在此基础上写他针对不顾农民利益、无视事实驳斥杂交水稻的观点，以平和的语气、无可辩驳的事实以及具体的数据进行回复，充分否定了不实观点，以事实捍卫了科学的尊严。这部分不仅强调了袁隆平作为科学家**实事求是**的态度和捍卫真理的科学精神，还写出了他在论辩中表现的平和个性。\n\n第四部分“饥饿的威胁在退却”开头以袁隆平谈他的梦这个典型细节写起，引出袁隆平对杂交水稻育种的**战略设想**，表现他不断进取的精神以及培育**超级杂交稻**、让杂交稻走向世界的远大目标。在这部分里，作者不仅写出了袁隆平的成就，还强调了两点：一是袁隆平不仅对“谁来养活中国”的疑问做出了有说服力的回答，而且使饥饿的威胁在退却，引导我们走向一个营养充足的世界；二是作为有世界影响力的中国科学家，袁隆平正在引导一场**新的绿色革命**。\n\n纵观全文的时间线：1961年发现天然杂交稻株、确定研究方向，到1964年发现**天然雄性不育株**、开创研究新纪元，从1982年针对否定三系法的观点发表文章、用事实捍卫真理，到1986年提出杂交水稻育种战略设想并付诸实践。从袁隆平身上可以看到的精神品质有：**重视实践、探索规律、勇于挑战、坚持创新、捍卫真理、实事求是、勇于担当、造福民众**。更看到一个坚守了60年的信念，看到了起点的坚定、当下的坚持与未来的期许。\n\n把握了文章写了什么，接下来要透过文本挖掘人物通讯怎么写。采写人物通讯是为了通过人的思想、人的精神面貌去教育人、感染人：光写事迹不写思想，人物是平面的；写了思想，人才有了灵魂、生命，才能有感染他人的力量。人物通讯的写作媒介是真切的实践活动，但隐含在活动背后的，是作者借助各种技巧将思想融入写作，赋予人物立体鲜活的生命力。具体有四点写法。\n\n第一，**抓住吸引人的故事**。人物通讯如何做到故事化？首先要正确选取能够表现人物特点的故事情节，其次要设法增强故事或情节的跌宕起伏、悬念吸引力。但人物通讯故事化有一条底线：**人物故事必须是真实的，不能艺术化**，否则就失去了新闻的真实性，人物通讯就变成小说了。作者笔下的袁隆平故事，叙述并不繁复冗杂，而是抓住典型时间节点的典型特征加以重点描绘：只写袁隆平作为国家最高科学技术奖获得者这一身份，写出杂交水稻之父与杂交水稻的交集部分，重点突出、画面集中、条理清晰，让读者跟随作者的视野、袁隆平的脚步，感受杂交水稻培育之路的坎坷与辛劳。\n\n第二，**打造动人的细节**。细节常被称作**新闻的细胞、通讯的血肉**，是人物生活中最真实、最具特色的精华部分，是新闻的活力所在。形象、真实、可信地表现人物，就是要让细节说话。文章里的三个典型细节句值得细品。其一，“袁隆平眯起双眼，出神地打量着这几百亩大的实验田，然后跨过水渠，迈步走进田间，他蹲下身子，翻看着土壤”——抓住“眯起”“出神地打量”等一系列动词，生动准确地写出袁隆平面对实验田的专注、仔细；借助“跨过、迈步走近、蹲下、翻看”这一串熟练的动作描写，更凸显他是一个真正的实践派科学家，所有科学研究都是自己深入田间地头亲自完成，流畅熟练、毫不马虎，埋头苦干的质朴品质展露无遗。其二，“泥腿子专家，泥腿子院士”——作者以自己跟在袁隆平身后走下稻田时产生的瞬间错觉，写出袁隆平给人的巨大反差的两个印象：杰出的科学家与地道的湖南农民；“挽起裤腿走下稻田，是人们从播种到收获季节见到的袁隆平最标准的形象”一句作答：袁隆平绝对是专家，也是名副其实的院士，但更是土地的儿子、百姓爱戴的国家栋梁。“泥腿子”**一语双关**，既是袁隆平扎根泥土、耕耘土地的写照，也是他专注农业的最好象征。其三，“突然，他那敏锐的目光停留在了一兜形态特异、鹤立鸡群的水稻植株上，他屏住呼吸，伸出双手，欣喜地抚摸着那可爱的稻穗，激动得几乎要喊出声来”——神态与动作描写传神地表现了袁隆平发现杂交水稻植株时的专业、小心翼翼与爱不释手；“几乎”这个程度副词写出了他激动与喜悦的程度，涌动欲出、理性克制。其四，“他头顶烈日，脚踩淤泥，弯腰驼背，去寻找这种天然雄性不育株，已经第十四天了”——“头顶烈日、脚踩淤泥、弯腰驼背”三个四字词语叠加却不用标点隔开，朗读时缩短词语之间的停顿，显现出一种一气呵成的阅读状态，让人感受到袁隆平寻找时的忘我精神、不顾一切、无法阻挡；时间词“十四天”和“马上”“终于”这些典型副词，处处透露寻找的艰难、得到的惊喜、成功的来之不易。\n\n第三，**体现个性化的语言**。语言使人物更生动。人物语言要合乎所写人物的年龄、身份、职业等，要逼真、口语化，还要合乎人物所处的特定环境、特定时期、特定心情和说话对象，做到恰如其分、恰到好处、贴切自然、生动传神。文章第四部分捕捉了袁隆平的语言：“袁隆平是一位世界级的伟大科学家，同时也是一个凡人，当然要做梦。他高兴地回答，他曾经梦见水稻长得像高粱那么高，稻穗像扫帚那么大。”作为凡人，袁隆平也会做梦；作为世界级的伟大科学家，他的梦和他所热爱的事业息息相关。这段语言描写生动形象，夸张比喻的运用突出了袁隆平对粮食丰收的最大期许：杂交稻又高又大，还能真正解决更多人的饥饿问题，让饥饿逐渐退却——如此悲天悯人的情怀、如此造福百姓的社会担当，借助袁隆平的语言传递着动人的力量。这就是他的**“禾下乘凉梦”**。\n\n第四，**抓住影响人的思想线**。人物通讯有两条线：一条是**过程线**，一条是**思想线**。过程线是人物生活的经历或事件发展的过程，是事物的表面现象；思想线则是作者根据人物事迹所提炼出的中心思想，贯穿于人物的典型事迹中，反映事物的本质意义。找思想线要看议论句。第一部分里有这样的句子：“袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战”，从中可以读出袁隆平的坚韧个性与不屈品质，感受到一个伟大的科学家不惧困难的勇气和敢于攀登的执着。第二部分里：“他根据自己的实践，以科学家的胆识和眼光断定，杂交水稻研究具有光辉的前景，他决心义无反顾地坚持研究”——作者直接把科学家的胆识和眼光写出来，和后文“义无反顾的坚持”形成呼应。还有一句议论：“在理论与事实发生矛盾时，袁隆平的态度是尊重权威，但不崇拜权威，不能跟在权威后面亦步亦趋，不敢越雷池一步，他不迷信权威的每一个观点”——这里作者直接提出观点：袁隆平对权威的尊重和对真理的坚持。这与后文的句子也形成呼应：“**科学家是真理的使者，是事实的追随者**。袁隆平坚信实践能发现事实、发现真理，并能验证真理。所有的科学家都将真理奉为圭臬，他们总是将事实真相作为自己不断探寻的目标，在发现事实、发现真理、验证真理中推动人类的不断发展与进步。”因此，总有一些时候，袁隆平作为伟大的科学家站了出来：凡是涉及不顾农民利益、无视事实的事，他都能挺身而出、毫不含糊地阐明事实；至于是不是要担风险，袁隆平在所不惜。就这样，袁隆平捍卫了事实，也捍卫了真理。最后，作者引述的内容更加值得深思：美国学者唐·帕尔伯格在《走向丰衣足食的世界》一书中写道，袁隆平使饥饿的威胁在退却，正引导我们走向一个营养充足的世界；袁隆平是世界上最有影响的中国科学家之一，他正在引导一场新的绿色革命。这是世界对袁隆平的高度评价，也反映出他不仅仅是中国的“泥腿子院士”，更是为世界发展做出卓越贡献的中国科学家。**科学没有国界，大爱无疆**。\n\n课的最后回顾阅读人物通讯的方法：一要抓住吸引人的故事，二要抓住打动人的细节，三要抓住个性化的语言，四要抓住影响人的思想线。学以致用：请同学们仿照本课对细节内容的筛选过程，自读《探界者钟扬》并填写表格——表格有时代身份、典型事件、精神品质三个填写角度：钟扬的第一个时代身份是英雄少年，典型事件是考入中科大少年班、对植物学产生浓厚兴趣、旁听五大课程、做好植物学知识储备，精神品质是雷厉风行、追求梦想、敢想敢做；第二个时代身份是种子达人，典型事件是在西藏收集种子、努力建设来自世界各地的种子宝库、采集种子获得的快乐惊喜与存在的风险，精神品质是执着追求、献身科学；第三个时代身份是科学队长，典型事件是热心科普工作，精神品质是胸怀人类、不辞辛劳；第四个时代身份是接棒导师，典型事件是接过转导师的学生、为学生量身规划、鼓励少数民族地区学生报考自己的研究生，精神品质是热爱教育、关爱学生；第五个时代身份是生命延续先锋，典型事件是研究长寿基因、超负荷工作，精神品质是敢为人先、不懈奉献。再仿照本课对细节内容的分析理解，自读《心有一团火，温暖众人心》，找出表现张秉贵全心全意为人民服务精神品质的细节并加以分析：文章运用语言、神态和心理描写，表现张秉贵面对无端发火的女顾客，不是以冷对冷，而是以热对冷、变冷为热；他站在顾客的立场、为顾客着想，用优质服务、耐心和善带给顾客温暖和慰藉，展现的是对为人民服务宗旨的完全彻底，是一个服务工作者的责任心，是一个平凡劳动者伟大的精神世界。\n\n课后作业有两项：一是阅读第27届中国新闻奖一等奖作品《折翼海天》，通过分析典型事件和细节描写把握人物精神；二是观赏第29届中国新闻奖一等奖获奖作品《见证》，理解事实与观点的关系、把握报道的立场。课堂上还朗读了一段德国媒体的报道：2020年9月7日，袁隆平迎来自己的90岁生日，德国电视一台网站报道称，中国的一位科学英雄迎来自己的90岁生日，他的伟大功绩是培育出了比普通水稻更高产的新水稻品种；袁隆平让中国人从几十年前开始就能吃饱肚子、不必再忍饥挨饿；无论过去还是现在，让全世界的人都吃饱饭是这位科学家的伟大目标，在中国这一目标已基本实现；如今杂交水稻种植面积占全国水稻种植总面积的50%以上；袁隆平和他的团队自上世纪60年代以来一直在培育能大幅提升产量的特殊水稻品种；上世纪我们的研究目标是培育高产水稻，如今随着人民生活水平的显著提高，目标不仅是高产，还要注重高质量；袁隆平领导的研究中心近年来致力于培育耐盐碱杂交水稻品种；90岁的袁隆平说自己仍在参与工作，没有固定的工作时间，想工作时就去办公室，不工作的时候待在家里看电视或打排球、有时也出去旅游，但即便不在全天工作，每天也要去看看自己的水稻。课程最后用一段对袁隆平的颁奖词收束：袁隆平，毕生梦想消除饥饿，他是一位真正的耕耘者；当他还是一个乡村教师的时候，已经具有颠覆世界权威的胆识；当他名满天下的时候，却仍然只是专注于田畴，淡泊名利；一介农夫，播洒智慧，收获富足；他毕生的梦想，就是让所有的人远离饥饿。喜看稻菽千重浪，最是风流袁隆平。", "vtech": [["小标题就是语段的核心", "拿到文章先看小标题：四个小标题对应四个部分——1961年发现天然杂交稻株、敢于创新挑战权威、用事实捍卫真理、袁隆平的梦与超级杂交稻战略设想；答结构题先列小标题，再按时间线展开。"], ["细节描写三处必考点", "“眯起双眼、出神地打量、跨过、蹲下、翻看”一串动词写袁隆平专注田间、埋头苦干的实践派本色；“泥腿子”一语双关，既是扎根泥土的写照，也是专注农业的象征；“头顶烈日、脚踩淤泥、弯腰驼背”连用四字词、不加标点，一气呵成写出寻找雄性不育株十四天的执着。"], ["人物通讯的两条线", "过程线是人物生活的经历或事件发展的过程（表面现象），思想线是作者根据人物事迹提炼的中心思想（本质意义）；找思想线看议论句，如“向国际知名的权威发起挑战”“尊重权威但不崇拜权威”“科学家是真理的使者”。"], ["故事化的底线是真实", "人物通讯要抓住吸引人的故事、增强情节的跌宕与悬念，但故事必须是真实的，不能艺术化，否则就失去了新闻的真实性，人物通讯就变成小说了。"]], "vgaokao": []}}, "chn_c007": {"name": "心有一团火·“探界者”钟扬", "sec": 1, "secTitle": "第4课 新闻三篇", "page": 38, "desc": "两篇自读通讯：一篇写售货员的「一团火」，一篇写种子猎人钟扬。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c006"], "next": [], "content": {"advance": {"a": "共性：都用典型细节塑人，都写平凡岗位里的不平凡。差异：张秉贵是「空间型」人物，一生守在一个柜台前，细节在服务动作里；钟扬是「空间漫游型」人物，足迹遍布青藏高原，细节在跋涉与收集种子的行动里。人物的工作性质决定了细节的选法。", "kind": "self", "q": "两篇通讯里，主人公的精神分别藏在什么样的细节中？比较两篇的细节选择角度。"}, "apply": [{"ans": 1, "opts": ["说明他购物经验丰富", "一个习惯动作写出他把岗位当事业、待顾客如亲人的职业品格", "交代他的年龄", "为下文埋伏笔"], "q": "《心有一团火》中写张秉贵练就「一抓准」的绝活，是为了（ ）", "why": "细节题：所有绝活细节都服务于「一团火」式的职业品格，答题要落到人物精神上。"}, {"ans": 2, "opts": ["旅游见闻的手记", "一味渲染艰苦", "以种子为线索，把科学探索、家国情怀与生命意义编织在一起", "纯粹的人物传记"], "q": "《“探界者”钟扬》以「种子」贯穿全篇，其效果是（ ）", "why": "线索题：物件即人物精神的载体，线索与主题合一是散文式通讯的特点。"}], "basics": [{"ans": 1, "opts": ["袁隆平", "张秉贵", "钟扬", "李斌"], "q": "《心有一团火，温暖众人心》的主人公是北京百货大楼的售货员（ ）", "why": "张秉贵是全国劳动模范，「一团火」精神即源于他的服务态度。"}, {"ans": 1, "opts": ["医学样本", "植物种子", "矿产标本", "动物化石"], "q": "钟扬长期在青藏高原收集的是（ ）", "why": "钟扬为国家收集、保存植物种子，为生物多样性与未来育种留备份。"}], "case": {"a": "细节：他把为国家保存种子的工作比作给未来留火种，明知高原反应危险仍一次次出发，直到以身殉职。作用：一个行动选择同时完成三重刻画——科学家的使命感、探索者的无畏、普通人的生命意识，不需要作者评价，人物自己站了起来。", "q": "从两篇自读通讯中各摘一个细节，说明作者怎样用细节代替评价（举一例即可）。", "title": "案例：细节代替评价"}, "intro": "两篇自读通讯：《心有一团火》写售货员**张秉贵**，《“探界者”钟扬》写植物学家**钟扬**。==自读篇目抓一条线：细节如何代替评价——作者从不说主人公「伟大」，却让你读完忍不住这么想。==", "learn": [{"h": "心有一团火", "p": "林为民作品。张秉贵是北京百货大楼的售货员，「一团火」是他自己总结的服务精神：对顾客像一团火一样热情。他练就称糖「一抓准」、算账比计算器快的绝活。写法上，作者不写他的简历，专写他工作中的**习惯性细节**——人物精神就藏在这些一遍遍重复的动作里。"}, {"h": "“探界者”钟扬", "p": "叶雨婷作品。钟扬是复旦大学教授，十六年行走青藏高原，收集了上千种植物的数千万颗种子，为国家种子库留下备份；2017 年因车祸殉职。文章以「种子」为线索：种子既是他的工作对象，也是他生命意义的隐喻——人会消逝，种子会留给未来。考点：**线索的一语双关**。"}, {"h": "自读通讯的读法", "p": "自读篇目不单独深考，常与第 4 课精读通讯做比较阅读：文体相同（人物通讯），选材角度、细节类型可以互相对照。答题时记得各引一处细节作证，不能只说大道理。"}], "pitfalls": ["把钟扬写成研究动物的科学家——他是植物学家，研究对象是种子与植物多样性。", "比较题只写共性不写差异，或只贴标签不举例。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 7, "t": "新闻三篇（喜看稻菽千重浪）", "dur": "27:10", "from": "名师课堂", "vtop": ["人物通讯以人物的新近行动为新闻，重在表现人物的品质、性格和精神面貌，通过个别显示一般、通过平凡突出伟大，达到揭示时代特征、感染教育读者的目的。", "《喜看稻菽千重浪》四部分四个小标题：曾记否，到中流击水（1961年发现天然杂交稻株）／创新是科学家的灵魂和本质／事实是科学家的空气／饥饿的威胁在退却——小标题就是语段的核心内容。", "读人物通讯抓四点：吸引人的故事、打动人的细节、个性化的语言、影响人的思想线；过程线是经历与事件，思想线是作者提炼的中心思想。"], "vsum": "本课讲第二单元“劳动光荣”里的《喜看稻菽千重浪》。先说清楚：这节视频只细讲这一篇人物通讯，单元里另外两篇自读通讯《探界者钟扬》和《心有一团火，温暖众人心》课上只布置了自读填表和细节分析的任务，没有逐篇细讲。\n\n开场先交代篇目：《喜看稻菽千重浪》是沈英甲写的人物通讯，发表在《科技日报》2001年2月22日，写的是首届**国家最高科学技术奖**获得者**袁隆平**。本课的学习目标有三条：一是学会阅读人物通讯，把握报道的立场，提升**媒介素养**；二是学会分析通讯的**报道角度**，理解**事实与观点**的关系；三是深入体会**劳动最光荣、劳动最伟大**的思想，培养创新的意识与勇气，形成正确的劳动观念。老师先引了一句普利策新闻奖作品序言里的话：新闻之所以重要，那就是人——写人、影响人。人物通讯在通讯家族里数量占比比较大，研究并掌握它的写作方法，是时代赋予新闻记者的神圣使命。\n\n先明晰概念：**人物通讯以人物的新近行动为新闻**，重在表现人物的品质、性格和精神面貌，**通过个别显示一般，通过平凡突出伟大**，达到揭示时代特征、感染并且教育读者的目的。人物通讯肩负着反映社会主流价值观和国家宣传导向、传播文化与价值的责任。\n\n接下来从题目入手分析。主标题“喜看稻菽千重浪”出自毛泽东的《七律·到韶山》：“喜看稻菽千重浪，遍地英雄下夕烟”。这首诗回顾韶山人民的革命历史，描绘人民公社社员通过热情劳动喜获丰收，赞扬革命人民艰苦卓绝的战斗精神。作者借用诗句为袁隆平作记：一个“喜”字，写出了袁隆平通过不断探索、收获良田稻香的喜悦；“稻”指的是**天然杂交水稻**，“千重浪”营造了开阔意境，既有风吹稻浪的滚滚金黄，又有一望无际的辽阔千里，也让人联想起袁隆平在田间地头育种耕耘的汗水。题目精准生动、富有诗意。副标题“首届国家最高科学技术奖获得者袁隆平”明确交代了人物通讯的写作对象，补充说明主标题的内容。\n\n正文一共分为四个部分，分别由四个小标题引领：**“曾记否，到中流击水”“创新是科学家的灵魂和本质”“事实是科学家的空气”“饥饿的威胁在退却”**。小标题既是语段的标题，同样也是语段的核心内容，拿到文章要对它们足够重视。\n\n第一部分“曾记否，到中流击水”出自毛泽东《沁园春·长沙》“曾记否，到中流击水，浪遏飞舟”，作者用这样有气魄的句子回顾袁隆平的研究历程。这部分是对过去时间段生活内容的回顾：1961年，31岁的袁隆平发现了**天然杂交稻株**，那份激动与喜悦以及这一发现的重大意义。文章不仅写了杂交水稻研究起始阶段的欣喜、期待、失望、思索及发现，还以中国人“**民以食为天**”的观念以及当年普遍发生的饥饿作为社会背景，写了青年袁隆平作为科学工作者要用农业科技战胜饥饿的使命感和责任心，凸显他在研究过程中表现出的**敏于发现、勇于探索**的科学素养。结构上，以“袁隆平的发现注定要成为世界农业上的经典事例”收束，强调这一发现的重大意义，也揭示科研探索过程的艰辛，并引起下文——袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战。\n\n第二部分“创新是科学家的灵魂和本质”揭示这部分内容的主旨：主要写袁隆平面对水稻杂种优势利用这道世界性难题所表现出的敢于挑战的勇气和信心，突出他作为科学家**勇于创新**的精神品格。值得注意的是，这部分里作者写道，袁隆平“从而拉开了我国水稻杂种优势利用的序幕，开创了水稻研究的新纪元”，对袁隆平的成果给予了高度评价；并通过写袁隆平对“中国有中国的有利条件”的分析，显示了他对祖国的热爱以及对制度、道路和文化的自信。\n\n第三部分“事实是科学家的空气”开头先以典型细节写袁隆平对中国亿万农民的深厚感情及为农民造福的追求；在此基础上写他针对不顾农民利益、无视事实驳斥杂交水稻的观点，以平和的语气、无可辩驳的事实以及具体的数据进行回复，充分否定了不实观点，以事实捍卫了科学的尊严。这部分不仅强调了袁隆平作为科学家**实事求是**的态度和捍卫真理的科学精神，还写出了他在论辩中表现的平和个性。\n\n第四部分“饥饿的威胁在退却”开头以袁隆平谈他的梦这个典型细节写起，引出袁隆平对杂交水稻育种的**战略设想**，表现他不断进取的精神以及培育**超级杂交稻**、让杂交稻走向世界的远大目标。在这部分里，作者不仅写出了袁隆平的成就，还强调了两点：一是袁隆平不仅对“谁来养活中国”的疑问做出了有说服力的回答，而且使饥饿的威胁在退却，引导我们走向一个营养充足的世界；二是作为有世界影响力的中国科学家，袁隆平正在引导一场**新的绿色革命**。\n\n纵观全文的时间线：1961年发现天然杂交稻株、确定研究方向，到1964年发现**天然雄性不育株**、开创研究新纪元，从1982年针对否定三系法的观点发表文章、用事实捍卫真理，到1986年提出杂交水稻育种战略设想并付诸实践。从袁隆平身上可以看到的精神品质有：**重视实践、探索规律、勇于挑战、坚持创新、捍卫真理、实事求是、勇于担当、造福民众**。更看到一个坚守了60年的信念，看到了起点的坚定、当下的坚持与未来的期许。\n\n把握了文章写了什么，接下来要透过文本挖掘人物通讯怎么写。采写人物通讯是为了通过人的思想、人的精神面貌去教育人、感染人：光写事迹不写思想，人物是平面的；写了思想，人才有了灵魂、生命，才能有感染他人的力量。人物通讯的写作媒介是真切的实践活动，但隐含在活动背后的，是作者借助各种技巧将思想融入写作，赋予人物立体鲜活的生命力。具体有四点写法。\n\n第一，**抓住吸引人的故事**。人物通讯如何做到故事化？首先要正确选取能够表现人物特点的故事情节，其次要设法增强故事或情节的跌宕起伏、悬念吸引力。但人物通讯故事化有一条底线：**人物故事必须是真实的，不能艺术化**，否则就失去了新闻的真实性，人物通讯就变成小说了。作者笔下的袁隆平故事，叙述并不繁复冗杂，而是抓住典型时间节点的典型特征加以重点描绘：只写袁隆平作为国家最高科学技术奖获得者这一身份，写出杂交水稻之父与杂交水稻的交集部分，重点突出、画面集中、条理清晰，让读者跟随作者的视野、袁隆平的脚步，感受杂交水稻培育之路的坎坷与辛劳。\n\n第二，**打造动人的细节**。细节常被称作**新闻的细胞、通讯的血肉**，是人物生活中最真实、最具特色的精华部分，是新闻的活力所在。形象、真实、可信地表现人物，就是要让细节说话。文章里的三个典型细节句值得细品。其一，“袁隆平眯起双眼，出神地打量着这几百亩大的实验田，然后跨过水渠，迈步走进田间，他蹲下身子，翻看着土壤”——抓住“眯起”“出神地打量”等一系列动词，生动准确地写出袁隆平面对实验田的专注、仔细；借助“跨过、迈步走近、蹲下、翻看”这一串熟练的动作描写，更凸显他是一个真正的实践派科学家，所有科学研究都是自己深入田间地头亲自完成，流畅熟练、毫不马虎，埋头苦干的质朴品质展露无遗。其二，“泥腿子专家，泥腿子院士”——作者以自己跟在袁隆平身后走下稻田时产生的瞬间错觉，写出袁隆平给人的巨大反差的两个印象：杰出的科学家与地道的湖南农民；“挽起裤腿走下稻田，是人们从播种到收获季节见到的袁隆平最标准的形象”一句作答：袁隆平绝对是专家，也是名副其实的院士，但更是土地的儿子、百姓爱戴的国家栋梁。“泥腿子”**一语双关**，既是袁隆平扎根泥土、耕耘土地的写照，也是他专注农业的最好象征。其三，“突然，他那敏锐的目光停留在了一兜形态特异、鹤立鸡群的水稻植株上，他屏住呼吸，伸出双手，欣喜地抚摸着那可爱的稻穗，激动得几乎要喊出声来”——神态与动作描写传神地表现了袁隆平发现杂交水稻植株时的专业、小心翼翼与爱不释手；“几乎”这个程度副词写出了他激动与喜悦的程度，涌动欲出、理性克制。其四，“他头顶烈日，脚踩淤泥，弯腰驼背，去寻找这种天然雄性不育株，已经第十四天了”——“头顶烈日、脚踩淤泥、弯腰驼背”三个四字词语叠加却不用标点隔开，朗读时缩短词语之间的停顿，显现出一种一气呵成的阅读状态，让人感受到袁隆平寻找时的忘我精神、不顾一切、无法阻挡；时间词“十四天”和“马上”“终于”这些典型副词，处处透露寻找的艰难、得到的惊喜、成功的来之不易。\n\n第三，**体现个性化的语言**。语言使人物更生动。人物语言要合乎所写人物的年龄、身份、职业等，要逼真、口语化，还要合乎人物所处的特定环境、特定时期、特定心情和说话对象，做到恰如其分、恰到好处、贴切自然、生动传神。文章第四部分捕捉了袁隆平的语言：“袁隆平是一位世界级的伟大科学家，同时也是一个凡人，当然要做梦。他高兴地回答，他曾经梦见水稻长得像高粱那么高，稻穗像扫帚那么大。”作为凡人，袁隆平也会做梦；作为世界级的伟大科学家，他的梦和他所热爱的事业息息相关。这段语言描写生动形象，夸张比喻的运用突出了袁隆平对粮食丰收的最大期许：杂交稻又高又大，还能真正解决更多人的饥饿问题，让饥饿逐渐退却——如此悲天悯人的情怀、如此造福百姓的社会担当，借助袁隆平的语言传递着动人的力量。这就是他的**“禾下乘凉梦”**。\n\n第四，**抓住影响人的思想线**。人物通讯有两条线：一条是**过程线**，一条是**思想线**。过程线是人物生活的经历或事件发展的过程，是事物的表面现象；思想线则是作者根据人物事迹所提炼出的中心思想，贯穿于人物的典型事迹中，反映事物的本质意义。找思想线要看议论句。第一部分里有这样的句子：“袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战”，从中可以读出袁隆平的坚韧个性与不屈品质，感受到一个伟大的科学家不惧困难的勇气和敢于攀登的执着。第二部分里：“他根据自己的实践，以科学家的胆识和眼光断定，杂交水稻研究具有光辉的前景，他决心义无反顾地坚持研究”——作者直接把科学家的胆识和眼光写出来，和后文“义无反顾的坚持”形成呼应。还有一句议论：“在理论与事实发生矛盾时，袁隆平的态度是尊重权威，但不崇拜权威，不能跟在权威后面亦步亦趋，不敢越雷池一步，他不迷信权威的每一个观点”——这里作者直接提出观点：袁隆平对权威的尊重和对真理的坚持。这与后文的句子也形成呼应：“**科学家是真理的使者，是事实的追随者**。袁隆平坚信实践能发现事实、发现真理，并能验证真理。所有的科学家都将真理奉为圭臬，他们总是将事实真相作为自己不断探寻的目标，在发现事实、发现真理、验证真理中推动人类的不断发展与进步。”因此，总有一些时候，袁隆平作为伟大的科学家站了出来：凡是涉及不顾农民利益、无视事实的事，他都能挺身而出、毫不含糊地阐明事实；至于是不是要担风险，袁隆平在所不惜。就这样，袁隆平捍卫了事实，也捍卫了真理。最后，作者引述的内容更加值得深思：美国学者唐·帕尔伯格在《走向丰衣足食的世界》一书中写道，袁隆平使饥饿的威胁在退却，正引导我们走向一个营养充足的世界；袁隆平是世界上最有影响的中国科学家之一，他正在引导一场新的绿色革命。这是世界对袁隆平的高度评价，也反映出他不仅仅是中国的“泥腿子院士”，更是为世界发展做出卓越贡献的中国科学家。**科学没有国界，大爱无疆**。\n\n课的最后回顾阅读人物通讯的方法：一要抓住吸引人的故事，二要抓住打动人的细节，三要抓住个性化的语言，四要抓住影响人的思想线。学以致用：请同学们仿照本课对细节内容的筛选过程，自读《探界者钟扬》并填写表格——表格有时代身份、典型事件、精神品质三个填写角度：钟扬的第一个时代身份是英雄少年，典型事件是考入中科大少年班、对植物学产生浓厚兴趣、旁听五大课程、做好植物学知识储备，精神品质是雷厉风行、追求梦想、敢想敢做；第二个时代身份是种子达人，典型事件是在西藏收集种子、努力建设来自世界各地的种子宝库、采集种子获得的快乐惊喜与存在的风险，精神品质是执着追求、献身科学；第三个时代身份是科学队长，典型事件是热心科普工作，精神品质是胸怀人类、不辞辛劳；第四个时代身份是接棒导师，典型事件是接过转导师的学生、为学生量身规划、鼓励少数民族地区学生报考自己的研究生，精神品质是热爱教育、关爱学生；第五个时代身份是生命延续先锋，典型事件是研究长寿基因、超负荷工作，精神品质是敢为人先、不懈奉献。再仿照本课对细节内容的分析理解，自读《心有一团火，温暖众人心》，找出表现张秉贵全心全意为人民服务精神品质的细节并加以分析：文章运用语言、神态和心理描写，表现张秉贵面对无端发火的女顾客，不是以冷对冷，而是以热对冷、变冷为热；他站在顾客的立场、为顾客着想，用优质服务、耐心和善带给顾客温暖和慰藉，展现的是对为人民服务宗旨的完全彻底，是一个服务工作者的责任心，是一个平凡劳动者伟大的精神世界。\n\n课后作业有两项：一是阅读第27届中国新闻奖一等奖作品《折翼海天》，通过分析典型事件和细节描写把握人物精神；二是观赏第29届中国新闻奖一等奖获奖作品《见证》，理解事实与观点的关系、把握报道的立场。课堂上还朗读了一段德国媒体的报道：2020年9月7日，袁隆平迎来自己的90岁生日，德国电视一台网站报道称，中国的一位科学英雄迎来自己的90岁生日，他的伟大功绩是培育出了比普通水稻更高产的新水稻品种；袁隆平让中国人从几十年前开始就能吃饱肚子、不必再忍饥挨饿；无论过去还是现在，让全世界的人都吃饱饭是这位科学家的伟大目标，在中国这一目标已基本实现；如今杂交水稻种植面积占全国水稻种植总面积的50%以上；袁隆平和他的团队自上世纪60年代以来一直在培育能大幅提升产量的特殊水稻品种；上世纪我们的研究目标是培育高产水稻，如今随着人民生活水平的显著提高，目标不仅是高产，还要注重高质量；袁隆平领导的研究中心近年来致力于培育耐盐碱杂交水稻品种；90岁的袁隆平说自己仍在参与工作，没有固定的工作时间，想工作时就去办公室，不工作的时候待在家里看电视或打排球、有时也出去旅游，但即便不在全天工作，每天也要去看看自己的水稻。课程最后用一段对袁隆平的颁奖词收束：袁隆平，毕生梦想消除饥饿，他是一位真正的耕耘者；当他还是一个乡村教师的时候，已经具有颠覆世界权威的胆识；当他名满天下的时候，却仍然只是专注于田畴，淡泊名利；一介农夫，播洒智慧，收获富足；他毕生的梦想，就是让所有的人远离饥饿。喜看稻菽千重浪，最是风流袁隆平。", "vtech": [["小标题就是语段的核心", "拿到文章先看小标题：四个小标题对应四个部分——1961年发现天然杂交稻株、敢于创新挑战权威、用事实捍卫真理、袁隆平的梦与超级杂交稻战略设想；答结构题先列小标题，再按时间线展开。"], ["细节描写三处必考点", "“眯起双眼、出神地打量、跨过、蹲下、翻看”一串动词写袁隆平专注田间、埋头苦干的实践派本色；“泥腿子”一语双关，既是扎根泥土的写照，也是专注农业的象征；“头顶烈日、脚踩淤泥、弯腰驼背”连用四字词、不加标点，一气呵成写出寻找雄性不育株十四天的执着。"], ["人物通讯的两条线", "过程线是人物生活的经历或事件发展的过程（表面现象），思想线是作者根据人物事迹提炼的中心思想（本质意义）；找思想线看议论句，如“向国际知名的权威发起挑战”“尊重权威但不崇拜权威”“科学家是真理的使者”。"], ["故事化的底线是真实", "人物通讯要抓住吸引人的故事、增强情节的跌宕与悬念，但故事必须是真实的，不能艺术化，否则就失去了新闻的真实性，人物通讯就变成小说了。"]], "vgaokao": []}}, "chn_c008": {"name": "以工匠精神雕琢时代品质", "sec": 2, "secTitle": "第5课", "page": 51, "desc": "一篇新闻评论：由李斌个案上升到时代话题，看评论怎样立论。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c006"], "next": [], "content": {"advance": {"a": "从「个体劳动者的品格」上升到「民族复兴所需要的时代精神」。这样处理使评论不停留在一个人身上：李斌是例证，工匠精神是论点，时代品质是落点。这正是新闻评论由事及理、由小见大的典型路数。", "kind": "self", "q": "本文由李斌一人写到整个时代，标题却是《以工匠精神雕琢时代品质》。请谈谈这种「由个体到时代」的处理有什么好处。"}, "apply": [{"ans": 1, "opts": ["表达感慨", "概括分论点，将工匠精神拆解为可论述的几个侧面", "填充版面", "引用权威言论"], "q": "文中以「守正」「精进」等分层推进，主要是为了（ ）", "why": "结构题：评论的分论点就是把大概念拆开论证的可操作支架。"}, {"ans": 1, "opts": ["只能写具体新闻事件", "由一个典型人物切入，提炼出带有普遍性的时代话题，并加以论证阐发", "只发表个人感受", "与新闻报道完全无关"], "q": "对「评论」这一文体的特点，概括准确的是（ ）", "why": "评论的本质是说理：事实是引子，观点是主体，论证是骨架。"}], "basics": [{"ans": 1, "opts": ["消息", "评论", "通讯", "报告文学"], "q": "《以工匠精神雕琢时代品质》的文体是（ ）", "why": "它以李斌的事迹为由头、发表议论，属于新闻评论；第 4 课的通讯才是叙事为主。"}, {"ans": 1, "opts": ["只干好自己的活", "执着专注、精益求精、一丝不苟、追求卓越的职业精神", "速度越快越好", "多赚钱多升职"], "q": "「工匠精神」的核心内涵是（ ）", "why": "工匠精神是职业品质：专注、精益、严谨、卓越，指向产品与工作的极致。"}], "case": {"a": "骨架：总论点——工匠精神是时代品质的根基（由李斌个案引出）；分论点一——工匠精神意味着专注与坚守；分论点二——工匠精神意味着精益求精、不断突破；收束——各行各业都需要工匠精神来雕琢时代品质。", "q": "用四句话搭出本文的论证骨架：总论点一句、分论点两句、收束一句。", "title": "案例：搭评论的骨架"}, "intro": "第 5 课换文体了：从通讯到**新闻评论**，写的是数控专家李斌，谈的是「工匠精神」如何雕琢「时代品质」。==评论的读法是抓骨架：由头、论点、分论点、收束，各就各位。==", "learn": [{"h": "文体：新闻评论", "p": "评论是新闻的「议论」部分：针对新闻事实或社会现象发表意见、加以分析。本篇以李斌从普通工人成长为数控专家的事例为**由头**，议题却是全时代的职业精神。与通讯对照记：通讯重叙事与细节，评论重观点与论证；考试常把两者放在一起辨别文体。"}, {"h": "论点与分论点的拆分", "p": "总论点：要以工匠精神雕琢时代品质。论证时把「工匠精神」拆开：专注坚守、对技术精益求精、在平凡岗位上追求卓越——每一层都用李斌的事例或同类事例作支撑。==评论题的通用答法：先找总论点，再数分论点，最后看每条分论点用什么事实供血。=="}, {"h": "由个体到时代的升格", "p": "文章只写一个李斌不够，评论的落点是「时代品质」：制造业升级、各行各业转型都需要工匠精神。这种「小切口、大主题」的写法是高考作文与评论写作都能借用的结构：一个人是一扇窗，窗外是整个时代。"}], "pitfalls": ["把本篇当通讯读，只复述李斌的事迹，答不出论点结构。", "工匠精神内涵答偏：它是职业精神，不是鼓励加班。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 8, "t": "以工匠精神雕琢时代品质", "dur": "26:47", "from": "名师课堂", "vtop": ["工匠精神的内涵是四句话：炉火纯青的技术、专心如一的热爱、臻于至善的追求、不改初衷的境界——出自第四自然段，顺序别记乱。", "新闻评论由论点、论据、论证三要素组成，特点是政策性、针对性、准确性；主要表现方法是夹叙夹议、以理以情。", "四种论证方法要会认：引证法、对比论证、类比论证、假设论证——“倘若没有……怎能有……”就是假设论证。"], "vsum": "本课学第一单元第5课《以工匠精神雕琢时代品质》，是一篇新闻评论，作者李斌。开场先引习近平同志的话：要弘扬工匠精神，精心打磨每一个零部件，生产优质的产品。只有打造更多精品、塑造更多中国品牌，中国经济才能进入质量效益时代，中国制造业才能在做大做强中跻身世界前列。接着老师抛出三个问题：什么是工匠精神？自动化程度越来越高的现代社会，传统社会孕育的工匠精神还有没有坚守的必要？如果有，我们应该怎样践行？这三个问题关乎如何认识劳动的意义和价值，带着问题学完全文。\n\n先补知识点。**新闻评论**是媒体编辑部或作者对新近发生的有价值的新闻事件和有普遍意义的紧迫问题，运用分析和综合的方法，就事论理、就实论虚，有着鲜明针对性和指导性的一种新闻文体，是社论、评论、评论员文章、短评、编者按、专栏评论和评述等的总称，属于论说文的范畴。简单说，新闻评论就是对有价值的新闻事实和社会现象发表意见、以指导实践的文体。新闻评论由**论点、论据、论证**三个要素组成，特点是政策性、针对性、准确性；要求立意新颖，在有限的篇幅里靠独特的见解吸引读者；论述精当、文采斐然；主要面向广大群众。它的主要表现方法是**夹叙夹议**——对一件事发表看法，既要写事又要写看法；**以理以情**——在理性评判和分析时，又动之以情。写作的基本思路分四步：引述材料摆出现象，从现象中提取论述的观点，分析论证观点、联系实际、紧紧围绕论点运用各种论证方法论证，总结全文、提出倡议。\n\n再看写作背景。现代科技时代，工匠似乎已经远离我们，但实现中华民族伟大复兴的中国梦，不仅需要大批科学技术专家，同时也需要千千万万的能工巧匠。更重要的是，工匠精神作为一种优秀的职业道德文化，它的传承和发展契合了时代发展的需要，具有重要的时代价值与广泛的社会意义。2017年的政府工作报告提出，大力弘扬工匠精神，厚植工匠文化，恪尽职业操守，崇尚精益求精，完善激励机制，培育众多中国工匠，打造更多享誉世界的中国品牌，推动中国经济发展进入质量时代。我国是技能人才大国，也是制造业大国，制造业在国民经济中的地位和作用举足轻重，当前正处在从工业大国向工业强国迈进的关键时期，培育和弘扬严谨认真、精益求精、追求完美的工匠精神，对于建设制造强国具有重要意义。作者李斌，女，汉族，1954年10月出生，辽宁抚顺人，1981年6月入党，1974年7月参加工作，研究生学历，经济学博士，研究员。\n\n整体阅读先读一则材料：故宫“男神”王津。故宫博物院的钟表收藏居世界首位，现存1500多件钟表，除了产自本国，还有来自英国、法国、瑞士等国的珍品，不仅报时准确、造型精美，而且融绘画、雕塑、工艺、天文、音乐、机械、科技于一体，代表着18至20世纪初世界钟表制造精湛技艺的最高成就。钟表修复技术是故宫里唯一绵延下来、没有断层的**非物质文化遗产**，已传承了三百多年。王津是国家级非物质文化遗产“古钟表修复技艺”第三代传承人，41年待在一间仅60平方米的工作室里，日复一日、年复一年干同一件事。要真正喜爱才能耐得住寂寞，因为喜欢就能干一辈子。自央视纪录片《我在故宫修文物》热播后，镜头中工作专注、执着内敛、气质儒雅的王津被网友封为“故宫男神”，也让文物修复师这个冷门职业广为人知。宫廷钟表都是特制的，一般只生产一个或一对，大多是孤品，没有配件可换，修复必须遵循不改变文物原状的原则，技艺必须由师父手把手教徒弟、口传身授，再通过修复每一件文物钟表遇到的不同类型问题，不断学习和积累方法与经验，代代传承。一件待修的钟表运来，先拍照记录，制定修复方案，再拆解、清洗、补配、组装、调试，直至运转正常，最后进库保存。从1981年上手修复第一件钟算起，经王津修复成功的故宫钟表已超过200座，故宫钟表馆中陈列的120多件钟表中，约三分之一都是他修复的。而每让一只故宫古钟表转动，都要花费几个月甚至一年的功夫。与其他文物修缮不同，钟表修复的独特之处在于不仅要恢复走时功能，更重要的是恢复表演功能才叫修好了。令王津印象最深刻、修复得最满意的文物，是一件铜镀金魔术人钟，钟内部有超过一千个零部件、七套系统、五套机械联动，被故宫认为世界上最难修复的钟表之一，王津与团队耗时一年多集中修理，才最终将其表演功能重现于世，此钟后来远赴荷兰展出半年，让世界为之惊艳。读完材料再想：像王津师傅一样，工匠精神要有一流的技术，更要有一颗热爱的心、一种耐得住寂寞的境界。\n\n课文是怎样高屋建瓴地概括工匠精神内涵的呢？重点读第四自然段：**工匠精神**的内涵是**炉火纯青的技术**、**专心如一的热爱**、**臻于至善的追求**、**不改初衷的境界**。工匠精神蕴藏的既有格物致知、正心诚意的生命哲学，又有超然达观的人生信念。细读两句重要的话：第一句“将一门技术掌握到炉火纯青、绝技在身，但工匠精神的内涵远不限于此”——意思是工匠精神首先要掌握一门炉火纯青的技术，这已经不是一件容易的事，但是只有技术还不够，还要有技术之外的精神品质。第二句“我们不必人人成为工匠，却可以人人成为工匠精神的践行者”——意思是并非人人都能做到心思巧妙、技术精湛、造诣高深，但我们都应该追求并实践工匠精神，体现了作者对工匠精神的推崇和倡导。\n\n再读文本理清思路。中心话题是工匠精神的时代特征，开篇从时代特点和企业打造金字招牌的角度引出话题，紧扣时代品质，具有很强的现实性。文章分三部分：第一部分是第一自然段，提出工匠精神的话题；第二部分是第二至四自然段，论述工匠精神的内涵，其中第二自然段论述“匠”的时代内涵及工匠精神对个人、企业和国家的作用与意义；第三部分是第五自然段，从个人与时代的关系角度总结全文。\n\n论证方法有四种。一是**引证法**：文中多处引用，如引用企业家的话写出工匠精神在当代的意义，引用《说文解字》里对“匠”的记载写出“匠”古已有之、然后写出其演变，引用鲁迅的话在此基础上再深入论证，从不同角度分析论述，使文章更有说服力、观点更加深入人心。二是**对比论证**：如“工匠精神从来都不是什么雕虫小技，而是一种改变世界的现实力量”，边破边立，写出了工匠精神的作用。三是**类比论证**：如第一段“像手工匠人一样雕琢记忆、打造产品，企业才有金字招牌，产品才能经受住用户最挑剔眼光的检验”，将手工匠人和企业进行类比，写出了企业拥有工匠精神的重要性。四是**假设论证**：如第四段中“倘若没有发自肺腑、专心如一的热爱，怎能有废寝忘食、尽心竭力的付出；没有臻于至善、超今贯古的追求，怎能有出类拔萃、巧夺天工的卓越；没有冰心一片、不改初衷的境界，怎能有雷打不动、脚踏实地的笃行”，假设论证写出了工匠精神的内涵。\n\n语言特色是**整散结合**、生动形象、富有说服力。文章是时评，却没有枯燥说教的感觉，生动形象、绚丽多彩，主要是因为语言生动、整散结合。第一段用了“高精尖”等具有时代特点的新词，使人们容易接受和理解；第二段用“气质雍容、活力涌流”来写企业，使企业拥有了人的特点，生动地写出了拥有工匠精神对企业的意义；第三、四、五段运用排比句式，起到增强气势、调节音律的作用，增强了读者的阅读兴趣，使观点更加鲜明突出、更具有说服力。此外，本文运用大量成语，言简意赅，掷地有声。\n\n拓展延伸：类似王津师傅这样体现工匠精神的事例还有哪些？一是高凤林，为火箭焊接心脏的人。焊接技术千变万化，为火箭发动机焊接更不是一般人能胜任的。三十多年来，高凤林先后参与北斗导航、嫦娥探月、载人航天等国家重点工程，以及长征五号新一代运载火箭的研制工作，一次次攻克发动机喷管焊接技术世界级难关，出色完成亚洲最大的全箭振动试验塔的焊接攻关，修复苏制图-154飞机发动机，还被丁肇中教授钦点，成功解决反物质探测器项目难题。他吃饭时拿筷子、喝水时端着盛满水的杯子练稳定性，休息时举着铁块练耐力，冒着高温观察铁水的流动规律，为了保障一次大型科学实验的顺利完成，他的双手至今还留有被严重烫伤的疤痕；为了攻克国家某重点攻关项目，近半年的时间，他天天趴在冰冷的产品上，关节麻木了，他甚至被戏称为“和产品结婚的人”。二是顾秋亮，深海“蛟龙”守护者。“蛟龙”号载人潜水器是目前世界上潜水最深的载人潜水器，其研制难度不亚于航天工程，在这个高精尖的重大技术攻关中，有一个普通钳工技师的身影，他就是顾秋亮，中国船舶重工集团公司第七〇二研究所水下工程研究开发部职工，“蛟龙”号载人潜水器首席装配钳工技师。作为首席装配钳工技师，工作中面对技术难题是常有的事，而每次顾秋亮都能见招拆招，靠的就是工作40余年来养成的螺丝钉精神。他爱琢磨、善钻研，喜欢啃工作中的硬骨头，凡是交给他的活，他总是绞尽脑汁，想着如何改进安装方法和工具、提高安装精度、确保高质量地完成安装任务，正是凭着这股爱钻研的劲儿，顾秋亮练就了较强的创新和解决技术难题的技能，出色完成了各项高技术、高难度、高水平的工程安装调试任务。三是宁允展，高铁上的“中国精度”。宁允展是南车青岛四方机车车辆股份有限公司车辆钳工高级技师、高铁首席研磨师，国内第一位从事高铁转向架定位销研磨的工人，也是这道工序最高技能水平的代表，他研磨的定位销已经创造了连续十年无次品的纪录。转向架是高速动车组九大关键技术之一，转向架上有个定位销是关键中的关键，高速动车组在运行时速达200多公里的情况下，定位销和轮对节点必须有75%以上的接触面、间隙小于0.05毫米，否则会直接影响行车安全。宁允展的工作就是确保这个间隙小于0.05毫米，他的风动砂轮纯手工研磨操作法将研磨效率提高了一倍多，接触面的贴合率也从原来的75%提高到了90%以上，他发明的精加工表面缺陷焊修方法，修复精度最高可达到0.01毫米，相当于一根细头发丝的五分之一。他执着于创新研究，主持了多项课题攻关，发明了多种工装，其中有两项通过专利审查、获得了国家专利，每年为公司节约创效近三百万元。四是张东伟，80后造船工匠。张东伟是个80后，但手里的活儿却让老师傅们竖起大拇指。LNG船是国际上公认的高技术、高难度、高附加值的“三高”船舶，作为LNG船核心的维护系统，焊接是重中之重，维护系统使用的殷瓦钢大部分为0.7毫米厚，殷瓦钢焊接犹如在钢板上绣花，对操作人员的技术、耐心和责任心要求非常高。面对肩上的重担，张东伟不断磨练自己的心性、培养专注度、潜心研究焊接工艺，为了攻破技术难关，他与技术人员放弃休息时间、日夜埋头图纸堆中、潜心钻研技术，最终他主持的实验取得成功，得到专利方的认可并用于LNG船实船生产，收到良好成效。张东伟是中国广大造船工匠的杰出代表，他用自己火红的青春，谱写了一曲执着于国家海洋装备建设的奉献之歌。\n\n最后回到我们自己：我们也拥有火红的青春，应该如何践行工匠精神呢？首先要努力学习文化知识，知识是工匠精神的力量源泉，“问渠那得清如许，为有源头活水来”。其次要有严谨的态度，态度决定一切，在我们的学习和生活中起着举足轻重的作用，一个人只有用严谨的态度对待一切学习活动，才能以严格的标准要求自己、深刻地理解和牢固地掌握各类文化知识，才能认认真真、一丝不苟地做好日常生活中的每一件事，为成功打下基础。再次要学会持之以恒，“事业千古事，非一朝一夕之功”，学习或者工作，要像工匠求艺那样，一定要耐得住寂寞、稳得住心神、经得住诱惑，要有滚石上山的勇气和气魄，少一些急功近利，多一些真抓实干，一步一步推进，一点一点积累，实现量变到质变的跨越，那么即使铺满荆棘的道路也会变得平坦。\n\n总结全文：从本质上讲，工匠精神是一种职业精神，它是职业道德、职业能力、职业品质的体现，是从业者的一种职业价值取向和行为表现。在新的时代，弘扬和践行工匠精神，需深入把握其基本内涵、当代价值与培育途径。工匠精神是时代的呼唤，也是社会主义核心价值观题中应有之义，培育工匠精神、弘扬工匠精神，这绝不仅限于物质生产，还需要全社会各行各业驱除浮躁，培育和弘扬精益求精、一丝不苟、追求卓越、爱岗敬业的品格，从而提供高品质产品和高水准服务。课后作业有两个：一是结合本单元人物通讯篇目，基于其呈现的事实，任选一篇、自选角度进行评论，写一篇三百字左右的小评论；二是思考中学生如何践行工匠精神，将所思写成一篇五百字左右的作文。结尾寄语：同学们，我们已经踏上实现中华民族伟大复兴的征程，要让蓝图变现实、让梦想成真，需要一砖一瓦的接力，需要每时每刻的努力，无论在哪个岗位上，我们都要做一名专注的工匠，让我们只争朝夕、不负韶华，为梦想而战，让人生绽放光彩。", "vtech": [["新闻评论的定义一句话", "对有价值的新闻事实和社会现象发表意见、以指导实践的论说文；看到“就事论理、就实论虚”就想到新闻评论，别和一般议论文搞混。"], ["工匠精神内涵四句话按顺序记", "炉火纯青的技术→专心如一的热爱→臻于至善的追求→不改初衷的境界；技术、热爱、追求、境界层层递进，第四自然段原话。"], ["四种论证方法看标志词", "引证法看引用（企业家的话、《说文解字》、鲁迅的话）；对比论证看“不是……而是……”；类比论证看“像……一样”；假设论证看“倘若没有……怎能有……”。"], ["写作思路四步", "引述材料摆现象→从现象中提取观点→分析论证联系实际→总结全文提出倡议；问“本文写作思路”就按这四步答。"]], "vgaokao": []}}, "chn_c009": {"name": "芣苢·插秧歌", "sec": 3, "secTitle": "第6课 诗经两首", "page": 53, "desc": "《诗经》的重章叠句与杨万里的农事即景：劳动之歌的两种唱法。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《芣苢》最突出的手法是什么？", "answer": "重章叠句：只更换少数动词，反复咏唱采摘芣苢的过程，写出劳动的欢乐。"}, "pre": ["chn_c001"], "next": ["chn_c010", "chn_c031"], "content": {"advance": {"a": "《芣苢》：情感由内容转向形式，劳动之乐藏在吟唱的节奏与动作的推进里，淡中见趣。《插秧歌》：情感直接发自劳动场面本身，乐在分工协作与丰收盼望，画面活泼明快。前者更含蓄，后者更直露；但都把劳动写成歌，而不是苦役。", "kind": "self", "q": "两首诗都写劳动之乐，抒情方式有何不同？"}, "apply": [{"ans": 1, "opts": ["写芣苢长势茂盛", "写采摘过程的推进与劳动场合的欢快气氛", "哀叹生活艰难", "表现妇女的悲苦"], "q": "「采之、有之、掇之、捋之、袺之、襭之」一连串动词变化的作用是（ ）", "why": "动词链就是动作链：采、收、拾、捋、掖起、兜满，劳动的进程与欢愉全在其中。"}, {"ans": 1, "opts": ["先苦后甜的叙事结构", "以劳动场景为画面、用人物动作与口吻立画面，寓生活情趣于农事即景", "用了大量典故", "语言晦涩难懂"], "q": "《插秧歌》写农事的生动之处在于（ ）", "why": "杨万里的「诚斋体」以活脱生动见长，本首以画面与动作取胜，用典晦涩都是错项。"}], "basics": [{"ans": 1, "opts": ["国风·卫风", "国风·周南", "小雅", "大雅"], "q": "《芣苢》选自《诗经》的（ ）", "why": "教材选本标注：《芣苢》为《诗经·周南》篇目，与同单元《插秧歌》并读。"}, {"ans": 0, "opts": ["重章叠句", "用典", "夸张", "象征"], "q": "《芣苢》在形式上最突出的特点是（ ）", "why": "全诗三章只换几个动词反复咏唱，是《诗经》重章叠句的典型样本。"}], "case": {"a": "动词链：采（开始采集）→有（采有所得）→掇（拾取）→捋（成把捋取）→袺（提起衣襟兜着）→襭（把衣襟掖在腰间盛放）。推进感正是从动作的由少到多、由手到衣里长出来的，欢快藏在忙碌里。", "q": "按顺序写出《芣苢》六个变化的动词，并用一句话说明它们如何写出劳动的推进感。", "title": "案例：动词推进图"}, "intro": "第 6 课两首劳动诗：《诗经》的**《芣苢》**采野菜，杨万里的**《插秧歌》**插秧。==隔着一千多年，劳动的欢乐是同一种唱法：节奏。==", "learn": [{"h": "芣苢：重章叠句的标本", "p": "《诗经·周南》篇目。芣苢就是车前草。全诗三章十二句，除了六个动词，几乎字字相同：采之、有之、掇之、捋之、袺之、襭之。==这就是《诗经》最典型的**重章叠句**：靠词语的微变推进内容，靠复沓的节奏传达情绪。==六个动词其实写尽了采摘的全程——从伸手去采到满载而归，劳动的欢快不靠形容词，全在动作里。"}, {"h": "插秧歌：诚斋体的活画", "p": "南宋杨万里的田园诗，写一家人在水田里抛秧插秧：田夫抛秧、农妇插秧、孩童学样，还有「笠是兜鍪蓑是甲，雨从头上湿到胛」的诙谐比喻。杨万里诗风活泼生动（诚斋体），本诗把农事写成全家总动员的欢快场面，结尾「莫管」式的展望又透出对收成的期盼。"}, {"h": "单元位置：劳动主题的收束", "p": "第二单元以「劳动光荣」为主题：通讯写劳动模范、评论谈工匠精神、诗歌唱劳动之乐。两首诗证明，劳动入诗的历史和《诗经》一样久。考试中若出现单元综合题，记住这个三段结构：写人—说理—咏唱。"}], "pitfalls": ["「芣苢」读音与释义：读 fúyǐ，是车前草，不要望文生义。", "只答「重章叠句」四个字，不写出六个动词的变化（光有术语没有证据是答题大忌）。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 9, "t": "诗经两首（芣苢/插秧歌）", "dur": "26:15", "from": "名师课堂", "vtop": ["《芣苢》六个动词分三组：采、有是概略叙述；掇、捋是具体描写（一颗颗、一把把）；袺、襭是用衣襟兜取——动词变化写出芣苢越采越多，劳动过程层层推进。", "《芣苢》重章叠句：三章十二句，除六个动词外其余诗句不断重复，产生简单明快、往复回环的音乐节奏，契合采摘劳动轻快的动作节拍。", "《插秧歌》“唤”与“不答”：有人唤农人吃早饭歇一歇，农人低头折腰只不答——看似答非所问，实则传神：秧根未牢、田未插完，庄稼才是农家人的命根；鉴赏要捕捉这种刹那间的意趣之美。"], "vsum": "本课是必修上册第二单元第6课，讲两首写古代劳动的诗：《诗经》里的《芣苢》和南宋杨万里的《插秧歌》。单元主题是劳动，前面几课讲的是新时代的劳动者和工匠精神，这节课走进古代人民的劳动场景，感受劳动的美好与欢乐，体会劳动的崇高与美丽。\n\n先回顾《诗经》的文学常识：《诗经》是我国第一部诗歌总集，共收录从西周初年到春秋中叶的诗歌305篇，先秦时称《诗》或《诗三百》，汉代被尊为经典，称《诗经》并沿用至今。形式上以四言为主，多数隔句用韵，章法上讲究重章叠句、反复咏唱。内容上分风、雅、颂三部分：风是各诸侯国的土风歌谣，大多是民歌，又分十五国风；雅是西周王畿地区的正声雅乐，分小雅（用于贵族宴享）和大雅（用于诸侯朝会）；颂是统治阶级宗庙祭祀的舞曲歌词，分周颂、鲁颂、商颂。艺术手法主要是赋、比、兴：赋是直接铺陈叙述，比是比喻，兴是先言他物以引出所咏之物。\n\n第一首是《芣苢》，出自《诗经·周南》。《芣苢》就是车前草。全诗三章十二句：“采采芣苢，薄言采之。采采芣苢，薄言有之……”先跟老师准确诵读全诗，把握节奏。注释要记牢：“薄言”是发语词，没有实在意义；“采”就是采摘，“有”是取得、获得，“掇”是一颗颗地摘取，“捋”是从茎上成把地取下，“袺”是提起衣襟兜东西，“襭”是把衣襟掖在腰带上兜东西。六个动词可以分三组：采、有是概略叙述采集劳动；掇、捋是对摘取动作的具体描写，一颗颗、一把把，写得真切生动；袺、襭是对用衣襟兜取的描写。动词的变化写出了劳动的实际操作过程，芣苢越采越多，把劳动细节细腻地描绘出来，展现了一幅三五成群的田家妇女在平原旷野、风和日丽中边唱边采的集体劳动场景。\n\n清代姚际恒在《诗经通论》里说，《芣苢》三章，每章四句，每二句只换一字——全诗只有六个动词不断变化，其余诗句不断重复。这种重章叠句的写法在不断重叠中产生了简单明快、往复回环的音乐节奏，正好契合采摘芣苢劳动的轻快动作节拍，表现出歌声中的喜悦之情。文化知识补充：采集芣苢是古老的习俗，按《毛传》的说法，芣苢就是车前草，相传吃了芣苢能受胎生子、解难产，所以周南女子怀着繁衍种族、祈求神灵赐福的愿望，三五成群愉快地劳作——她们摘着芣苢、唱着芣苢，心里荡漾着虔诚与激情。这首产生于自然与生命的乐章，是有着浓厚生活气息的劳动之歌。\n\n第二首是南宋杨万里的《插秧歌》。先认识诗人：杨万里，字廷秀，号诚斋，吉州吉水人，与陆游、尤袤、范成大并称“中兴四大家”，诗作达4200余首，在宋代仅次于陆游。他善于巧妙摄取自然景物的特征和动态，语言平易浅近、自然活泼，善于熔炼俗语、口语入诗，幽默诙谐，形成独具特色的诚斋体。这首《插秧歌》作于淳熙六年（1179年），杨万里由常州卸任返回吉州故里，途经衢州时看到农人插秧的场景，有感而作。\n\n全诗八句：“田夫抛秧田妇接，小儿拔秧大儿插。笠是兜鍪蓑是甲，雨从头上湿到甲。唤取朝餐歇半霎，低头折腰只不答。秧根未牢莳未匝，照管鹅儿与除鸭。”注释记牢：“抛秧”是插秧前把秧苗从秧田拔出、捆成小捆扔进稻田；“兜鍪”是古代战士戴的头盔；“甲”是铠甲；“半霎”是极短的时间；“莳”是移栽种植；“匝”是布满、遍及；“照管”在这里是提防的意思。\n\n逐句赏析：一二句“田夫抛秧田妇接，小儿拔秧大儿插”，从田夫、田妇、小儿、大儿可知插秧是全家总动员，“抛、接、拔、插”四个动词把全家的劳作真切地表现出来，大家各有分工、相互配合、井然有序，一气呵成，渲染出一家人齐心协力、其乐融融的劳动氛围。三四句“笠是兜鍪蓑是甲，雨从头上湿到甲”，把农人的斗笠比作头盔、蓑衣比作铠甲，写出农人如兵士一般在农田中冒雨插秧，有如在天地之中奋勇战斗，说明插秧时节性强，即便下雨农人也不停止劳作；接着笔锋一转，农人虽然带盔披甲，却还是被雨水淋得从头湿到甲，一句通俗浅白，农人的艰辛跃然纸上。五六句“唤取朝餐歇半霎，低头折腰只不答”，有人招呼农人吃早饭、歇一歇，可农人仍然弯腰干活，没有回答；七八句“秧根未牢莳未匝，照管鹅儿与除鸭”给出答案：秧苗刚种下去还不牢，这块田还没插完秧，还要看管好饲养的鹅和鸭，提防它们来捣乱。最后两句看似答非所问，实则传神地反映了农事生产的劳身和劳心。诗人用“唤”和“不答”描写农家夫妇的对话和对话时的情态，为我们开辟了一条鉴赏文学作品的路径：捕捉刹那间的意趣之美——“唤”与“不答”之间存在逻辑上的悖论，在文学审美上却是美的；吃饭不重要，庄稼才是农家人的命根，这种认知是我们民族所共有的。\n\n两首诗还要放在一起比较。先比较唐代李绅的《悯农》和杨万里的《插秧歌》：同样写古代农人的劳动生活，侧重点不同——李绅“锄禾日当午，汗滴禾下土”，描绘劳动的辛苦，对劳动人民充满同情；杨万里侧重表现劳动人民的紧张繁忙、齐心协力、勤劳，抱着欣赏的态度客观表现劳动场面，流露出诗人对劳动和劳动者的赞美。再比较《芣苢》和《插秧歌》本身：都是描写古代劳动场景、关注普通劳动者，但表现形式和描写角度不同——《芣苢》句式整齐、节奏明朗轻快，以一系列动词的变换和重章叠句的写法，自然流露出劳动的喜悦；《插秧歌》运用民歌手法，选取日常劳动场景，善用口语，显白流畅，富于生活情趣，字里行间洋溢着吃苦耐劳、勤奋乐观的精神。劳动者特写也不同：《芣苢》塑造的是先秦时期采摘芣苢的劳动妇女，特写采集、收取、收成的动作，描绘三五成群妇女集体劳动的场景，表现出劳动者喜悦的心情；《插秧歌》塑造的是南宋时期参加插秧的一家四口，特写抛、接、拔、插的具体动作，描绘呼唤农人吃早饭的插曲，传神地表现农事生产的劳身和劳心，表现农人吃苦耐劳、勤劳乐观的优秀品质。\n\n课堂反馈三道题：第一题考《芣苢》的赏析，不恰当的一项是B项——“采采”的叠唱有着采集野菜的急促感，这种表述不正确，应该是音乐美感；重章叠句产生的是简单明快、往复回环的音乐节奏，切合采摘劳动轻快的动作节拍。第二题考《插秧歌》的逐句评析：一二句写热火朝天的劳动场面，抛、接、拔、插四个动词准确具体，又暗示分工明确；三四句点明雨中抢插的情形，以盔甲防护之人，雨水仍然从头上流入、沾湿肩膀，领会春雨之密、之急、之大；五六句写劳作的忘我程度，家人送饭让歇一会儿却无人答话，连抬头看一眼的功夫也没有，写出抢插的紧张程度；七八句运用口语化的语言，随意写取天赋的肢体动作和对答语言，写出全家其乐融融的画面，使读者有身临其境之感。第三题考《诗经·秦风·无衣》中重章叠句的表达效果：全诗三章，采用重章叠唱的形式，每章句数、字数相等，但结构的相同并不意味着简单的机械重复，而是在不断递进中有所发展——每章首二句以豪迈的语气表现奋起从军、慷慨相助的精神，“同袍、同泽、同裳”深重地表现出大敌当前战友们克服困难、团结互助的精神；每章的三四句写他们一听到君王要发兵的命令，便急忙修整武器、磨砺兵刃、整装待发，“修我戈矛、修我矛戟、修我甲兵”正反映出摩拳擦掌、积极奋战的高昂战斗热情；每章的末句“同仇、偕作、偕行”写共同的仇恨与共同奋起奔赴战场，表现出团结一心、同仇敌忾、誓死保卫疆土的义愤。这种重章叠句的形式与舞蹈的节奏起落、回环往复紧密结合，构成诗中主旋律的是一股战斗的激情，激情的起伏跌宕自然形成乐曲的节奏与舞蹈动作。\n\n课后作业：阅读北宋苏辙的《文氏外孙入村收麦》，选择恰当的角度，比较《芣苢》《插秧歌》《文氏外孙入村收麦》三首诗的异同。本课学习的古诗都是描写劳动的，从中可以感受到劳动的欢乐与情趣，要自觉地在实践中感悟劳动之美，自觉继承和发扬中华民族尊重劳动、热爱劳动的美德。", "vtech": [["《芣苢》六个动词分三组", "采、有是概略叙述采集劳动；掇、捋是对摘取动作的具体描写（一颗颗、一把把）；袺、襭是对用衣襟兜取的描写；动词变化体现劳动实际操作过程，芣苢越采越多。"], ["重章叠句的表达效果", "三章十二句，除动词外其余诗句不断重复，在重叠中产生简单明快、往复回环的音乐节奏，契合劳动轻快的动作节拍；《秦风·无衣》同理，三章递进：首二句同袍/同泽/同裳写团结互助，三四句修我戈矛/矛戟/甲兵写整装待发，末句同仇/偕作/偕行写同仇敌忾。"], ["《插秧歌》的动词与比喻", "抛、接、拔、插四个动词写全家总动员、各有分工；笠是兜鍪、蓑是甲，把农人穿戴比作兵士的头盔铠甲，写出雨中抢插的紧张与奋勇；雨从头上湿到甲，通俗浅白，农人的艰辛跃然纸上。"], ["两首诗对比：同情与赞美", "李绅《悯农》锄禾日当午、汗滴禾下土，侧重写劳动的辛苦，对劳动者充满同情；杨万里《插秧歌》侧重写劳动的紧张繁忙、齐心协力，抱欣赏态度，赞美劳动和劳动者；《芣苢》句式整齐、重章叠句显音乐美，《插秧歌》善用口语、民歌手法显自然新鲜的意趣。"]], "vgaokao": []}}, "chn_c010": {"name": "短歌行", "sec": 1, "secTitle": "第7课", "page": 58, "desc": "曹操求贤若渴：比兴、用典与「忧」的三重层次，默写高频篇。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《短歌行》中借《诗经》句子表达求贤之心的两句。", "answer": "青青子衿，悠悠我心（「衿」读 jīn，不要写成「子今」）"}, "pre": ["chn_c009"], "next": ["chn_c011"], "content": {"advance": {"a": "「山不厌高，海不厌深」写君主胸怀：山海不嫌弃高深，招纳贤才也不嫌多；下接「周公吐哺，天下归心」，以周公礼贤下士自比，表明自己愿以这样的胸怀待贤才，天下贤士自会归心。两组句子一喻一典，落点都是求贤。", "kind": "self", "q": "赏析结尾「山不厌高，海不厌深。周公吐哺，天下归心」的表达效果。"}, "apply": [{"ans": 2, "opts": ["只有功名未就一层", "只有人生短暂一层", "三层：人生短促之忧、贤才难得之忧、功业未就之忧", "主要是思乡之忧"], "q": "诗人所「忧」包含几层，概括全面的是（ ）", "why": "三层递进是本诗赏析的骨架，答少任何一层都会丢分。"}, {"ans": 1, "opts": ["写景句，与主题无关", "以月之永恒反衬人生短暂，并以月悬难拾起兴，转入贤才难求之忧", "夸赞月色优美", "抱怨月光刺眼"], "q": "「明明如月，何时可掇？忧从中来，不可断绝」的作用是（ ）", "why": "关键句要答双层：反衬＋过渡，起兴转入下一层忧。"}], "basics": [{"ans": 1, "opts": ["对饮酒的厌恶", "人生短暂，时光易逝", "劝人不要饮酒", "酒逢知己的快乐"], "q": "「对酒当歌，人生几何！譬如朝露，去日苦多」表达的情感是（ ）", "why": "开篇即点出第一层忧：人生如朝露，短暂易逝。"}, {"ans": 0, "opts": ["《诗经·郑风·子衿》", "《楚辞·离骚》", "《诗经·小雅·鹿鸣》", "汉乐府《长歌行》"], "q": "「青青子衿，悠悠我心」出自（ ）", "why": "子衿出自《诗经·郑风·子衿》；呦呦鹿鸣才出自《小雅·鹿鸣》，两处用典不要记反。"}], "case": {"a": "出处：《诗经·小雅·鹿鸣》，原诗写宴宾之乐。作用：曹操借古人宴乐待宾之典，委婉表达自己对贤才的热切期待与礼遇之心，化用典故使求贤之意典雅而含蓄。", "q": "「呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙」出自《诗经》，曹操引用它表达了什么意思？", "title": "案例：用典溯源"}, "intro": "《短歌行》是**曹操**求贤若渴的自白。==全诗的「忧」有三层：忧人生短促、忧贤才难得、忧功业未就——三层递进，是本课的骨架。==再加上密集的**用典**，这首诗几乎每四句一个考点。", "learn": [{"h": "第一层忧：时光", "p": "开篇「对酒当歌，人生几何！譬如朝露，去日苦多」，以**朝露**为喻写人生短促；「何以解忧？唯有杜康」是表层答案，真正的解法在下文。赏析提示：曹操的忧不是消沉，而是因时光紧迫而生出的功业焦虑，这与一般及时行乐的饮酒诗根本不同。"}, {"h": "第二层忧：贤才", "p": "「青青子衿，悠悠我心」化用《诗经·郑风·子衿》，原是写女子思慕情人，曹操借来写自己思慕贤才；「呦呦鹿鸣，食野之苹」引《小雅·鹿鸣》写宴宾，以示礼贤。「明明如月，何时可掇」把贤才比作明月，可望而难即。==用典题的答法：出处＋原意＋此处的新意，三句缺一不可。=="}, {"h": "第三层与收束", "p": "「月明星稀，乌鹊南飞。绕树三匝，何枝可依」以乌鹊择枝喻贤士择主——贤才在观望，诗人更急。结尾「山不厌高，海不厌深。周公吐哺，天下归心」以周公自比，亮明胸怀：我能礼贤，天下自归。情感由忧转为自信，是全诗的落点。"}], "pitfalls": ["用典出处记反：子衿出自《郑风·子衿》，鹿鸣出自《小雅·鹿鸣》。", "默写错字：「何时可掇」的「掇」误作「辍」；「契阔谈讌」的「讌」是「宴」的异体字。", "把全诗情感笼统答成「忧愁」，丢了三层结构与结尾的自信。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 11, "t": "短歌行·归园田居", "dur": "25:48", "from": "名师课堂", "vtop": ["诗眼是“忧”，曹操三忧：人生短暂、求贤不得、功业未就——三者相连：有建功立业、一统天下的壮志，才会感到人生短暂，更要抓紧时间延揽天下人才。", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“纵我不往，子宁不嗣音”的省略是含蓄提醒：就算我没去找你们，你们为什么不主动来投奔我呢？", "“周公吐哺，天下归心”：周公洗头、吃饭时贤士来见，握着湿发、吐出口中食物就出来见客——诗人以周公自比，表明像周公一样热切殷勤待贤才、渴望求贤以统一天下。"], "vsum": "本课是必修上册第三单元“生命的诗意”第7课。先说明一点：这个视频只讲《短歌行》一首，同课的陶渊明《归园田居》不在这个视频里，它在合集的下一页 P12，学完这首再去看 P12，不要以为这一课就讲完了。\n\n学诗先讲方法：赏析诗词有一个非常重要的解读方法，叫**知人论世**，最早由孟子提出——“颂其诗，读其书，不知其人，可乎？是以论其世也”。意思是只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容。这节课就用这个方法走进作者、解读全诗。\n\n先认识作者。曹操，字孟德，是三国时期杰出的政治家、军事家、文学家。陈寿在《三国志》里评价他是“**非常之人，超世之杰**”。作为政治家，他外定武功、内兴文学，知人善察、**唯才是举**；作为军事家，他指挥了**官渡之战**，逐步统一了中国北方；作为文学家，他是**建安文学**的开创者和组织者。他的诗歌语言质朴、感情深沉、格调苍凉悲壮，被誉为**建安风骨**（也称魏晋风骨）：建安时期的作品真实反映了现实的动乱和人民的苦难，抒发了建功立业的理想和积极进取的精神，同时流露出人生短暂、壮志难酬的悲凉忧怨，意境宏大，具有鲜明的时代特征和个性特征。他用**乐府古题**写实事，继承了汉乐府“感于哀乐，缘事而发”的现实主义精神。乐府诗有长歌和短歌之分，叶嘉莹教授认为一般根据歌声的长短而定：长歌比较热烈奔放，短歌节奏短促、低回短唱，适合抒发内心的忧愁和苦闷——这首诗作者是否也要抒发内心的忧愁和苦闷呢？带着这个问题往下学。\n\n写作背景有不同的说法，不可轻信其一。《三国演义》第48回写曹操平定北方后率百万雄师与孙权决战，月明之夜在大江之上置酒宴月，酒酣时取槊立于船头慷慨而歌，歌词就是这首《短歌行》；苏轼的《前赤壁赋》也说此诗作于赤壁大战前夕（“方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗”）。但这些都是小说家言和文学家的想象推测，缺乏可信的史料依据，还不能作出准确的结论。毫无疑问的是，曹操把他英雄的气质、诗人的才情和霸主的野心都集中表现在了这首诗中。\n\n全诗可分为**八章，每章四句**。先找**诗眼**：哪个字最能体现全诗的感情？是“**忧**”。“诗言志，歌永言”——曹操为何而忧，又是如何抒发这种情感的呢？\n\n第一二章：对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧？唯有杜康。“对”和“当”都是面对的意思，对酒当歌就是面对着酒与歌，即饮酒听歌。面前有酒有歌，作者情绪激动起来，就会想到这对酒当歌的美好快乐日子能有多少，眼前的快乐更反衬出人生无常的哀叹，于是发出“人生几何”的感叹——让人想起《左传·襄公八年》的“**俟河之清，人寿几何**”：黄河水清象征天下太平，可人寿有限，哪等得到那一天？开头两句就表现了诗人对于生命短促和人生无常的哀叹。“譬如朝露，去日苦多”用**比喻**：人生就像早晨的露水，太阳一出就晒干了。汉乐府《薤露歌》说“薤上露，何易晞。露晞明朝更复落，人死一去何时归”——草叶上的露水干了，明天早晨还会落上新的露水，而人死了以后就再也不会回来了。“朝露”这个意象在古诗文中有特定的含义，就是生命短促。“慨当以慷”：慷慨是形容感情激动的样子，“当以”没有实在意义。接下来的“唯有杜康”：杜康相传是最早造酒的人，这里用**借代**的修辞手法，以杜康代酒。借代能使表达形象生动、重点突出、简洁精炼。中国文人历来与酒有着不解之缘：范仲淹“浊酒一杯家万里”表达思乡之情，王维“劝君更尽一杯酒，西出阳关无故人”表达送别之情，杜甫晚年穷困潦倒却还感叹“艰难苦恨繁霜鬓，潦倒新停浊酒杯”，李白“五花马，千金裘，呼儿将出换美酒，与尔同销万古愁”“抽刀断水水更流，举杯消愁愁更愁”——借杯中酒浇胸中块垒，一直是中国知识分子的精神寄托方式。\n\n第一二章乍读起来似乎情调消沉，其实不然。诗人生逢乱世，目睹百姓颠沛流离，渴望建功立业而未得，不能不产生苦闷和感慨；但这种苦闷和感慨，只有对事业和感情执着的人、只有不满现实而又积极要求改变现实的人才可能产生。所以诗人的苦闷和感慨正是英雄人物的苦闷和感慨，是烈士的一种悲心，自有它的积极意义——全诗蕴含着应及时努力的思想。诗人一方面抒发个人之情，感叹时间过得太快、恐怕来不及有所作为，另一方面也是在巧妙地感染广大贤才：人生就像朝露那样容易消失，岁月已经流逝了很多，应该赶快拿定主意，到他那里施展抱负。这样积极的目的用低沉的调子来发端，固然表明诗人确有他的愁思，说得真切；但也唯有通过这样的调子，才更能打开处于下层、多方艰难、又急于寻找出路的贤才的心扉。\n\n第三四章：青青子衿，悠悠我心。但为君故，沉吟至今。“青青子衿，悠悠我心”语出《诗经·郑风·子衿》，原写姑娘思念情人，这里用来比喻渴望得到贤才。“子”是对对方的尊称，“青衿”指周代读书人青色交领的服装，“悠悠”是长远的样子，形容思虑连绵不断。诗人这里引用《诗经》中的诗句，还说自己一直低低地吟诵它，实在太巧妙了。但更重要的是他所省略的原诗中的两句——“**纵我不往，子宁不嗣音**”：虽然我不能去找你，你为什么不主动给我音信？诗人由于事实上不可能一个一个去找那些贤才，所以用这种含蓄的方法提醒他们：就算我没去找你们，你们为什么不主动来投奔我呢？由这层含而不露的意思可以看出，他求才的用心十分真诚，的确具有感人的力量。“但为君故，沉吟至今”：这里指思念和倾慕贤人。“君”在《诗经》中可能指一个具体的人，而在这里则具有了广泛的意义——在当时凡是读到曹操此诗的贤士，都可以自认为就是曹操渴求的对象，正因为这样，此诗流传开去才会起到巨大的社会作用。紧接着，作者又引用了《诗经·小雅·鹿鸣》中的四句——“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”，描写宾主欢宴的情景：鹿鸣本是周代朝廷宴请宾客的诗，鹿喜欢群居，每当找到了艾蒿，便悠悠地呼唤着同伴相聚而食；这里用来表达招纳贤才的热情，意思是只要你们到我这里来，我一定会待以嘉宾之礼，我们能够欢快融洽地相处并合作。三四两章从表面看，曹操自己的话只有“但为君故，沉吟至今”两句，但他通过用典婉转而清晰地吐露了自己的情意：第三章写他求贤而不得的日夜思慕，第四章写他求贤既得后设宴欢迎的情景，两相对照，表达了**求贤若渴**之情。加上青青之色、悠悠之声，诗中有声有色，顿觉词彩鲜艳、音韵悠扬。\n\n第五六章：明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈讌，心念旧恩。“明明如月，何时可掇”有两种理解：一种把“掇”当作拾取、摘取的意思——诗人奇想天外，明朗的月亮什么时候才能把它摘到手呢？后来李白“欲上青天揽明月”的诗句应由此脱胎；这两句写得非常精彩，除了显示诗人不失赤子之心、想上九天揽月之外，还运用了比喻的修辞手法，将人才比作月亮，把寻求贤士生动地比作无法揽取的明月，是那样的渴望而不可及。另一种解释把“掇”当作同“辍”、停止的意思——皓月当空运转永不停止，而我的求贤之心也不会停止。两种解释都合理，无论是“掇”还是“辍”，这四句都道出了作者深深的忧虑：忧贤才不得。“越陌度阡”：陌、阡都是田间小路，南北叫阡、东西叫陌，这里引用《风俗通》里的古谚；“枉用相存”：枉是屈驾的意思，用是以，相存是问候、探望，合起来是屈驾来访；“契阔谈讌”：契阔是久别重逢，谈讌是谈心宴饮，合起来是久别重逢、欢聚畅谈；“心念旧恩”指往日的情意。当贤才们跨越乡间的小路、长途跋涉，一个个屈尊前来探望作者时，彼此就像久别重逢的好友，谈心宴饮、诉说往日的情谊，诗人又因贤才远道而来归附自己而喜不自胜。五六两章一忧一喜，忽忧忽喜的矛盾心理把求贤过程中的悲喜情状曲折有致地表现出来，充分表现了诗人思贤若渴的主题。五六两章也是对前四章的强调和照应：前四章主要讲了两个意思——忧人生短暂、为求贤而愁，又表示要待贤以礼，这是全诗的两个主旋律；五六两章就是这两个主旋律的复线和变奏，“明明如月，何时可掇，忧从中来，不可断绝”是照应第一二章，“越陌度阡，枉用相存，契阔谈讌，心念旧恩”是照应第三四章。表面看来五六两章与前四章重复，但实际上由于主旋律的复现和变奏，使全诗更有一扬一抑、反复咏叹之致，加强了抒情的意味。\n\n第七八章是全诗的关键，也是艺术感染力最强的地方。先看第七章：月明星稀，乌鹊南飞。绕树三匝，何枝可依？明月皎洁、夜星稀疏，乌鹊向南飞去，围着树木绕来绕去，不知哪个枝干可以依附。这可能就是写眼前的实景。中国古人常说“**良禽择木而栖，良臣择主而事**”：一只好的鸟不会随便栖落在一个污秽肮脏的地方，它一定会选择一棵好的树作为栖息之所；传说中的凤凰更是非梧桐不栖。在这里，作者运用比喻的手法，用乌鹊比喻贤才，用“绕树三匝，何枝可依”比喻贤士们在三国鼎立的局面下无所侍从的情形。诗人启发他们不要三心二意，要善于择木而栖，赶紧到自己这一边来。这四句生动地刻画了那些犹豫彷徨者的处境与心情，然而诗人不仅丝毫没有指责，反而在浓郁的诗意中透露出对这些人的关心和同情。同时，由于汉末大乱、北方人口大量迁移，这首诗除了可能含有诗人在另一首乐府诗《蒿里行》中所表现的征故怀乡之感，也可能含有慨叹人民流离失所的情感。我们不仅能感受到诗人渴求贤才的心情，而且还能够从中感觉到当时社会的氛围。再看结尾：山不厌高，海不厌深。周公吐哺，天下归心。“山不厌高，海不厌深”仿用《管子·形势解》里的话——“海不辞水，故能成其大；山不辞土，故能成其高；明主不厌人，故能成其众”：海从来不拒绝水，所有的水都流到海里，所以海才会这么大；山从来不拒绝土石，所有的土石都可以落在山上，所以山才会那么高；明主从不拒绝归附他的人，所有的人都来投奔他，所以他才拥有很大的力量。诗人用这两句比喻贤才多多益善。下面“周公吐哺”又是一个典故：周公是周武王的弟弟、周成王的叔叔，武王死后成王年幼，周公辅政，平息了武庚的叛乱，并且制作礼乐，使天下大治，被后代称为圣贤的典范；周公的儿子伯禽受封于鲁，周公说他在辅政的时候从来不敢怠慢前来求见的贤士，如果在洗头发的时候有人来见他，他来不及把头发梳好，握着湿头发就出来见客，如果在吃饭的时候有人来见他，他来不及嚼完口中的食物，就把食物吐出来、出去见客，就这样他还唯恐疏漏了国中的贤人。这里借用这个典故表示自己会像周公一样热切殷勤地接待贤才，突出地表现了诗人求贤的心愿。最后四句画龙点睛，明明白白地披肝沥胆，希望人才都来归顺，点明此诗的主题；同时作者以周公自比，表明自己渴望求贤以统一天下的宏图大志。曹操的这种宏图大志值得充分肯定：三国时期军阀割据、战祸连年，生产力遭到了极大的破坏，人民饱尝流离的痛苦、面临死亡的威胁，中原地区尤为严重，曹操的《蒿里行》对此有过真实的写照——“白骨露于野，千里无鸡鸣。生民百遗一，念之断人肠。”那时人心思定，要求尽快结束纷争的局面，是大势所趋、势在必行，曹操正是顺应时代的潮流，肩负起完成统一大业的英雄。\n\n学完这首诗，总结一下：曹操为何而忧？他所忧的是**人生短暂、求贤不得、功业未就**。这三者之间有何内在的联系呢？正因为诗人有建功立业、一统天下的壮志，所以才会想到人生短暂，更应当抓紧时间延揽天下人才，及早尽快建功立业。这首诗的艺术特色主要有两点：一是**运用典故**、合理引用和化用，例如“青青子衿，悠悠我心”是引用《诗经》的诗句，将女子对情人的相思之情变成了诗人对贤才的思慕；“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”也是引用《诗经》的诗句，意在表达诗人期待贤者的热忱；再如“周公吐哺，天下归心”，化用《史记·鲁周公世家》中周公的事迹，诗人以周公自比，表达求贤建业的雄心。用典的好处在于能用极精简的语言表达丰富的思想，可以丰富诗歌的内容、强化诗歌的内涵。二是**妙用比喻**：用朝露比喻人生的短暂，用“明明如月，何时可掇”将贤才比作高空的明月、渴望而不可及，又用“月明星稀，乌鹊南飞。绕树三匝，何枝可依”中乌鸦难以择枝的情景比喻贤才无所依托，还用“山不厌高，海不厌深”比喻贤才越多越好。最后是反馈与评价三道题：第一题，“青青子衿，悠悠我心”表达了作者对贤才的思慕；第二题，“山不厌高，海不厌深”表现了作者渴望多招纳贤才；第三题，课堂讨论清人吴淇“纯是一片求才意思”的评价——你同意“求才”一说吗？老师认为可以同意：这首诗是曹操诗歌中具有代表性的杰出之作，全诗通过对时光易逝、贤才难得的再三咏叹，抒发了自己求贤若渴的感情，表现出统一天下的雄心壮志和自强不息的进取精神。", "vtech": [["知人论世：读诗先读人", "孟子提出的方法：颂其诗、读其书，不知其人可乎？是以论其世也——只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容；本课就用这个方法走进曹操、解读全诗。"], ["用典：化用《诗经》与周公典故", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“呦呦鹿鸣，食野之苹”化用《诗经·小雅·鹿鸣》，写宾主欢宴、待贤以礼；“周公吐哺，天下归心”化用《史记·鲁周公世家》，以周公自比。用典能用极精简的语言表达丰富的思想、丰富诗歌内容、强化诗歌内涵。"], ["比喻：朝露、明月、乌鹊、山海", "“譬如朝露”比喻人生短暂；“明明如月，何时可掇”把贤才比作高空的明月，寻求贤士比作无法揽取的明月；“月明星稀，乌鹊南飞。绕树三匝，何枝可依”比喻贤才无所依托、犹豫彷徨；“山不厌高，海不厌深”比喻贤才多多益善。"], ["借代与“忧”的三重结构", "“唯有杜康”以杜康代酒，是借代；全诗两个主旋律是忧人生短暂、为求贤而愁，第五六章是主旋律的复现与变奏，“明明如月”照应第一二章，“越陌度阡”照应第三四章，一扬一抑、反复咏叹。"]], "vgaokao": []}}, "chn_c011": {"name": "归园田居（其一）", "sec": 1, "secTitle": "第7课", "page": 59, "desc": "陶渊明的归田宣言：白描写景与「守拙」的自白。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c010"], "next": ["chn_c012"], "content": {"advance": {"a": "「拙」是诗人自认不合世俗机巧的本性，「守拙」就是守住这份本真、不随波逐流改变自我。它与「尘网」「樊笼」相对，点明归田不是一时避世，而是回归本性的选择——这是陶诗超越一般田园描写的思想深度。", "kind": "self", "q": "如何理解「守拙归园田」中「拙」的含义？它为什么是全篇的题眼？"}, "apply": [{"ans": 1, "opts": ["只写环境偏僻", "远村模糊、炊烟轻淡，景中有远意，与诗人冲淡闲适的心境完全合拍", "村子很贫穷", "诗人视力不佳"], "q": "「暧暧远人村，依依墟里烟」的赏析，恰当的是（ ）", "why": "炼字赏析要景情合一：「暧暧」「依依」的朦胧感正是心境的平和悠远。"}, {"ans": 0, "opts": ["白描与情景交融", "堆砌典故", "大起大落的抒情", "严整的排律对仗"], "q": "本诗写景的突出特点是（ ）", "why": "本诗写景几乎不见形容词的雕饰，以白描取胜，情在景中自然透出。"}], "basics": [{"ans": 1, "opts": ["十年", "三十年", "三年", "十三年（教材注释作三十年，一作十三年）"], "q": "「误落尘网中，一去三十年」中诗人说自己做官前后大约（ ）", "why": "教材取「三十年」之说（有本作十三年）：自出仕到归田，前后约三十年（一说十三年），表达久陷官场的悔意。"}, {"ans": 1, "opts": ["官场", "樊笼", "泥潭", "尘网与樊笼都是"], "q": "诗中诗人把官场生活比作（ ）", "why": "「尘网」「樊笼」双喻官场：一个言束缚于罗网，一个言困于笼中。"}], "case": {"a": "「羁鸟」是被束缚的鸟，「池鱼」是养在池中的鱼，都非其自然之性；诗人以两物自喻：身在官场如鸟在笼、鱼在池，本性向往的是旧林与故渊——自由的田园。比喻中完成了自我剖析。", "q": "「羁鸟恋旧林，池鱼思故渊」两句用了什么方法写诗人自己？", "title": "案例：比喻自况"}, "intro": "陶渊明辞官归田的宣言诗。==五言古诗，白描到底：屋、树、村、烟、狗、鸡，寻常物象里写出「复得返自然」的解脱感。==本课考点在**白描**与诗人本性的自白。", "learn": [{"h": "自白：性本爱丘山", "p": "开篇四句交代归田的原因：本性爱丘山，却「误落尘网中」。「羁鸟恋旧林，池鱼思故渊」以两物**自喻**——诗人不是一时厌倦官场，而是本性与官场天然不合。「守拙」的「拙」，就是他不肯丢掉的本真。理解全诗，先抓住这条因果线：性—误—归。"}, {"h": "白描：八九间草屋的图景", "p": "方宅、草屋、榆柳、桃李、远村、墟烟、狗吠、鸡鸣——全是名词的铺排，几乎不用形容词，这就是**白描**：以最素朴的笔法写最真实的景物。「暧暧远人村，依依墟里烟」两个叠词是全篇最见功力之处，朦胧轻淡，正合诗人平和的心境。==白描题的答法：指出手法＋列举物象＋点出情感，三者齐全才满分。=="}, {"h": "收束：樊笼与自然的对照", "p": "「户庭无尘杂，虚室有余闲」由景转心：环境越空，心越满。结尾「久在樊笼里，复得返自然」与开头「误落尘网」首尾呼应。主题落点不是田园多美，而是**回归本真**的生命选择——这也是陶渊明成为后世隐逸诗之祖的原因。"}], "pitfalls": ["把「守拙」理解成笨拙、能力不足——它是守住本真、不慕机巧。", "默写错字：「榆柳荫后檐」的「荫」读 yìn，不要写作「阴」；「暧暧」不要写作「暖暖」。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 11, "t": "短歌行·归园田居", "dur": "25:48", "from": "名师课堂", "vtop": ["诗眼是“忧”，曹操三忧：人生短暂、求贤不得、功业未就——三者相连：有建功立业、一统天下的壮志，才会感到人生短暂，更要抓紧时间延揽天下人才。", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“纵我不往，子宁不嗣音”的省略是含蓄提醒：就算我没去找你们，你们为什么不主动来投奔我呢？", "“周公吐哺，天下归心”：周公洗头、吃饭时贤士来见，握着湿发、吐出口中食物就出来见客——诗人以周公自比，表明像周公一样热切殷勤待贤才、渴望求贤以统一天下。"], "vsum": "本课是必修上册第三单元“生命的诗意”第7课。先说明一点：这个视频只讲《短歌行》一首，同课的陶渊明《归园田居》不在这个视频里，它在合集的下一页 P12，学完这首再去看 P12，不要以为这一课就讲完了。\n\n学诗先讲方法：赏析诗词有一个非常重要的解读方法，叫**知人论世**，最早由孟子提出——“颂其诗，读其书，不知其人，可乎？是以论其世也”。意思是只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容。这节课就用这个方法走进作者、解读全诗。\n\n先认识作者。曹操，字孟德，是三国时期杰出的政治家、军事家、文学家。陈寿在《三国志》里评价他是“**非常之人，超世之杰**”。作为政治家，他外定武功、内兴文学，知人善察、**唯才是举**；作为军事家，他指挥了**官渡之战**，逐步统一了中国北方；作为文学家，他是**建安文学**的开创者和组织者。他的诗歌语言质朴、感情深沉、格调苍凉悲壮，被誉为**建安风骨**（也称魏晋风骨）：建安时期的作品真实反映了现实的动乱和人民的苦难，抒发了建功立业的理想和积极进取的精神，同时流露出人生短暂、壮志难酬的悲凉忧怨，意境宏大，具有鲜明的时代特征和个性特征。他用**乐府古题**写实事，继承了汉乐府“感于哀乐，缘事而发”的现实主义精神。乐府诗有长歌和短歌之分，叶嘉莹教授认为一般根据歌声的长短而定：长歌比较热烈奔放，短歌节奏短促、低回短唱，适合抒发内心的忧愁和苦闷——这首诗作者是否也要抒发内心的忧愁和苦闷呢？带着这个问题往下学。\n\n写作背景有不同的说法，不可轻信其一。《三国演义》第48回写曹操平定北方后率百万雄师与孙权决战，月明之夜在大江之上置酒宴月，酒酣时取槊立于船头慷慨而歌，歌词就是这首《短歌行》；苏轼的《前赤壁赋》也说此诗作于赤壁大战前夕（“方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗”）。但这些都是小说家言和文学家的想象推测，缺乏可信的史料依据，还不能作出准确的结论。毫无疑问的是，曹操把他英雄的气质、诗人的才情和霸主的野心都集中表现在了这首诗中。\n\n全诗可分为**八章，每章四句**。先找**诗眼**：哪个字最能体现全诗的感情？是“**忧**”。“诗言志，歌永言”——曹操为何而忧，又是如何抒发这种情感的呢？\n\n第一二章：对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧？唯有杜康。“对”和“当”都是面对的意思，对酒当歌就是面对着酒与歌，即饮酒听歌。面前有酒有歌，作者情绪激动起来，就会想到这对酒当歌的美好快乐日子能有多少，眼前的快乐更反衬出人生无常的哀叹，于是发出“人生几何”的感叹——让人想起《左传·襄公八年》的“**俟河之清，人寿几何**”：黄河水清象征天下太平，可人寿有限，哪等得到那一天？开头两句就表现了诗人对于生命短促和人生无常的哀叹。“譬如朝露，去日苦多”用**比喻**：人生就像早晨的露水，太阳一出就晒干了。汉乐府《薤露歌》说“薤上露，何易晞。露晞明朝更复落，人死一去何时归”——草叶上的露水干了，明天早晨还会落上新的露水，而人死了以后就再也不会回来了。“朝露”这个意象在古诗文中有特定的含义，就是生命短促。“慨当以慷”：慷慨是形容感情激动的样子，“当以”没有实在意义。接下来的“唯有杜康”：杜康相传是最早造酒的人，这里用**借代**的修辞手法，以杜康代酒。借代能使表达形象生动、重点突出、简洁精炼。中国文人历来与酒有着不解之缘：范仲淹“浊酒一杯家万里”表达思乡之情，王维“劝君更尽一杯酒，西出阳关无故人”表达送别之情，杜甫晚年穷困潦倒却还感叹“艰难苦恨繁霜鬓，潦倒新停浊酒杯”，李白“五花马，千金裘，呼儿将出换美酒，与尔同销万古愁”“抽刀断水水更流，举杯消愁愁更愁”——借杯中酒浇胸中块垒，一直是中国知识分子的精神寄托方式。\n\n第一二章乍读起来似乎情调消沉，其实不然。诗人生逢乱世，目睹百姓颠沛流离，渴望建功立业而未得，不能不产生苦闷和感慨；但这种苦闷和感慨，只有对事业和感情执着的人、只有不满现实而又积极要求改变现实的人才可能产生。所以诗人的苦闷和感慨正是英雄人物的苦闷和感慨，是烈士的一种悲心，自有它的积极意义——全诗蕴含着应及时努力的思想。诗人一方面抒发个人之情，感叹时间过得太快、恐怕来不及有所作为，另一方面也是在巧妙地感染广大贤才：人生就像朝露那样容易消失，岁月已经流逝了很多，应该赶快拿定主意，到他那里施展抱负。这样积极的目的用低沉的调子来发端，固然表明诗人确有他的愁思，说得真切；但也唯有通过这样的调子，才更能打开处于下层、多方艰难、又急于寻找出路的贤才的心扉。\n\n第三四章：青青子衿，悠悠我心。但为君故，沉吟至今。“青青子衿，悠悠我心”语出《诗经·郑风·子衿》，原写姑娘思念情人，这里用来比喻渴望得到贤才。“子”是对对方的尊称，“青衿”指周代读书人青色交领的服装，“悠悠”是长远的样子，形容思虑连绵不断。诗人这里引用《诗经》中的诗句，还说自己一直低低地吟诵它，实在太巧妙了。但更重要的是他所省略的原诗中的两句——“**纵我不往，子宁不嗣音**”：虽然我不能去找你，你为什么不主动给我音信？诗人由于事实上不可能一个一个去找那些贤才，所以用这种含蓄的方法提醒他们：就算我没去找你们，你们为什么不主动来投奔我呢？由这层含而不露的意思可以看出，他求才的用心十分真诚，的确具有感人的力量。“但为君故，沉吟至今”：这里指思念和倾慕贤人。“君”在《诗经》中可能指一个具体的人，而在这里则具有了广泛的意义——在当时凡是读到曹操此诗的贤士，都可以自认为就是曹操渴求的对象，正因为这样，此诗流传开去才会起到巨大的社会作用。紧接着，作者又引用了《诗经·小雅·鹿鸣》中的四句——“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”，描写宾主欢宴的情景：鹿鸣本是周代朝廷宴请宾客的诗，鹿喜欢群居，每当找到了艾蒿，便悠悠地呼唤着同伴相聚而食；这里用来表达招纳贤才的热情，意思是只要你们到我这里来，我一定会待以嘉宾之礼，我们能够欢快融洽地相处并合作。三四两章从表面看，曹操自己的话只有“但为君故，沉吟至今”两句，但他通过用典婉转而清晰地吐露了自己的情意：第三章写他求贤而不得的日夜思慕，第四章写他求贤既得后设宴欢迎的情景，两相对照，表达了**求贤若渴**之情。加上青青之色、悠悠之声，诗中有声有色，顿觉词彩鲜艳、音韵悠扬。\n\n第五六章：明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈讌，心念旧恩。“明明如月，何时可掇”有两种理解：一种把“掇”当作拾取、摘取的意思——诗人奇想天外，明朗的月亮什么时候才能把它摘到手呢？后来李白“欲上青天揽明月”的诗句应由此脱胎；这两句写得非常精彩，除了显示诗人不失赤子之心、想上九天揽月之外，还运用了比喻的修辞手法，将人才比作月亮，把寻求贤士生动地比作无法揽取的明月，是那样的渴望而不可及。另一种解释把“掇”当作同“辍”、停止的意思——皓月当空运转永不停止，而我的求贤之心也不会停止。两种解释都合理，无论是“掇”还是“辍”，这四句都道出了作者深深的忧虑：忧贤才不得。“越陌度阡”：陌、阡都是田间小路，南北叫阡、东西叫陌，这里引用《风俗通》里的古谚；“枉用相存”：枉是屈驾的意思，用是以，相存是问候、探望，合起来是屈驾来访；“契阔谈讌”：契阔是久别重逢，谈讌是谈心宴饮，合起来是久别重逢、欢聚畅谈；“心念旧恩”指往日的情意。当贤才们跨越乡间的小路、长途跋涉，一个个屈尊前来探望作者时，彼此就像久别重逢的好友，谈心宴饮、诉说往日的情谊，诗人又因贤才远道而来归附自己而喜不自胜。五六两章一忧一喜，忽忧忽喜的矛盾心理把求贤过程中的悲喜情状曲折有致地表现出来，充分表现了诗人思贤若渴的主题。五六两章也是对前四章的强调和照应：前四章主要讲了两个意思——忧人生短暂、为求贤而愁，又表示要待贤以礼，这是全诗的两个主旋律；五六两章就是这两个主旋律的复线和变奏，“明明如月，何时可掇，忧从中来，不可断绝”是照应第一二章，“越陌度阡，枉用相存，契阔谈讌，心念旧恩”是照应第三四章。表面看来五六两章与前四章重复，但实际上由于主旋律的复现和变奏，使全诗更有一扬一抑、反复咏叹之致，加强了抒情的意味。\n\n第七八章是全诗的关键，也是艺术感染力最强的地方。先看第七章：月明星稀，乌鹊南飞。绕树三匝，何枝可依？明月皎洁、夜星稀疏，乌鹊向南飞去，围着树木绕来绕去，不知哪个枝干可以依附。这可能就是写眼前的实景。中国古人常说“**良禽择木而栖，良臣择主而事**”：一只好的鸟不会随便栖落在一个污秽肮脏的地方，它一定会选择一棵好的树作为栖息之所；传说中的凤凰更是非梧桐不栖。在这里，作者运用比喻的手法，用乌鹊比喻贤才，用“绕树三匝，何枝可依”比喻贤士们在三国鼎立的局面下无所侍从的情形。诗人启发他们不要三心二意，要善于择木而栖，赶紧到自己这一边来。这四句生动地刻画了那些犹豫彷徨者的处境与心情，然而诗人不仅丝毫没有指责，反而在浓郁的诗意中透露出对这些人的关心和同情。同时，由于汉末大乱、北方人口大量迁移，这首诗除了可能含有诗人在另一首乐府诗《蒿里行》中所表现的征故怀乡之感，也可能含有慨叹人民流离失所的情感。我们不仅能感受到诗人渴求贤才的心情，而且还能够从中感觉到当时社会的氛围。再看结尾：山不厌高，海不厌深。周公吐哺，天下归心。“山不厌高，海不厌深”仿用《管子·形势解》里的话——“海不辞水，故能成其大；山不辞土，故能成其高；明主不厌人，故能成其众”：海从来不拒绝水，所有的水都流到海里，所以海才会这么大；山从来不拒绝土石，所有的土石都可以落在山上，所以山才会那么高；明主从不拒绝归附他的人，所有的人都来投奔他，所以他才拥有很大的力量。诗人用这两句比喻贤才多多益善。下面“周公吐哺”又是一个典故：周公是周武王的弟弟、周成王的叔叔，武王死后成王年幼，周公辅政，平息了武庚的叛乱，并且制作礼乐，使天下大治，被后代称为圣贤的典范；周公的儿子伯禽受封于鲁，周公说他在辅政的时候从来不敢怠慢前来求见的贤士，如果在洗头发的时候有人来见他，他来不及把头发梳好，握着湿头发就出来见客，如果在吃饭的时候有人来见他，他来不及嚼完口中的食物，就把食物吐出来、出去见客，就这样他还唯恐疏漏了国中的贤人。这里借用这个典故表示自己会像周公一样热切殷勤地接待贤才，突出地表现了诗人求贤的心愿。最后四句画龙点睛，明明白白地披肝沥胆，希望人才都来归顺，点明此诗的主题；同时作者以周公自比，表明自己渴望求贤以统一天下的宏图大志。曹操的这种宏图大志值得充分肯定：三国时期军阀割据、战祸连年，生产力遭到了极大的破坏，人民饱尝流离的痛苦、面临死亡的威胁，中原地区尤为严重，曹操的《蒿里行》对此有过真实的写照——“白骨露于野，千里无鸡鸣。生民百遗一，念之断人肠。”那时人心思定，要求尽快结束纷争的局面，是大势所趋、势在必行，曹操正是顺应时代的潮流，肩负起完成统一大业的英雄。\n\n学完这首诗，总结一下：曹操为何而忧？他所忧的是**人生短暂、求贤不得、功业未就**。这三者之间有何内在的联系呢？正因为诗人有建功立业、一统天下的壮志，所以才会想到人生短暂，更应当抓紧时间延揽天下人才，及早尽快建功立业。这首诗的艺术特色主要有两点：一是**运用典故**、合理引用和化用，例如“青青子衿，悠悠我心”是引用《诗经》的诗句，将女子对情人的相思之情变成了诗人对贤才的思慕；“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”也是引用《诗经》的诗句，意在表达诗人期待贤者的热忱；再如“周公吐哺，天下归心”，化用《史记·鲁周公世家》中周公的事迹，诗人以周公自比，表达求贤建业的雄心。用典的好处在于能用极精简的语言表达丰富的思想，可以丰富诗歌的内容、强化诗歌的内涵。二是**妙用比喻**：用朝露比喻人生的短暂，用“明明如月，何时可掇”将贤才比作高空的明月、渴望而不可及，又用“月明星稀，乌鹊南飞。绕树三匝，何枝可依”中乌鸦难以择枝的情景比喻贤才无所依托，还用“山不厌高，海不厌深”比喻贤才越多越好。最后是反馈与评价三道题：第一题，“青青子衿，悠悠我心”表达了作者对贤才的思慕；第二题，“山不厌高，海不厌深”表现了作者渴望多招纳贤才；第三题，课堂讨论清人吴淇“纯是一片求才意思”的评价——你同意“求才”一说吗？老师认为可以同意：这首诗是曹操诗歌中具有代表性的杰出之作，全诗通过对时光易逝、贤才难得的再三咏叹，抒发了自己求贤若渴的感情，表现出统一天下的雄心壮志和自强不息的进取精神。", "vtech": [["知人论世：读诗先读人", "孟子提出的方法：颂其诗、读其书，不知其人可乎？是以论其世也——只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容；本课就用这个方法走进曹操、解读全诗。"], ["用典：化用《诗经》与周公典故", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“呦呦鹿鸣，食野之苹”化用《诗经·小雅·鹿鸣》，写宾主欢宴、待贤以礼；“周公吐哺，天下归心”化用《史记·鲁周公世家》，以周公自比。用典能用极精简的语言表达丰富的思想、丰富诗歌内容、强化诗歌内涵。"], ["比喻：朝露、明月、乌鹊、山海", "“譬如朝露”比喻人生短暂；“明明如月，何时可掇”把贤才比作高空的明月，寻求贤士比作无法揽取的明月；“月明星稀，乌鹊南飞。绕树三匝，何枝可依”比喻贤才无所依托、犹豫彷徨；“山不厌高，海不厌深”比喻贤才多多益善。"], ["借代与“忧”的三重结构", "“唯有杜康”以杜康代酒，是借代；全诗两个主旋律是忧人生短暂、为求贤而愁，第五六章是主旋律的复现与变奏，“明明如月”照应第一二章，“越陌度阡”照应第三四章，一扬一抑、反复咏叹。"]], "vgaokao": []}}, "chn_c012": {"name": "梦游天姥吟留别", "sec": 2, "secTitle": "第8课", "page": 60, "desc": "李白的梦游仙境：夸张、想象与结尾的傲岸宣言。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《梦游天姥吟留别》结尾表明诗人态度的两句。", "answer": "安能摧眉折腰事权贵，使我不得开心颜！"}, "pre": ["chn_c011"], "next": ["chn_c013"], "content": {"advance": {"a": "前段的仙境越瑰丽，后文「世间行乐亦如此，古来万事东流水」的幻灭感越强，最终「安能摧眉折腰事权贵」的宣言才越有分量。没有梦的绚烂，就没有醒后拒绝妥协的震撼——梦是宣言的蓄势。", "kind": "self", "q": "有人认为梦境部分是炫技，与主题无关。你如何反驳？"}, "apply": [{"ans": 1, "opts": ["记叙文式平铺直叙", "沿梦境推进：入梦—登山—开门—仙境—惊醒，时空跳跃、虚实相生", "完全按时间顺序的游记", "以议论为主线"], "q": "本诗结构安排的特点是（ ）", "why": "梦境结构允许想象驰骋，也是浪漫主义诗歌组织材料的方式。"}, {"ans": 2, "opts": ["怀疑仙境是否存在", "对友人的婉拒之词", "对权贵的蔑视与保持人格独立的宣言，与全诗结尾相呼应", "感叹时光流逝"], "q": "「安能摧眉折腰事权贵，使我不得开心颜」表达的是（ ）", "why": "这是全诗主旨句：宁可不开心颜——绝不向权贵低头，须与作者生平（赐金放还）联系理解。"}], "basics": [{"ans": 1, "opts": ["思念故乡", "借梦游仙境，抒发对自由的向往与对权贵的不屈", "写天姥山的旅游攻略", "劝人出家修道"], "q": "本诗的主旨是（ ）", "why": "这是李白的代表作：表面游仙，实为宣言，落点在不事权贵的人格独立。"}, {"ans": 0, "opts": ["夸张", "用典", "排比", "对偶"], "q": "「天台四万八千丈，对此欲倒东南倾」中「四万八千丈」运用的是（ ）", "why": "数字极言其高，是浪漫主义夸张的典型笔法。"}], "case": {"a": "线索：现实中听闻天姥（起）—梦中飞渡、登山、洞开、仙境（承转）—神人降临后忽然惊醒（转）—醒后感慨与宣言（合）。梦的边界由「忽魂悸以魄动，恍惊起而长嗟」一句划开。", "q": "用四个词组概括本诗的情节线索，并指出梦境结束的标志句。", "title": "案例：梦的边界线"}, "intro": "**李白**最著名的梦游诗。==结构就四步：入梦、游仙、梦醒、宣言——其中梦境是浪漫想象的放飞，结尾两句是全诗的魂。==注意那些读错就丢分的字：姥、剡、渌、殷、訇。", "learn": [{"h": "入梦：由实入虚", "p": "开篇借「海客谈瀛洲」「越人语天姥」的传闻起势，天姥山「云霞明灭或可睹」。诗人夜着谢公屐、踏云霞而上。谢公屐暗用谢灵运典故，是李白向山水诗前辈的致意。梦境的入口写得越真实，后面的飞跃越可信——浪漫主义也要有逻辑台阶。"}, {"h": "游仙：想象的放飞", "p": "半壁见海日、熊咆龙吟、列缺霹雳、丘峦崩摧、洞天石扉訇然中开、青冥浩荡、仙人纷至——**夸张与想象**层层加码，节奏由缓到急再到极盛。==鉴赏浪漫主义诗歌，先圈出最不可能的画面：越离奇，越是诗人情感的真实强度。==「世间行乐亦如此，古来万事东流水」一句冷水，为梦醒作铺垫。"}, {"h": "梦醒与宣言", "p": "梦醒之后，诗人先叹人生如梦、万事东流，末段笔锋一转：「安能摧眉折腰事权贵，使我不得开心颜！」结合背景：李白曾奉诏入京又被赐金放还，此诗是给友人的留别诗，宣言正是写给权贵世界看的。情感曲线是全诗的逻辑：向往—极乐—幻灭—傲岸。"}], "pitfalls": ["读音字形：「天姥」读 mǔ 不读 lǎo；「剡溪」读 shàn；「渌水」读 lù；「殷岩泉」殷读 yǐn（雷声）；「訇然」读 hōng。", "把主旨答成「热爱大自然」，丢掉不事权贵的宣言层。", "默写错字：「列缺霹雳」的「缺」是空隙之意（通「隙」），不要写作「决」。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 13, "t": "李杜白三篇", "dur": "25:23", "from": "名师课堂", "vtop": ["“梦游”是贯穿全诗的主线：梦前（海客谈瀛洲至对此欲倒东南倾）、梦中（我欲因之梦吴越至仙之人兮列如麻）、梦后（忽魂悸以魄动至篇末），做题先按三段切分再找手法。", "全诗主旨落在结尾“安能摧眉折腰事权贵，使我不得开心颜”：追求个性解放、蔑视权贵，前面所有瑰丽梦境都是为这一句铺垫。", "浪漫主义两大招：神奇的想象（民间传说、神话、梦境）加 大胆的夸张（天姥之高、仙人盛会），夸张总与具体事物结合、自然不露痕迹。"], "vsum": "本课只讲《梦游天姥吟留别》一篇。《登高》《琵琶行》不在本视频内，在合集 P14（cid 818559059），后续补。开场先定李白的地位：诗仙，继屈原之后又一位伟大的浪漫主义诗人，杜甫说他的诗是“笔落惊风雨，诗成泣鬼神”。本课三个目标：一是**知人论世**，把握诗歌内涵、理解李白的精神境界；二是诵读涵咏，品味诗中神奇瑰丽的诗境、认识李白豪迈飘逸的诗风；三是体察李白对社会与人生的思考。先**解题**：“吟”本指吟咏、作诗，后来成为乐府歌行体的一种诗体名称；“留别”是临行前留下这首诗向朋友话别；全题的意思就是用梦游天姥的诗向朋友话别，别名《梦游天姥山别东鲁诸公》。旧诗分古体和近体，唐人把新出现的格律诗叫近体诗，把唐以前较少格律限制的叫古体诗，《梦游天姥吟留别》是古体诗。接着落实读音和特殊句式，圈出天姥、瀛洲、渌水、澹澹、霹雳等易读错的字。再把握全诗脉络：**“梦游”是贯穿全诗的主线**，开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，从“忽魂悸以魄动”到篇末是梦后。本诗最突出的特点是浪漫主义的艺术特色，即神奇的想象和大胆的夸张：想象有来源于民间传说的（如仙境的种种细节），也有出于诗人个性爱好的（如“湖月照我影，送我至剡溪”，跟“举杯邀明月，对影成三人”一样，是把月看成最亲密的朋友）；夸张不是简单的放大，而是融合着诗人的感情，如开头写天姥山横空出世的雄姿，里面就含着诗人对天姥山的景仰和向往。**写作背景**：李白字太白，号青莲居士，一生最重要的活动在开元盛世，怀着济苍生、安社稷的政治理想，希望有一番作为。天宝二年因朋友吴筠推荐被唐玄宗召入长安，做了翰林供奉，这时他已 42 岁。本想借此施展才能，却只得了一个侍从闲职，没有被重用，又因一身傲骨不肯与权贵同流合污、得罪了权贵，在长安仅住了一年多就被赐金放还，政治上的失败使他心情苦闷，也让他看清了封建统治者的荒淫腐朽。被排挤出长安的第二年，即天宝四年，李白准备由东鲁南游吴越，行前写了这首向朋友表明自己心志的诗。李白诗歌的浪漫主义手法有三点：一是善于凭借想象，以主观现客观，现实事物、自然景观、神话传说、历史典故、梦中幻境无不成为想象的媒介，常借助想象超越时空，把现实与梦境、自然界与人类社会交织一体；二是把**拟人与比喻**巧妙结合，以情寓物、将物比人；三是抓住事物某一特点，在生活真实的基础上大胆想象夸张，夸张得自然不露痕迹、大胆又真实可信，有时还把夸张与鲜明对比结合，通过加大艺术反差加强效果。李白最擅长的体裁是七言歌行和绝句，七言歌行大开大合、跳跃跌宕，开头常突兀如狂飙骤起，中间形象转换疏忽、往往省略过渡照应，结尾都在感情高潮处戛然而止。**整体阅读**：抓住梦游主线，先读梦前。诗人借“海客谈瀛洲”衬托天姥山，瀛洲是海上仙山，写它也是为天姥山拢上一层神秘浪漫的色彩；接着着力写天姥山的高大，用的是夸张和对比。明朝王思任说天姥不过一小山峰，诗人竟写得如此气势巍峨——其实真正的天姥山并不高大，李白是用夸张、对比等手法描绘自己心中的天姥山，所谓“**一切景语皆情语**”，诗人的浪漫笔墨正是源自豪放胸襟。梦中分三幅画面：**月夜渡湖、著屐登山、仙人盛会**。诗人“一夜飞度镜湖月，湖月照我影，送我至剡溪”，渡过镜湖在月的映照下来到剡溪；“谢公宿处今尚在，渌水荡漾清猿啼”，相传南朝谢灵运到浙江永嘉任太守，喜遨游山水，伐木取径开辟了通往天姥的古道；诗人“脚著谢公屐，身登青云梯”，立在前人开拓的古道上展开想象。登山所见：“半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝”，所闻：“熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟”——连深林、层巅都能栗、能惊，烟、水、青云都满含幽郁，与诗人的情感融成一体。忽然“列缺霹雳，丘峦崩摧。洞天石扉，訇然中开”，梦境推向高潮：“青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。虎鼓瑟兮鸾回车，仙之人兮列如麻。”金台银台与日月交相辉映，仙人列队迎接诗人，这是全诗写景最辉煌灿烂的一段，也是人世间生活的反映：里面既有长期漫游经历过的万壑千山的印象、古代传说和屈原诗歌的启发，也有长安宫廷生活的记忆，全靠浪漫主义的非凡想象凝聚在一起。**梦后**只有七句：“忽魂悸以魄动，恍惊起而长嗟。惟觉时之枕席，失向来之烟霞。”梦已尽而思无穷，结尾落在“**安能摧眉折腰事权贵，使我不得开心颜**”——这才是全诗的主旨：诗人追求个性解放、蔑视权贵。老师提醒两点：一是“吟”多有悲愁慨叹之意；二是解读作品要了解作家的思想，李白既怀有儒家兼善天下的抱负，也有道家逍遥自在的情怀，表面看这是一首游仙诗，主体是神仙世界的描写，但他向往这个世界正是因为厌恶眼前黑暗的现实世界。全诗特点有二：一是构思上富有浪漫主义色彩，突破了一般送别诗惜别伤离的老套，借留别表明自己蔑视权贵的政治态度，围绕一场由先的梦幻来构思，直到最后才落到蔑视权贵的主旨上，给幻想的驰骋开拓了广阔领域；二是句法上以七言为基调，交错运用四言、五言、六言、九言的句子，灵活多样却浑然一体，因为全诗有一条感情发展的脉络贯穿，诗句随感情起落而有长有短、节拍有急有缓。课堂小结引王思任的话：天姥攀缘入李白之梦，李白一做梦便吟诗，一吟诗就使得天姥山与天台山不分伯仲——李白写的是梦游，是用浪漫的艺术抒发对理想人生的热烈追求。课后作业：充满感情地诵读梦后部分，其中“安能摧眉折腰事权贵，使我不得开心颜”连读三遍；专题延伸推荐阅读《品中国文人·李白》。", "vtech": [["梦游三段怎么切", "先找梦的边界：开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，“忽魂悸以魄动”起是梦后；结构题、思路题先报三段再展开，别从头平铺直叙。"], ["夸张题的答法：先还原再说效果", "天姥山其实并不高大，李白用夸张、对比写心中之山；答题先说“诗人用夸张写……”，再说突出了什么、表达了什么感情，缺了还原那一步就只剩套话。"], ["“安能摧眉折腰”为什么是主旨", "结尾两句是全诗唯一的直接表态，前面梦境越瑰丽、反衬现实越黑暗；问主旨、问情感就落在这两句上，答“追求个性解放、蔑视权贵”，再回扣梦境铺垫。"], ["古体诗的句式怎么答", "本诗以七言为基调，交错四言、五言、六言、九言，长短句随感情起落而变化；考句式就答“句式灵活多变、浑然一体”，别只说“七言古诗”四个字。"]], "vgaokao": []}}, "chn_c013": {"name": "登高", "sec": 2, "secTitle": "第8课", "page": 61, "desc": "杜甫的「古今七律第一」：八句皆对仗，景与情层层收束。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《登高》颈联（写身世之悲的两句）。", "answer": "万里悲秋常作客，百年多病独登台。"}, "pre": ["chn_c012"], "next": ["chn_c014"], "content": {"advance": {"a": "景语：风、天、猿、渚、沙、鸟、落木、长江，全是悲秋意象，又有急、哀、下、滚滚等词加压，景的悲凉就是情的悲凉。情语：悲秋、作客、多病、登台、苦恨、潦倒，层层自述。诗人把身世之悲、家国之忧、老病之哀全压进秋景里，不分彼此——这正是「情景交融」的最高形态。", "kind": "self", "q": "说说本诗是怎样做到「景中有情、情中有景」的。"}, "apply": [{"ans": 2, "opts": ["没有对仗", "只有颔联对仗", "首、颔、颈三联皆对仗，尾联以散句收束", "通篇不对仗"], "q": "本诗的对仗情况是（ ）", "why": "三联对仗是本诗律法精严的标志：「万里」对「百年」、「悲秋」对「多病」皆工对。"}, {"ans": 1, "opts": ["因果关系", "景中含情、层层收束：前四句写景之悲，后四句写身之悲，景愈阔情愈沉", "先情后景", "景与情各自独立"], "q": "「无边落木萧萧下，不尽长江滚滚来」与后四句的关系是（ ）", "why": "颔联是全诗的枢纽：落木、长江由景生情，自然转到身世之悲。"}], "basics": [{"ans": 0, "opts": ["沉郁顿挫", "豪放飘逸", "清新自然", "婉约细腻"], "q": "本诗的风格是杜甫一贯的（ ）", "why": "沉郁顿挫是杜诗的总体风格；豪放飘逸属李白，不要张冠李戴。"}, {"ans": 1, "opts": ["春望", "登高", "茅屋为秋风所破歌", "望岳"], "q": "被明代胡应麟称为「古今七律第一」的是（ ）", "why": "《登高》以气象、声律、情感俱臻极致获此评；注意评价者是后世评论家而非杜甫自评。"}], "case": {"a": "工整在三点：词性相对（万里/百年是数量，悲秋/多病状心境，作客/登台写行为）；结构相对（万里悲秋—常作客 与 百年多病—独登台 句式平行）；内容相对（空间之远对时间之长，漂泊之久对疾病之深），把个人遭际写得极有概括力。", "q": "以颈联「万里悲秋常作客，百年多病独登台」为例，说说本诗对仗「工整」体现在哪里。", "title": "案例：颈联工对"}, "intro": "**杜甫**晚年在夔州登高所作，被称「古今七律第一」。==八句句句是考点：三联对仗、情景交融、悲秋意象群——七律的鉴赏方法在这首诗里一次学全。==", "learn": [{"h": "前四句：悲秋意象群", "p": "风急、天高、猿啸哀、渚清、沙白、鸟飞回、落木萧萧、长江滚滚——八句之内意象密集而有序：由高到低、由远及近。**叠词与声音**不可忽视：「萧萧下」的落叶声、「滚滚来」的江水势，把秋天的悲凉写成了可听可感的现场。首联十四字写了六种景物，是杜甫「精严」的招牌。"}, {"h": "后四句：身世之悲的三层", "p": "颈联「万里悲秋常作客，百年多病独登台」一联写尽一生：空间上万里漂泊，时间上百年多病。尾联「艰难苦恨繁霜鬓，潦倒新停浊酒杯」把个人之悲与家国艰难合流——「艰难」既指国运也指身世。情感三层：**羁旅之悲、老病之哀、家国之忧**，答题时三层都要点到。"}, {"h": "律诗鉴赏的通用抓手", "p": "读七律抓四点：对仗（对偶句在哪几联）、炼字（萧萧、滚滚等）、意象群（是否成系统）、情感层次（是否由景入情层层深入）。本诗四点全占，这也是它成为标杆的原因。下次遇到陌生律诗，照此清单逐项过。"}], "pitfalls": ["默写错字：「渚清沙白」的「渚」误作「诸」；「潦倒新停」的「潦」不要少写一点水。", "把「百年」误解成实指一百年，它是言人生暮年、一生。", "只答悲秋，不答家国之忧这一层。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 13, "t": "李杜白三篇", "dur": "25:23", "from": "名师课堂", "vtop": ["“梦游”是贯穿全诗的主线：梦前（海客谈瀛洲至对此欲倒东南倾）、梦中（我欲因之梦吴越至仙之人兮列如麻）、梦后（忽魂悸以魄动至篇末），做题先按三段切分再找手法。", "全诗主旨落在结尾“安能摧眉折腰事权贵，使我不得开心颜”：追求个性解放、蔑视权贵，前面所有瑰丽梦境都是为这一句铺垫。", "浪漫主义两大招：神奇的想象（民间传说、神话、梦境）加 大胆的夸张（天姥之高、仙人盛会），夸张总与具体事物结合、自然不露痕迹。"], "vsum": "本课只讲《梦游天姥吟留别》一篇。《登高》《琵琶行》不在本视频内，在合集 P14（cid 818559059），后续补。开场先定李白的地位：诗仙，继屈原之后又一位伟大的浪漫主义诗人，杜甫说他的诗是“笔落惊风雨，诗成泣鬼神”。本课三个目标：一是**知人论世**，把握诗歌内涵、理解李白的精神境界；二是诵读涵咏，品味诗中神奇瑰丽的诗境、认识李白豪迈飘逸的诗风；三是体察李白对社会与人生的思考。先**解题**：“吟”本指吟咏、作诗，后来成为乐府歌行体的一种诗体名称；“留别”是临行前留下这首诗向朋友话别；全题的意思就是用梦游天姥的诗向朋友话别，别名《梦游天姥山别东鲁诸公》。旧诗分古体和近体，唐人把新出现的格律诗叫近体诗，把唐以前较少格律限制的叫古体诗，《梦游天姥吟留别》是古体诗。接着落实读音和特殊句式，圈出天姥、瀛洲、渌水、澹澹、霹雳等易读错的字。再把握全诗脉络：**“梦游”是贯穿全诗的主线**，开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，从“忽魂悸以魄动”到篇末是梦后。本诗最突出的特点是浪漫主义的艺术特色，即神奇的想象和大胆的夸张：想象有来源于民间传说的（如仙境的种种细节），也有出于诗人个性爱好的（如“湖月照我影，送我至剡溪”，跟“举杯邀明月，对影成三人”一样，是把月看成最亲密的朋友）；夸张不是简单的放大，而是融合着诗人的感情，如开头写天姥山横空出世的雄姿，里面就含着诗人对天姥山的景仰和向往。**写作背景**：李白字太白，号青莲居士，一生最重要的活动在开元盛世，怀着济苍生、安社稷的政治理想，希望有一番作为。天宝二年因朋友吴筠推荐被唐玄宗召入长安，做了翰林供奉，这时他已 42 岁。本想借此施展才能，却只得了一个侍从闲职，没有被重用，又因一身傲骨不肯与权贵同流合污、得罪了权贵，在长安仅住了一年多就被赐金放还，政治上的失败使他心情苦闷，也让他看清了封建统治者的荒淫腐朽。被排挤出长安的第二年，即天宝四年，李白准备由东鲁南游吴越，行前写了这首向朋友表明自己心志的诗。李白诗歌的浪漫主义手法有三点：一是善于凭借想象，以主观现客观，现实事物、自然景观、神话传说、历史典故、梦中幻境无不成为想象的媒介，常借助想象超越时空，把现实与梦境、自然界与人类社会交织一体；二是把**拟人与比喻**巧妙结合，以情寓物、将物比人；三是抓住事物某一特点，在生活真实的基础上大胆想象夸张，夸张得自然不露痕迹、大胆又真实可信，有时还把夸张与鲜明对比结合，通过加大艺术反差加强效果。李白最擅长的体裁是七言歌行和绝句，七言歌行大开大合、跳跃跌宕，开头常突兀如狂飙骤起，中间形象转换疏忽、往往省略过渡照应，结尾都在感情高潮处戛然而止。**整体阅读**：抓住梦游主线，先读梦前。诗人借“海客谈瀛洲”衬托天姥山，瀛洲是海上仙山，写它也是为天姥山拢上一层神秘浪漫的色彩；接着着力写天姥山的高大，用的是夸张和对比。明朝王思任说天姥不过一小山峰，诗人竟写得如此气势巍峨——其实真正的天姥山并不高大，李白是用夸张、对比等手法描绘自己心中的天姥山，所谓“**一切景语皆情语**”，诗人的浪漫笔墨正是源自豪放胸襟。梦中分三幅画面：**月夜渡湖、著屐登山、仙人盛会**。诗人“一夜飞度镜湖月，湖月照我影，送我至剡溪”，渡过镜湖在月的映照下来到剡溪；“谢公宿处今尚在，渌水荡漾清猿啼”，相传南朝谢灵运到浙江永嘉任太守，喜遨游山水，伐木取径开辟了通往天姥的古道；诗人“脚著谢公屐，身登青云梯”，立在前人开拓的古道上展开想象。登山所见：“半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝”，所闻：“熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟”——连深林、层巅都能栗、能惊，烟、水、青云都满含幽郁，与诗人的情感融成一体。忽然“列缺霹雳，丘峦崩摧。洞天石扉，訇然中开”，梦境推向高潮：“青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。虎鼓瑟兮鸾回车，仙之人兮列如麻。”金台银台与日月交相辉映，仙人列队迎接诗人，这是全诗写景最辉煌灿烂的一段，也是人世间生活的反映：里面既有长期漫游经历过的万壑千山的印象、古代传说和屈原诗歌的启发，也有长安宫廷生活的记忆，全靠浪漫主义的非凡想象凝聚在一起。**梦后**只有七句：“忽魂悸以魄动，恍惊起而长嗟。惟觉时之枕席，失向来之烟霞。”梦已尽而思无穷，结尾落在“**安能摧眉折腰事权贵，使我不得开心颜**”——这才是全诗的主旨：诗人追求个性解放、蔑视权贵。老师提醒两点：一是“吟”多有悲愁慨叹之意；二是解读作品要了解作家的思想，李白既怀有儒家兼善天下的抱负，也有道家逍遥自在的情怀，表面看这是一首游仙诗，主体是神仙世界的描写，但他向往这个世界正是因为厌恶眼前黑暗的现实世界。全诗特点有二：一是构思上富有浪漫主义色彩，突破了一般送别诗惜别伤离的老套，借留别表明自己蔑视权贵的政治态度，围绕一场由先的梦幻来构思，直到最后才落到蔑视权贵的主旨上，给幻想的驰骋开拓了广阔领域；二是句法上以七言为基调，交错运用四言、五言、六言、九言的句子，灵活多样却浑然一体，因为全诗有一条感情发展的脉络贯穿，诗句随感情起落而有长有短、节拍有急有缓。课堂小结引王思任的话：天姥攀缘入李白之梦，李白一做梦便吟诗，一吟诗就使得天姥山与天台山不分伯仲——李白写的是梦游，是用浪漫的艺术抒发对理想人生的热烈追求。课后作业：充满感情地诵读梦后部分，其中“安能摧眉折腰事权贵，使我不得开心颜”连读三遍；专题延伸推荐阅读《品中国文人·李白》。", "vtech": [["梦游三段怎么切", "先找梦的边界：开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，“忽魂悸以魄动”起是梦后；结构题、思路题先报三段再展开，别从头平铺直叙。"], ["夸张题的答法：先还原再说效果", "天姥山其实并不高大，李白用夸张、对比写心中之山；答题先说“诗人用夸张写……”，再说突出了什么、表达了什么感情，缺了还原那一步就只剩套话。"], ["“安能摧眉折腰”为什么是主旨", "结尾两句是全诗唯一的直接表态，前面梦境越瑰丽、反衬现实越黑暗；问主旨、问情感就落在这两句上，答“追求个性解放、蔑视权贵”，再回扣梦境铺垫。"], ["古体诗的句式怎么答", "本诗以七言为基调，交错四言、五言、六言、九言，长短句随感情起落而变化；考句式就答“句式灵活多变、浑然一体”，别只说“七言古诗”四个字。"]], "vgaokao": []}}, "chn_c014": {"name": "琵琶行并序", "sec": 2, "secTitle": "第8课", "page": 62, "desc": "白居易的长篇叙事诗：三段音乐描写与「同是天涯沦落人」。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《琵琶行》中点明全诗主旨的句子。", "answer": "同是天涯沦落人，相逢何必曾相识。"}, "pre": ["chn_c013"], "next": ["chn_c015"], "content": {"advance": {"a": "身份的平行：琵琶女由京城名伎沦为商人妇，年长色衰、门前冷落；诗人由京城官员贬为江州司马，谪居湿地。同为从繁华跌入冷落，所以一句「同是天涯沦落人」才能同时安放两个人的身世，诗的主旨也由同情她人扩至自伤自叹。", "kind": "self", "q": "为什么说「同是天涯沦落人，相逢何必曾相识」能同时概括诗人和琵琶女两个人？"}, "apply": [{"ans": 1, "opts": ["只强调声音大", "以急雨、私语、珠落玉盘等比喻化抽象音乐为可感形象，写尽乐声的起伏变化", "主要写演奏者的姿态", "说明诗人懂音乐理论"], "q": "「大弦嘈嘈如急雨，小弦切切如私语」等句写音乐的高明之处是（ ）", "why": "音乐描写题的标准答法：以声写声、以形喻声，调动通感让无形可感。"}, {"ans": 1, "opts": ["交代琵琶女的住址", "序交代了贬谪背景与创作缘起，使正文的同情与自伤有现实根基", "序是凑字数的", "序与诗无关"], "q": "诗前小序的作用是（ ）", "why": "长篇叙事诗的序常交代时间、地点、缘起，是理解正文情感的钥匙。"}], "basics": [{"ans": 1, "opts": ["元稹", "白居易", "杜甫", "李商隐"], "q": "《琵琶行》的作者是（ ）", "why": "白居易与元稹并称「元白」，同为新乐府运动倡导者；本诗与《长恨歌》同为其长篇名作。"}, {"ans": 1, "opts": ["琵琶女的丈夫", "诗人谪居江州时送客，闻琵琶声而结识的演奏者琵琶女", "宫廷乐师", "诗人的妻子"], "q": "诗题中的「行」与主人公关系正确的是（ ）", "why": "《琵琶行》是乐府歌行体：主人公是琵琶女，诗人是听者兼自伤者。"}], "case": {"a": "三段：未成曲调先有情的蓄势段（调弦动作与情感外露）；大弦小弦交错的演奏高潮段（由急雨到私语再到珠落玉盘，声情渐强）；冰泉冷涩弦凝绝、银瓶乍破的转折终结段（先抑至无声，再爆发出裂帛之响），以「此时无声胜有声」为情绪顶点。", "q": "把诗中琵琶演奏的描写按节奏变化分成三段，各写一句概括。", "title": "案例：音乐三段论"}, "intro": "**白居易**的长篇叙事诗，与《长恨歌》并称。==三大考点：音乐描写、琵琶女自叙身世、主旨句的由来。==诗前有**序**，交代元和十一年诗人被贬江州司马、浔阳江头夜送客的来由。", "learn": [{"h": "结构：闻声—见人—自叙—感同", "p": "全诗推进：江头送客闻琵琶→千呼万唤请出琵琶女→第一段演奏→琵琶女自叙身世（京城名伎、年老嫁商）→第二段演奏→诗人自陈贬谪之叹→主旨句收束。每一步都靠琵琶声承转，这是叙事诗的**线索结构**，比单纯的时间顺序更有情感逻辑。"}, {"h": "音乐描写：以声写声", "p": "「大弦嘈嘈如急雨，小弦切切如私语。嘈嘈切切错杂弹，大珠小珠落玉盘」用生活之声比乐声；「间关莺语花底滑，幽咽泉流冰下难」再转涩滞；「银瓶乍破水浆迸，铁骑突出刀枪鸣」终至爆发；中间「别有幽愁暗恨生，此时无声胜有声」以静衬动。==音乐描写题永远答这四样：比喻通感、节奏变化、演奏者情感、听众反应。=="}, {"h": "主旨句的份量", "p": "「同是天涯沦落人，相逢何必曾相识」之所以成为千古名句，在于它把同情推成了共情：诗人与琵琶女地位悬殊，却在「沦落」二字上相遇。诗人随后的自述（谪居卧病、苦竹黄茅）不是离题，而是让主旨句成立的另一半证据。"}], "pitfalls": ["默写高频错字：「枫叶荻花」的「荻」读 dí；「呕哑嘲哳」四字最易写错；「钿头银篦」的「篦」不要写成「蓖」。", "只分析琵琶女，漏掉诗人自身的贬谪之悲，主旨就少了一半。", "把「同是天涯沦落人」的「沦落」理解成道德堕落，它是漂泊沦落的处境义。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 13, "t": "李杜白三篇", "dur": "25:23", "from": "名师课堂", "vtop": ["“梦游”是贯穿全诗的主线：梦前（海客谈瀛洲至对此欲倒东南倾）、梦中（我欲因之梦吴越至仙之人兮列如麻）、梦后（忽魂悸以魄动至篇末），做题先按三段切分再找手法。", "全诗主旨落在结尾“安能摧眉折腰事权贵，使我不得开心颜”：追求个性解放、蔑视权贵，前面所有瑰丽梦境都是为这一句铺垫。", "浪漫主义两大招：神奇的想象（民间传说、神话、梦境）加 大胆的夸张（天姥之高、仙人盛会），夸张总与具体事物结合、自然不露痕迹。"], "vsum": "本课只讲《梦游天姥吟留别》一篇。《登高》《琵琶行》不在本视频内，在合集 P14（cid 818559059），后续补。开场先定李白的地位：诗仙，继屈原之后又一位伟大的浪漫主义诗人，杜甫说他的诗是“笔落惊风雨，诗成泣鬼神”。本课三个目标：一是**知人论世**，把握诗歌内涵、理解李白的精神境界；二是诵读涵咏，品味诗中神奇瑰丽的诗境、认识李白豪迈飘逸的诗风；三是体察李白对社会与人生的思考。先**解题**：“吟”本指吟咏、作诗，后来成为乐府歌行体的一种诗体名称；“留别”是临行前留下这首诗向朋友话别；全题的意思就是用梦游天姥的诗向朋友话别，别名《梦游天姥山别东鲁诸公》。旧诗分古体和近体，唐人把新出现的格律诗叫近体诗，把唐以前较少格律限制的叫古体诗，《梦游天姥吟留别》是古体诗。接着落实读音和特殊句式，圈出天姥、瀛洲、渌水、澹澹、霹雳等易读错的字。再把握全诗脉络：**“梦游”是贯穿全诗的主线**，开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，从“忽魂悸以魄动”到篇末是梦后。本诗最突出的特点是浪漫主义的艺术特色，即神奇的想象和大胆的夸张：想象有来源于民间传说的（如仙境的种种细节），也有出于诗人个性爱好的（如“湖月照我影，送我至剡溪”，跟“举杯邀明月，对影成三人”一样，是把月看成最亲密的朋友）；夸张不是简单的放大，而是融合着诗人的感情，如开头写天姥山横空出世的雄姿，里面就含着诗人对天姥山的景仰和向往。**写作背景**：李白字太白，号青莲居士，一生最重要的活动在开元盛世，怀着济苍生、安社稷的政治理想，希望有一番作为。天宝二年因朋友吴筠推荐被唐玄宗召入长安，做了翰林供奉，这时他已 42 岁。本想借此施展才能，却只得了一个侍从闲职，没有被重用，又因一身傲骨不肯与权贵同流合污、得罪了权贵，在长安仅住了一年多就被赐金放还，政治上的失败使他心情苦闷，也让他看清了封建统治者的荒淫腐朽。被排挤出长安的第二年，即天宝四年，李白准备由东鲁南游吴越，行前写了这首向朋友表明自己心志的诗。李白诗歌的浪漫主义手法有三点：一是善于凭借想象，以主观现客观，现实事物、自然景观、神话传说、历史典故、梦中幻境无不成为想象的媒介，常借助想象超越时空，把现实与梦境、自然界与人类社会交织一体；二是把**拟人与比喻**巧妙结合，以情寓物、将物比人；三是抓住事物某一特点，在生活真实的基础上大胆想象夸张，夸张得自然不露痕迹、大胆又真实可信，有时还把夸张与鲜明对比结合，通过加大艺术反差加强效果。李白最擅长的体裁是七言歌行和绝句，七言歌行大开大合、跳跃跌宕，开头常突兀如狂飙骤起，中间形象转换疏忽、往往省略过渡照应，结尾都在感情高潮处戛然而止。**整体阅读**：抓住梦游主线，先读梦前。诗人借“海客谈瀛洲”衬托天姥山，瀛洲是海上仙山，写它也是为天姥山拢上一层神秘浪漫的色彩；接着着力写天姥山的高大，用的是夸张和对比。明朝王思任说天姥不过一小山峰，诗人竟写得如此气势巍峨——其实真正的天姥山并不高大，李白是用夸张、对比等手法描绘自己心中的天姥山，所谓“**一切景语皆情语**”，诗人的浪漫笔墨正是源自豪放胸襟。梦中分三幅画面：**月夜渡湖、著屐登山、仙人盛会**。诗人“一夜飞度镜湖月，湖月照我影，送我至剡溪”，渡过镜湖在月的映照下来到剡溪；“谢公宿处今尚在，渌水荡漾清猿啼”，相传南朝谢灵运到浙江永嘉任太守，喜遨游山水，伐木取径开辟了通往天姥的古道；诗人“脚著谢公屐，身登青云梯”，立在前人开拓的古道上展开想象。登山所见：“半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝”，所闻：“熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟”——连深林、层巅都能栗、能惊，烟、水、青云都满含幽郁，与诗人的情感融成一体。忽然“列缺霹雳，丘峦崩摧。洞天石扉，訇然中开”，梦境推向高潮：“青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。虎鼓瑟兮鸾回车，仙之人兮列如麻。”金台银台与日月交相辉映，仙人列队迎接诗人，这是全诗写景最辉煌灿烂的一段，也是人世间生活的反映：里面既有长期漫游经历过的万壑千山的印象、古代传说和屈原诗歌的启发，也有长安宫廷生活的记忆，全靠浪漫主义的非凡想象凝聚在一起。**梦后**只有七句：“忽魂悸以魄动，恍惊起而长嗟。惟觉时之枕席，失向来之烟霞。”梦已尽而思无穷，结尾落在“**安能摧眉折腰事权贵，使我不得开心颜**”——这才是全诗的主旨：诗人追求个性解放、蔑视权贵。老师提醒两点：一是“吟”多有悲愁慨叹之意；二是解读作品要了解作家的思想，李白既怀有儒家兼善天下的抱负，也有道家逍遥自在的情怀，表面看这是一首游仙诗，主体是神仙世界的描写，但他向往这个世界正是因为厌恶眼前黑暗的现实世界。全诗特点有二：一是构思上富有浪漫主义色彩，突破了一般送别诗惜别伤离的老套，借留别表明自己蔑视权贵的政治态度，围绕一场由先的梦幻来构思，直到最后才落到蔑视权贵的主旨上，给幻想的驰骋开拓了广阔领域；二是句法上以七言为基调，交错运用四言、五言、六言、九言的句子，灵活多样却浑然一体，因为全诗有一条感情发展的脉络贯穿，诗句随感情起落而有长有短、节拍有急有缓。课堂小结引王思任的话：天姥攀缘入李白之梦，李白一做梦便吟诗，一吟诗就使得天姥山与天台山不分伯仲——李白写的是梦游，是用浪漫的艺术抒发对理想人生的热烈追求。课后作业：充满感情地诵读梦后部分，其中“安能摧眉折腰事权贵，使我不得开心颜”连读三遍；专题延伸推荐阅读《品中国文人·李白》。", "vtech": [["梦游三段怎么切", "先找梦的边界：开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，“忽魂悸以魄动”起是梦后；结构题、思路题先报三段再展开，别从头平铺直叙。"], ["夸张题的答法：先还原再说效果", "天姥山其实并不高大，李白用夸张、对比写心中之山；答题先说“诗人用夸张写……”，再说突出了什么、表达了什么感情，缺了还原那一步就只剩套话。"], ["“安能摧眉折腰”为什么是主旨", "结尾两句是全诗唯一的直接表态，前面梦境越瑰丽、反衬现实越黑暗；问主旨、问情感就落在这两句上，答“追求个性解放、蔑视权贵”，再回扣梦境铺垫。"], ["古体诗的句式怎么答", "本诗以七言为基调，交错四言、五言、六言、九言，长短句随感情起落而变化；考句式就答“句式灵活多变、浑然一体”，别只说“七言古诗”四个字。"]], "vgaokao": []}}, "chn_c015": {"name": "念奴娇·赤壁怀古", "sec": 1, "secTitle": "第9课 宋词三首", "page": 65, "desc": "苏轼豪放词的代表作：写景、怀古、抒怀三段与「樯橹」易错字。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《念奴娇·赤壁怀古》中写周瑜儒将风度的句子（含易错字）。", "answer": "羽扇纶巾，谈笑间，樯橹灰飞烟灭（「樯」不能写成「墙」，「纶」读 guān）"}, "pre": ["chn_c014"], "next": ["chn_c016"], "content": {"advance": {"a": "词人从怀古的豪情中忽然自嘲：周瑜三十四岁建功，自己四十七岁却功业无成（早生华发）。自嘲中藏着功业未就的感慨，但结尾以「人生如梦」自我开解，把感慨放下——豪放之中有旷达，不是纯然的失意。", "kind": "self", "q": "「多情应笑我，早生华发」是自嘲吗？结合苏轼的处境谈谈这句的感情层次。"}, "apply": [{"ans": 1, "opts": ["议论散文笔法", "借登临所见的壮阔江山引出赤壁古战场，把眼前景、历史人、词人情编织在一体", "只写了景物", "抄录了史书原文"], "q": "上阕写景的作用是（ ）", "why": "怀古词的通用结构：景是引子，景的壮阔正是为了衬出历史人物的风流与词人的感慨。"}, {"ans": 1, "opts": ["消极遁世，什么都无所谓", "在功业未就的感慨之上，以旷达自慰，仍葆有对人生的热爱与超脱", "真的认为人生如梦，准备出家", "对周瑜的嫉妒"], "q": "结尾「人生如梦，一尊还酹江月」的情感落点是（ ）", "why": "苏轼式的收束：感慨是真的，旷达也是真的，答题要写出这两层。"}], "basics": [{"ans": 1, "opts": ["李清照", "苏轼", "辛弃疾", "柳永"], "q": "《念奴娇·赤壁怀古》的作者是（ ）", "why": "苏轼是豪放派的开创者，本词与辛弃疾的词合称词坛双璧式的怀古名篇。"}, {"ans": 1, "opts": ["黄州赤壁（赤鼻矶）", "安徽赤壁", "湖北嘉鱼赤壁", "与赤壁之战完全无关"], "q": "词中怀古的赤壁，一般认为并非三国赤壁之战的原址，而是（ ）", "why": "苏轼明知此赤壁未必是古战场，「人道是」三字已留余地——怀古重在借景抒怀，不在考据。"}], "case": {"a": "以盛衬衰的横向对照：同写三国人物，周瑜写「小乔初嫁、雄姿英发」的得意，衬出的正是苏轼自己年近半百、功业未成的处境。衬托方向：以他人的年少功成，反衬自己的早生华发，感慨才有落差。", "q": "词中写周瑜「小乔初嫁了，雄姿英发」，对照诗人自己。请用一句话点明这种对照的作用。", "title": "案例：周瑜与苏轼"}, "intro": "**苏轼**豪放词的压卷之作，也是怀古词的模板。==三段看清它：上阕写景、下阕先怀古（周瑜）后抒怀（自嘲与旷达）。==默写最易翻车的一个词：「樯橹」，别写成「墙橹」。", "learn": [{"h": "上阕：大景与古迹", "p": "「大江东去，浪淘尽，千古风流人物」开篇即把时间拉长：江水淘尽的是人物，不变的是江山。继而落到此地：「乱石穿空，惊涛拍岸，卷起千堆雪」，三句写尽赤壁之险与江涛之势，「江山如画，一时多少豪杰」总收。==怀古词的结构密码：景越大，古人越显，词人的感慨越有根基。=="}, {"h": "下阕前半：遥想周瑜", "p": "写周瑜不写战阵，先写「小乔初嫁了，雄姿英发」，再到「羽扇纶巾，谈笑间，樯橹灰飞烟灭」——儒将的从容与战功一并写出。注意用字：「纶巾」的「纶」读 guān，是文士的头巾；「樯橹」指曹军战船的桅杆与船桨，代指曹军水师。"}, {"h": "下阕后半：笑我与江月", "p": "「故国神游，多情应笑我，早生华发」：词人自嘲多情、年华已老而功业无成（苏轼时年四十七，因乌台诗案贬黄州）。结尾「人生如梦，一尊还酹江月」把感慨化作旷达：人生短暂，唯江月永恒。情感结构：壮景—豪杰—自伤—旷达，四步是全词的骨。"}], "pitfalls": ["默写错字重灾区：「樯橹」误作「墙橹」；「一尊还酹江月」的「酹」误作「洒」；「早生华发」误作「早生花发」。", "把周瑜的形象答成纯粹的军事将领，漏掉「儒将风流」这层。", "整体风格说成婉约——本词是豪放派的代表作。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 15, "t": "宋词三首", "dur": "57:12", "from": "名师课堂", "vtop": ["念奴娇的豪放有三点：描绘壮丽之景（大江东去、乱石穿空、惊涛拍岸、卷起千堆雪，夸张加比喻）、刻画豪迈之人（周瑜羽扇纶巾、谈笑间樯橹灰飞烟灭，儒将风度）、表现壮志难酬又能自我解脱的放达（故国神游、多情应笑我、人生如梦、一尊还酹江月）。", "永遇乐全靠典故推进：孙权（千古江山、英雄无觅）、刘裕（斜阳草树、气吞万里如虎）、刘义隆（元嘉草草、封狼居胥、赢得仓皇北顾）、拓跋焘（佛狸祠下、一片神鸦社鼓）、廉颇（凭谁问、廉颇老矣、尚能饭否），每个典故先讲史实再讲用意，考典故题就按这个顺序答。", "两首词都是怀古抒怀，但词风不同：苏词潇洒疏朗、旷达超脱，不平之意最后能参悟平复；辛词多用典故、充满奋勇抗敌的热情与报国无门的悲哀，慷慨悲壮。"], "vsum": "本课由两段视频拼成：前 26 分钟是名师课堂讲《念奴娇·赤壁怀古》和《永遇乐·京口北固亭怀古》，后 31 分钟是语文老师倪文韬逐句精讲《声声慢》。三首词全讲到了，没有缺口。开场先定本课三个目标：一是鉴赏《念奴娇》雄浑壮阔的意境、分析周瑜形象、体会词人壮志难酬的情感、了解豪放风格；二是掌握《永遇乐》中典故的含义及作用、赏析其豪放风格；三是对比分析两首词，体会思想情感和艺术手法的异同。先讲《念奴娇》。**苏轼生平**：字子瞻，号东坡居士，眉州眉山人，北宋著名文学家、唐宋八大家之一。嘉祐二年进士，宋神宗时在杭州、密州、徐州、湖州等地任职，元丰三年因乌台诗案被贬为黄州团练副使；宋哲宗即位后任礼部郎中、翰林学士等职，又出知杭州、颍州、扬州、定州等地；晚年因新党执政被贬惠州、儋州，宋徽宗时获大赦北还、途中病逝常州。《念奴娇·赤壁怀古》写于宋神宗元丰五年七月，正是苏轼被贬黄州期间，抱负遭遇重挫、人身行动受限、内心极度彷徨苦闷，试图通过踏寻古迹、咏怀古人实现精神突围。**豪放特征**从四个方面赏析。写景句“乱石穿空”三句是现场写景：写山石用“穿”，写浪涛用“拍”，写出景物的动态美，表现山之奇峭高峻、水之汹涌澎湃；“卷起千堆雪”以雪比喻波涛，“千堆”是数量上的夸张，更写出波涛的气势；几种物象作用于视觉、听觉，视听结合，呈现出一个有声有色、富有动感、豪放壮阔的画面。人物塑造：“羽扇纶巾”写周瑜手持羽扇、头戴纶巾，通过描写人物典型装束塑造他的儒将形象；“谈笑间”写他指挥若定、从容不迫的大将风度；“樯橹灰飞烟灭”写强大的敌人在周瑜面前不堪一击，既写出辉煌战功，也写出潇洒风度、沉着性格。塑造人物还用了**衬托**：正衬如用“千古风流人物”“一时多少豪杰”陪衬周郎，反衬如以雄姿英发的周郎反衬早生华发的词人自我。周瑜 24 岁为将，人称周郎，性情温厚、精通音乐，34 岁与 28 岁的诸葛亮统帅孙刘联军，在赤壁大战中用火攻把 54 岁的曹操打得一败涂地，这样的人物在苏轼眼中当然值得向往。情感部分：上片写景开篇，感慨“江山如画，一时多少豪杰”，表现对时光流逝的感慨；下片“遥想公瑾当年，小乔初嫁了，雄姿英发”是咏史，写风流人物、战功卓越，表达对英雄豪杰的仰慕赞颂；结尾“故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月”转入抒怀：“故国神游”即神游故国，“多情应笑我”即应笑我多情，都是倒装；想到周瑜 34 岁便建立惊天动地的功业，而自己却贬谪在此、头发早白，相形之下无限感慨；头发变白是由于多情、不能忘情于世事，而这种自作多情仔细想来又可笑，于是“人生如梦”，不如借酒浇愁——“酹”是把酒倒在地上表示祭奠，这里却指对月敬酒，如李白月下独酌“举杯邀明月”之意，所邀乃江中月影，在地不在天。内容上这首词表现了作者用世与避世、入世与出世思想之间的矛盾，这是封建社会知识分子的普遍矛盾：没有机会为国为民做出一番事业，就只有在无可奈何的心情下寻求解脱。**豪放特征总结三点**：一是描绘壮丽之景，“大江东去”“乱石穿空”“卷起千堆雪”运用夸张、比喻，呈现广阔景致、宏大气魄；二是刻画豪迈之人，肯定周瑜在赤壁之战中的关键作用，赞颂其才华功勋，塑造指挥若定、从容不迫的儒将形象；三是表现词人壮志难酬又能自我解脱的放达，生不逢时、空有一腔抱负，壮志难酬不如在江月下举杯逍遥，在失落中找到了解脱。最后回顾念奴娇写景、咏史、抒情如何融为一体：先写山之奇峭、水之汹涌澎湃，联想江山如画、一时多少豪杰，为后文咏史刻画周瑜、续写赤壁之战场景做铺垫，同时表现对时光流逝的感慨；下片咏史抒情，回想周瑜指挥赤壁之战的场景，表达仰慕赞颂，再由周瑜想到自身，抒发壮志难酬之叹，同时寻求内心解脱。再讲《永遇乐》。**辛弃疾生平**：字幼安，号稼轩，历城人，南宋词人，出生时中原已为金兵所占，21 岁参加抗金义军，与党怀英齐名北方、号称“辛党”，青年时参与耿京起义、擒杀叛徒张安国回归南宋，献《美芹十论》等，历任江西、湖北、湖南转运使、安抚使等职，一生力主抗金，提出的抗金建议很少被采纳，还遭到主和派打压、长期落职闲居；其词艺术风格多样、以豪放为主，与苏轼并称“苏辛”。本词是辛弃疾 65 岁登临镇江北固亭所作，时为南宋开禧元年秋，当时韩侂胄把持朝政大权，企图用北伐中原来提高自己的声誉，于嘉泰三年启用闲居的抗金派代表辛弃疾，先任命为绍兴知府、浙东安抚使，次年调任镇江知府；镇江古名京口，素来是军事重镇，南宋时处于抗金前线。韩侂胄抗金的主张符合辛弃疾收复失地的一贯志愿，但韩侂胄在军事上准备并不充分，辛弃疾忧心忡忡，登临北固亭时览景有感。**以点入词是本词一大特色**，五个典故逐个讲。“千古江山，英雄无觅孙仲谋处”刻画孙权：词题为京口北固亭怀古，一开头就从镇江的历史人物孙权说起，孙权是三国时吴国皇帝，在南京建都、打垮北方的曹操、保卫了国家；如今江山如故却无处寻找像孙权那样的英雄，惋惜之余暗含无人可用的愤懑。“斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎”刻画刘裕：寄奴是南朝宋武帝刘裕的小字，刘裕在京口起兵讨伐桓玄、平定叛乱；斜阳照着草丛树木与普通街道，人们说刘裕曾在这里住过，回想当年他指挥强劲精良的兵马、气势如猛虎；从回顾刘裕生平揭示出寒门庶族、低微出身并不妨碍英雄建功立业，表达对古代英雄的赞叹，也暗含以英雄业绩鼓励鞭策自己、抗敌救国的心情。“元嘉草草，封狼居胥，赢得仓皇北顾”刻画刘义隆：元嘉是南朝宋文帝的年号，宋文帝刘义隆是刘裕的儿子，不能继承父业、好大喜功，听信王玄谟的北伐之策、打无准备之仗，结果一败涂地；“封狼居胥”讲汉朝霍去病战胜匈奴、在狼居胥山举行祭天大礼的故事，宋文帝听了王玄谟的大话、对臣下说“闻王玄谟言，使人有封狼居胥意”；词人借此表达对当时执政者急功近利、主张用兵而不做充分准备的警告。“可堪回首，佛狸祠下，一片神鸦社鼓”刻画拓跋焘：拓跋焘小字佛狸，属鲜卑族，击败刘宋军队后率追兵直达长江北岸的瓜步山、在山上建立行宫，就是后来的佛狸祠；当地老百姓年年在佛狸祠下迎神赛会，神鸦是吃祭品的乌鸦、社鼓是祭神的鼓声；词人感叹往事怎忍再回顾，如今佛狸祠香火正盛，而江北各地沦陷已久，不迅速谋求恢复的话，民众安于异族统治、忘记自己是宋氏臣民，借此提醒人们不要忘记江北仍处在金人铁蹄之下、不要忘记收复故土，表达对南宋统治者苟安、不思收复失地的悲愤。“凭谁问：廉颇老矣，尚能饭否”刻画廉颇：又谁来问廉颇将军老了、饭量还好吗？廉颇虽老还想为赵王所用，在赵王使者面前一顿吃了一斗米做的饭、十斤肉，又披甲上马表示自己尚有余勇；诗人联想自己，并不如廉颇老迈、却没有人来过问，这里运用典故、以廉颇自比，表示仍能为国效力，同时抒发报国无门、壮志难酬之愤。有人批评辛弃疾的词“掉书袋”，岳飞的孙子岳珂说“用事多是这首词的毛病”，这是不恰当的批评：这首词所用的故事除了末尾廉颇一事以外，都是有关镇江的史实，眼前风光是京口怀古这个题目应有的内容，且都和词的思想感情密切相连；就艺术手法论，围绕作品的思想内容使用许多史事，以加强作品的说服力和感染力，在词里是不多见的，这正是这首词的长处。**对比鉴赏**：用典上，苏词以精细笔墨集中塑造儒雅倜傥、击败强曹的青年将领周瑜，渲染其显赫功业、横溢才华时又巧妙点染他温文尔雅的风度和幸福美满的婚姻，以一个特写镜头“谈笑间，樯橹灰飞烟灭”现出军事统帅风度翩翩、气宇轩昂、运筹帷幄、指挥若定的儒将风范；辛词上片写孙权、刘裕两人，不像苏词那样亲比于人物的音容笑貌、神情风采，而是侧重于史实的铺叙，下片写刘义隆急于求成、仓促北伐，只落得仓皇北顾的下场，沉重追溯惨痛的历史教训，道古以讽今、告诫当政者谨慎用兵、免蹈前车之辙，末尾廉颇渴望为国出力、却报国无门，词人以己自比。借景抒情上，念奴娇集中写景、浓墨重彩，“乱石”写形状之雄奇、“惊涛”写声音之汹涌、“卷起千堆雪”写色彩之磅礴，绘出一幅雄浑壮丽的江山图；永遇乐没有纯粹的景物描写，景物描写有机穿插在史实叙述中、次第出现，都是淡笔勾勒，开篇景物大至江山、小至舞榭歌台、斜阳草树，浅墨淡彩、不着点缀，纯客观的轻描淡写，意在暗示事过境迁、物是人非。词风上，苏词偏于潇洒疏朗、旷达超脱，词中的不平之意最后能通过对人生的参悟逐渐平复，因而读到乐观旷达；辛词喜欢用典，充满奋勇抗敌的热情和报国无门的悲哀，给人慷慨悲壮之感。相同点是境界开阔、感情豪放，都借古人抒怀。最后一段是倪文韬讲《声声慢》。先逐句讲字面意思：开篇“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”是七组十四个叠字连用，非常打破常规，历来诗论家词论家都赞叹“精妙出奇”；“寻寻觅觅”展现似乎在寻找什么的彷徨、空虚、迷茫的心理状态，“冷冷清清”既是外部环境的凄清，也是体感上的冷表达内心世界的清冷，“凄”有寒冷、悲伤、静寂三种意思，“惨”是程度极深的悲伤、“戚”是忧愁悲哀，三个字意思相近、通过叠词连在一起，把感伤忧愁的情绪渲染得非常浓烈。“乍暖还寒时候，最难将息”：“将息”是调养、休息的意思，乍暖还寒的时节最难将息，因为气温不稳定、很容易生病；“乍暖还寒”究竟是什么时候？课下注解给的是忽冷忽热、天气变化无常，一般指由冬入春（“乍”是刚刚、起初，“还”是又回到：刚刚天气热起来、又回到了寒冷，就是春寒），但本词后面有“雁过也”“满地黄花堆积”，黄花是秋天开的菊花、大雁秋冬南飞，似乎更像由秋入冬；不过大雁春天北归时也能看到，春天也有迎春花这样的黄花，所以由秋入冬还是由冬入春都可以，不必死抠。字面意思讲完（约 37 分钟）进入两个重点：一是**内容情感层面**，这首词当然表现的是愁情（“这次第，怎一个愁字了得”），但究竟是怎样的愁、愁从何而来、愁到了什么程度，值得仔细玩味；这是李清照的晚期作品，正是作者最为抑郁痛苦的时期，要了解这愁从何而来、自然要考察李清照的人生经历——她出生在和平年代，年轻时婚姻美满、生活安逸，父亲李格非是礼部员外郎、后做吏部侍郎，公公是宰相赵挺之，夫妻二人都是高干子弟，曾经度过一段非常安逸美满的生活，一个经历过盛世再进入乱世的人，那种生命体验与出生在乱世的人完全不同；二是**创作技巧层面**，重点分析开篇十四个叠字：从声调看，平声昂扬、去声分明、入声短促，如“寻寻觅觅”第二声、第四声、阳平到去声，阳平有升起的感觉；“凄凄”后边的“凄”都是擦音，念的时候给人哽咽的感觉；这十四个字不仅在声调上一扬顿挫、不流于呆板繁复，而且能暗示情绪流动的状态。李清照填词对声律要求极其严格，这正是她“词别是一家”的词学观。课末老师预告下期讲《窦娥冤》。", "vtech": [["典故题三步答法", "先说典故讲的是谁、什么事（如刘义隆元嘉北伐、封狼居胥），再说词人借它说什么（告诫当政者谨慎用兵），最后落到情感（忧愤、讽谏）；只讲故事不讲用意，等于白写。"], ["对比鉴赏先列不同再说相同", "用典不同（苏词集中写一人、辛词连用五典）、写景不同（苏词浓墨重彩、辛词淡笔勾勒）、词风不同（旷达超脱 vs 慷慨悲壮）；相同点是境界开阔、感情豪放、都借古人抒怀。"], ["“故国神游，多情应笑我”怎么断句讲", "故国神游即神游故国，多情应笑我即应笑我多情，都是倒装；情感是联想自身、壮志难酬，又转念以江月举杯求解脱，答题要把“感慨—解脱”两层都说到。"], ["叠字题抓声音和情绪", "声声慢开篇七组十四个叠字连用，寻寻觅觅写彷徨迷茫、冷冷清清写内外清冷、凄凄惨惨戚戚把悲愁渲染到极致；再看声调，平声昂扬、去声分明、入声短促、擦音哽咽，声音本身就在传情绪。"]], "vgaokao": []}}, "chn_c016": {"name": "永遇乐·京口北固亭怀古", "sec": 1, "secTitle": "第9课 宋词三首", "page": 66, "desc": "辛弃疾用典最密的一首词：五典连用，典典有现实指向。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《永遇乐》中刘裕的典故是哪两句？寄奴是何人？", "answer": "想当年，金戈铁马，气吞万里如虎；寄奴即南朝宋武帝刘裕的小名。"}, "pre": ["chn_c015"], "next": ["chn_c017"], "content": {"advance": {"a": "廉颇年老仍能饭，仍想为国所用却遭谗言所阻。辛弃疾时年六十六，自比廉颇：既有廉颇的壮心与能力，又怕落得廉颇被弃的下场——既是自许，也是忧惧，更是对当权者的反问。这一个典故里叠了三层心理。", "kind": "self", "q": "结尾用廉颇之典，一共叠了几层意思？逐层说说。"}, "apply": [{"ans": 1, "opts": ["纯粹歌颂刘裕", "以刘裕北伐建功的盛事，反衬南宋偏安、无人北伐的现状，表达收复失地的渴望", "与主题无关的闲笔", "历史知识展示"], "q": "上阕用刘裕（寄奴）之典的作用是（ ）", "why": "怀古词用典多为对照：以昔盛衬今衰，典故的方向感是得分点。"}, {"ans": 1, "opts": ["说明典故用得越多越好", "五典连用而各有指向：赞孙权、慕刘裕、戒刘义隆、哀佛狸祠、比廉颇，词意全靠典的密度推进", "典故都是炫耀学问", "典故与情感无关"], "q": "下阕连用刘义隆、佛狸祠、廉颇三典，表明本词用典的特点是（ ）", "why": "本词被称为用典的极致：典多不乱，因为每个典都有明确的情感任务。"}], "basics": [{"ans": 1, "opts": ["苏轼", "辛弃疾", "陆游", "岳飞"], "q": "《永遇乐·京口北固亭怀古》的作者是（ ）", "why": "辛弃疾是南宋豪放派词人，一生力主北伐抗金，本词作于他镇守京口之时。"}, {"ans": 1, "opts": ["佛教寺庙", "北魏太武帝拓跋焘的行宫，后成祭祀之所，词中指金人侵占之地的象征", "一位将军的名字", "一座山峰"], "q": "「佛狸祠」指的是（ ）", "why": "佛狸是拓跋焘的小名；词中写其祠下香火旺盛，反衬南宋百姓已安于异族统治遗迹，刺痛人心。注意「佛」在此读 bì。"}], "case": {"a": "刘义隆（元嘉草草）：急于北伐、轻启兵端而大败——讽喻当时主政者贸然北伐的危险。廉颇：老将能饭而见疑不用——词人自况，壮志难酬的忧惧。两典一戒人一戒己，方向不同，合起来是「北伐须谨慎，人才须重用」的完整主张。", "q": "从下阕三典中任选两个，分别写出它们对现实的指向。", "title": "案例：典故对位表"}, "intro": "**辛弃疾**六十六岁登北固亭之作，用典密度为宋词之最。==学习目标只有一个：把五个典故逐个对位——赞谁、戒谁、讽谁、比谁。==", "learn": [{"h": "上阕：两典两态度", "p": "孙仲谋（孙权）：在京口建都称帝、抵抗曹军——「千古江山，英雄无觅，孙仲谋处」，先立一个英雄的标高。刘裕（寄奴）：在京口起兵、北伐建功，「想当年，金戈铁马，气吞万里如虎」写尽其盛。两典共同指向：此地曾经出过英雄与功业——反衬当今无人。"}, {"h": "下阕：三典三指向", "p": "刘义隆「元嘉草草，封狼居胥，赢得仓皇北顾」：好大喜功、草草北伐而败，戒当权者轻举妄动。佛狸祠：拓跋焘南侵所建行宫，如今香火旺盛，百姓安于其下——写沦陷之痛与偏安之哀。廉颇：结尾自比，「廉颇老矣，尚能饭否」，壮心未已而疑虑丛生。==五典各有表：颂、慕、戒、哀、比，默记这五个字就抓住了全词。=="}, {"h": "用典的鉴赏答法", "p": "高考用典题的固定三问：何典、何意、何情。作答模板：先指出典故人物与出处，再说词中用它表达的现实指向，最后落到词人情感。本词是练习这一模板的最佳材料：任何一句都能拆出完整的一道题。"}], "pitfalls": ["「佛狸」的「佛」读 bì 不读 fó；「烽火扬州路」的「烽」不要漏写。", "典故张冠李戴：封狼居胥本是霍去病的典故，词中借指刘义隆想学霍去病却落得「仓皇北顾」。", "把用典简单答成「增加了文学性」，不写现实指向。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 15, "t": "宋词三首", "dur": "57:12", "from": "名师课堂", "vtop": ["念奴娇的豪放有三点：描绘壮丽之景（大江东去、乱石穿空、惊涛拍岸、卷起千堆雪，夸张加比喻）、刻画豪迈之人（周瑜羽扇纶巾、谈笑间樯橹灰飞烟灭，儒将风度）、表现壮志难酬又能自我解脱的放达（故国神游、多情应笑我、人生如梦、一尊还酹江月）。", "永遇乐全靠典故推进：孙权（千古江山、英雄无觅）、刘裕（斜阳草树、气吞万里如虎）、刘义隆（元嘉草草、封狼居胥、赢得仓皇北顾）、拓跋焘（佛狸祠下、一片神鸦社鼓）、廉颇（凭谁问、廉颇老矣、尚能饭否），每个典故先讲史实再讲用意，考典故题就按这个顺序答。", "两首词都是怀古抒怀，但词风不同：苏词潇洒疏朗、旷达超脱，不平之意最后能参悟平复；辛词多用典故、充满奋勇抗敌的热情与报国无门的悲哀，慷慨悲壮。"], "vsum": "本课由两段视频拼成：前 26 分钟是名师课堂讲《念奴娇·赤壁怀古》和《永遇乐·京口北固亭怀古》，后 31 分钟是语文老师倪文韬逐句精讲《声声慢》。三首词全讲到了，没有缺口。开场先定本课三个目标：一是鉴赏《念奴娇》雄浑壮阔的意境、分析周瑜形象、体会词人壮志难酬的情感、了解豪放风格；二是掌握《永遇乐》中典故的含义及作用、赏析其豪放风格；三是对比分析两首词，体会思想情感和艺术手法的异同。先讲《念奴娇》。**苏轼生平**：字子瞻，号东坡居士，眉州眉山人，北宋著名文学家、唐宋八大家之一。嘉祐二年进士，宋神宗时在杭州、密州、徐州、湖州等地任职，元丰三年因乌台诗案被贬为黄州团练副使；宋哲宗即位后任礼部郎中、翰林学士等职，又出知杭州、颍州、扬州、定州等地；晚年因新党执政被贬惠州、儋州，宋徽宗时获大赦北还、途中病逝常州。《念奴娇·赤壁怀古》写于宋神宗元丰五年七月，正是苏轼被贬黄州期间，抱负遭遇重挫、人身行动受限、内心极度彷徨苦闷，试图通过踏寻古迹、咏怀古人实现精神突围。**豪放特征**从四个方面赏析。写景句“乱石穿空”三句是现场写景：写山石用“穿”，写浪涛用“拍”，写出景物的动态美，表现山之奇峭高峻、水之汹涌澎湃；“卷起千堆雪”以雪比喻波涛，“千堆”是数量上的夸张，更写出波涛的气势；几种物象作用于视觉、听觉，视听结合，呈现出一个有声有色、富有动感、豪放壮阔的画面。人物塑造：“羽扇纶巾”写周瑜手持羽扇、头戴纶巾，通过描写人物典型装束塑造他的儒将形象；“谈笑间”写他指挥若定、从容不迫的大将风度；“樯橹灰飞烟灭”写强大的敌人在周瑜面前不堪一击，既写出辉煌战功，也写出潇洒风度、沉着性格。塑造人物还用了**衬托**：正衬如用“千古风流人物”“一时多少豪杰”陪衬周郎，反衬如以雄姿英发的周郎反衬早生华发的词人自我。周瑜 24 岁为将，人称周郎，性情温厚、精通音乐，34 岁与 28 岁的诸葛亮统帅孙刘联军，在赤壁大战中用火攻把 54 岁的曹操打得一败涂地，这样的人物在苏轼眼中当然值得向往。情感部分：上片写景开篇，感慨“江山如画，一时多少豪杰”，表现对时光流逝的感慨；下片“遥想公瑾当年，小乔初嫁了，雄姿英发”是咏史，写风流人物、战功卓越，表达对英雄豪杰的仰慕赞颂；结尾“故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月”转入抒怀：“故国神游”即神游故国，“多情应笑我”即应笑我多情，都是倒装；想到周瑜 34 岁便建立惊天动地的功业，而自己却贬谪在此、头发早白，相形之下无限感慨；头发变白是由于多情、不能忘情于世事，而这种自作多情仔细想来又可笑，于是“人生如梦”，不如借酒浇愁——“酹”是把酒倒在地上表示祭奠，这里却指对月敬酒，如李白月下独酌“举杯邀明月”之意，所邀乃江中月影，在地不在天。内容上这首词表现了作者用世与避世、入世与出世思想之间的矛盾，这是封建社会知识分子的普遍矛盾：没有机会为国为民做出一番事业，就只有在无可奈何的心情下寻求解脱。**豪放特征总结三点**：一是描绘壮丽之景，“大江东去”“乱石穿空”“卷起千堆雪”运用夸张、比喻，呈现广阔景致、宏大气魄；二是刻画豪迈之人，肯定周瑜在赤壁之战中的关键作用，赞颂其才华功勋，塑造指挥若定、从容不迫的儒将形象；三是表现词人壮志难酬又能自我解脱的放达，生不逢时、空有一腔抱负，壮志难酬不如在江月下举杯逍遥，在失落中找到了解脱。最后回顾念奴娇写景、咏史、抒情如何融为一体：先写山之奇峭、水之汹涌澎湃，联想江山如画、一时多少豪杰，为后文咏史刻画周瑜、续写赤壁之战场景做铺垫，同时表现对时光流逝的感慨；下片咏史抒情，回想周瑜指挥赤壁之战的场景，表达仰慕赞颂，再由周瑜想到自身，抒发壮志难酬之叹，同时寻求内心解脱。再讲《永遇乐》。**辛弃疾生平**：字幼安，号稼轩，历城人，南宋词人，出生时中原已为金兵所占，21 岁参加抗金义军，与党怀英齐名北方、号称“辛党”，青年时参与耿京起义、擒杀叛徒张安国回归南宋，献《美芹十论》等，历任江西、湖北、湖南转运使、安抚使等职，一生力主抗金，提出的抗金建议很少被采纳，还遭到主和派打压、长期落职闲居；其词艺术风格多样、以豪放为主，与苏轼并称“苏辛”。本词是辛弃疾 65 岁登临镇江北固亭所作，时为南宋开禧元年秋，当时韩侂胄把持朝政大权，企图用北伐中原来提高自己的声誉，于嘉泰三年启用闲居的抗金派代表辛弃疾，先任命为绍兴知府、浙东安抚使，次年调任镇江知府；镇江古名京口，素来是军事重镇，南宋时处于抗金前线。韩侂胄抗金的主张符合辛弃疾收复失地的一贯志愿，但韩侂胄在军事上准备并不充分，辛弃疾忧心忡忡，登临北固亭时览景有感。**以点入词是本词一大特色**，五个典故逐个讲。“千古江山，英雄无觅孙仲谋处”刻画孙权：词题为京口北固亭怀古，一开头就从镇江的历史人物孙权说起，孙权是三国时吴国皇帝，在南京建都、打垮北方的曹操、保卫了国家；如今江山如故却无处寻找像孙权那样的英雄，惋惜之余暗含无人可用的愤懑。“斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎”刻画刘裕：寄奴是南朝宋武帝刘裕的小字，刘裕在京口起兵讨伐桓玄、平定叛乱；斜阳照着草丛树木与普通街道，人们说刘裕曾在这里住过，回想当年他指挥强劲精良的兵马、气势如猛虎；从回顾刘裕生平揭示出寒门庶族、低微出身并不妨碍英雄建功立业，表达对古代英雄的赞叹，也暗含以英雄业绩鼓励鞭策自己、抗敌救国的心情。“元嘉草草，封狼居胥，赢得仓皇北顾”刻画刘义隆：元嘉是南朝宋文帝的年号，宋文帝刘义隆是刘裕的儿子，不能继承父业、好大喜功，听信王玄谟的北伐之策、打无准备之仗，结果一败涂地；“封狼居胥”讲汉朝霍去病战胜匈奴、在狼居胥山举行祭天大礼的故事，宋文帝听了王玄谟的大话、对臣下说“闻王玄谟言，使人有封狼居胥意”；词人借此表达对当时执政者急功近利、主张用兵而不做充分准备的警告。“可堪回首，佛狸祠下，一片神鸦社鼓”刻画拓跋焘：拓跋焘小字佛狸，属鲜卑族，击败刘宋军队后率追兵直达长江北岸的瓜步山、在山上建立行宫，就是后来的佛狸祠；当地老百姓年年在佛狸祠下迎神赛会，神鸦是吃祭品的乌鸦、社鼓是祭神的鼓声；词人感叹往事怎忍再回顾，如今佛狸祠香火正盛，而江北各地沦陷已久，不迅速谋求恢复的话，民众安于异族统治、忘记自己是宋氏臣民，借此提醒人们不要忘记江北仍处在金人铁蹄之下、不要忘记收复故土，表达对南宋统治者苟安、不思收复失地的悲愤。“凭谁问：廉颇老矣，尚能饭否”刻画廉颇：又谁来问廉颇将军老了、饭量还好吗？廉颇虽老还想为赵王所用，在赵王使者面前一顿吃了一斗米做的饭、十斤肉，又披甲上马表示自己尚有余勇；诗人联想自己，并不如廉颇老迈、却没有人来过问，这里运用典故、以廉颇自比，表示仍能为国效力，同时抒发报国无门、壮志难酬之愤。有人批评辛弃疾的词“掉书袋”，岳飞的孙子岳珂说“用事多是这首词的毛病”，这是不恰当的批评：这首词所用的故事除了末尾廉颇一事以外，都是有关镇江的史实，眼前风光是京口怀古这个题目应有的内容，且都和词的思想感情密切相连；就艺术手法论，围绕作品的思想内容使用许多史事，以加强作品的说服力和感染力，在词里是不多见的，这正是这首词的长处。**对比鉴赏**：用典上，苏词以精细笔墨集中塑造儒雅倜傥、击败强曹的青年将领周瑜，渲染其显赫功业、横溢才华时又巧妙点染他温文尔雅的风度和幸福美满的婚姻，以一个特写镜头“谈笑间，樯橹灰飞烟灭”现出军事统帅风度翩翩、气宇轩昂、运筹帷幄、指挥若定的儒将风范；辛词上片写孙权、刘裕两人，不像苏词那样亲比于人物的音容笑貌、神情风采，而是侧重于史实的铺叙，下片写刘义隆急于求成、仓促北伐，只落得仓皇北顾的下场，沉重追溯惨痛的历史教训，道古以讽今、告诫当政者谨慎用兵、免蹈前车之辙，末尾廉颇渴望为国出力、却报国无门，词人以己自比。借景抒情上，念奴娇集中写景、浓墨重彩，“乱石”写形状之雄奇、“惊涛”写声音之汹涌、“卷起千堆雪”写色彩之磅礴，绘出一幅雄浑壮丽的江山图；永遇乐没有纯粹的景物描写，景物描写有机穿插在史实叙述中、次第出现，都是淡笔勾勒，开篇景物大至江山、小至舞榭歌台、斜阳草树，浅墨淡彩、不着点缀，纯客观的轻描淡写，意在暗示事过境迁、物是人非。词风上，苏词偏于潇洒疏朗、旷达超脱，词中的不平之意最后能通过对人生的参悟逐渐平复，因而读到乐观旷达；辛词喜欢用典，充满奋勇抗敌的热情和报国无门的悲哀，给人慷慨悲壮之感。相同点是境界开阔、感情豪放，都借古人抒怀。最后一段是倪文韬讲《声声慢》。先逐句讲字面意思：开篇“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”是七组十四个叠字连用，非常打破常规，历来诗论家词论家都赞叹“精妙出奇”；“寻寻觅觅”展现似乎在寻找什么的彷徨、空虚、迷茫的心理状态，“冷冷清清”既是外部环境的凄清，也是体感上的冷表达内心世界的清冷，“凄”有寒冷、悲伤、静寂三种意思，“惨”是程度极深的悲伤、“戚”是忧愁悲哀，三个字意思相近、通过叠词连在一起，把感伤忧愁的情绪渲染得非常浓烈。“乍暖还寒时候，最难将息”：“将息”是调养、休息的意思，乍暖还寒的时节最难将息，因为气温不稳定、很容易生病；“乍暖还寒”究竟是什么时候？课下注解给的是忽冷忽热、天气变化无常，一般指由冬入春（“乍”是刚刚、起初，“还”是又回到：刚刚天气热起来、又回到了寒冷，就是春寒），但本词后面有“雁过也”“满地黄花堆积”，黄花是秋天开的菊花、大雁秋冬南飞，似乎更像由秋入冬；不过大雁春天北归时也能看到，春天也有迎春花这样的黄花，所以由秋入冬还是由冬入春都可以，不必死抠。字面意思讲完（约 37 分钟）进入两个重点：一是**内容情感层面**，这首词当然表现的是愁情（“这次第，怎一个愁字了得”），但究竟是怎样的愁、愁从何而来、愁到了什么程度，值得仔细玩味；这是李清照的晚期作品，正是作者最为抑郁痛苦的时期，要了解这愁从何而来、自然要考察李清照的人生经历——她出生在和平年代，年轻时婚姻美满、生活安逸，父亲李格非是礼部员外郎、后做吏部侍郎，公公是宰相赵挺之，夫妻二人都是高干子弟，曾经度过一段非常安逸美满的生活，一个经历过盛世再进入乱世的人，那种生命体验与出生在乱世的人完全不同；二是**创作技巧层面**，重点分析开篇十四个叠字：从声调看，平声昂扬、去声分明、入声短促，如“寻寻觅觅”第二声、第四声、阳平到去声，阳平有升起的感觉；“凄凄”后边的“凄”都是擦音，念的时候给人哽咽的感觉；这十四个字不仅在声调上一扬顿挫、不流于呆板繁复，而且能暗示情绪流动的状态。李清照填词对声律要求极其严格，这正是她“词别是一家”的词学观。课末老师预告下期讲《窦娥冤》。", "vtech": [["典故题三步答法", "先说典故讲的是谁、什么事（如刘义隆元嘉北伐、封狼居胥），再说词人借它说什么（告诫当政者谨慎用兵），最后落到情感（忧愤、讽谏）；只讲故事不讲用意，等于白写。"], ["对比鉴赏先列不同再说相同", "用典不同（苏词集中写一人、辛词连用五典）、写景不同（苏词浓墨重彩、辛词淡笔勾勒）、词风不同（旷达超脱 vs 慷慨悲壮）；相同点是境界开阔、感情豪放、都借古人抒怀。"], ["“故国神游，多情应笑我”怎么断句讲", "故国神游即神游故国，多情应笑我即应笑我多情，都是倒装；情感是联想自身、壮志难酬，又转念以江月举杯求解脱，答题要把“感慨—解脱”两层都说到。"], ["叠字题抓声音和情绪", "声声慢开篇七组十四个叠字连用，寻寻觅觅写彷徨迷茫、冷冷清清写内外清冷、凄凄惨惨戚戚把悲愁渲染到极致；再看声调，平声昂扬、去声分明、入声短促、擦音哽咽，声音本身就在传情绪。"]], "vgaokao": []}}, "chn_c017": {"name": "声声慢（寻寻觅觅）", "sec": 1, "secTitle": "第9课 宋词三首", "page": 67, "desc": "李清照的叠字开篇与愁的递进：声声慢慢，字字是愁。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《声声慢》开篇的十四个叠字。", "answer": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚（最后一个是「戚戚」，不是「切切」）"}, "pre": ["chn_c016"], "next": [], "content": {"advance": {"a": "用叠字取声：寻寻觅觅的迟疑、冷冷清清的空寂、凄凄惨惨戚戚的悲苦，读音由平缓转入低回，如泣如诉。词人自觉声情可通：叠字先给耳朵定调，再给心情定调，是婉约词以声传情的高境。", "kind": "self", "q": "自古评家说《声声慢》妙在起笔十四叠字「作愁人之词，音韵最先入耳」。结合作品谈谈叠字在声音上的作用。"}, "apply": [{"ans": 1, "opts": ["四季景物的拼盘", "由景生情、由小见大：早晨的冷清—酒后的孤寂—雁、黄花、梧桐细雨层层堆积，最后总爆为一句「愁」", "纯粹的写景抒情散文", "与前文无关的结尾"], "q": "全词情感推进的结构特点是（ ）", "why": "李清照此词的情感是逐景累积、层层加压的，结尾一句总收——分析结构必须答出这条曲线。"}, {"ans": 1, "opts": ["全部用了典故", "意象多为日常小景：淡酒、孤雁、黄花、梧桐、细雨，无一壮景而愁意逼人", "意象越宏大愁越深", "没有意象"], "q": "本词意象选择的特点是（ ）", "why": "婉约词写深愁反用小景：意象的日常性与情感的极致性形成反差，是赏析的抓手。"}], "basics": [{"ans": 1, "opts": ["前期（南渡前）", "后期（南渡后）", "少女时期", "无法判断"], "q": "《声声慢》写于李清照人生的哪个阶段（ ）", "why": "词中有国破、家亡、夫死之痛，是南渡后晚景凄凉的代表作，与前期明快词风迥异。"}, {"ans": 1, "opts": ["高兴", "层层递进地渲染愁苦：从动作到环境到感受", "写景顺序的安排", "词人的口头禅"], "q": "开篇连用七组叠字的作用是（ ）", "why": "十四叠字从寻觅、无着到凄惨悲戚，是愁的三级推进，开篇即定全词声情。"}], "case": {"a": "三组：孤雁——「雁过也，正伤心，却是旧时相识」，雁是旧信使，今成伤心物，写孤独与今昔之感。黄花——「满地黄花堆积，憔悴损，如今有谁堪摘」，菊花憔悴如人，写自伤。梧桐细雨——「梧桐更兼细雨，到黄昏、点点滴滴」，以声写静、点滴入心，收束全篇的愁。", "q": "选出词中的三组意象（雁、黄花、梧桐细雨），各用一句话说明它们承载的愁情。", "title": "案例：意象三连"}, "intro": "**李清照**后期的代表作，词史以叠字名篇著称。==考点两条：十四叠字如何定调、日常意象如何叠出深愁。==背景是南渡之后：国破、家亡、夫死，三重打击全压在词里。", "learn": [{"h": "起笔：十四叠字的声情", "p": "「寻寻觅觅，冷冷清清，凄凄惨惨戚戚」：先写动作的无着（寻觅而不得），再写环境的空寂（冷冷清清），最后直抵内心的悲苦（凄凄惨惨戚戚）。==叠字题的答法：分层次——动作层、环境层、心理层，层层递进。==声韵上平仄相间、低回往复，未入正题已令人心酸。"}, {"h": "中段：意象的逐个加压", "p": "淡酒不敌晚风（孤弱）、雁过伤心（旧识今痛）、黄花堆积憔悴（自喻）、守窗待黑（难熬）、梧桐细雨黄昏（绵密）——一组意象加一层愁，全是日常小物，没有一个宏大意象。**婉约词的深愁正走这条路：以小见哀。**「这次第，怎一个愁字了得」结尾一句反问，把所有累积一次释放。"}, {"h": "词人与时代", "p": "前期李清照词清新明快（如《如梦令》），后期因靖康之变南渡、丈夫赵明诚病逝，词风转为沉痛凄苦。读本词要把个人遭际与家国之变联系起来答：愁里有身世，更有时代的影子。这是「知人论世」在词学鉴赏中的标准用法。"}], "pitfalls": ["默写错字：「凄凄惨惨戚戚」的「戚」误作「切」；「乍暖还寒时候，最难将息」的「将息」误作「奖息」。", "风格贴标签错误：本词是婉约词的代表作，不要说成豪放。", "情感只答「思念丈夫」，漏掉国破家亡的时代之痛。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 15, "t": "宋词三首", "dur": "57:12", "from": "名师课堂", "vtop": ["念奴娇的豪放有三点：描绘壮丽之景（大江东去、乱石穿空、惊涛拍岸、卷起千堆雪，夸张加比喻）、刻画豪迈之人（周瑜羽扇纶巾、谈笑间樯橹灰飞烟灭，儒将风度）、表现壮志难酬又能自我解脱的放达（故国神游、多情应笑我、人生如梦、一尊还酹江月）。", "永遇乐全靠典故推进：孙权（千古江山、英雄无觅）、刘裕（斜阳草树、气吞万里如虎）、刘义隆（元嘉草草、封狼居胥、赢得仓皇北顾）、拓跋焘（佛狸祠下、一片神鸦社鼓）、廉颇（凭谁问、廉颇老矣、尚能饭否），每个典故先讲史实再讲用意，考典故题就按这个顺序答。", "两首词都是怀古抒怀，但词风不同：苏词潇洒疏朗、旷达超脱，不平之意最后能参悟平复；辛词多用典故、充满奋勇抗敌的热情与报国无门的悲哀，慷慨悲壮。"], "vsum": "本课由两段视频拼成：前 26 分钟是名师课堂讲《念奴娇·赤壁怀古》和《永遇乐·京口北固亭怀古》，后 31 分钟是语文老师倪文韬逐句精讲《声声慢》。三首词全讲到了，没有缺口。开场先定本课三个目标：一是鉴赏《念奴娇》雄浑壮阔的意境、分析周瑜形象、体会词人壮志难酬的情感、了解豪放风格；二是掌握《永遇乐》中典故的含义及作用、赏析其豪放风格；三是对比分析两首词，体会思想情感和艺术手法的异同。先讲《念奴娇》。**苏轼生平**：字子瞻，号东坡居士，眉州眉山人，北宋著名文学家、唐宋八大家之一。嘉祐二年进士，宋神宗时在杭州、密州、徐州、湖州等地任职，元丰三年因乌台诗案被贬为黄州团练副使；宋哲宗即位后任礼部郎中、翰林学士等职，又出知杭州、颍州、扬州、定州等地；晚年因新党执政被贬惠州、儋州，宋徽宗时获大赦北还、途中病逝常州。《念奴娇·赤壁怀古》写于宋神宗元丰五年七月，正是苏轼被贬黄州期间，抱负遭遇重挫、人身行动受限、内心极度彷徨苦闷，试图通过踏寻古迹、咏怀古人实现精神突围。**豪放特征**从四个方面赏析。写景句“乱石穿空”三句是现场写景：写山石用“穿”，写浪涛用“拍”，写出景物的动态美，表现山之奇峭高峻、水之汹涌澎湃；“卷起千堆雪”以雪比喻波涛，“千堆”是数量上的夸张，更写出波涛的气势；几种物象作用于视觉、听觉，视听结合，呈现出一个有声有色、富有动感、豪放壮阔的画面。人物塑造：“羽扇纶巾”写周瑜手持羽扇、头戴纶巾，通过描写人物典型装束塑造他的儒将形象；“谈笑间”写他指挥若定、从容不迫的大将风度；“樯橹灰飞烟灭”写强大的敌人在周瑜面前不堪一击，既写出辉煌战功，也写出潇洒风度、沉着性格。塑造人物还用了**衬托**：正衬如用“千古风流人物”“一时多少豪杰”陪衬周郎，反衬如以雄姿英发的周郎反衬早生华发的词人自我。周瑜 24 岁为将，人称周郎，性情温厚、精通音乐，34 岁与 28 岁的诸葛亮统帅孙刘联军，在赤壁大战中用火攻把 54 岁的曹操打得一败涂地，这样的人物在苏轼眼中当然值得向往。情感部分：上片写景开篇，感慨“江山如画，一时多少豪杰”，表现对时光流逝的感慨；下片“遥想公瑾当年，小乔初嫁了，雄姿英发”是咏史，写风流人物、战功卓越，表达对英雄豪杰的仰慕赞颂；结尾“故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月”转入抒怀：“故国神游”即神游故国，“多情应笑我”即应笑我多情，都是倒装；想到周瑜 34 岁便建立惊天动地的功业，而自己却贬谪在此、头发早白，相形之下无限感慨；头发变白是由于多情、不能忘情于世事，而这种自作多情仔细想来又可笑，于是“人生如梦”，不如借酒浇愁——“酹”是把酒倒在地上表示祭奠，这里却指对月敬酒，如李白月下独酌“举杯邀明月”之意，所邀乃江中月影，在地不在天。内容上这首词表现了作者用世与避世、入世与出世思想之间的矛盾，这是封建社会知识分子的普遍矛盾：没有机会为国为民做出一番事业，就只有在无可奈何的心情下寻求解脱。**豪放特征总结三点**：一是描绘壮丽之景，“大江东去”“乱石穿空”“卷起千堆雪”运用夸张、比喻，呈现广阔景致、宏大气魄；二是刻画豪迈之人，肯定周瑜在赤壁之战中的关键作用，赞颂其才华功勋，塑造指挥若定、从容不迫的儒将形象；三是表现词人壮志难酬又能自我解脱的放达，生不逢时、空有一腔抱负，壮志难酬不如在江月下举杯逍遥，在失落中找到了解脱。最后回顾念奴娇写景、咏史、抒情如何融为一体：先写山之奇峭、水之汹涌澎湃，联想江山如画、一时多少豪杰，为后文咏史刻画周瑜、续写赤壁之战场景做铺垫，同时表现对时光流逝的感慨；下片咏史抒情，回想周瑜指挥赤壁之战的场景，表达仰慕赞颂，再由周瑜想到自身，抒发壮志难酬之叹，同时寻求内心解脱。再讲《永遇乐》。**辛弃疾生平**：字幼安，号稼轩，历城人，南宋词人，出生时中原已为金兵所占，21 岁参加抗金义军，与党怀英齐名北方、号称“辛党”，青年时参与耿京起义、擒杀叛徒张安国回归南宋，献《美芹十论》等，历任江西、湖北、湖南转运使、安抚使等职，一生力主抗金，提出的抗金建议很少被采纳，还遭到主和派打压、长期落职闲居；其词艺术风格多样、以豪放为主，与苏轼并称“苏辛”。本词是辛弃疾 65 岁登临镇江北固亭所作，时为南宋开禧元年秋，当时韩侂胄把持朝政大权，企图用北伐中原来提高自己的声誉，于嘉泰三年启用闲居的抗金派代表辛弃疾，先任命为绍兴知府、浙东安抚使，次年调任镇江知府；镇江古名京口，素来是军事重镇，南宋时处于抗金前线。韩侂胄抗金的主张符合辛弃疾收复失地的一贯志愿，但韩侂胄在军事上准备并不充分，辛弃疾忧心忡忡，登临北固亭时览景有感。**以点入词是本词一大特色**，五个典故逐个讲。“千古江山，英雄无觅孙仲谋处”刻画孙权：词题为京口北固亭怀古，一开头就从镇江的历史人物孙权说起，孙权是三国时吴国皇帝，在南京建都、打垮北方的曹操、保卫了国家；如今江山如故却无处寻找像孙权那样的英雄，惋惜之余暗含无人可用的愤懑。“斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎”刻画刘裕：寄奴是南朝宋武帝刘裕的小字，刘裕在京口起兵讨伐桓玄、平定叛乱；斜阳照着草丛树木与普通街道，人们说刘裕曾在这里住过，回想当年他指挥强劲精良的兵马、气势如猛虎；从回顾刘裕生平揭示出寒门庶族、低微出身并不妨碍英雄建功立业，表达对古代英雄的赞叹，也暗含以英雄业绩鼓励鞭策自己、抗敌救国的心情。“元嘉草草，封狼居胥，赢得仓皇北顾”刻画刘义隆：元嘉是南朝宋文帝的年号，宋文帝刘义隆是刘裕的儿子，不能继承父业、好大喜功，听信王玄谟的北伐之策、打无准备之仗，结果一败涂地；“封狼居胥”讲汉朝霍去病战胜匈奴、在狼居胥山举行祭天大礼的故事，宋文帝听了王玄谟的大话、对臣下说“闻王玄谟言，使人有封狼居胥意”；词人借此表达对当时执政者急功近利、主张用兵而不做充分准备的警告。“可堪回首，佛狸祠下，一片神鸦社鼓”刻画拓跋焘：拓跋焘小字佛狸，属鲜卑族，击败刘宋军队后率追兵直达长江北岸的瓜步山、在山上建立行宫，就是后来的佛狸祠；当地老百姓年年在佛狸祠下迎神赛会，神鸦是吃祭品的乌鸦、社鼓是祭神的鼓声；词人感叹往事怎忍再回顾，如今佛狸祠香火正盛，而江北各地沦陷已久，不迅速谋求恢复的话，民众安于异族统治、忘记自己是宋氏臣民，借此提醒人们不要忘记江北仍处在金人铁蹄之下、不要忘记收复故土，表达对南宋统治者苟安、不思收复失地的悲愤。“凭谁问：廉颇老矣，尚能饭否”刻画廉颇：又谁来问廉颇将军老了、饭量还好吗？廉颇虽老还想为赵王所用，在赵王使者面前一顿吃了一斗米做的饭、十斤肉，又披甲上马表示自己尚有余勇；诗人联想自己，并不如廉颇老迈、却没有人来过问，这里运用典故、以廉颇自比，表示仍能为国效力，同时抒发报国无门、壮志难酬之愤。有人批评辛弃疾的词“掉书袋”，岳飞的孙子岳珂说“用事多是这首词的毛病”，这是不恰当的批评：这首词所用的故事除了末尾廉颇一事以外，都是有关镇江的史实，眼前风光是京口怀古这个题目应有的内容，且都和词的思想感情密切相连；就艺术手法论，围绕作品的思想内容使用许多史事，以加强作品的说服力和感染力，在词里是不多见的，这正是这首词的长处。**对比鉴赏**：用典上，苏词以精细笔墨集中塑造儒雅倜傥、击败强曹的青年将领周瑜，渲染其显赫功业、横溢才华时又巧妙点染他温文尔雅的风度和幸福美满的婚姻，以一个特写镜头“谈笑间，樯橹灰飞烟灭”现出军事统帅风度翩翩、气宇轩昂、运筹帷幄、指挥若定的儒将风范；辛词上片写孙权、刘裕两人，不像苏词那样亲比于人物的音容笑貌、神情风采，而是侧重于史实的铺叙，下片写刘义隆急于求成、仓促北伐，只落得仓皇北顾的下场，沉重追溯惨痛的历史教训，道古以讽今、告诫当政者谨慎用兵、免蹈前车之辙，末尾廉颇渴望为国出力、却报国无门，词人以己自比。借景抒情上，念奴娇集中写景、浓墨重彩，“乱石”写形状之雄奇、“惊涛”写声音之汹涌、“卷起千堆雪”写色彩之磅礴，绘出一幅雄浑壮丽的江山图；永遇乐没有纯粹的景物描写，景物描写有机穿插在史实叙述中、次第出现，都是淡笔勾勒，开篇景物大至江山、小至舞榭歌台、斜阳草树，浅墨淡彩、不着点缀，纯客观的轻描淡写，意在暗示事过境迁、物是人非。词风上，苏词偏于潇洒疏朗、旷达超脱，词中的不平之意最后能通过对人生的参悟逐渐平复，因而读到乐观旷达；辛词喜欢用典，充满奋勇抗敌的热情和报国无门的悲哀，给人慷慨悲壮之感。相同点是境界开阔、感情豪放，都借古人抒怀。最后一段是倪文韬讲《声声慢》。先逐句讲字面意思：开篇“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”是七组十四个叠字连用，非常打破常规，历来诗论家词论家都赞叹“精妙出奇”；“寻寻觅觅”展现似乎在寻找什么的彷徨、空虚、迷茫的心理状态，“冷冷清清”既是外部环境的凄清，也是体感上的冷表达内心世界的清冷，“凄”有寒冷、悲伤、静寂三种意思，“惨”是程度极深的悲伤、“戚”是忧愁悲哀，三个字意思相近、通过叠词连在一起，把感伤忧愁的情绪渲染得非常浓烈。“乍暖还寒时候，最难将息”：“将息”是调养、休息的意思，乍暖还寒的时节最难将息，因为气温不稳定、很容易生病；“乍暖还寒”究竟是什么时候？课下注解给的是忽冷忽热、天气变化无常，一般指由冬入春（“乍”是刚刚、起初，“还”是又回到：刚刚天气热起来、又回到了寒冷，就是春寒），但本词后面有“雁过也”“满地黄花堆积”，黄花是秋天开的菊花、大雁秋冬南飞，似乎更像由秋入冬；不过大雁春天北归时也能看到，春天也有迎春花这样的黄花，所以由秋入冬还是由冬入春都可以，不必死抠。字面意思讲完（约 37 分钟）进入两个重点：一是**内容情感层面**，这首词当然表现的是愁情（“这次第，怎一个愁字了得”），但究竟是怎样的愁、愁从何而来、愁到了什么程度，值得仔细玩味；这是李清照的晚期作品，正是作者最为抑郁痛苦的时期，要了解这愁从何而来、自然要考察李清照的人生经历——她出生在和平年代，年轻时婚姻美满、生活安逸，父亲李格非是礼部员外郎、后做吏部侍郎，公公是宰相赵挺之，夫妻二人都是高干子弟，曾经度过一段非常安逸美满的生活，一个经历过盛世再进入乱世的人，那种生命体验与出生在乱世的人完全不同；二是**创作技巧层面**，重点分析开篇十四个叠字：从声调看，平声昂扬、去声分明、入声短促，如“寻寻觅觅”第二声、第四声、阳平到去声，阳平有升起的感觉；“凄凄”后边的“凄”都是擦音，念的时候给人哽咽的感觉；这十四个字不仅在声调上一扬顿挫、不流于呆板繁复，而且能暗示情绪流动的状态。李清照填词对声律要求极其严格，这正是她“词别是一家”的词学观。课末老师预告下期讲《窦娥冤》。", "vtech": [["典故题三步答法", "先说典故讲的是谁、什么事（如刘义隆元嘉北伐、封狼居胥），再说词人借它说什么（告诫当政者谨慎用兵），最后落到情感（忧愤、讽谏）；只讲故事不讲用意，等于白写。"], ["对比鉴赏先列不同再说相同", "用典不同（苏词集中写一人、辛词连用五典）、写景不同（苏词浓墨重彩、辛词淡笔勾勒）、词风不同（旷达超脱 vs 慷慨悲壮）；相同点是境界开阔、感情豪放、都借古人抒怀。"], ["“故国神游，多情应笑我”怎么断句讲", "故国神游即神游故国，多情应笑我即应笑我多情，都是倒装；情感是联想自身、壮志难酬，又转念以江月举杯求解脱，答题要把“感慨—解脱”两层都说到。"], ["叠字题抓声音和情绪", "声声慢开篇七组十四个叠字连用，寻寻觅觅写彷徨迷茫、冷冷清清写内外清冷、凄凄惨惨戚戚把悲愁渲染到极致；再看声调，平声昂扬、去声分明、入声短促、擦音哽咽，声音本身就在传情绪。"]], "vgaokao": []}}, "chn_c018": {"name": "家乡文化生活（学习活动）", "sec": 1, "secTitle": "第四单元 家乡文化生活", "page": 71, "desc": "做一回本地人的人文调查：记录家乡的人和物、写一份现状调查。", "criteria": ["能说清本单元活动的目标与流程", "能制定可执行的记录或调查方案", "能独立完成一次访谈提纲或记录稿", "能写出结构完整的报告或展示稿", "能结合本地实例做汇报并讲清依据"], "diag": null, "pre": [], "next": [], "content": {"advance": {"a": "地方志是系统记录，多为官方修纂、体例统一、重在存档；家乡文化生活调查是亲历参与，重在发现问题、记录鲜活的人与现状、提出参与建议。前者重「存史」，后者重「参与」；把两者结合，先查地方志定背景，再做田野访谈补细节，是比较稳妥的做法。", "kind": "self", "q": "单元活动要求写调查报告。说说「调查报告」与照抄「地方志」的区别，调查报告最怕什么？"}, "apply": [{"ans": 1, "opts": ["尽量使用文学抒情语言", "有明确的调查目的、分项呈现现状、数据与事例对应、建议落到建议要具体可行", "篇幅越长越好", "多引用名人名言"], "q": "一份合格的家乡文化生活现状调查报告应具备（ ）", "why": "调查报告的评分项：目的、方法、数据、事例、建议，五样齐全才成型。"}, {"ans": 0, "opts": ["先定访谈对象与提纲，再实录，最后整理成文", "想到哪问到哪，回来凭记忆写", "只查网络资料，不用出门", "全靠文学想象"], "q": "记录「家乡的人和物」开展人物访谈的正确流程是（ ）", "why": "活动题答流程：先准备（对象、提纲）、再实施（记录）、后整理（成文），三步不可颠倒。"}], "basics": [{"ans": 1, "opts": ["两个", "三个", "四个", "五个"], "q": "第四单元共设置了几个学习活动（ ）", "why": "记录家乡的人和物、家乡文化生活现状调查、参与家乡文化生活三项活动层层递进。"}, {"ans": 1, "opts": ["闭门编造材料", "先定对象列提纲，带着问题去访谈并做实录", "只需把网上资料拼起来", "访谈时不断打断对方发表自己的看法"], "q": "做人物访谈前最关键的准备是（ ）", "why": "访谈质量取决于提纲：对象、问题、记录方式都要提前定好，这是本单元的核心方法。"}], "case": {"a": "要点：目的交代（了解本镇老茶馆的现状与传承困境）—对象与方法（访谈茶客、店主，观察记录经营状况）—发现分列（顾客老龄化、年轻客源少、非遗茶艺有亮点）—建议对应（结合短视频推广、设立体验日等）。评分关键是每条建议都能对应前面的一个发现。", "q": "围绕「老街茶馆的存续」拟一份家乡文化生活现状调查提纲，写出四个组成部分的标题与每部分一句话要点。", "title": "案例：调查提纲四件套"}, "intro": "第四单元没有课文，只有一件事：**做一回自己家乡的人文调查**。==这个单元考的不是阅读，而是方法：怎么访谈、怎么做调查、怎么把成果写成像样的文字。==", "learn": [{"h": "三个活动一条线", "p": "活动一「记录家乡的人和物」：选一位有代表性的家乡人物（如老匠人、社区医生、退休教师），通过访谈记录他的故事，练的是**人物访谈与记叙**。活动二「家乡文化生活现状调查」：选一个切口（老街、方言、集市、庙会、非遗）做小型调查，练的是**调查方法与报告写作**。活动三「参与家乡文化生活建设」：为前两步的发现提一条可落地的建议，练的是**建议书与应用文**。三步是完整的实践链。"}, {"h": "访谈的方法清单", "p": "访谈五步：定对象（有故事、有代表性、可联系）—列提纲（生平节点、关键事件、情感转折、代表细节）—善提问（开放式问题为主，如「您最难忘的一次是？」）—做记录（笔录、录音需经同意、拍细节照片）—整理成文（按主题而非问答顺序重组）。==活动题答不出高分，多半输在没有「方法意识」：阅卷人要看你是否真的会做。=="}, {"h": "调查报告的模样", "p": "调查报告的结构：标题—前言（调查目的、对象、方法）—主体（现状分条呈现，配数据与实例）—问题分析—建议对策。最忌两个毛病：一是抒情散文化，只有感慨没有数据；二是只摆问题不开药方。福建多山多侨乡，写宁德本地题材时，老茶馆、畲族习俗、海上渔村都是现成的好切口。"}], "pitfalls": ["把活动课当阅读课，只背概念不做方案设计。", "调查报告写成抒情散文：全是「我爱家乡」，没有数据与事例。", "建议空泛（「要加强保护」），没有对应具体问题的可执行措施。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 17, "t": "家乡文化生活", "dur": "26:30", "from": "名师课堂", "vtop": ["本单元是学习活动单元，没有课文精讲：三个活动是记录家乡的人和物、家乡文化生活现状调查、参与家乡文化建设，从调查访谈到提建议，层层递进。", "访谈是活动一的核心方法：流程是定目的、定时间进度、选代表性对象、定形式设计问题；问题要紧扣目的、清晰具体、层层深入；访谈时熟悉问题、用对谈方式、善于追问，访谈者不分享自己的观点倾向、要忠实记录。", "调查报告与建议书是两项输出：调查报告要包括教材列出的一般要素、也可加图表目录致谢附录；建议书格式与一般书信大体相同，标题可写“关于某某某的建议书”，中学生写建议书要用委婉的建议语气、不能是说教或命令语气。"], "vsum": "本课是“家乡文化生活”单元的导读课，没有课文精讲，讲的是本单元要做的三件事怎么做。开场先定家乡文化的地位：家乡文化既是中国文化的主要组成部分，又是个体精神生活的重要依托，它并不是抽象的存在——家乡的各色人物、各类人文和自然景观、独特的风俗习惯和历史文化，都承载着丰富的情感与记忆。**单元目标四点**：一是思考家乡文化生活与自我成长之间的关系，形成关注和参与当代文化生活的意识，培养家国情怀；二是了解访谈的基本概念和特点，掌握有关访谈的基本知识、方法、程序和技巧，提高在具体情境下的语言文字运用能力；三是阅读有关调查研究、乡土风俗等方面的文章，帮助完成本单元要求的学习活动，提升理性思维能力和审美鉴赏能力，学会灵活运用常见工具书和网络、根据一定的目的查阅所需信息资料、快速定位信息；四是学会从现象中提炼有价值的典型问题，形成专题研究意识，根据事实说话、学会论证说理、学会分析书面材料、掌握研究方法，了解调查报告应包括的一般要素并完成调查报告写作，培养理性思考、深入认识问题的能力。**三个学习活动各有侧重**：第一个活动“记录家乡的人和物”，面向日常生活、梳理值得记下的人和物素材，从熟悉的场景中激活记忆、凝练认识、感受家乡的底蕴；第二个活动“家乡文化生活现状调查”，从人际关系、道德风尚、文物古迹的保护、文化生活的方式等不同主题展开调查研究，在某一个专题方向深入了解、感受家乡的变化；第三个活动“参与家乡文化建设”，从风俗习惯、邻里关系、生活方式、文化环境等方面思考可以改进的地方，这是语文学习的课外延伸，也是当代同学应该担负的责任。第一个活动侧重通过调查访谈深入了解家乡的人、物、历史、习俗等，第二个活动侧重通过访谈和调查了解家乡文化生活现象、辩证思考文化发展与个人、社会的关系，第三个活动侧重在掌握大量一手材料后提出丰富家乡文化生活的建议，在这一学习活动过程中提升语文素养、培养热爱家乡进而热爱祖国的感情。**活动一：记录家乡的人和物**，核心方法是访谈。访谈是一种交谈活动，以口头形式围绕特定目的、根据被询问者的答复搜集客观的、不带偏见的事实材料，以准确地说明问题；面对复杂问题时运用访谈的方法，遴选不同方面的各具代表性的人物，可以了解不同类型的材料，就有一定的灵活性和覆盖性。访谈前要了解关于访谈的一般知识、知道怎样进行访谈，分四部分讲。**一、访谈的一般流程**：确定访谈的目的、功能以及理由；确定访谈的时间及进度；选择有代表性的访谈对象；确定访谈形式、设计问题。例如记录家乡人物，可以从家庭几代人、同学和朋友中选择相应的代表性人物；确定访谈对象后在访谈开始前做好充分准备，例如了解访谈对象的情况、制作访谈问题表、准备录音或摄像器材等等。**二、访谈问题的设计**：问题设计要紧扣访谈目的，清晰具体、简单明白、便于回答，具体明确、层层深入；提问的方式、用词的选择、问题的范围要适合被访者的知识水平和习惯；如有可能，也可以事先发给访谈对象访问题纲，让访谈对象提前做好准备。**三、必要的访谈技巧**：访谈前熟悉访谈问题，这样不用照着读出来，用对谈的方式可以让受访者更好地参与进来；访谈时要根据访谈对象的特点，通过一定的话题切入拉近距离，让氛围变得轻松、适于交流，与受访者加强了解和沟通，营造友善的谈话氛围、建立良好的访谈人际关系；抓住时机、灵活呈现问题，旁敲侧击、善于提问与追问，将谈话引向深入；对非语言信息保持敏感、适当回应，使访谈顺利进行；访谈者不需要向受访者分享你的个人经历或观点倾向，这会影响访谈所获得的信息；要能忠实准确地记录访谈内容。**四、访谈后要根据一定的结构完成初始研究资料的整理**。**活动二：家乡文化生活现状调查**。地方文化可以反映在各个方面，例如某地代表性的建筑、街道，甚至一草一木、一砖一瓦、一人一物，都可以是家乡文化的反映；发展家乡文化可以提升同学们的主人翁意识、增强归属感、维系良好的人际关系、提高文化生活质量。调查社区文化生活现状，下面的题目可供参考：一是家乡文化遗产保护传承情况调查，二是家乡群众性业余文化活动调查，三是家乡图书室藏书与借阅情况调查，四是家乡商家招牌体现的商业文化调查，五是家乡文化习俗生活方式的变化调查。调查前要规划调查路线、确定调查重点；调查时要认真观察、做好记录，尽可能详尽地留下第一手材料，包括影像资料，要注意准确记录各种信息的来源。**调查要有问题意识**：家乡文化生活并非静态的存在，随着社会的发展会呈现出哪些变化？原因是什么？每个人的想法可能不同。如何形成理性全面的认识，需要在调研观察中发现典型现象，在对现象的审视中提出问题，针对具体问题搜集材料、分析问题、梳理材料、研讨有关文化现象，增强对问题的深入认识。具体到语言文字任务，要通过多种渠道获得信息、初步形成研究资料：通过自己的观察搜集材料，以调查访谈的方式获得典型个案，通过各类报刊、利用图书馆和网络进行文献阅读，从有关部门获得数据，汇聚各个角度的信息、形成较为全面的研究资料，然后才能运用学到的知识，对有关现象与成因做出推理、解释、判断、得出结论。调查大多会包括一系列的任务，为了很好地完成这一学习活动，需要制定一个初步的调研计划：一般来说科研工作者的研究计划会涉及研究目的、价值、预设、文献综述、路径、内容以及可能遇到的问题与应对策略等，这里不需要那么系统，研究的过程就是发现、提出问题、分析、解决问题的过程，这份调研计划可以定位为任务计划书，目的是让我们据此开展一系列具体的学习活动，促使我们去思考要调查什么、有哪些渠道可以获得材料、如何判断这些材料有效有用、怎样分析这些材料、需要多少同学做什么事、各自的分工是什么、时间节点又是什么，同学们要在一到两周的时间完成这个学习任务；当代文化参与的特点是将语文学习和日常生活联系起来，制定计划时可以课内课外相结合。家乡不仅是生活的场所，也是文化熏陶的场所：你家乡的文化生活状况如何？那里的文化设施是否齐全？使用情况如何？人们日常都开展哪些活动？有没有图书阅览室？是否经常开展读书活动？开展调查时可以以小组为单位，通过访谈、考察等方式了解家乡的文化生活现状；汇报展示时可以以调查报告的方式，也可以制作成演示文稿。调查报告呈现的是同学们自己搜集到的研究材料，搜集材料的方法与路径包括调查、访谈、阅读所获等，以及分析这些材料之后的研究发现；报告中需要对具体案例进行剖析，对家乡文化生活的一些典型现象，应结合调查、访谈、观察、阅读等所得进行分析。**调查报告应包括的一般要素**教材上已经列出，同学们撰写调查报告时以上要素要尽量齐备，但并不一定要照搬，必要的话也可以通过课堂交流研讨等环节，将研究内容、研究结论中的具体要点提炼出来成为标题，并在报告中具体展开阐释；调查报告也可以加入图表、目录、致谢语、附录等其他内容。**活动三：参与家乡文化建设**。了解家乡的文化生活、参与家乡的文化建设，是语文学习的课外延伸，也是当代同学们应该担负的责任；在对家乡文化生活现状调查的基础上，也许同学们会发现一些可以改进和改善的地方，不妨做一些操练、提一些可行性建议，教材上有一些活动提示，可以选择某项开展活动。**关于建议书**：建议书的格式和一般书信大体相同，标题可以只写“建议书”三个字，有时为了突出建议的具体内容，还可以写“关于某某某的建议书”，题目要写在第一行的中间、字体要大；建议书的对象可以是家乡的相关部门，要注意语言表达的得体，因为写作者的身份是中学生，所以在表达中不能是说教语气、更不能是命令语气，应是委婉的建议语气；对部门的建议可以是理性分析为主，要陈述建议的内容、建议的理由、实施的步骤和可行性，要有依据，切记不能根据个人好恶提建议。每个学习活动后同学们都可以设置交流与研讨的环节，以多种方式展示学习收获：班级展示采用幻灯片配讲解的形式，校园展示采用图片配文字的形式，网络展示则可以建立公众号、采用文字图片视频加音频的形式等等；在展示的同时整理自己的思路，但更重要的是相互借鉴启发，在交流与研讨中深化对问题的认识。如果是小组交流，各小组要注意确定发言人、记录者，发言要有一定的组织纪律，组内交流先达成共识，各组发言时要避免发言无序、更要避免不必要的争论。同学们要将自己的观点通过语言准确地表达出来，让别人能理解，这种说的素养包括思维的逻辑性、语言的组织能力、参与讨论的风度等。对很多同学而言，当众发言及其组织语言是相当困难的，大多数同学平时也很少会有意识地将其作为学习内容；发言时听众是我们的同学，无需紧张，目的是让同学们听明白，而不是赶紧说完完成任务；发言前要先做准备，先撰写发言提纲，可以用若干关键词来提示，说话时要清楚和缓、注意节奏与停顿，重要的观点可以借助加重语气、必要的重复等方式予以强调；别人发言时要认真聆听，不能随便打断，能够听出别人说话的重点、问题，才能合理有效地吸收他人意见、互相借鉴、共同提高。**活动举例：写家乡风物志**。我们生活的家乡，各种风光景物、风俗物产，这些风物往往承载家乡的历史、文化，寄托了人们对家乡的情思；为这些风物写一个风物志，是同学们了解家乡文化、积极参与家乡文化建设的重要方式；冲破挖掘这些风物的文化内涵，可以更深入地理解当代文化，也有利于同学们在真实情境中提升语文素养。学习活动一：掌握家乡风物志撰写所需要的相关知识。一是风物志知识学习：风物志的概念——“志”是记录的意思，是古代记叙事物、抒发感情的一种文体，所谓风物志是指对家乡风光景物、风俗物产的介绍；撰写对象选取基本原则——应该选取反映本地历史、体现本地风土民情、对本地文化生活有重要影响的自然景物、建筑、物产、风俗等；写作对象选取定向——小组讨论本地有哪些适合写入家乡风物志的风物，确定写作具体对象并明确选取理由，初步确定所写的主要话题。二是学习访谈设计：访谈准备——先查阅资料、了解所写风物的基本情况，寻找了解该风物的人员、进行访谈、设计访谈问题；访谈方案设计——先了解访谈对象，进入正式访谈前先通过互相寒暄、自我介绍、真诚求教等方式拉近与被访者的心理距离，然后进入访谈主题；采访问题直接明确、切记空泛，围绕访谈目的进行；通过提问引导被采访者，保证访谈方向不偏离；可以请被采访者陈述事实、介绍信息、发表看法，也可以请被采访者讲述细节，必要时可以与被采访者展开讨论，但不宜喧宾夺主、更不宜与被采访者发生争论；访谈问题设计举例——请问您在本地生活了多久，在您的印象中家乡人的习俗是否有变化，如果有、变化的原因是什么；听说您是这里的老住户，对这里的情况特别了解，您能给我们讲讲这座石桥当年是怎么立起来的、有哪些故事。三是学习如何实施访谈：从简单问题入手、启发调查对象充分发表自己的看法；访谈中提出问题应具体明确，避免笼统、含糊不清；控制话题、避免谈话离题太远；交流中要注意倾听受访人的看法，随时给予积极回应；最重要问题可以用不同方式重复提问，重复对方关于此问题的回答、看其是否肯定此说法；访谈结束后要及时整理访谈记录、整合访谈内容。学习活动二：针对本校学情，利用学校和同学们所在村镇、社区资源开展家乡风物志写作活动。任务动员、领会活动目的：一是增进对家乡风光景物、风俗物产的了解，二是训练写作风物介绍文字、家乡风物志的能力，三是深入了解家乡、村镇和社区，提升参与家乡文化建设的能力；在教师指导下进行课堂讨论，搜集、列举本地各类家乡风物，制作家乡风物名录——明确列入风物名录的原则：本地著名的自然景物、建筑、物产、风俗，具有本地特色、可以作为本地标志，有历史积淀或反映本地最新变化的事物；分小组讨论、确定本小组撰写风物志的具体风物，明确写作内容、确定具体风物，研讨采访方案与内容。学习活动三：在教师指导下明确访谈思路与技巧。了解风物志内容获取途径：根据提纲方案的内容，在网络上查阅相关材料、获取调研访谈线索；采访与风物有关的人员，包括相关风物的管理人员、久居本地的居民等；查阅本地地方志等材料。了解风物志主要内容：该风物的特点，该风物的历史沿革、传说故事，该风物名称的内涵，家乡风物体现的乡土情感；访谈问题举例——以本地中学某棵纪念树为例：这棵树是哪年种植的，当年是因为什么事情种植的；您还记得当年种树时的场景吗；这棵树从种植到现在发生过哪些有意义的事情。学习活动四：以小组为单位开展访谈、为写作做准备。确定采访名单，访谈名单举例以当地学校的中外友谊树为例：采访学校校长与老教师，采访当年参与种树的老校友，采访现在的同学对这棵树的感受；拟定调研访谈程序与方案：根据所写风物确定关键词、上网搜索资料，确定调研、访谈和查阅资料的方向，根据调研与资料查阅成果确定访谈内容，整理资料、编制资料目录，以某学校中外友谊树所需资料为例，所查资料目录包括本地地方志中的中外交流资料、学校的校史特别是国际交流资料、植树当年的中外交流事件记录、当年植树的当事人回忆录、该友谊树相关学校的信息、植树之后学校与相关联谊学校的交流记录；开展访谈，考虑到不熟悉本地区的人的阅读需要，全篇结尾处要有对被访谈者的感谢，并附相关图片。交流展示家乡风物志：在学校网站建立专栏，在家乡风物处粘贴二维码、扫码后可供来访者阅读，班内交流。可供参考的活动方向（提示下面提供的一系列活动任务，可以任选一个展开调查；家乡在外地的同学，可以自动把下面涉及有关的内容换成自己家乡的内容）：一是人物——注意采访人物的生平、主要事迹、贡献和影响等；二是建筑——历史、现状、故事、建筑特色等；三是风景；四是风物——来源、特点、文化价值等；五是风俗、生活方式；六是家乡的历史、文化遗产；七是建议书。学习资源包括《俗世奇人》《毛泽东与调查研究》《胡同文化》、调查报告的一般结构、撰写调查报告应注意的问题、弘扬传统文化、半量现代生活：济南市历城区民间伴奏队伍调查报告、纪录片《五大道》等。课堂小结：通过本课的学习，同学们应形成关注和参与当代文化生活的意识，培养家国情怀，了解访谈的基本概念和特点，提高在具体情境下的语言文字运用能力。", "vtech": [["访谈问题怎么设计", "紧扣访谈目的、清晰具体、简单明白、便于回答，层层深入；提问方式、用词、问题范围要适合被访者的知识水平和习惯；有条件可事先发给访谈对象问题提纲，让对方提前准备。"], ["调查报告的要素怎么凑齐", "按教材列出的一般要素尽量齐备、不必照搬；先把研究内容、研究结论的具体要点提炼出来做标题、再展开；也可加入图表、目录、致谢语、附录；报告里要对典型案例做剖析。"], ["建议书语气怎么把握", "对象是家乡相关部门，写作者是中学生，语言要得体：委婉的建议语气，不能是说教语气、更不能是命令语气；内容要有建议内容、建议理由、实施步骤和可行性，切记不能凭个人好恶提建议。"], ["风物志选题怎么定", "选反映本地历史、体现本地风土民情、对本地文化生活有重要影响的自然景物、建筑、物产、风俗；先列风物名录（本地著名、有本地特色、有历史积淀或反映最新变化），再定具体风物和采访方案。"]], "vgaokao": []}}, "chn_c019": {"name": "乡土中国（整本书阅读）", "sec": 1, "secTitle": "第五单元 整本书阅读", "page": 79, "desc": "费孝通的学术小册子：差序格局等十四个概念读懂中国乡土社会。", "criteria": ["能复述全书篇目与核心概念清单", "能用核心概念解释一个现实事例", "能独立做对基础题（概念辨析）", "能独立做对应用题（材料分析）", "能写出有自己观点的读书札记并讲清依据"], "diag": {"question": "《乡土中国》中与「团体格局」相对的概念是什么？", "answer": "差序格局：以个人为中心、像水波纹一样向外推的社会关系格局。"}, "pre": [], "next": [], "content": {"advance": {"a": "「从基层上看去，中国社会是乡土性的」这句总判断位于首篇《乡土本色》，统领全书：后文的文字下乡、差序格局、礼治、长老统治等概念，都是从「乡土」这一基层质地里生长出来的。抓住这句话，就抓住了全书的地基。", "kind": "self", "q": "《乡土中国》开宗明义说「从基层上看去，中国社会是乡土性的」。这句总判断与后面十四个概念是什么关系？"}, "apply": [{"ans": 1, "opts": ["城市居民比农村居民高贵", "社会关系像石子投入水中形成的波纹：以自己为中心，亲疏远近逐层推出", "家族成员完全平等", "法律关系网"], "q": "「差序格局」最贴切的说明是（ ）", "why": "波纹比喻是原书的原话级表述：亲疏有差、关系有别，答题要抓住「以己为中心＋亲疏序列」。"}, {"ans": 1, "opts": ["法律", "礼治（礼）与传统习惯", "宗教戒律", "舆论谴责"], "q": "乡土社会维持秩序主要靠（ ）", "why": "礼治是乡土社会的秩序方式：靠传统与教化，不靠成文法强行推行。"}], "basics": [{"ans": 1, "opts": ["老舍", "费孝通", "沈从文", "钱穆"], "q": "《乡土中国》的作者是（ ）", "why": "费孝通是社会学家，本书由他在西南联大讲授「乡村社会学」的讲稿整理而成。"}, {"ans": 1, "opts": ["地理环境决定的居住方式", "中国社会结构的格局：以己为中心、亲疏有等差的人际关系网络", "宗法制度的别称", "户籍管理制度"], "q": "「差序格局」是费孝通提出的（ ）", "why": "差序格局是对中国传统社会结构最著名的概括，与西方的「团体格局」相对照提出。"}], "case": {"a": "差序格局：关系以个人为中心，越亲越近、越疏越远，义务与权利随亲疏而变——这正是差序格局的运行方式。对比团体格局：成员资格与权利义务由团体界限划定，不因亲疏而有差等。材料占哪边，要看它描述的是「圈层亲疏」还是「团体边界」。", "q": "材料：某村修祠堂集资时，村民先看与户主的亲疏远近决定出多少钱；同一单位职工福利却按编制身份统一发放。用差序格局与团体格局分别解释这两种现象。", "title": "案例：概念读材料"}, "intro": "第五单元只有一本书：费孝通的《**乡土中国**》。==整本书阅读的抓手是核心概念清单：差序格局、礼治秩序、文字下乡、无讼、长老统治——概念读懂了，整本书就读通了。==", "learn": [{"h": "全书的骨架", "p": "《乡土中国》共十四篇，由社会学讲稿改成，每篇解决一个问题：乡土本色（定调）—文字下乡（乡土社会为什么不需要文字）—再论文字下乡—差序格局（社会结构）—维系私人的道德—家族—男女有别—礼治秩序—无讼—无为政治—长老统治—血缘与地缘—名实分离—从欲望到需要。==读书先列目录学：把十四篇按「定性—结构—秩序—变迁」四组归类，全书立刻变薄。=="}, {"h": "第一概念：差序格局", "p": "与西方「团体格局」（成员如捆好的柴，界限分明）对照：中国社会是**差序格局**——每个人像一块投入水中的石子，波纹一圈圈推出去，关系的亲疏决定义务的轻重。由这个概念可以解释：为什么中国人讲人情、讲圈子、公私界限相对化。考试最爱考的就是拿材料让你辨「哪种格局」。"}, {"h": "其他高频概念", "p": "**礼治秩序**：乡土社会靠礼（传统习惯）维持秩序，不是法治。**无讼**：教化使人耻于打官司，纠纷多靠调解。**长老统治**：靠经验与教化权的统治方式。**文字下乡**：乡土社会是面对面社群，文字在这里不是必需品——注意，它不是骂农民愚昧，而是分析环境的产物。概念题的答法：定义一句、举例一句、与现代社会对照一句。"}], "pitfalls": ["把「差序格局」写错成「差序格居」或与「等级制度」混为一谈，它的核心是亲疏波纹不是上下等级。", "把「文字下乡」理解成批评农民没有文化，原意是乡土环境本身不依赖文字。", "只背概念名词，不会用材料验证——考试里概念从不在名词解释里单独出现。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 18, "t": "乡土中国（整本书阅读）", "dur": "26:13", "from": "名师课堂", "vtop": ["整本书阅读建议共四点：先粗后细逐步推进、抓住核心概念、创作思维导图把握知识体系、品读文章感受写作特色；先按这四点搭阅读框架，再进正文。", "粗读三点：读序言后记了解写作背景和目的（二十世纪四十年代后期，费孝通在西南联大等校讲授乡村社会学课程，整理授课内容写成十四篇文章）、浏览目录大体了解内容和章节结构、浏览正文快速跳读形成整体感知；细读注重概念、材料、论证、推理。", "差序格局是核心概念：由亲属关系和地缘关系决定的有差等的次序关系，与西洋社会的团体格局相对；作者用生活经验、历史事实、民间俗语、《红楼梦》情节、《论语》《大学》名言等材料论证，用了比喻、事实、道理、对比论证，由具体事实概括出一般理论是归纳推理。"], "vsum": "本课是《乡土中国》整本书阅读的导读课：先介绍作者费孝通，再给四点阅读建议，最后留两个练习并附参考答案。开场先定这本书的地位：《乡土中国》是一部经典的社会学著作，作者费孝通以实地调查为基础，研究中国乡村社会的特点，提出许多具有启发性和影响力的观点。**作者费孝通**：江苏吴江人，社会学家、人类学家、民族学家、社会活动家，早年赴英留学，1938 年学成回国，曾任西南联大教授、清华大学教授、中国社会科学院社会学研究所所长等职，长期从事社会学、社会人类学的教学和研究工作，主要著作有《江村经济》《禄村农田》《生育制度》《乡土中国》等，其中《乡土中国》是最为脍炙人口的一本。《乡土中国》是一部社科类学术著作，同学们之前很少接触学术著作、不知应该如何着手阅读，老师给出四点阅读建议。**阅读建议第一点：先粗后细，逐步推进**。粗读指的是粗读，细指的是细读，阅读社会科学论著最好将粗读与细读结合起来，先粗读后细读。粗读主要包括三点。第一，在阅读书的正文内容之前，先阅读书的序言后记，来了解作者的写作背景和写作目的：二十世纪四十年代后期，费孝通在西南联大等校讲授乡村社会学课程，他不喜欢用现有的教材，而是独立思考和探索，将自己的研究成果分享给学生，后来应《世纪评论》之约，费孝通将授课内容进行整理，写成分期连载的十四篇文章；阅读序言和后记还可以了解此书的写作目的，是要探讨中国乡村社会的特点，回答作为中国基层社会的乡土社会究竟是个什么样的社会这个问题。第二，浏览目录，大体了解著作的基本内容和章节结构：社科类著作的目录一般都比较明晰，主要的观点往往会出现在章节标题中，阅读目录中的章节标题就能对全书的内容和结构有粗略的了解；《乡土中国》除了重刊序言和后记之外，包括十四篇文章，分别是《乡土本色》《文字下乡》《再论文字下乡》《差序格局》《维系着私人的道德》《家族》《男女有别》《礼治秩序》《无讼》《无为政治》《长老统治》《血缘和地缘》《名实的分离》《从欲望到需要》；阅读目录中的文章标题，再结合在序言和后记中了解到的研究背景、研究目的等内容，可以大致断定本书的主要内容是谈论中国乡土社会的特点，涉及文字的使用、社会结构、道德观念、传统感情、宗法制度、社会变迁等方面的内容；初次读目录，你可能对其中一些题目的含义不太理解、存有疑问，这是很正常的，这样你阅读正文的时候就带着这些疑问去阅读，在阅读中解决疑惑。第三，浏览正文、快速跳读，对全书形成初步的整体感知：在浏览正文时可以留意每个章节的开头和结尾，以及每个段落的开头和结尾，那里往往会出现观点；看到阐述观点或定义概念的句子，顺手勾画下来；其他部分可以一目十行、自行跳读，知其大意即可。以上讲的是粗读，通过粗读形成对全书的第一印象，有了第一印象就会产生对这本书的疑问点和兴趣点，也就产生了阅读期待，带着这样的期待去阅读会有更好的阅读效果。在粗读之后再自行细读：细读是指对文章进行精细深入的阅读，注重概念、材料、论证、推理等要素，深入思考、不断提炼。以《差序格局》这一篇为例说一说细读需要注意的方面：首先关注作者提出的概念，在这一章节中作者提出的核心概念是**差序格局**，用它来指称中国传统社会结构的格局，差序格局是指由亲属关系和地缘关系所决定的有差等的次序关系；作者为了更好地说明差序格局，举出另一个可与之构成对比的概念，就是**团体格局**，团体格局是用来指称西洋社会结构格局的概念。其次注意区分观点与材料，看一看作者是如何用材料来支撑观点的：在《差序格局》这篇文章中，费孝通运用了丰富的材料，包括生活经验、历史事实、民间俗语、《红楼梦》中的情节、《论语》《大学》中的名言；在细读文章的时候，需要弄明白作者为何使用这些材料，他用这些材料验证了什么样的观点。再次关注作者是如何论证观点的、他使用了什么样的论证方法：在《差序格局》这篇文章中，作者运用了比喻论证、事实论证、道理论证、对比论证等论证方法来论证自己的观点。最后注意分析作者是如何进行逻辑推理的：在差序格局中，作者由一系列具体的事实概括出中国传统社会结构的格局是差序格局这一结论，这种由一系列具体的事实概括出一般理论的推理方法是**归纳**的推理方法。运用细读的方法去阅读，能够让我们更好地把握作者的观点和论述的逻辑。**阅读建议第二点：抓住核心概念，找出概念间的联系**。学术著作往往会提出一些重要的概念，然后从理论上进行阐释，阅读《乡土中国》要特别关注其中的重要概念，如礼俗社会、差序格局、无讼、无为政治等；费孝通先生在《乡土中国》的序言里说，搞清楚我所谓乡土社会这个概念，就可以帮助我们去理解具体的中国社会，概念在这个意义上是我们认识事物的工具，理解书中的核心概念、找到作者认识事物解决问题的工具，就等于掌握了阅读学术类著作的钥匙，借助这把钥匙就能够把握全书的主要内容、理解其学术研究的价值。那么应该怎样抓住和理解核心概念呢？第一，留意目录中的核心概念：《乡土中国》的目录包含一些核心概念，如差序格局、无讼等等，在读目录时可以留心记下这些核心概念，把它们抓住。第二，在阅读正文时也要实时留意概念，碰到概念先区分它是一般概念还是核心概念，如果是核心概念，要将它勾画下来，并且思考这个概念是在什么样的语境中提出来的、它的内涵是什么、作者是如何围绕它展开论述的。第三，在对比中理解核心概念：在《乡土中国》这本书中，作者提出许多用来指称乡土社会的概念，并且往往同时提出指称其他社会的对应概念，比如作者分别用差序格局和团体格局这两个概念来分别表示乡土社会结构和西洋社会结构的格局，在两者的对比中，每个概念各自的内涵就更加清晰了；在理解某一个核心概念时，就可以尝试找到与它构成对比的另一个概念，在比较中更好地理解每一个概念；教材上有一个《乡土中国》概念对比表，同学们可以利用这个表格，梳理作者用来指称乡土社会的概念和与之相对应的指称其他社会的概念，并结合作者的论述理解这些概念的含义。第四，注意理解概念之间的联系：《乡土中国》中的很多概念都具有紧密的关联，例如差序格局和维系着私人的道德这两个概念就具有紧密的联系，用作者的话说就是，在差序格局中，社会关系是逐渐从一个一个人推出去的，是私人联系的增加，社会范围是一根根私人联系所构成的网络，因之我们传统社会里所有的社会道德也只在私人联系中发生意义，道德观念是依社会格局而决定的，有差序格局这样的社会结构格局，就自然会有维系着私人的道德；如果能将书中重要概念之间的联系弄清楚，就能更好地理解这本书的知识体系。第五，有时也会遇到一些不容易理解的概念，在这种情况下可以反复阅读、联系上下文用心推敲它的含义，或者查阅一些资料，如词典、百科全书等，促进对概念的理解；面对一些比较抽象的概念，也可以调动自己的生活经验和知识，积极思考、促进对著作的理解。**阅读建议第三点：创作思维导图，把握知识体系**。《乡土中国》的正文包括 14 篇文章，作者在每一篇文章都提出了一些观点，而这 14 篇文章又相互关联、构成一个完整的知识体系；在阅读每一篇文章之后应该想一想，作者在这篇文章中阐述了怎样的内容；在阅读全书之后也应该想一想，这些文章分别讲到乡土社会哪些方面的特点，它们之间有何联系；可以将思考结果用思维导图的形式呈现出来：读完每一篇文章时，尝试画一个思维导图来概括这一篇文章的主要内容；如果认为某几篇文章的联系非常紧密、它们是在讲一个问题的不同方面，也可以尝试用一个思维导图去概括这几篇文章的主要内容；当阅读完整本书时，回顾之前画过的思维导图，利用这些思维导图去思考、分析全书各篇文章的联系，进一步尝试画一个总的思维导图来概括整本书的内容。举一个例子说明：《乡土中国》的第二篇和第三篇文章分别是《文字下乡》和《再论文字下乡》，阅读这两篇之后发现这两篇都是在讲乡土社会的语言文字使用情况，并且从不同角度来阐述为何乡土社会有语言而无文字，所以可以将这两篇归拢到一起，画一个思维导图来理清作者的论证思路：作者先由“乡下人在城里人的眼里是愚的”谈起，原因是乡下人不识字，但不识字其实是知识问题、不是智力问题，不识字并不是愚的表现；乡下多文盲，是因为乡下本来无需文字，这和乡土社会的本质有关——文字的发生是在人和人传情达意受到空间和时间阻隔的情境里，乡土社会的人是在熟人里长大的，他们是一个面对面的社群，在面对面的社群里有话可以当面说明白、无需借助文字；此外，乡下生活是同一方式的反复重演，乡下人身处于熟悉的社会中、过着定型的生活，就个人而言，生活经验用记忆和语言来保存就足够了，无需文字，就社会而言，语言足够传递世代间的经验，也无需文字，所以乡下人不识字，不是因为愚，而是因为他们没有使用文字的需要；作者进一步指出，中国社会乡土性的基层发生了变化，才能更好地推行文字下乡。借助这样一个思维导图，抓住了作者的主要观点、理清了作者的论证思路，将原文的内容化繁为简。画思维导图时需要注意：首先应该独立完成，思维导图创作的过程就是个人对这本书再阅读、再思考、再总结的过程，应该独立完成，而不要满足于现成的答案；别人的思维导图可以参考、借鉴，以此来优化自己的思维导图，但不应用别人的思考来代替自己的思考；此外，在阅读《乡土中国》时，会发现作者在每一篇中都提出了一些关键概念、阐明了一些观点，为了将概念解释得更清晰、让观点更加具有说服力，作者使用了大量的材料，例如民俗调查的案例、历史事实、生活经验、经典著作原文、民间俗语等，当画思维导图时，只需要呈现关键的概念、主要的观点即可，不必涉及材料；再有，在画思维导图时，应该尽量用准确、凝练的语言去概括作者的观点。**阅读建议第四点：品读文章，感受写作特色**。《乡土中国》是一部学术著作，读起来却并不觉得枯燥难懂，而是感觉它非常通俗自然、生动有趣，具有很强的可读性；阅读这本书，除了可以拓展视野、了解一些社会学的知识之外，还可以从文章品读的角度入手，感受作者的写作特色，从中借鉴一些写作方面的经验。第一是论点鲜明：《乡土中国》的每一篇文章都集中解决一个问题，而且文章的标题往往就是作者观点的凝练表达，例如读到“差序格局”这个标题，就能够明确这篇文章的主要论点是乡土社会的结构是差序格局，读到“无讼”这个标题，就能够明确这篇文章的主要论点是乡土社会维持秩序的理想手段是教化而不是诉讼，等等。第二是事例丰富而贴切：作者使用了大量的事例，并且这些事例都能够很好地验证作者的论点，例如在《礼治秩序》一文中，作者提到抗战时期自己在乡下的经历，孩子啼哭不止、自己找不到医生而请教房东老太太，老太太利用生活经验顺利地解决了问题，这个事例能够很好地论证作者的观点——乡土社会的生活很少变动，后人可以用前人的生活经验来解决很多问题，所以乡土社会里的人敬畏传统、主动地服膺于传统；作者运用贴切的事例，使读者更容易理解他的观点，也使观点更有说服力。第三是善用旧典翻出新意：在这本书中，作者也用了不少传统典籍文献，并且以新的视角、新的思路去解读他们，来验证自己的观点，例如在《维系着私人的道德》一文中，作者运用了《论语》中孔子对“人”的不同解释，指出《论语》中“人”这个观念并没有非常确定的解释，人其实是一系列私人间道德要素的总和，这表明在乡土社会的差序格局中没有超乎私人关系的道德观念；作者善于将旧典翻出新意、将旧典纳入到自己的论述体系之中，使人读到之后往往眼前一亮。第四是比喻巧妙：《乡土中国》里有不少巧妙的比喻，例如在《差序格局》一文中，作者将西洋社会的团体格局比喻成捆柴，将乡土社会的差序格局比喻成石头丢在水面上的一圈圈波纹；在《无讼》这篇文章中，作者用足球比赛来比喻礼治秩序的性质，这些比喻都十分形象，是对抽象理论的生动说明。第五是善于对比：作者在文中经常对比乡土社会与现代社会、乡土社会与西洋社会的诸多不同，这种对比展现了作者开阔的视野与宏观的思考，也使读者更加容易理解不同社会类型的特点。第六是语言通俗自然：《乡土中国》是一部学术著作，读来却并不感到枯燥和艰涩，作者用通俗易懂、朴实自然的语言，向读者阐明一个个抽象的概念和理论，这展现了作者深厚的学术素养和不凡的语言功力。以上就是给同学们提供的《乡土中国》整本书阅读建议，希望这些建议能够帮助你更好地展开阅读，也希望同学们在读书的过程中积累学术著作阅读的经验、形成适合自己的读书方法、养成良好的阅读习惯。课末两个练习：一是阅读学术著作要先粗读后细读，那么粗读和细读分别指什么；二是阅读《乡土中国》要关注核心概念，那么我们应该怎样抓住和理解核心概念呢。第一题参考答案：粗读主要包括三点——阅读序言后记，了解作者的写作背景和写作目的；浏览目录，大体了解著作的基本内容和章节结构；浏览正文、快速跳读，对全书形成初步的整体感知。细读是指对文章进行精细深入的阅读，注重概念、材料、论证、推理等要素，深入思考、不断提炼。第二题参考答案：留意目录中的核心概念；勾画正文中的核心概念，思考其产生的语境、内涵，以及作者如何围绕它展开论述；在对比中理解核心概念；理解概念之间的联系；反复阅读、查阅资料、联系经验，促进理解。", "vtech": [["核心概念怎么抓", "五法：留意目录中的核心概念；在正文里勾画核心概念、想它在什么语境提出、内涵是什么、作者如何围绕它展开论述；在对比中理解（如差序格局 vs 团体格局）；理解概念之间的联系（如差序格局与维系着私人的道德）；难懂的概念反复读、查词典百科、联系生活经验。"], ["思维导图怎么画", "每读完一篇文章画一个导图概括主要内容；联系紧密的几篇（如《文字下乡》《再论文字下乡》）合画一个；读完整本书再画总导图；导图只呈现关键概念和主要观点、不必涉及材料；独立完成、不用别人的思考代替自己的思考。"], ["细读一篇怎么下手", "以《差序格局》为例：先抓核心概念（差序格局及其对比概念团体格局），再区分观点与材料（看作者用什么材料支撑观点），再看论证方法（比喻、事实、道理、对比），最后看逻辑推理（由具体事实概括出一般理论是归纳推理）。"], ["写作特色六点怎么答", "论点鲜明（标题往往就是观点的凝练表达）、事例丰富而贴切、旧典翻出新意（《论语》中“人”的不同解释）、比喻巧妙（团体格局如捆柴、差序格局如水波纹、礼治秩序如足球比赛）、善于对比、语言通俗自然。"]], "vgaokao": []}}, "chn_c020": {"name": "劝学", "sec": 1, "secTitle": "第10课", "page": 83, "desc": "荀子论学习：比喻论证的教科书，通假字与默写双高频篇目。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《劝学》中说明学习要善于借助外力的句子（含通假字）。", "answer": "君子生非异也，善假于物也（「生」通「性」）"}, "pre": [], "next": ["chn_c021"], "content": {"advance": {"a": "荀子说学不可以已却反对空想：「吾尝终日而思矣，不如须臾之所学也」。韩愈则强调从师而学、博约结合。相通处：都把后天持续的学习看作人超越本性的唯一通道，都反对自满与自弃。差别在侧重：劝学重个人的积累与坚持，师说重向他人求教的途径。", "kind": "self", "q": "《劝学》与《师说》都谈学习，观点上有什么相通与不同？"}, "apply": [{"ans": 1, "opts": ["只有本体没有喻体", "本体是「学习贵在积累、坚持、专一」的道理，喻体是积土成山、骐骥驽马、锲而不舍、蚓蟹对比等一系列生活事理", "把荀子比作蚓", "比喻对象都是动物"], "q": "本篇比喻论证的特点是（ ）", "why": "比喻论证要拆本体与喻体：道理是本体，一连串自然事理是喻体，一喻多证是荀子的标志。"}, {"q": "「青，取之于蓝，而青于蓝」中介词结构「于蓝」放在动词之后，这种句式是（ ）", "opts": ["宾语前置", "判断句", "被动句", "状语后置（介词结构后置）"], "ans": 3, "why": "「于蓝」是介词结构，位置在动词「取」之后，属于状语后置；现代汉语语序应为「从蓝草中取出」。"}], "basics": [{"ans": 1, "opts": ["「暴」通「曝」，晒；「有」通「又」", "「暴」就是暴力；「有」是拥有", "「暴」通「爆」，爆炸", "与通假无关"], "q": "「虽有槁暴，不复挺者」中的通假关系是（ ）", "why": "「有」通「又」（再），「暴」通「曝」（晒干）；全句：木材经晒干、火烤弯曲便不再直了。"}, {"ans": 1, "opts": ["劝说别人入学", "勉励（人勤学）", "强迫", "建议"], "q": "《劝学》的「劝」在古代汉语中的意思是（ ）", "why": "这是古今异义：劝，古义为勉励，今义多为劝说、规劝。"}], "case": {"a": "「青于蓝」：青胜过蓝——学习可以使人超越原有水平。「冰寒于水」：冰比水冷——后天的加工可以改变事物的程度。合起来：两个比喻同向，都在论证学习（加工）对人的提升作用，为「学不可以已」提供第一层证据。", "q": "翻译并分析：「青，取之于蓝，而青于蓝；冰，水为之，而寒于水。」两句各自的论证指向是什么？", "title": "案例：翻译加论证"}, "intro": "第六单元开篇是**荀子**的《劝学》。==这篇的考点密度全册最高：**比喻论证**的系统、通假字四个、默写名句六组。==**读法：把它当成一篇「道理＋比喻」的双层文本——每组比喻对应一条学习之理。**", "learn": [{"h": "总论点与三段论证", "p": "首句「学不可以已」是总论点。以下三段各攻一个方面：第一段（青、冰、木、金）论学习可以**改变与提升人**；第二段（登高、疾风、假舟楫、假舆马）论学习要**借助外物**——「君子生非异也，善假于物也」；第三段（积土积水、骐骥驽马、锲、蚓蟹）论学习的**积累、坚持、专一**。答题写结构，必须按这三层说。"}, {"h": "通假字与古今异义", "p": "通假四例必记：「輮」通「煣」（火烤使弯曲）、「有」通「又」、「暴」通「曝」、「知」通「智」、以及第二段的「生」通「性」（君子生非异也）。古今异义：「爪牙」古指动物的爪与牙（中性），今为贬义的帮凶；「劝」古义勉励。==通假题的答法固定：写出本字＋释义＋整句翻译，三件缺一扣一半。=="}, {"h": "默写名句六组与易错字", "p": "高频六组：①青，取之于蓝，而青于蓝 ②不积跬步，无以至千里；不积小流，无以成江海 ③骐骥一跃，不能十步；驽马十驾，功在不舍 ④锲而舍之，朽木不折；锲而不舍，金石可镂 ⑤蚓无爪牙之利…用心一也 ⑥君子博学而日参省乎己，则知明而行无过矣。易错字：「跬」不是「硅」；「锲」不要写成「契」；「輮以为轮」的「輮」读 róu。"}], "pitfalls": ["「虽有槁暴」的通假配对记反：是「有」通「又」、「暴」通「曝」。", "翻译「善假于物也」的「假」误作真假之假——它是凭借、借助之义。", "结构题把第二、三段混成一段：借物（善假）与积累坚持专一是两层不同的论证。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 19, "t": "劝学·师说", "dur": "69:13", "from": "名师课堂", "vtop": ["劝学中心论点是“学不可以已”：第一段讲学习的意义（青出于蓝、冰寒于水、木直中绳輮以为轮、金就砺则利，学习提高智能、改造品性），第二段讲学习的作用（登高而招、顺风而呼、假舆马、假舟楫，借助外物事半功倍），第三段讲学习的方法与态度（积累、坚持、专一）。", "师说中心论点是“师者，所以传道受业解惑也”：第一段提出中心论点并从两个角度阐述，第二段用对比论证（古之圣人 vs 今之众人、巫医乐师百工之人 vs 士大夫、句读之不知 vs 惑之不解）层层深入，第三段以李蟠为例，末段交代写作缘起。", "两篇都是说理文但路子不同：劝学通篇比喻论证（青、冰、木、金、登高、顺风、假舆马、假舟楫、积土成山、锲而不舍、蚓无爪牙之利），师说以对比论证为主、兼用引用论证；背诵与默写都要落实文言实词、通假字、词类活用、特殊句式。"], "vsum": "本课由两段视频拼成：前 25 分钟是名师课堂讲《劝学》，后 44 分钟是黄姨语文逐句精讲《师说》。两篇都讲全了，没有缺口。先讲《劝学》。开场走进作者：荀子，名况，字卿，赵国人；散文说理透彻，后人编为《荀子》，其中绝大部分是荀子的作品，其余为荀子弟子记录的荀子言论和思想观点；荀子在教育目的上与先秦儒者保持一致，即通过教育来培养士、君子、圣人，认为人的知识、道德不是天赋予的，而是经过后天教育、学习逐渐培养的；他写《劝学》就是为了勉励人们积善成德、成为君子，《劝学》是《荀子》中的第一篇。接着对本课重点文言知识进行总结：借助字源示意的办法学习两个重要的文言实词，再过通假字、特殊句式，然后借助书下注释翻译全文。**品读感悟**：第一自然段，作者借在学问上有修养的人提出“学不可以已”的观点，“君子”指有学问有修养的人；作者从学习的意义分析，有条理有层次、论述严密。第二段末句“君子博学而日参省乎己，则知明而行无过矣”是前文几组比喻得出的结论，从这一点看，荀子劝学是劝人们首先要学习做人。第三段作者连用“登高而招，顺风而呼，假舆马，假舟楫”四个比喻，从见、闻、陆、水等方面阐明在实际生活中利用和借助外界条件所起的重要作用——善假于物。第四段共有三个层次：第一层论述学习要积累，作者先正面论述，从积土、积水推论到积善，正面论述积累的作用，说明学习上的成就是不断积累起来的，接着又用“不积跬步，不积小流”两个比喻，从反面说明如果不积累就不能达到远大目标；第二层论述学习要持之以恒，先用骐骥与驽马对比，坚持不懈才是学好的关键，进一步说明只有坚持不懈、持之以恒才会有所成就；第三层论述学习要专一，作者用蚓和蟹两个比喻正反对照，说明做到积累和坚持不懈后还要专一。第一段的五个比喻（青取之于蓝而青于蓝、冰水为之而寒于水、木直中绳輮以为轮、金就砺则利）论述了学习的意义在于能提高人的智能、改造人的品性，使人智慧明达、不犯过错，学习的重要性被提升到了新的高度，学习是人类不断进步的阶梯。课末思考：本文的中心论点是什么——“学不可以已”。再讲《师说》。开场先讲作者韩愈与背景知识：韩愈是唐代古文运动的倡导者，所谓古文运动首先是文学上的一种改革；写作背景是当时士大夫耻于从师、师道不振，韩愈写《师说》抨击这种风气。逐句精讲第一段：“师者，所以传道受业解惑也”——老师是用来传授道理、教授学业、解答疑难的人，“所以”有两个固定意思，一是“用来”，二是“……的原因”；“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；“生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之”；“吾师道也，夫庸知其年之先后生于吾乎？是故无贵无贱，无长无少，道之所存，师之所存也”。讲到“耻学于师”与通假字，再讲“圣人无常师”与“巫医乐师百工之人，不耻相师”，以及“六艺经传皆通习之”中的“六艺经传”就是解释经的书。**中心论点与结构**：第一段提出中心论点并从两个角度阐述中心论点；第二段用对比论证——古之圣人其出人也远矣，犹且从师而问焉，今之众人其下圣人也亦远矣，而耻学于师；再拿巫医乐师百工之人与士大夫之族对比，句读之不知、惑之不解，小学而大遗；对比有横比和纵比，三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论；第三段以李蟠为例；最后引用论证收束。知识点总结后讲特殊句式：状语后置（如《曹刿论战》“战于长勺”，翻译过来就是“于长勺战”，即在长勺作战，介宾做状语、还后置了，所以叫状语后置）、省略句（如《桃花源记》“见渔人”，省略了主语“村民”，古文的原则是能省就省），并提醒学习古文最懵的就是省略，要多读几遍。全文收束：像《劝学》还有《师说》这些文章都很简单，老师不停地讲为什么要讲《劝学》、为什么要讲《师说》，都是在鼓励大家去学习——劝学是鼓励大家学习，师说是叫大家一定要端正自己求学的态度，把这些文章放在一起给大家讲，也是想让大家真真正正地意识到学习的重要性，因为学习可以改变你的命运，你不学习、你的命运就这样了，但是你学习之后一切皆有可能。", "vtech": [["劝学比喻题怎么答", "先认比喻本体和喻体：青取之于蓝而青于蓝（学习提高）、冰水为之而寒于水、木直中绳輮以为轮（改造品性）、金就砺则利；登高而招、顺风而呼、假舆马、假舟楫（善假于物）；积土成山、积水成渊、积善成德、不积跬步（积累）、骐骥一跃、驽马十驾、锲而不舍、金石可镂（坚持）、蚓无爪牙之利、蟹六跪而二螯（专一）；答题先点比喻、再说论证了什么。"], ["师说对比论证三组怎么分", "纵比：古之圣人其出人也远矣，犹且从师而问焉；今之众人其下圣人也亦远矣，而耻学于师；横比：巫医乐师百工之人不耻相师，士大夫之族耻相师；句读之不知、惑之不解，小学而大遗；三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论。"], ["文言知识四件套怎么落实", "通假字、词类活用、古今异义、特殊句式四件套每篇先过一遍再进文本：如“受”通“授”、句读之不知是宾语前置、战于长勺是状语后置、见渔人是省略句；默写只考名句，先把主旨句写对。"], ["两篇主旨句怎么背", "劝学背“学不可以已”与“君子博学而日参省乎己，则知明而行无过矣”；师说背“师者，所以传道受业解惑也”与“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；默写只考名句，先把这两句写对。"]], "vgaokao": []}}, "chn_c021": {"name": "师说", "sec": 1, "secTitle": "第10课", "page": 84, "desc": "韩愈论从师：破立结合，「道之所存，师之所存也」。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《师说》中定义老师职能的句子（含通假字）。", "answer": "师者，所以传道受业解惑也（「受」通「授」）"}, "pre": ["chn_c020"], "next": ["chn_c024", "chn_c028"], "content": {"advance": {"a": "巫医乐师百工之人不耻相师，是因为技艺学习有明确标准、不涉及社会等级面子；而士大夫以从师为耻，是因为他们把「师」与身份地位捆绑，怕被人笑位卑者为师。韩愈由此点出：耻于从师的根源是世俗的等级观，而不是学习本身有什么可耻。", "kind": "self", "q": "韩愈说「巫医乐师百工之人，不耻相师」，而士大夫却耻学于师。差异的根源在哪里？联系课文说说。"}, "apply": [{"ans": 0, "opts": ["古之圣人（圣人）与今之众人：圣人无常师、不耻下问，众人却耻学于师，结果「圣益圣，愚益愚」", "君子与小人谁更有钱", "老师与学生的年龄", "文章长短的对比"], "q": "文中第一组正反对比是（ ）", "why": "三组对比须按顺序记牢：圣人与众人、自己孩子与自己、百工之人与士大夫。"}, {"ans": 1, "opts": ["判断句", "被动句", "宾语前置句", "省略句"], "q": "「师者，所以传道受业解惑也」属于（ ）", "why": "「……者，……也」是文言判断句的标志句式，「所以」在此是「用来……的」之意。"}], "basics": [{"ans": 1, "opts": ["授予", "忍受", "享受", "给予"], "q": "「传道受业解惑」中的「受」通「授」，意思是（ ）", "why": "受通授：传授、教授；本句是《师说》最著名的定义句。"}, {"ans": 1, "opts": ["学生必须比老师年轻", "能者为师：谁先明白道理，谁就可以做老师，不必拘于年龄与地位", "老师只能传授书本知识", "从师是可耻的"], "q": "「道之所存，师之所存也」的核心主张是（ ）", "why": "这是全篇立论的关键：以道为师资标准，打破门第与年资的偏见。"}], "case": {"a": "这是宾语前置句，正常语序为「不知句读，不解惑」。韩愈说：士大夫对孩子学句读就请老师，对自己不懂的疑惑却不从师求解——小的方面学了，大的方面丢了，我看不出他们的高明。讽刺的就是这种选择性学习的荒谬。", "q": "翻译：「句读之不知，惑之不解，或师焉，或不焉，小学而大遗，吾未见其明也。」并指出句式特点。", "title": "案例：宾语前置"}, "intro": "**韩愈**为打破「耻学于师」的风气而作。==结构是标准的破立结合：先立「古之学者必有师」，再破士大夫之族的种种谬态。==考点集中在**对比论证**（三组）与那几个定义句。", "learn": [{"h": "立论：师与道", "p": "开篇即下定义：「古之学者必有师。师者，所以传道受业解惑也。」接着把从师的理由钉死：人非生而知之，孰能无惑；惑而不从师，其为惑也终不解矣。然后抛出全文的纲：「是故无贵无贱，无长无少，道之所存，师之所存也。」——以**道**为唯一标准，是韩愈从师观的革命性所在。"}, {"h": "三组对比", "p": "第一组：古之圣人 vs 今之众人（圣人无常师而从师之多，众人耻学于师，结果圣益圣、愚益愚）。第二组：爱其子（为孩子择师） vs 于其身（自己却耻师）——小学而大遗。第三组：巫医乐师百工之人（不耻相师） vs 士大夫之族（动曰「彼与彼年相若也，道相似也」，位卑则足羞，官盛则近谀）。==对比题答题要逐组对应：对照物、差别点、作者结论，三件齐备。=="}, {"h": "关键文言点", "p": "通假：「受」通「授」。句式：「句读之不知，惑之不解」是宾语前置（之字提宾）；「师不必贤于弟子」不是贬低老师，是说各有所长；「不耻相师」的「耻」是意动用法，以……为耻（的反面：不以相师为耻）。「句读」读 jù dòu，指文章停顿处。"}], "pitfalls": ["把「受业」按字面解成接受学业：受通授，是传授。", "「师不必贤于弟子，弟子不必不如师」理解成老师可以不如学生——原意是各有专长、道无先后。", "默写错字：「传道受业解惑」的「惑」与「吾未见其明也」的判断不要丢。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 19, "t": "劝学·师说", "dur": "69:13", "from": "名师课堂", "vtop": ["劝学中心论点是“学不可以已”：第一段讲学习的意义（青出于蓝、冰寒于水、木直中绳輮以为轮、金就砺则利，学习提高智能、改造品性），第二段讲学习的作用（登高而招、顺风而呼、假舆马、假舟楫，借助外物事半功倍），第三段讲学习的方法与态度（积累、坚持、专一）。", "师说中心论点是“师者，所以传道受业解惑也”：第一段提出中心论点并从两个角度阐述，第二段用对比论证（古之圣人 vs 今之众人、巫医乐师百工之人 vs 士大夫、句读之不知 vs 惑之不解）层层深入，第三段以李蟠为例，末段交代写作缘起。", "两篇都是说理文但路子不同：劝学通篇比喻论证（青、冰、木、金、登高、顺风、假舆马、假舟楫、积土成山、锲而不舍、蚓无爪牙之利），师说以对比论证为主、兼用引用论证；背诵与默写都要落实文言实词、通假字、词类活用、特殊句式。"], "vsum": "本课由两段视频拼成：前 25 分钟是名师课堂讲《劝学》，后 44 分钟是黄姨语文逐句精讲《师说》。两篇都讲全了，没有缺口。先讲《劝学》。开场走进作者：荀子，名况，字卿，赵国人；散文说理透彻，后人编为《荀子》，其中绝大部分是荀子的作品，其余为荀子弟子记录的荀子言论和思想观点；荀子在教育目的上与先秦儒者保持一致，即通过教育来培养士、君子、圣人，认为人的知识、道德不是天赋予的，而是经过后天教育、学习逐渐培养的；他写《劝学》就是为了勉励人们积善成德、成为君子，《劝学》是《荀子》中的第一篇。接着对本课重点文言知识进行总结：借助字源示意的办法学习两个重要的文言实词，再过通假字、特殊句式，然后借助书下注释翻译全文。**品读感悟**：第一自然段，作者借在学问上有修养的人提出“学不可以已”的观点，“君子”指有学问有修养的人；作者从学习的意义分析，有条理有层次、论述严密。第二段末句“君子博学而日参省乎己，则知明而行无过矣”是前文几组比喻得出的结论，从这一点看，荀子劝学是劝人们首先要学习做人。第三段作者连用“登高而招，顺风而呼，假舆马，假舟楫”四个比喻，从见、闻、陆、水等方面阐明在实际生活中利用和借助外界条件所起的重要作用——善假于物。第四段共有三个层次：第一层论述学习要积累，作者先正面论述，从积土、积水推论到积善，正面论述积累的作用，说明学习上的成就是不断积累起来的，接着又用“不积跬步，不积小流”两个比喻，从反面说明如果不积累就不能达到远大目标；第二层论述学习要持之以恒，先用骐骥与驽马对比，坚持不懈才是学好的关键，进一步说明只有坚持不懈、持之以恒才会有所成就；第三层论述学习要专一，作者用蚓和蟹两个比喻正反对照，说明做到积累和坚持不懈后还要专一。第一段的五个比喻（青取之于蓝而青于蓝、冰水为之而寒于水、木直中绳輮以为轮、金就砺则利）论述了学习的意义在于能提高人的智能、改造人的品性，使人智慧明达、不犯过错，学习的重要性被提升到了新的高度，学习是人类不断进步的阶梯。课末思考：本文的中心论点是什么——“学不可以已”。再讲《师说》。开场先讲作者韩愈与背景知识：韩愈是唐代古文运动的倡导者，所谓古文运动首先是文学上的一种改革；写作背景是当时士大夫耻于从师、师道不振，韩愈写《师说》抨击这种风气。逐句精讲第一段：“师者，所以传道受业解惑也”——老师是用来传授道理、教授学业、解答疑难的人，“所以”有两个固定意思，一是“用来”，二是“……的原因”；“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；“生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之”；“吾师道也，夫庸知其年之先后生于吾乎？是故无贵无贱，无长无少，道之所存，师之所存也”。讲到“耻学于师”与通假字，再讲“圣人无常师”与“巫医乐师百工之人，不耻相师”，以及“六艺经传皆通习之”中的“六艺经传”就是解释经的书。**中心论点与结构**：第一段提出中心论点并从两个角度阐述中心论点；第二段用对比论证——古之圣人其出人也远矣，犹且从师而问焉，今之众人其下圣人也亦远矣，而耻学于师；再拿巫医乐师百工之人与士大夫之族对比，句读之不知、惑之不解，小学而大遗；对比有横比和纵比，三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论；第三段以李蟠为例；最后引用论证收束。知识点总结后讲特殊句式：状语后置（如《曹刿论战》“战于长勺”，翻译过来就是“于长勺战”，即在长勺作战，介宾做状语、还后置了，所以叫状语后置）、省略句（如《桃花源记》“见渔人”，省略了主语“村民”，古文的原则是能省就省），并提醒学习古文最懵的就是省略，要多读几遍。全文收束：像《劝学》还有《师说》这些文章都很简单，老师不停地讲为什么要讲《劝学》、为什么要讲《师说》，都是在鼓励大家去学习——劝学是鼓励大家学习，师说是叫大家一定要端正自己求学的态度，把这些文章放在一起给大家讲，也是想让大家真真正正地意识到学习的重要性，因为学习可以改变你的命运，你不学习、你的命运就这样了，但是你学习之后一切皆有可能。", "vtech": [["劝学比喻题怎么答", "先认比喻本体和喻体：青取之于蓝而青于蓝（学习提高）、冰水为之而寒于水、木直中绳輮以为轮（改造品性）、金就砺则利；登高而招、顺风而呼、假舆马、假舟楫（善假于物）；积土成山、积水成渊、积善成德、不积跬步（积累）、骐骥一跃、驽马十驾、锲而不舍、金石可镂（坚持）、蚓无爪牙之利、蟹六跪而二螯（专一）；答题先点比喻、再说论证了什么。"], ["师说对比论证三组怎么分", "纵比：古之圣人其出人也远矣，犹且从师而问焉；今之众人其下圣人也亦远矣，而耻学于师；横比：巫医乐师百工之人不耻相师，士大夫之族耻相师；句读之不知、惑之不解，小学而大遗；三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论。"], ["文言知识四件套怎么落实", "通假字、词类活用、古今异义、特殊句式四件套每篇先过一遍再进文本：如“受”通“授”、句读之不知是宾语前置、战于长勺是状语后置、见渔人是省略句；默写只考名句，先把主旨句写对。"], ["两篇主旨句怎么背", "劝学背“学不可以已”与“君子博学而日参省乎己，则知明而行无过矣”；师说背“师者，所以传道受业解惑也”与“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；默写只考名句，先把这两句写对。"]], "vgaokao": []}}, "chn_c022": {"name": "反对党八股（节选）", "sec": 2, "secTitle": "第11课", "page": 85, "desc": "毛泽东列党八股八大罪状：针对性最强的政论文，看立场与读者意识。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": [], "next": ["chn_c023"], "content": {"advance": {"a": "毛泽东说党八股的第一条罪状就是空话连篇、言之无物。他反对的其实是一种脱离实际、脱离群众的工作作风与文风。把文风与作风连起来看：形式主义文风的背后是形式主义的工作方法——这是全文最深一层的意思。", "kind": "self", "q": "《反对党八股》在延安整风中提出。本文批判的只是「文章写法」吗？谈谈你的理解。"}, "apply": [{"ans": 1, "opts": ["堆砌辞藻", "列举罪状、条分缕析，有破有立（如何写好文章）", "通篇讲故事", "大量引用古典"], "q": "本文说理的主要方式是（ ）", "why": "政论文的典型结构：把批判对象分条列罪，破后有立，条理感就是说服力。"}, {"ans": 1, "opts": ["不需要考虑读者是谁", "要有明确的对象感：文章写给谁、要解决什么问题，据此决定内容与语言", "对象越模糊越好", "只需考虑上级"], "q": "从「无的放矢」一条可提炼的写作原则是（ ）", "why": "「的」就是目标、对象：写作必须有对象意识，这是本篇最可迁移的写作学。"}], "basics": [{"ans": 1, "opts": ["五条", "八条", "三条", "十条"], "q": "「党八股」之名源于文章列出的罪状共（ ）", "why": "八大罪状与明清科举的八股文条数相呼应，「党八股」由此得名。"}, {"ans": 1, "opts": ["古希腊寓言", "明清科举考试的八股文", "八种乐器", "八卦"], "q": "「八股」原指（ ）", "why": "八股文是明清科举的程式化文体，毛泽东借喻党内程式化、教条化的坏文风。"}], "case": {"a": "例子：开会发言先引用文件十条，再逐项复述，最后表态完毕——内容空洞（对罪状一）、照本宣科不看听众（对罪状三）、用词套话连篇（对罪状四）。改进：先说本单位的三个真问题，只引一条文件作依据，用大白话讲清两条打算。", "q": "用身边一个例子（如班会发言、社团总结）对照八大罪状中的任意两条，说明它的问题，并给出改进版的第一句话。", "title": "案例：罪状对号入座"}, "intro": "第 11 课是**毛泽东**在延安干部会议上的讲演。==它骂的是一种文体病——「党八股」：话很长，理没有。==读政论文，抓的是**针对性**：每一句都知道在打谁、为什么打。", "learn": [{"h": "什么是党八股", "p": "八股本是明清科举的程式文，有固定段落与套话。毛泽东借这个名字，骂党内一些人写文章、作报告时的程式化、教条化文风，并一一列明**八大罪状**：空话连篇，言之无物；装腔作势，借以吓人；无的放矢，不看对象；语言无味，像个瘪三；甲乙丙丁，开中药铺；不负责任，到处害人；肿毒流传，毒害党体；传播出去，祸国殃民。"}, {"h": "针对性：政论文的命门", "p": "这篇讲演的听众是延安的干部，讲的问题全是他们正犯的毛病——这正是它打的第一枪「无的放矢，不看对象」的反面示范。考点意识：政论文与散文不同，评价标准第一位是**对象明确、问题明确、主张明确**。答题时把这三明确说出来，就切中了政论文的文体特点。"}, {"h": "由破到立", "p": "列完罪状，文章还给出正面主张：学好马克思列宁主义、向群众学习语言、文章要让普通人读得懂。这种**破立结合**与《师说》《拿来主义》是同一种论证骨架——第六单元的四篇文章，可以在这条线上串成一道大题。"}], "pitfalls": ["把「党八股」误解为八个段落或八个部分：它是罪状有八条，名字借自科举八股文。", "答题只列罪状名称，不说明每条针对什么问题——名称是骨架，问题是血肉。"]}, "video": {"bvid": "BV1Lu411H7GG", "p": 1, "t": "反对党八股（节选）", "dur": "26:00", "from": "小熊图书", "vtop": ["党八股是党内某些人写的文章，如同八股文：八股文连字数都有限制，考生只能按题目字数敷衍成文，写出来的文章没有内容、只讲形式，是文字的游戏；党八股就是党内的这种不良文风，毛泽东持反对态度。", "本文写于1942年延安整风时期：整风三个方面是反对主观主义、反对宗派主义、反对党八股；全文分五个部分——总说反对党八股的必要性、分析党八股的历史根源和阶级根源、列举党八股的罪状并深刻剖析、提出打倒党八股的办法、照应开头号召彻底打倒党八股；本课选讲第三部分（八大罪状）。", "本视频只讲了前三条罪状：第一条空话连篇、言之无物；第二条装腔作势、借以吓人；第三条无的放矢、不看对象；第四至第八条老师说下节课继续讲，不在本视频内。"], "vsum": "本课讲《反对党八股》（节选），但只讲了八大罪状中的前三条：第四至第八条老师说下节课继续讲，不在本视频内。开场先讲八股文：这种八股文连字数都有限制，考生只能够按照题目的字数敷衍成文，所以最后写出来的文章是没有内容、只讲形式的文章，是文字的游戏；党内也出现了类似八股文的现象，所以伟大的领袖毛泽东就需要反对党八股。学习目标有三：学习作者的论证方法（列举、比喻等论证方法，表达方式也是论证方法的一个扩展），学习作者在写作时生动活泼的语言风格，从内容上了解不良文风的具体表现；还要掌握论点、论据、论证三要素。**作者与定义**：作者是毛泽东；党八股指的是党内某些人所写的文章，就如同八股文，所以被毛泽东称为党八股；对此党八股，毛泽东持反对的态度。**写作背景**：本文是毛泽东 1942 年在延安整风运动中写的文章；当时整风有三个方面，一个是反对主观主义，一个是反对宗派主义，而第三个就是反对党八股；争取抗日战争的最后胜利，这是当时的社会背景。**全文共分为五个部分**：第一部分是总说反对党八股的必要性；第二部分是详细地分析党八股的历史根源和阶级根源；第三部分就列举了党八股的罪状，对党八股进行全面而深刻的剖析；第四部分提出打倒党八股的办法；第五部分照应开头，号召人们彻底打倒党八股。**本课选讲第三部分，即党八股的罪状**。选文又分三部分：第一部分概括党八股的八大罪状，引出下文对八大罪状的具体分析和批判；第二部分从党八股的第一条罪状一直到第二条、第三条、第四条、第五条罪状，第六、七、八条到此处来了一个总结；第三部分总结前文的阐述，反对党八股、树立马克思列宁主义新文风的重要意义。接着逐条讲罪状。**第一罪状：空话连篇，言之无物**。**第二罪状：装腔作势，借以吓人**。主观主义和宗派主义表现在党八股式的文章和演说里面，却深怕人家不懂，非常胆怯，于是就靠装样子吓人，以为这一下人家就闭口了、自己就可以得胜回朝了；这里分析了第二条罪状产生的原因，就是想要吓唬别人、让别人不敢说话，深刻揭示了写这种文章的人表面上很厉害、实际上内心是空虚的心理状态；“得胜回朝”原指取得胜利归来，此处用来写党八股装腔作势、吓过别人后自以为是、自以为成功、自欺欺人的心理状态，这里用词是反语，反语能够达到辛辣尖锐讽刺的效果，加引号表示反语、否定和讽刺的效果。整个段落的论证思路是：先摆出第二大罪状，并且来分析它的原因和危害——作者先在和空话连篇的比较中摆出第二重罪状，说他简直是无赖，接着分析他产生的原因，即是主观主义、宗派主义，并非真理，最后指出他的危害，即不能反映真理、而是妨碍了真理；行文思路是先摆出罪状、分析问题，最后指出危害；同时作者结合党内斗争的历史教训进一步分析他的危害：首先指出了“残酷斗争”和“无情打击”这两种手段，尖锐地分析了错误地应用这两种手段的原因，及没有分析清楚该针对什么样的对象，所以来装腔作势、借以吓人，最后进一步指出吓人战术的危害及其本质，以吃饭这样的事情来做比喻，明确指出共产党要靠马克思列宁主义的真理、靠实事求是才能够吃饭，表明自己鲜明的立场、得出结论，才能够正面阐明观点。**第三罪状：无的放矢，不看对象**。“的”指的是靶心，即没有把心去放箭、不看对象，这就是他们写文章存在的问题；这一段主要论述做宣传工作必须要有“的”，“的”指的是群众，必须要联系实际，这也是一个“的”；开篇举了“工人”两个字的写法，从反面批评某些做宣传工作的同志没有“的”、脱离了“的”、脱离了实际的做法，又从正面指出共产党员如果真想做宣传就要看对象；接着通过分析那些不看对象的人的心理，揭示这一党八股调的主观主义思想实质，并创造性地运用“对牛弹琴”这一成语，对无的放矢、不看对象的党八股给予讽刺和严厉的批判；最后用“射箭要看靶子，弹琴要看听众，交朋友要互相知心”这样的大众常识来做比喻，从正面说明做宣传工作必须要联系实际、要有调查的对象、要联系实际，从而进行调查研究分析，这才是正确的做法。课末小结：老师已经讲了三条罪状，大家先消化，下一节课继续讲党八股的第四条罪状，看看下面的四、五、六、七、八到底是什么样的罪状、作者又想表达什么。", "vtech": [["罪状段落的论证思路怎么答", "先摆出罪状，再分析它产生的原因（主观主义、宗派主义），最后指出它的危害（不能反映真理、反而妨碍真理）；答题按“摆罪状—析原因—指危害”三步走，别只抄罪状名字。"], ["反语和比喻怎么辨", "“得胜回朝”原指取得胜利归来，这里写党八股装腔作势吓过别人后自以为成功、自欺欺人，是反语、加引号表示否定和讽刺；“吃饭”比喻共产党要靠马克思列宁主义的真理、靠实事求是才能够吃饭；“射箭要看靶子、弹琴要看听众、交朋友要互相知心”是大众常识作比喻，正面说明做宣传工作必须联系实际。"], ["无的放矢的“的”指什么", "“的”指的是靶心：没有把心去放箭、不看对象；做宣传工作必须要有“的”，“的”就是群众、就是实际；开篇举“工人”两个字的写法，从反面批评某些做宣传工作的同志脱离了“的”、脱离了实际。"], ["八大罪状只记住前三条够不够", "不够：考试若问八大罪状，要知道本视频只讲了前三条（空话连篇、装腔作势、无的放矢），后五条在下节视频；先把前三条的罪状名、表现、原因、危害背熟，再补后五条。"]], "vgaokao": []}}, "chn_c023": {"name": "拿来主义", "sec": 3, "secTitle": "第12课", "page": 88, "desc": "鲁迅的杂文范式：先破后立，比喻论证一段接一段。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《拿来主义》中对待文化遗产的方针用原文怎么说？", "answer": "我们要运用脑髓，放出眼光，自己来拿；实行「占有，挑选」。"}, "pre": ["chn_c022"], "next": [], "content": {"advance": {"a": "鸦片象征的是文化遗产中麻醉人、有害的一面。但鲁迅的态度是分类处理：作为药物它有真实用途（药用保管），作为毒品则害人。这一比喻反对两种极端：全盘否定（连同澡盆倒掉孩子）与全盘吸纳（见毒不避）。联系「挑选」的总原则，文化遗产必须辨别成分、区别对待。", "kind": "self", "q": "在「大宅子」的比喻里，鸦片被要求「送入药房」。联系全文，谈谈这一处理背后的态度。"}, "apply": [{"ans": 1, "opts": ["先大段表扬对方", "先破：批驳闭关主义与送去主义；后立：提出拿来主义的主张", "只破不立", "只立不破"], "q": "本文的论证结构是（ ）", "why": "破立结合是杂文的经典结构：不先扫清错误道路，自己的主张就没有位置。"}, {"ans": 1, "opts": ["只起装饰作用", "让抽象的文化取舍变成可触可感的生活场景，道理深入浅出，是鲁迅杂文的招牌手法", "纯粹为了幽默", "说明鲁迅喜欢收藏"], "q": "「大宅子、鱼翅、鸦片、烟枪、姨太太」一连串比喻在论证中的作用是（ ）", "why": "比喻论证在本篇达到极致：一个宅子模型装下了整套取舍逻辑。"}], "basics": [{"ans": 1, "opts": ["全盘西化", "运用脑髓，放出眼光，自己来拿", "全面拒绝外来文化", "先送去，再拿来"], "q": "「拿来主义」的核心主张是（ ）", "why": "「自己来拿」是主动选择，与被动接受、闭关自守都相对立。"}, {"ans": 2, "opts": ["鱼翅", "鸦片", "烟枪和烟灯", "姨太太"], "q": "按鲁迅的处置：只配送进博物馆（或毁掉）的是（ ）", "why": "烟枪烟灯只是古董陈列品，没有实用价值——象征遗产中纯供摆设炫耀的部分。"}], "case": {"a": "四分法：鱼翅——有营养价值，直接使用（遗产中精华、拿来滋养）；鸦片——有害但有药用价值，送药房存放利用（批判地吸收）；烟枪烟灯——无实用价值，送博物馆陈列（保留作标本反面教材）；姨太太——有害无益，大批送走（彻底清除的糟粕）。合起来就是「占有，挑选」四字的完整释义。", "q": "把鲁迅对四样东西的处置连同理由各写一句。", "title": "案例：四样东西四种处置"}, "intro": "**鲁迅**杂文的典范之作。==全文只有一条论证链：先堵死两条错路（闭关、送去），再亮出自己的路——对文化遗产，先「占有」，再「挑选」。==比喻是这篇的发动机。", "learn": [{"h": "先破：两条错路", "p": "第一条错路是**闭关主义**：自己不去、别人进来也不许，碰了钉子才慢慢知道。第二条是**送去主义**：把国粹、展览一味送出去讨好别人，鲁迅讽刺其下场——等到我们的子孙拿不出东西，就只能伸手向别人要「拿来」了。破得干脆，立才有地盘。"}, {"h": "后立：占有与挑选", "p": "核心公式：「我们要运用脑髓，放出眼光，自己来拿。」拿来的前提是**占有**（先不管是新宅子还是旧宅子，接受遗产），关键是**挑选**：有益的吸收，有害有害又有用的改造利用，无用有害的清除或封存。这一公式对今天对待外来文化与传统文化，仍然有效——这是本篇的现代价值点。"}, {"h": "比喻群：大宅子的四种处置", "p": "穷青年得了一所大宅子，比喻继承文化遗产。处置四样东西对应四种态度：鱼翅（有益，吃掉使用）、鸦片（有害但药用，送药房）、烟枪烟灯（无用，送博物馆）、姨太太（有害无益，放走）。==比喻论证题的标准拆法：喻体一个个拆，本体的对应关系一项项对齐——这道题在高考里出现过同类考法。=="}], "pitfalls": ["把「拿来主义」说成对外开放引进技术：它谈的是对文化遗产（首先是传统）的态度。", "处置对应记混：鸦片是送药房（利用），烟枪烟灯才是送博物馆（陈列）。", "只背结论句，不会拆解大宅子的比喻系统。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 20, "t": "拿来主义", "dur": "27:19", "from": "名师课堂", "vtop": ["全文分两部分：第一部分1–7段破，先破闭关主义、送去主义，再破送来主义，层层剥落各种文化现象、从而引出中心；第二部分8–10段立，集中阐释拿来主义的主张。", "中心论点是“我们要运用脑髓，放出眼光，自己来拿”，三个关键词：运用脑髓（独立思考、分辨是非）、放出眼光（既开阔宽广、又深刻独到）、自己来拿（敢拿、会拿）。", "杂文特点：结合现实、针砭时弊，提出观点不是主要目的、有现实针对性才是写作原则；作者不是一上来就提出中心论点，而是层层剥落各种文化现象从而引出中心，这是杂文和一般议论文结构有区别的地方。"], "vsum": "本课讲鲁迅《拿来主义》，全文讲全了，没有缺口。开场：今天我们来学习第十二课，鲁迅先生的《拿来主义》；在这篇文章中，鲁迅先生提出，运用脑髓，放出眼光，自己来拿。**作者介绍**：鲁迅，原名周树人，鲁迅是他发表《狂人日记》时所用的笔名，也是他影响最为广泛的笔名；鲁迅曾把杂文分为社会批判和文明批判，所强调的正是杂文的批评与批判的特点，顺次翻开鲁迅的十多本杂文集，就可以看一部不停息的批判；鲁迅杂文所显示的这种不屈不挠、战则不止的不屈精神，从根本上有别于传统士大夫的中庸之道，集中体现了鲁迅其人其文的现实性与反叛性。**写作背景**：鲁迅针对当时种种社会文化现象，深思熟虑后提出拿来主义。**第一部分 1–7 段**，先破后立：鲁迅曾说，杂文家批评一个人或一种社会现象、文化思潮，常加以简括的名称，虽只寥寥数字，却需要明确的判断力和表现的才能；这篇《拿来主义》用的也是这样的简括法，把当时对待外来文化的种种错误态度概括为闭关主义、送去主义、送来主义，再确立拿来主义的观点。第一段提出闭关主义和送去主义：在清政府奉行闭关主义的锁国政策下，闭关主义的本质就是排外，而危害则是清政府的丧权辱国，比喻成碰了一串钉子，暗含着讽刺的意味；接着论述送去主义，鲁迅敏锐地注意到，只送不拿、只输出不输入，这是一种媚外行径。第二段提出拿来的主张，这里需要大家注意，文章批判的锋芒不是对着几位艺术家，而是针对媚外的国民党当局及其反动文人。第三段指出，送去主义者盲目自大，送去主义的危害在于对文化只是自我陶醉、而不思变革进取，长此以往，丧失主动权，只能被动接受别人的残羹冷炙。四五六段集中分析送去和送来的关系：第四段揭示了送来的真实面目，即“抛给”——鲁迅一语中的，不要误解为抛来的东西，这是抛给的，说得文雅些，可以称之为送来；请大家比较一下抛来与抛给的感情色彩，抛来是个中性词，没有轻蔑侮辱的意味，不过是自己不要的东西扔出来罢了，而抛给犹如送来之物，含有轻蔑和鄙视，更多了强迫和不怀好意；鲁迅先生说，对送来的东西不想举出实例，其实这背后也是有现实的针对性，1933 年，国民政府和美国签署了棉麦借款协定，购买美国的小麦、面粉和棉花，美国借此向中国倾销了大量物资；所以第五段再次强调了送去之外还得拿来；为了进一步阐述送去与拿来的关系，文章没有直接论述，而是在第六段对送来继续列举事实、揭示本质：先有英国的鸦片，德国的废枪炮，后有法国的香粉，美国的电影，日本的印着“完全国货”的各种小东西；大家可以思考，这些外国势力送来的东西有什么特点：既有毒害国民身体的毒品，也有不能使用的军事武器，还有日用品，更有文化和思想的输出，可以说覆盖了社会生活和精神的方方面面；这是抛给的，是强制接受并且不允许选择，不同于主动的拿来，实际上是一种经济倾销、文化扩张；在鸦片战争以来的历史上，是西方殖民者军事、政治、经济侵略的伴随物；通过分析送来的本质，鲁迅先生启发我们认识送去与送来的关系：如果只是一味地送去，本质上是一种文化保守主义，最终会导致外国势力无孔不入的侵略和渗透，也就是送来；必须在送去之外奉行拿来主义，与外国在经济、技术、文化上进行双向交流；此外，第六段还直接揭示了送来的危害，连清醒的青年们也对洋货发生了恐怖，这就表明被动接受送来的东西，一方面处于被侵略的地位，另一方面也导致社会对西方文化的全面排斥和恐惧；一味送去的保守主义和媚外行径不可取，而盲目排外的主张也不可取；所以我们要运用脑髓，放出眼光，自己来拿，于是第七段就提出了拿来主义的宗旨。第一部分为了阐明中心论点拿来主义，运用了驳论和立论相结合的论证方法：第一段批判闭关主义和送去主义，用讽刺的语言暗中指出各自的本质；第二段提出拿来，有破有立；第三段借指出送去主义的危害引出送来及抛给；第五段再次明确拿来的必要性；第六段进一步指出送来的本质和危害；第七段明确拿来的宗旨；由此可以体察到鲁迅先生的思路。本文提出了拿来主义的主张，杂文的一个特点即结合现实、针砭时弊，第一部分鲁迅先生针对当时种种社会文化现象，深思熟虑后提出拿来主义；提出观点不是杂文的主要目的，有现实针对性才是杂文的写作原则；所以读这篇文章，我们发现作者并不是一上来就提出中心论点，而是层层剥落各种文化现象，从而引出中心，这也是杂文和一般议论文结构有区别的地方。“我们要运用脑髓，放出眼光，自己来拿”，这是对拿来主义的概括，也是本文的中心论点，这里有三个关键词：运用脑髓、放出眼光、自己来拿；其二，放出眼光，既开阔宽广、又深刻独到。**第二部分 8–10 段**，集中阐释了拿来主义的主张：第八段以大宅子比喻外来文化，展开形象化论述；对待大宅子的三种态度，一是孱头，害怕继承、拒绝借鉴，二是勃然大怒、放一把火烧光的昏蛋，三是欣欣然接受一切的废物；第九段一上来就从正面具体而形象地阐明了拿来主义的原则和方法，“占有”呼应了第八段的“首先是不管三七二十一，拿来”，即敢拿；挑选呼应运用脑髓、放出眼光、自己来拿，即会拿；敢拿和会拿是拿来主义的两个重要内涵；鱼翅是文化中精华的部分；用鸦片比喻有利有弊的部分；用烟枪烟灯和姨太太比喻完全的糟粕；拿来主义凝结了三重内涵：沉着、勇猛、有辨别、不自私。**现实意义与收束**：运用脑髓、放出眼光、自己来拿，就是一个既要敢拿、又要会拿的创新的过程；创新需要有眼光、有魄力，既能分辨、又不要丢掉文化自主性，既要广泛接纳、又要有文化自信；沉着、勇猛、有辨别、不自私，这就是真正能面对世界、理直气壮与世界对话、向世界学习、同时宣传自己文化的心态；即使到今天，鲁迅先生的拿来主义仍然具有现实意义；在文艺成为新文艺的过程中，鲁迅先生敏锐地发现，没有拿来的人不能自成为新人；在民族新文化形成的过程中，既要冲破传统、向西方学习科学和物质文明，又要保持警惕、吸取西方的教训、重视传统文化的传承和重建；而其中最有价值的，鲁迅先生提醒我们，不要忘记根底在人，在人的解放和民族精神的重建，也就是培养新人；这是和鲁迅先生的启蒙思想和改造国民性的观念一脉相承的；由此也启发当下的我们思考，发扬我们的民族文化、树立文化自信，重要的是培养有眼光、有辨别、有创新、不自私的人才。**总结**：借课堂反馈的题目共同进行总结：一、用富有画面感的构思，借助比喻，把深奥的道理说得通俗易懂，用大宅子比喻外来文化，用孱头、昏蛋、废物比喻对待外来文化三种不同的态度，用鱼翅、鸦片、烟枪和烟灯、姨太太比喻外来文化中不同的组成部分；二、用幽默犀利、讽刺性强的语言，鲜明地表达自己的观点态度，例如“只有烟灯和烟枪，虽然形式和印度、波斯、阿拉伯的烟具都不同，却可以算是一种国粹”——国粹原指传统文化中的精华，这里是反语，暗含着讽刺意味，指文化中应该抛弃的部分。", "vtech": [["孱头、昏蛋、废物怎么答", "对待外来文化的三种态度：孱头是害怕继承、拒绝借鉴，昏蛋是勃然大怒、放一把火烧光，废物是欣欣然接受一切；三者都不对，拿来主义是沉着、勇猛、有辨别、不自私。"], ["鱼翅、鸦片、烟枪烟灯、姨太太怎么答", "用鱼翅比喻文化中精华的部分；用鸦片比喻有利有弊的部分；用烟枪烟灯和姨太太比喻完全的糟粕；只有烟灯和烟枪，虽然形式和印度、波斯、阿拉伯的烟具都不同，却可以算是一种国粹——国粹原指传统文化中的精华，这里是反语，暗含讽刺意味，指文化中应该抛弃的部分。"], ["抛来与抛给怎么辨", "抛来是个中性词，没有轻蔑侮辱的意味，不过是自己不要的东西扔出来罢了；抛给犹如送来之物，含有轻蔑和鄙视，更多了强迫和不怀好意；送来的东西是抛给的、强制接受并且不允许选择，不同于主动的拿来，实际上是一种经济倾销、文化扩张。"], ["送去与送来什么关系", "只是一味地送去，本质上是一种文化保守主义，最终会导致外国势力无孔不入的侵略和渗透，也就是送来；必须在送去之外奉行拿来主义，与外国在经济、技术、文化上进行双向交流；被动接受送来的东西，一方面处于被侵略的地位，另一方面也导致社会对西方文化的全面排斥和恐惧——一味送去的保守主义和媚外行径不可取，盲目排外的主张也不可取。"]], "vgaokao": []}}, "chn_c024": {"name": "读书：目的和前提·上图书馆", "sec": 4, "secTitle": "第13课 读书两篇", "page": 94, "desc": "黑塞谈读书的目的，王佐良回忆图书馆：自读两篇，抓观点即可。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c021"], "next": [], "content": {"advance": {"a": "王佐良写图书馆不写建筑与藏书量，专写人在图书馆中的状态：安静、专注、人与书的默契。这与黑塞「读书要有自我的目的」相呼应：图书馆的意义不在藏书之多，而在它为独立思考者提供的秩序与氛围——外在的图书馆，最终是为了内心的图书馆。", "kind": "self", "q": "《上图书馆》看似回忆文字，与《读书：目的和前提》放在一课有什么内在联系？"}, "apply": [{"ans": 1, "opts": ["读得越多越好，不管内容", "要有自己的目的与判断，从书籍中获得真正的教养而非消遣", "只读经典名著", "读书只是为了考试得高分"], "q": "按黑塞的看法，读书最要避免的是（ ）", "why": "黑塞反对把读书当被动消遣：没有自我的读书，读得越多离教养越远。"}, {"ans": 1, "opts": ["地点偏僻", "学者的专注、藏书的秩序与学术传统的日常化身", "免费开放", "装修豪华"], "q": "《上图书馆》中牛津图书馆给作者最深印象的是（ ）", "why": "本篇以小见大：图书馆的气质就是一所大学学术品格的缩影。"}], "basics": [{"ans": 1, "opts": ["歌德", "黑塞", "叔本华", "尼采"], "q": "《读书：目的和前提》的作者黑塞是哪个国家的作家（ ）——他是（ ）文学的代表作家之一。", "why": "赫尔曼·黑塞，德国作家，代表作《悉达多》《荒原狼》，获诺贝尔文学奖。"}, {"ans": 1, "opts": ["报告文学", "书信体小说", "回忆性散文", "演讲稿"], "q": "《上图书馆》的文体是（ ）", "why": "王佐良以散文笔法回忆求学时期的图书馆经历，属回忆性散文。"}], "case": {"a": "黑塞的标准：是否出于自己的目的去读、读后是否形成自己的见解。对照：刷题式阅读多为被动完成任务，需补一条规则——每读完一本（一单元），写三句自己的话（一个认同点、一个疑点、一个与自身经验的连接），把被动读变主动读。", "q": "用黑塞的标准反观自己的读书：列出你最近读的一本书，判断它是「消遣性阅读」还是「求教养的阅读」，并写一句改进办法。", "title": "案例：拿我的读书对照黑塞"}, "intro": "第 13 课两篇自读文章谈同一件事——**读书**：黑塞谈为什么读，王佐良谈在图书馆里读是什么感觉。==自读篇目抓观点：每篇用一句话说清作者的主张，就算过关。==", "learn": [{"h": "黑塞：读书的目的与前提", "p": "赫尔曼·黑塞（德国作家）认为，读书的目的不是消遣，也不是盲目猎奇，而是获得**真正的教养**——通过阅读走一条属于自己的、认识世界与自我的路。前提则是读书的人要有自己的立场与品味：我们应当从自己的需要出发去选择书，而不是被畅销榜牵着走。本质上，他把读书看作一种自我修养工程。"}, {"h": "王佐良：上图书馆", "p": "王佐良是学者型散文家，本篇回忆他在英国求学时在图书馆读书治学的经历：图书馆的宁静、学者的专注、书籍作为精神家园的质感。文字平静克制，感情藏在细节里——借书的手续、阅览室的氛围、老教授的日常，都是学术传统的具体模样。"}, {"h": "两篇互文", "p": "两篇并读，是第六单元「学习之道」的收束：劝学说为何学、师说说向谁学、反对党八股说怎么写、拿来主义说如何对待遗产、读书两篇说怎样自主地学——从荀子到黑塞，这个单元本身就是一部微缩的「学习论」。考试中的单元综合题，最爱在这条线索上命题。"}], "pitfalls": ["黑塞国籍记错：他是德国（后入瑞士籍）作家，不要写成英国作家。", "只记黑塞反对消遣，漏掉他的正面主张：为获得真正教养、走自己的路而读。"]}, "video": {"bvid": "BV1H14y1H7aA", "p": 1, "t": "读书两篇", "dur": "47:53", "from": "项仁军名师工作室", "vtop": ["本课精讲王佐良《上图书馆》，黑塞《读书：目的和前提》在比较阅读与课堂延伸中对照讲：两篇都与读书有关，但论述内容不同——黑塞讲阅读经典是获得真正教养的最重要途径、提出正确的读书观；王佐良写自己在不同图书馆读书的几段经历，讲读书之乐。", "上图书馆之乐分四种：文华中学图书馆的启蒙之乐、清华大学进入新世界之乐、飘摇中获得宁静之乐、感悟知识理性伟大力量之乐；开头引用名言引出“上图书馆之乐”，结尾引用阿尔比斯的台词说明人类创造了知识理性那种伟大的力量和高贵的理性。", "健康的阅读观三问：为什么读书（获得鲜活的知识、意识和理解，由此获得满足和幸福；启示思考、获得意义、增强自我意识）、读什么书（能引起共鸣的书、真正的杰作，而不是报纸或粗浅的流行文字）、如何读书（专注态度、花力气下功夫、认识自己、不盲从不教条、培养有教养的人格）。"], "vsum": "本课精讲王佐良《上图书馆》，黑塞《读书：目的和前提》在比较阅读与课堂延伸中对照讲，两篇都讲到了，没有缺口。开场先定本课：今天学习这个单元的最后一课《上图书馆》，学习目标是品味王佐良的读书经历，品味读书场景的描写，品读分析王佐良的读书观。**作者王佐良**：正统教育出身，作为中国莎士比亚学会成员、翻译研究会成员，留学牛津大学攻读英国文学研究生，回国以后在中国莎士比亚学会任职；其读书经历与上大学、参加工作都与文化、图书馆相关。先落实字音：教义、音训、高耸、苍穹、白炽、赤灯、见习、复复等第一组字音要注意。**第一段到第三自然段**引用名言引出“上图书馆之乐”这个标题，然后写作者上图书馆的经历。**第一部分 4–5 自然段**写中学阶段上图书馆：作者上的是文华中学，写的是文华中学图书馆；接着写上大学的时候：清华大学图书馆，说的是清华图书馆；然后是牛津大学的博德林图书馆，博德林就是牛津大学图书馆；后来又到大英博物馆的图书馆去读书的情况；最后一句说上图书馆也有其奇趣。第十自然段点出“上图书馆之乐”。随后梳理作者不同阶段的读书选择和读书的感受与思考，养成看英文杂志的习惯。**上图书馆之乐分写四种**：文华中学图书馆的启蒙之乐，清华大学进入新世界之乐，飘摇中获得宁静之乐，感悟知识理性伟大力量之乐；概括第三自然段“上图书馆之乐”分写的就是这四种乐。接着进入研读阶段，把握观点和论证方法、文中开头与结尾：结尾直接引用阿尔比斯的台词，说明人类创造了知识理性那种伟大的力量和高贵的理性。表格梳理：上图书馆之乐有什么——启蒙之乐、进入新世界之乐、知识理性高尚伟大力量之乐等，对自身的影响从哪些角度写——在进出自己上图书馆的经历时，多次写到了自己因受到外界影响而产生不同的心情。由此做一个探究：有人认为读书就应该是家事、国事、天下事事事关心，也有人认为读书就应该是心无旁骛、两耳不闻窗外事、一心只读圣贤书，你怎样看待这一问题？答案是读圣贤书与关心窗外事并不矛盾：读圣贤书要专心致志、心无旁骛，闲暇时就了解社会、浏览新闻、把握时代的脉搏，天文地理、政治、各地风土人情、民俗特色，逐一品味这一道道文化的大餐，把读圣贤书与关心窗外事结合起来，让圣贤书的理论开启我们的智慧、引领我们去深刻认识社会，练就我们的思维、培养我们的能力，然后以我们的能力再去丰富圣贤的理论，让圣贤之书发扬光大、代代传承；既要家事国事天下事事事关心，还要参加社会、国家的建设。**整合拓展：比较阅读**。《读书：目的和前提》与《上图书馆》这两篇文章都与读书有关，他们论述的内容有什么不同？《读书：目的和前提》主要论述阅读经典是获得真正教养的最重要的途径之一，并阐明阅读经典著作的重要意义，提出正确的读书观，比如“书中自有颜如玉，书中自有黄金屋”那是东方的读书观点；而《上图书馆》写作者在不同图书馆读书的几段经历，从而表明读书之后这个乐有启蒙之乐、进入新世界之乐、飘摇中获得宁静之乐、感悟知识理性伟大力量之乐。两篇文章的相同点：都是按时间顺序记叙，都写到了自己不同时期读到的书籍和自己的感受与收获；不同点：《读书：目的和前提》描写自己的感受和收获比较详细具体，《上图书馆》在叙述中还写到了各个图书馆的建筑华美等特点。**课堂延伸**：黑塞第一篇中说到“红房子”，第一次是阿尔卑斯南面的芬芳的红房子，第二次是正如白昼、春夜和夜晚之间，我的人生、旅行欲望和安家愿望之间渐渐消逝；如果有一个中心，所有的例子是从这个中心发现了两端摆动，那时生活是多么的不同，但是我生活没有这样的一个中心，没有这样的中心就是把我变成另一个模样的，不是我的事情，这是神奇的事情，谁要寻找神奇、谁要把他引来、谁要帮助他，他就逃避谁；其实作者说我的事情是漂浮在许多紧张对立的矛盾之间，并且做好了精神准备，如果奇迹突然降临到我头上，我的事情是不满并忍受着动荡不安；然后绿色花园中的红房子，我对你已经有过体验，可我不想再次体验；第七段说我还会走许多弯路、将还讲失望许多，有许多愿望，但到头来仍然会使我失望，总有一天一切都显示它的意义；那矛盾消失的地方，是涅槃境界，还是可爱的眷念的群星，还向我放射出明亮的光。根据整篇文章的阅读，阐释“红房子”的两层意思：第一层是实质的，红色房子和舒适的现实生活；第二层是象征，实现理想以及愿望，是象征手法。文章第八段画线句子应该怎样理解：矛盾消失的地方，是指人生不停追求的渴望和对安宁生活向往之间的这种矛盾得到解决的境界，矛盾消失了，那可爱的眷念的群星还向我放射出明亮的光，是指到达一个理想境界、实现一个愿望之后，人又会产生新的愿望、永远不会满足。在语言表达方面有什么特色：首先用了比较丰富的修辞，比如第一自然段的比喻、第四段的反复、第六段的排比，这都是高考必考的修辞，比喻、反复、排比增加了文章的表现力；从表达方式来说，通常说四种表达方式——叙述、议论、抒情和说明，本文用了叙述中的描写、议论和抒情，灵活多变、相辅相成；人称使用方面角度转换自由，第一段和第六段用了第二人称“你”，与红房子面对面交流、便于抒发作者的感情，第一、第二、第三人称都有，这是本文在语言表达方面的特色。**观念性阅读**：第一篇黑塞创作大约在一战前后，强权主义已经开始甚嚣尘上，所以文中会有为数众多的年轻人似乎觉得舍弃愉快的生活而埋头读书是既可笑又不值得的，这是一种事实性关联；王佐良主动外国文学及翻译，因此上图书馆的经历也主要围绕着英美文化等杂志和书籍展开，文章中也会有莎士比亚《哈姆雷特》的台词引用，无处不显示着外国文化的学术底蕴，这与当时的作者背景、经历是一致的；第二是观点性的关联：黑塞对于人性人格拥有非常深刻的思考和探索，他坚持提倡通过读书来提高修养、达到心灵和个性的自我完善；而王佐良在武昌文华中学、西南联大（清华大学）、牛津大学读研留学，养成了良好的读书习惯，拥有了深厚的学术功底，最终在外国文学翻译上有如此卓著的建树。**学生任务：健康的阅读观**。通过两位作家的两篇文章、两位作家的经历出发，你认为应该具备怎样的健康的阅读观呢？第一个问题是为什么要读书：要获得鲜活的知识、意识和理解，由此获得满足和幸福，还要启示我们思考、并获得意义、增强自我意识，就是自我阅读、个性和人格，追求真正的修养；第二个问题是读什么书：读能引起共鸣的书、真正的杰作，而不是报纸或者粗浅的流行文字；第三个问题是如何读书：专注态度、花力气下功夫、认识自己、不盲从不教条、培养有教养的人格。最后说一说随笔这种问题的魅力：随笔在结构上行文缜密而不失活泼，结构自由而不失严谨；形式上可以不受体裁的限制，灵活多变、不拘一格，可以观景抒情、也可以读书看报谈感想，一事一议、也可以同类事物综合议论，篇幅长短由内容而定；内容上获得文化知识、发表学术观点、评论世态人情，启人心智、引人深思、富有理趣，是随笔的突出特色。", "vtech": [["比较阅读怎么答", "先找相同点：两篇都在时间顺序记叙，都写了自己不同时期读到的书籍和感受收获；再找不同点：《读书：目的和前提》描写感受收获比较详细具体，《上图书馆》还写了各个图书馆的建筑华美等特点；最后落到关联性：事实性关联（黑塞一战前后、王佐良英美文化背景）与观点关联性（黑塞通过读书提高修养、达到心灵和人格自我完善；王佐良为外国文学翻译做出贡献）。"], ["“红房子”两层意思怎么答", "第一层是实质的：红色房子和舒适的现实生活；第二层是象征：实现理想以及愿望，是象征手法；第八段画线句“矛盾消失的地方……可爱的眷念的群星还向我放射出明亮的光”指人生不停追求的渴望和对安宁生活向往之间的矛盾得到解决的境界，愿望实现后人又会产生新的愿望、永远不会满足。"], ["语言特色三方面怎么答", "修辞：第一自然段的比喻、第四段的反复、第六段的排比，都是高考必考的修辞，增加了文章表现力；表达方式：叙述、议论、抒情和说明四种，本文用了叙述中的描写、议论和抒情，灵活多变、相辅相成；人称使用：第一段和第六段用了第二人称“你”，与红房子面对面交流、便于抒发作者感情，第一、第二、第三人称转换自由。"], ["随笔的特点怎么答", "结构上行文缜密而不失活泼，结构自由而不失严谨；形式上可以不受体裁限制、灵活多变、不拘一格，可以观景抒情、也可以读书看报谈感想，一事一议、也可以同类事物综合议论，篇幅长短由内容而定；内容上获得文化知识、发表学术观点、评论世态人情，启人心智、引人深思、富有理趣。"]], "vgaokao": []}}, "chn_c025": {"name": "故都的秋", "sec": 1, "secTitle": "第14课", "page": null, "desc": "郁达夫写北平的秋：清、静、悲凉，五幅图里全是情。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《故都的秋》中作者为北平之秋下的总评是哪三个字？", "answer": "清、静、悲凉（故都的秋的特点）"}, "pre": [], "next": ["chn_c026", "chn_c027"], "content": {"advance": {"a": "有其时代背景：1934 年的北平已是没落的故都，山河飘摇，文人心中普遍有一种盛世不再的苍凉；郁达夫本人的漂泊身世又加重了这种感受。悲凉既是秋的自然本色，也是故都命运与诗人心境的合写——所以它不同于一般的悲秋，而是故都之悲。", "kind": "self", "q": "本文的「悲凉」仅仅是秋天本身的悲凉吗？结合时代与个人背景谈谈。"}, "apply": [{"ans": 1, "opts": ["只有一幅全景图", "五幅图：小院清晨（静观）、槐树落蕊（听落）、秋蝉残声（闻声）、都市闲人品秋雨（闲话）、胜日佳果枣子（品味），由静到动、由己及人", "先写南国后写北国", "全写皇家园林"], "q": "文中北平秋景共写了几组画面，其安排是（ ）", "why": "五幅图须默记：这是本篇最常考的细节清单；顺序是庭院—街巷—郊野、由近及远。"}, {"ans": 1, "opts": ["闲笔，无作用", "以南国之秋的浓艳热闹反衬北国之秋的清静悲凉，并由此带出作者对故都之秋的偏爱", "说明南方不好", "凑篇幅"], "q": "文末把北国之秋与南国之秋作比，作用是（ ）", "why": "对比收束：用南衬北，爱憎分明，是散文的常用结尾法。"}], "basics": [{"ans": 1, "opts": ["热烈、浓艳、繁盛", "清、静、悲凉", "温暖、明丽、活泼", "苍劲、雄浑、壮丽"], "q": "作者概括故都之秋的特点是（ ）", "why": "开篇即点：「北国的秋，却特别地来得清，来得静，来得悲凉。」此三字是全文总纲。"}, {"ans": 1, "opts": ["欧阳修", "郁达夫", "朱自清", "史铁生"], "q": "《故都的秋》的作者是（ ）", "why": "郁达夫是现代著名小说家、散文家，代表作小说《沉沦》；《荷塘月色》是朱自清，两人不要混。"}], "case": {"a": "情感是依恋与赞叹中带着悲凉：清静的庭院、扫帚的丝纹、牵牛花的蓝朵，都是衰败中见生命力的细节。手法上以声衬静（以鸽声、扫帚声写静）、以小见大（一方小院见故都全秋），情景交融。", "q": "从「早晨的院子」一段中摘出两个细节，说明作者对故都怀着怎样的情感，并点出所用手法。", "title": "案例：五幅图读一幅"}, "intro": "**郁达夫**遥想北平之秋的散文。==全篇就围绕三个字：清、静、悲凉。==考点在**五幅秋景图**的清单与以情驭景的写法——景物都是被情感挑过、染过的。", "learn": [{"h": "总纲与五幅图", "p": "首句立总纲：「北国的秋，却特别地来得清，来得静，来得悲凉。」主体是五幅图：一、平房小院的清晨（牵牛花、槐树、鸽子与扫帚声）；二、槐树落蕊（无声地铺一地）；三、秋蝉的残声（衰弱的蝉声）；四、都市闲人对秋雨的闲话；五、向阳的尖顶枣子树（秋的果实）。五幅图由庭院到街巷到郊野，空间逐层放大。"}, {"h": "以情驭景的写法", "p": "散文的景不是摄像机拍的，是心情筛过的：同样的秋色，作者只取冷色与静景，连枣子的红也带着凉意。**情景交融**的答题路径：先指情感词（清、静、悲凉），再举两处景物细节作证，最后说二者的对应关系。漏掉任何一环，这类题都不完整。"}, {"h": "南国作衬与背景", "p": "文末拿南国之秋（看不饱、尝不透、赏不完，色彩浓、回味永）作对比，反衬北国秋的清淡与深味。背景须知道：本文作于 1934 年，作者客居青岛，遥想北平——「故都」二字本身已含兴亡之叹。情感的底色，既有故都的衰败，也有文人在乱世中的漂泊感。"}], "pitfalls": ["五幅图记不全或顺序记乱：院子、落蕊、秋蝉、秋雨、秋枣。", "把「悲凉」的原因只答成秋天景色萧条，漏掉故都衰败与时代背景。", "作者记混：郁达夫《故都的秋》，朱自清《荷塘月色》，同在第七单元最易混。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 22, "t": "故都的秋·荷塘月色", "dur": "26:52", "from": "名师课堂", "vtop": ["本课只讲《故都的秋》，《荷塘月色》不在本视频内，在合集P23（cid 818559469），后续补。", "文章结构：开头以感叹句抒发对秋的总体感觉、又荡开一笔拿江南之秋与北方之秋比较；三到十一段细腻描绘故都清秋景色；最后三段议论抒情收尾，再次将北方之秋与南方之秋比较，表达对故都之秋的深切怀念。", "五幅秋景图都取自北平普通老百姓的日常生活场景：破屋晨光、落蕊、秋蝉、秋雨、秋果；景物多半是冷色调的，写出清、静、悲凉——既是客观景物特点的描写和总结，又是作者内心的感受。"], "vsum": "本课只讲《故都的秋》一篇。《荷塘月色》不在本视频内，在合集 P23（cid 818559469），后续补。开场：今天学习必修上册第 24 课《故都的秋》。**作者简介**：郁达夫，中央人民政府追认为革命烈士。**写作背景与题目**：“故都”两个字指明描写的地点，不说北平而说故都，含有深切的眷念之意；“故都”与“古都”结合在一起，古都二字意味着北平不再是垂拱天下的政治中心；读出作者心中对这座历史名城的真爱赞叹以及深情的眷恋和向往。**文章结构十分精巧**：文章开头和结尾都以北国之秋和江南之秋做对比，中间细腻描绘故都的清秋景色，最后以议论和抒情收尾。文章开头就以一句感叹句抒发作者对于秋的总体感觉，也为全文奠定了基调；然而作者并没有沿着这个感觉往下陷，而是荡开一笔，将江南的秋拿来与北方的秋做比较，出现了北国之秋的浓烈、酣畅。那么到哪里去寻觅故都最有代表性的秋景呢？文章的三到十一段就是对故都的秋的细致描写，这些描写也是最能体现作家审美情趣的地方：他不写故都的皇家宫殿园林，也不写远近郊区众多优美的自然风光，顶多就是一笔带过——在南方每年到了秋天，总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，那些景致虽然也代表了故都的特色，但似乎离日常生活很遥远；他关注的更多是北平普通老百姓的日常生活场景。作者笔下的故都清秋主要集中在以下几种景致：住在人家一间破屋里，早晨起来看到碧绿的天色，听到鸽子的飞声，静静地对着喇叭花，疏疏落落的尖细且长的秋草；槐树的落蕊，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉，地上扫过之后留下的印记、灰土上留下的一条条扫帚的丝纹，看起来既觉得细腻、又觉得清闲，人意之下并且还觉得有点落寞；秋蝉，衰弱的残声，简直像是家家户户都养在家里的家虫；秋雨，稀里哗啦，一层秋雨一层凉，穿着很厚的青布单衣或夹袄的都市闲人，缓慢悠闲的声调；生长在屋角、墙头、茅房边上、枣树门口的枣子树，枣子、柿子、葡萄。从以上的事物可以看出，作者所描绘的都是故都普通人家日常的生活场景，是老百姓的日常生活环境，既不稀奇、也不富贵，但带着一股老北京所特有的悠闲、自如，又有一点落寞的感觉。这些景物的选区多半是冷色调的：房子是破屋，牵牛花以蓝色或白色者为佳，紫黑色次之，淡红色最下；不写长在树上的生气勃勃的槐花，而是已经落到地上快要干枯的花蕊，以及人们很少注意到的扫帚的痕迹。这些描写给人的感觉是不是特别的来得清、来得静、来得悲凉？这里的清、静、悲凉既是对客观景物特点的描写和总结，又是作者内心的感受；可以说，从寻常景象、甚至破败景象中看出、体验出美，正是郁达夫所独有的审美体验；这些细腻而独特的感受，显得淡而略显忧郁的情调，只有郁达夫这样一位传统且对孤独有真挚眷恋的读书人才能体验得到，也才能表现得这样细腻而深知。**文章最后三段是议论和抒情**：文章指出，无论是传统的文人学士，还是外国的诗人，都有很多关于秋的歌颂与悲叹，写秋的名篇特别多，因此得出结论——有感觉的动物、有情趣的人类，对于秋总是一样的能特别引起深沉、幽远、严厉、萧索的感触来的，而最能代表秋的深味的，就是这北国的秋天了；本章最后再次将北方的秋与南方的秋作比较，进一步表达了作者对故都之秋的深切怀念。在写景状物方面，本文极其精彩，而且包含作者的深情，情景完美交融，值得仔细体会、揣摩：如早晨起来，泡一碗浓茶，向院子一坐，你也能看得到很高很高的碧绿的天色，听得到青天下驯鸽的飞声，从槐树叶底朝东细数着一丝一丝漏下来的日光，或在破壁腰中静对着像喇叭似的牵牛花的蓝朵，自然而然地也能感觉到十分的秋意——这里写了视觉形象、听觉形象，景物写得非常细致，如一丝一丝漏下来的日光、像喇叭似的牵牛花的蓝朵，也写了观景赏景的心态动作如静对，给人以悠闲、惬意的感觉；又如北国的槐树，也是一种能使人联想起秋来的点缀，像花而又不是花的那一种落蕊，早晨起来会铺得满地，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉——这里写了视觉形象、触觉形象，花铺满地写视觉形象，脚踏花地是触觉感受，写触觉仿佛能拨动读者最微妙的感觉，给读者以逼真的感受；这里寂静无人，可以独自徘徊，静静享受与自然交融的情趣。**语言上也特别见功力**：文中有许多整齐的语句，排比句也很多，具有工整雅致之美，抒情味很浓厚，朗读起来又具有音韵之美，显示出作者很强的语言驾驭能力；“却特别的来得清、来得静、来得悲凉”三个短语精妙地概括了全文的意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾，语势舒缓，为文章整体抒情定下基础；“总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”这些描写性的名词短语，一个短语就是一幅画面，展现出生动的美景，成为故都的秋的美妙意境的重要组成部分，引人遐想，作者神往之情溢于言表。文章最后一段的语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语进去，运用“稀饭”“摸摸”“黄瓜”“大蟹”等词语，这些话语本来是缺乏诗意的，用在这充满古典的高雅趣味的文章中，是要冒不和谐的风险的，但是郁达夫却在这里构成了和谐的统一，这是因为他的情感亮点就是把大雅和大俗融为一体。**审美情趣方面**：秋天，无论在什么地方的秋天，总是好的，可是啊，北国的秋却特别的来得清、来得静、来得悲凉；郁达夫欣赏的正是这样一种萧瑟悲凉之美，因此文中所展示的是冷色调的牵牛花、已经落在地上的槐花的落蕊、疏疏落落的秋草等带有着衰败意味的景物，这些正体现了传统文人的审美情趣与审美追求。“不逢北国之秋已将近十余年了，在南方每年到了秋天总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”——审美是一种情感和感觉，文学的审美，一般化的情感和感觉是很难感染读者的，关键在于要有特点；当时的北平是一座大城市，是政治、经济、文化、教育的中心，一般知识分子久违了这个大城市，怀念什么呢？是那里的行人熙来攘往的街道吗？是那里的繁华商场吗？是那里的大学校园吗？是那里的名胜古迹吗？如果怀念这些东西，不是很能表现郁达夫知识分子的情趣吗？但是，如果他怀念的就是这些五光十色、热热闹闹的场景，就没有他的文化修养和与众不同的个性了；陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，没有大城市的商业繁华，也没有生活的喧嚣闹腾，相反，他所选中的芦花非常朴素，从形状到色彩几乎没有什么花的特点；是不是北平就没有比芦花更为鲜艳的花呢？当然有，西山的红叶、公园中的菊花就是鲜艳夺目的，但是都被郁达夫的记忆筛选掉了；他所选中的公园不是游人如织的圣地，而是比较幽静的陶然亭，就是在这比较安静的公园中，他所钟情的恰恰又平淡得只剩下柳条的影子；西山的虫唱，有的是野趣，与其说是大都市的，不如说是乡村的；潭柘寺的钟声，给人的联想是古老、宁静而幽远；在大城市的喧嚣中，没有宁静的心情是感受不到的；郁达夫所营造的孤独之美，在于超越了大城市的喧嚣。课末讨论：前四幅秋景图体现了清、静、悲凉的特点，容易理解，而最后一幅图画代表着丰收、代表着喜悦，是否与全文基调相悖？并不相悖：作者在这段中说道，像橄榄又像鸽蛋似的这枣子颗，在小椭圆形的细叶中间显出淡绿微黄的颜色的时候，正是秋的全盛时期；但之后紧接着说，等枣树叶落、枣子红完，西北风就要起来了，北方就是沙尘灰土的世界，在反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅能看到秋的衰败、更能看到秋的丰收，体现了作者细致、全面的感知力和审美力。", "vtech": [["五幅秋景图怎么背", "按顺序记：破屋晨光（碧绿的天色、鸽子飞声、喇叭花、秋草）、落蕊（槐树落蕊、脚踏上去声音也没有、气味也没有、只能感出一点点极微细极柔软的触觉）、秋蝉（衰弱的残声、家家户户都养在家里的家虫）、秋雨（一层秋雨一层凉、都市闲人缓慢悠闲的声调）、秋果（枣子、柿子、葡萄）；考写景就按这五幅图的顺序答。"], ["“清、静、悲凉”怎么答", "“来得清、来得静、来得悲凉”三个短语精妙概括全文意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾；答题要说清既是客观景物特点、又是作者内心感受，从寻常甚至破败景象中看出美、体验出美，正是郁达夫独有的审美体验。"], ["秋果图与基调相悖吗", "不相悖：枣子红时是秋的全盛时期，但之后紧接着说等枣树叶落、枣子红完、西北风就要起来了，北方就是沙尘灰土的世界，反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅看到秋的衰败、更能看到秋的丰收，体现细致全面的感知力和审美力。"], ["语言特色大雅大俗怎么答", "文章最后一段语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语（稀饭、摸摸、黄瓜、大蟹等），这些话语本来缺乏诗意，用在充满古典高雅趣味的文章中是要冒不和谐风险的，但郁达夫却构成和谐统一，因为他的情感亮点就是把大雅和大俗融为一体。"]], "vgaokao": []}}, "chn_c026": {"name": "荷塘月色", "sec": 1, "secTitle": "第14课", "page": null, "desc": "朱自清的写景抒情散文：通感与叠词的范本篇。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《荷塘月色》中通感的例句是哪一句？", "answer": "微风过处，送来缕缕清香，仿佛远处高楼上渺茫的歌声似的（嗅觉通听觉）。"}, "pre": ["chn_c025"], "next": [], "content": {"advance": {"a": "「颇不宁静」是全篇的情感原点：作者借夜游排遣内心的烦闷，月下荷塘的宁静让烦闷暂得平复，最后回到家中、情感复归平静。写景即是写心境的曲线：不宁静—暂得宁静—复归现实。答结构题时把这条线画出来，写景的顺序就自明。", "kind": "self", "q": "有人说《荷塘月色》的结构是「心情的变化史」。结合开头「这几天心里颇不宁静」谈谈你的理解。"}, "apply": [{"ans": 1, "opts": ["只是写香气浓郁", "嗅觉转听觉的通感，把花香的若有若无写得可感可听，是全文最著名的修辞例句", "夸张", "借代"], "q": "「微风过处，送来缕缕清香，仿佛远处高楼上渺茫的歌声似的」用了（ ）", "why": "通感定义：不同感官互通。此句嗅觉通听觉，与钱锺书论通感常并举。"}, {"ans": 1, "opts": ["随意排列", "按移步换景的游踪顺序：小煤屑路—月下荷塘—荷塘上的月色—荷塘四周，再收回家", "按时间先后整夜记录", "从大到小的顺序"], "q": "本文写景的顺序是（ ）", "why": "游记式结构：脚步到哪，笔写到哪；答写景顺序题先找作者的移动路线。"}], "basics": [{"ans": 0, "opts": ["朱自清", "郁达夫", "鲁迅", "冰心"], "q": "《荷塘月色》的作者是（ ）", "why": "朱自清的代表散文，写于 1927 年，地点是清华园的荷塘。"}, {"ans": 1, "opts": ["写荷叶密的样子", "叠词，写荷叶挨挨挤挤、层层叠叠的茂盛", "地名", "比喻"], "q": "「田田的叶子」中「田田」的意思是（ ）", "why": "田田形容荷叶相连、密布的样子，出自汉乐府《江南》「莲叶何田田」。"}], "case": {"a": "上半截写月下荷塘：叶子、花、清香、流水，重在荷塘本身的形态与生气。下半截写荷塘月色：月光如流水倾泻、薄雾浮动、光影参差，重在光影的朦胧。同一对象，分写「本体」与「月色中的本体」，层次便出来了。", "q": "月下荷塘与荷塘月色两段写的对象有什么分工？各用一句话概括。", "title": "案例：两段分工表"}, "intro": "**朱自清**的写景抒情散文范本。==两样东西必拿下：**通感**的定义与例句、**叠词**的密度。==还有一条暗线：开头一句「这几天心里颇不宁静」，是整篇文章的情感钥匙。", "learn": [{"h": "结构：一段夜游的心路", "p": "全文按游踪推进：心里不宁静而出门—沿小煤屑路到荷塘—先写月下荷塘（荷叶、荷花、清香、流水）—再写荷塘上的月色（月光、青雾、光与影）—环望四周（杨柳、山色、灯光）—想起采莲旧事—悄然回家。==结构题的标准答案：以情感变化为经、空间移动为纬。=="}, {"h": "语言：叠词与比喻的密集区", "p": "叠词随手可拾：蓊蓊郁郁、曲曲折折、田田、亭亭、脉脉、重重、缕缕、渺茫（近叠）。作用是增强节奏感与形象感，让景物有了可触摸的质地。比喻如叶子「像亭亭的舞女的裙」、月光「像笼着轻纱的梦」。答语言赏析题，先在这两类里找证据，基本不会空手。"}, {"h": "通感：本篇的名片修辞", "p": "「微风过处，送来缕缕清香，仿佛远处高楼上渺茫的歌声似的」：花香本属嗅觉，作者却用听觉去写——这就是**通感**（移觉），把一种感官的感觉移到另一种感官上。它的好处：花香的缥缈感用歌声的渺茫来比，两边都变得更可感。默记定义，高考语言运用题最爱拿这句设题。"}], "pitfalls": ["通感与比喻分不清：通感的前提是跨感官（嗅→听），单纯说像什么不是通感。", "把情感基调答成纯粹的愉悦：底色是烦闷中求片刻宁静，喜悦是淡淡的、暂时的。", "「田田」误作地名或人名，它是形容荷叶相连的样子。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 22, "t": "故都的秋·荷塘月色", "dur": "26:52", "from": "名师课堂", "vtop": ["本课只讲《故都的秋》，《荷塘月色》不在本视频内，在合集P23（cid 818559469），后续补。", "文章结构：开头以感叹句抒发对秋的总体感觉、又荡开一笔拿江南之秋与北方之秋比较；三到十一段细腻描绘故都清秋景色；最后三段议论抒情收尾，再次将北方之秋与南方之秋比较，表达对故都之秋的深切怀念。", "五幅秋景图都取自北平普通老百姓的日常生活场景：破屋晨光、落蕊、秋蝉、秋雨、秋果；景物多半是冷色调的，写出清、静、悲凉——既是客观景物特点的描写和总结，又是作者内心的感受。"], "vsum": "本课只讲《故都的秋》一篇。《荷塘月色》不在本视频内，在合集 P23（cid 818559469），后续补。开场：今天学习必修上册第 24 课《故都的秋》。**作者简介**：郁达夫，中央人民政府追认为革命烈士。**写作背景与题目**：“故都”两个字指明描写的地点，不说北平而说故都，含有深切的眷念之意；“故都”与“古都”结合在一起，古都二字意味着北平不再是垂拱天下的政治中心；读出作者心中对这座历史名城的真爱赞叹以及深情的眷恋和向往。**文章结构十分精巧**：文章开头和结尾都以北国之秋和江南之秋做对比，中间细腻描绘故都的清秋景色，最后以议论和抒情收尾。文章开头就以一句感叹句抒发作者对于秋的总体感觉，也为全文奠定了基调；然而作者并没有沿着这个感觉往下陷，而是荡开一笔，将江南的秋拿来与北方的秋做比较，出现了北国之秋的浓烈、酣畅。那么到哪里去寻觅故都最有代表性的秋景呢？文章的三到十一段就是对故都的秋的细致描写，这些描写也是最能体现作家审美情趣的地方：他不写故都的皇家宫殿园林，也不写远近郊区众多优美的自然风光，顶多就是一笔带过——在南方每年到了秋天，总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，那些景致虽然也代表了故都的特色，但似乎离日常生活很遥远；他关注的更多是北平普通老百姓的日常生活场景。作者笔下的故都清秋主要集中在以下几种景致：住在人家一间破屋里，早晨起来看到碧绿的天色，听到鸽子的飞声，静静地对着喇叭花，疏疏落落的尖细且长的秋草；槐树的落蕊，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉，地上扫过之后留下的印记、灰土上留下的一条条扫帚的丝纹，看起来既觉得细腻、又觉得清闲，人意之下并且还觉得有点落寞；秋蝉，衰弱的残声，简直像是家家户户都养在家里的家虫；秋雨，稀里哗啦，一层秋雨一层凉，穿着很厚的青布单衣或夹袄的都市闲人，缓慢悠闲的声调；生长在屋角、墙头、茅房边上、枣树门口的枣子树，枣子、柿子、葡萄。从以上的事物可以看出，作者所描绘的都是故都普通人家日常的生活场景，是老百姓的日常生活环境，既不稀奇、也不富贵，但带着一股老北京所特有的悠闲、自如，又有一点落寞的感觉。这些景物的选区多半是冷色调的：房子是破屋，牵牛花以蓝色或白色者为佳，紫黑色次之，淡红色最下；不写长在树上的生气勃勃的槐花，而是已经落到地上快要干枯的花蕊，以及人们很少注意到的扫帚的痕迹。这些描写给人的感觉是不是特别的来得清、来得静、来得悲凉？这里的清、静、悲凉既是对客观景物特点的描写和总结，又是作者内心的感受；可以说，从寻常景象、甚至破败景象中看出、体验出美，正是郁达夫所独有的审美体验；这些细腻而独特的感受，显得淡而略显忧郁的情调，只有郁达夫这样一位传统且对孤独有真挚眷恋的读书人才能体验得到，也才能表现得这样细腻而深知。**文章最后三段是议论和抒情**：文章指出，无论是传统的文人学士，还是外国的诗人，都有很多关于秋的歌颂与悲叹，写秋的名篇特别多，因此得出结论——有感觉的动物、有情趣的人类，对于秋总是一样的能特别引起深沉、幽远、严厉、萧索的感触来的，而最能代表秋的深味的，就是这北国的秋天了；本章最后再次将北方的秋与南方的秋作比较，进一步表达了作者对故都之秋的深切怀念。在写景状物方面，本文极其精彩，而且包含作者的深情，情景完美交融，值得仔细体会、揣摩：如早晨起来，泡一碗浓茶，向院子一坐，你也能看得到很高很高的碧绿的天色，听得到青天下驯鸽的飞声，从槐树叶底朝东细数着一丝一丝漏下来的日光，或在破壁腰中静对着像喇叭似的牵牛花的蓝朵，自然而然地也能感觉到十分的秋意——这里写了视觉形象、听觉形象，景物写得非常细致，如一丝一丝漏下来的日光、像喇叭似的牵牛花的蓝朵，也写了观景赏景的心态动作如静对，给人以悠闲、惬意的感觉；又如北国的槐树，也是一种能使人联想起秋来的点缀，像花而又不是花的那一种落蕊，早晨起来会铺得满地，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉——这里写了视觉形象、触觉形象，花铺满地写视觉形象，脚踏花地是触觉感受，写触觉仿佛能拨动读者最微妙的感觉，给读者以逼真的感受；这里寂静无人，可以独自徘徊，静静享受与自然交融的情趣。**语言上也特别见功力**：文中有许多整齐的语句，排比句也很多，具有工整雅致之美，抒情味很浓厚，朗读起来又具有音韵之美，显示出作者很强的语言驾驭能力；“却特别的来得清、来得静、来得悲凉”三个短语精妙地概括了全文的意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾，语势舒缓，为文章整体抒情定下基础；“总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”这些描写性的名词短语，一个短语就是一幅画面，展现出生动的美景，成为故都的秋的美妙意境的重要组成部分，引人遐想，作者神往之情溢于言表。文章最后一段的语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语进去，运用“稀饭”“摸摸”“黄瓜”“大蟹”等词语，这些话语本来是缺乏诗意的，用在这充满古典的高雅趣味的文章中，是要冒不和谐的风险的，但是郁达夫却在这里构成了和谐的统一，这是因为他的情感亮点就是把大雅和大俗融为一体。**审美情趣方面**：秋天，无论在什么地方的秋天，总是好的，可是啊，北国的秋却特别的来得清、来得静、来得悲凉；郁达夫欣赏的正是这样一种萧瑟悲凉之美，因此文中所展示的是冷色调的牵牛花、已经落在地上的槐花的落蕊、疏疏落落的秋草等带有着衰败意味的景物，这些正体现了传统文人的审美情趣与审美追求。“不逢北国之秋已将近十余年了，在南方每年到了秋天总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”——审美是一种情感和感觉，文学的审美，一般化的情感和感觉是很难感染读者的，关键在于要有特点；当时的北平是一座大城市，是政治、经济、文化、教育的中心，一般知识分子久违了这个大城市，怀念什么呢？是那里的行人熙来攘往的街道吗？是那里的繁华商场吗？是那里的大学校园吗？是那里的名胜古迹吗？如果怀念这些东西，不是很能表现郁达夫知识分子的情趣吗？但是，如果他怀念的就是这些五光十色、热热闹闹的场景，就没有他的文化修养和与众不同的个性了；陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，没有大城市的商业繁华，也没有生活的喧嚣闹腾，相反，他所选中的芦花非常朴素，从形状到色彩几乎没有什么花的特点；是不是北平就没有比芦花更为鲜艳的花呢？当然有，西山的红叶、公园中的菊花就是鲜艳夺目的，但是都被郁达夫的记忆筛选掉了；他所选中的公园不是游人如织的圣地，而是比较幽静的陶然亭，就是在这比较安静的公园中，他所钟情的恰恰又平淡得只剩下柳条的影子；西山的虫唱，有的是野趣，与其说是大都市的，不如说是乡村的；潭柘寺的钟声，给人的联想是古老、宁静而幽远；在大城市的喧嚣中，没有宁静的心情是感受不到的；郁达夫所营造的孤独之美，在于超越了大城市的喧嚣。课末讨论：前四幅秋景图体现了清、静、悲凉的特点，容易理解，而最后一幅图画代表着丰收、代表着喜悦，是否与全文基调相悖？并不相悖：作者在这段中说道，像橄榄又像鸽蛋似的这枣子颗，在小椭圆形的细叶中间显出淡绿微黄的颜色的时候，正是秋的全盛时期；但之后紧接着说，等枣树叶落、枣子红完，西北风就要起来了，北方就是沙尘灰土的世界，在反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅能看到秋的衰败、更能看到秋的丰收，体现了作者细致、全面的感知力和审美力。", "vtech": [["五幅秋景图怎么背", "按顺序记：破屋晨光（碧绿的天色、鸽子飞声、喇叭花、秋草）、落蕊（槐树落蕊、脚踏上去声音也没有、气味也没有、只能感出一点点极微细极柔软的触觉）、秋蝉（衰弱的残声、家家户户都养在家里的家虫）、秋雨（一层秋雨一层凉、都市闲人缓慢悠闲的声调）、秋果（枣子、柿子、葡萄）；考写景就按这五幅图的顺序答。"], ["“清、静、悲凉”怎么答", "“来得清、来得静、来得悲凉”三个短语精妙概括全文意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾；答题要说清既是客观景物特点、又是作者内心感受，从寻常甚至破败景象中看出美、体验出美，正是郁达夫独有的审美体验。"], ["秋果图与基调相悖吗", "不相悖：枣子红时是秋的全盛时期，但之后紧接着说等枣树叶落、枣子红完、西北风就要起来了，北方就是沙尘灰土的世界，反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅看到秋的衰败、更能看到秋的丰收，体现细致全面的感知力和审美力。"], ["语言特色大雅大俗怎么答", "文章最后一段语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语（稀饭、摸摸、黄瓜、大蟹等），这些话语本来缺乏诗意，用在充满古典高雅趣味的文章中是要冒不和谐风险的，但郁达夫却构成和谐统一，因为他的情感亮点就是把大雅和大俗融为一体。"]], "vgaokao": []}}, "chn_c027": {"name": "我与地坛（节选）", "sec": 2, "secTitle": "第15课", "page": null, "desc": "史铁生的生死之问：地坛与母亲两条线拧成一股。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": null, "pre": ["chn_c025"], "next": [], "content": {"advance": {"a": "节选主要写两个部分：地坛的四季景象与作者对生死的思考、母亲对儿子的牵挂与爱。地坛部分先把「生」的力量写足（荒芜而不衰败），思考才有依托；母亲部分再把思考落到亲情上（母亲的去世使作者懂得母爱与忏悔）。两条线一纵一横：一边是空间（地坛）里的顿悟，一边是时间里迟到的理解。", "kind": "self", "q": "节选两部分（一写地坛与生死之思，二写母亲）之间是什么关系？"}, "apply": [{"ans": 1, "opts": ["她直接训导儿子要坚强", "她不干涉、不催问，只是悄悄地来、四处寻找、远远望着又悄悄离开——以沉默的守望表达疼惜与理解", "她让儿子不要去地坛", "她与儿子长篇谈心"], "q": "母亲形象最动人的写法是（ ）", "why": "母亲形象的考点：避开直白抒情，用行为细节写深爱，这正是史铁生散文的力量。"}, {"ans": 1, "opts": ["地坛离家近很方便", "在作者最绝望时收留了他，荒芜却不衰败的景象让他领悟到死是必然、活要找到活的理由", "地坛风景优美是名胜", "母亲喜欢去那里"], "q": "「地坛」对作者的意义在于（ ）", "why": "地坛是精神支点：一个残疾青年在这里完成生死观的重建。"}], "basics": [{"ans": 1, "opts": ["余华", "史铁生", "莫言", "路遥"], "q": "《我与地坛》的作者是（ ）", "why": "史铁生 21 岁时双腿瘫痪，本篇是他关于生死与母爱的代表散文。"}, {"ans": 1, "opts": ["人迟早要做一番事业", "死是一件不必急于求成的事，是一个必然会降临的节日", "死亡离我们很远", "生死完全由命运安排无法抗拒"], "q": "文中名句「死是一个必然会降临的节日」的意思是（ ）", "why": "这句的要义：把死看作必然，从而不再畏惧、不必急于求成，腾出心思好好地活。"}], "case": {"a": "脚印说明：儿子摇着轮椅在园中留下的痕迹，母亲沿着它就能找到儿子——动作细节写出了母亲无言的寻找与守望。作用：母亲的爱不在语言而在脚步；每一次「悄悄」都是一层克制，克制越深，情感越重。对比儿子当年的不懂与后来的懂得，这组细节也是全文忏悔情感的支点。", "q": "文中母亲「在园中找我时留下的脚印」反复出现。这一细节写了什么、有什么作用？", "title": "案例：一组脚印"}, "intro": "**史铁生**的成名散文。==两条线拧成一股：地坛（生死之思）与母亲（迟到的理解）。==情感的推进是：绝望—顿悟—忏悔，每级都要在文中找到落点。", "learn": [{"h": "第一部分：地坛与生死之思", "p": "作者 21 岁双腿瘫痪后，地坛成了他逃避世界、思考命运的地方。地坛荒芜却不衰败：古柏、野草、落日、雨燕都在无声地活着。==作者由此完成关键一悟：死是不必急于求成的必然之事，活下去的问题才需要想清楚——「如何活」取代了「要不要活」。==答题时把荒芜而不衰败的景物与这一悟一一对应。"}, {"h": "第二部分：母亲这条线", "p": "母亲知道儿子心里苦，却从不强行劝慰：她只是送他出门、目送、又悄悄到地坛寻找，远远望见了又悄悄离开。儿子当时不懂，多年后母亲去世，他才读懂这份沉默的守望——全文最深的情感是**迟到的理解与忏悔**。「母亲再也不能理解儿子的痛苦」与「儿子终于理解了母亲」构成残酷的对照。"}, {"h": "文体与语言", "p": "本篇属哲理抒情散文：写景、叙事、议论三者不分段地交融。语言质朴而有力，长句多、思辨密。高考散文题的常规问法：关键句含义（死是一个必然会降临的节日）、母亲形象、景物描写的作用——三题的答案都已在上面两个小节里。"}], "pitfalls": ["把主题只概括成赞美母爱：生死之思与母爱是双线，缺一不可。", "「死是一个必然会降临的节日」误读成轻生思想：恰恰相反，它是对死的坦然换来的对生的珍惜。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 24, "t": "我与地坛（节选）", "dur": "27:14", "from": "名师课堂", "vtop": ["全文在作者与假想对象地坛的对话中展开，有两条线：一是作家与地坛非同寻常的亲情关系，二是作家对地坛中几个人物的观察、描写和思索；地坛是作者的精神家园，母亲是他的生命家园。", "地坛三处景物描写（第三、第五、第七自然段）用情景交融、情理结合的方法写：古园历尽沧桑的建筑和景物有着看尽繁华后的平静，连野草荒藤也都茂盛得自在坦荡，抚慰作者内心的痛苦、缓解迷茫的心绪，暗示生命的启示。", "母亲的形象靠动作写：目送、寻找、“知道”；母亲疼爱而且能够理解儿子，沉静、理性、意志坚韧；车辙与脚印合二为一——园中处处都有过我的车辙，有过我的车辙的地方也都有过母亲的脚印，我的成长处处离不开母亲的启发。"], "vsum": "本课讲《我与地坛》（节选），地坛与母亲两部分都讲全了，没有缺口。开场：今天就让我们带着这样的问题，沿着一道道轮椅的痕迹，走进地坛，去探索文学世界里的人生答案。学习目标之一是体会作者对生命的思考及对母亲的怀念之情，激发对生命和生活的热爱。**走近作者**：史铁生的写作与他的生命完全同构在了一起，在自己的写作之夜，他用残缺的身体说出了最为健全而丰满的思想；他体验到的是生命的苦难，表达出的却是存在的明朗和欢乐。**《我与地坛》是史铁生散文的代表作，写于 1989 年**：从他的腿残疾到写此文的漫长岁月中的大部分时间，他都是在地坛中度过的；地坛却于风吹雨打中，史铁生觉得他和地坛冥冥之中有一种缘分——他在找不到工作、找不到路、忽然间几乎什么都找不到了的情形下走进地坛。**全文在作者与假想对象地坛的对话中展开**：其一是作家与地坛的那种非同寻常的亲情关系，其二是作家对地坛中的几个人物的观察、描写和思索。作者从自己为何踏进这座古园写起，写了地坛四百多年的等待，与我冥冥之中的到来；作者在第二自然段说，地坛离我家很近，或者说我家离地坛很近，二者的变化实质上表现了作者的心路历程。21 岁时突至的残疾，使他人生道路急转直下；地坛对于作者来说是一种慰藉。**三处景物描写**：作者运用情景交融、情理结合的方法，对地坛进行了三处景物描写。第一处景物描写在第三自然段；第二处在第五自然段，写园子里小生命的顽强生命力；第三处在第七自然段。古园里历尽沧桑的建筑和景物，有着看尽繁华后的平静，连野草荒藤也都茂盛得自在坦荡，这样的景致抚慰了作者内心的痛苦，缓解了他迷茫的心绪，也使他感到生命的启示似乎在暗示给作者；在作者眼里，能够无拘无束、自由自在地飞，是多么让人艳羡的事；坐在轮椅上的史铁生，面对地坛充满生机的一切，虽有如同树上的蝉蜕一般的寂寞感；古老又充满生机，展现出自然景物的永恒，体现出作者对生命的思考，也显示了作者高超的语言表现力。**与自己对话**：作者在静默的氛围中学会了自己与自己的对话，深陷轮椅、空间缩小，但时间延长，于是有了更多的时间去想，想的内容是关于死的事，想过我为什么要出生；这样想了好几年，最后事情终于弄明白了；在这里，作者不是在讴歌死亡，而是在表达玄想或放下死亡后的轻松释然；地坛启发作者把握人生的意义；作者由最初的逃避者成长为思想者，由最初的几度选择赴死到最后选择向死而生。**另一个重要人物：作者的母亲**。如果说地坛是作者的精神家园，那母亲则是他的生命家园。这一部分是以“总是独自跑到地坛去的我，给母亲出了一个难题”开场的：这个难题就是残疾又沉默寡言的儿子总是独自地去地坛，这时本已痛苦的母亲更增加了悲伤和恐惧，却又不知道为儿子做些什么；然后围绕这个难题，作者回顾了当时自己的心路历程，以及由此而给母亲带来的烦恼痛苦。这一部分对母亲的塑造只有极少的语言描写，更多的是动作描写：在儿子陷入切肤之痛、无路可走的困境时，再多安慰的话都显得苍白，至爱无声，母亲只是默默地去做、去关注儿子的一举一动，用她宽容和隐忍的爱去温暖孩子的世界；她能做的就是送与寻找——当作者出门去地坛时，母亲想送，又不敢送，于是只能目送；当作者有事折回时，母亲仍站在原地，而且还是送我走时的姿势，她的眼睛依然望着我拐出小院去的那处墙角，并且她对我的回来竟然一时没有反应；“站”“送”“望”和“没有反应”这几个静态重词组构出一幅立体的画面，母亲的担忧、牵挂、心疼与无奈，诸多复杂的情感通过这些词语准确地表达了出来。母亲另外一个让人印象深刻的动作就是寻找：母亲的寻找是艰难的，因为她视力不好，端着眼镜像在寻找海上的一条船，与眼镜搭配的动词不是戴着、不是扶着，而是端着，可以想象母亲寻找时的极度艰难和胶着；母亲的寻找是无声的，她只是步履茫然又急迫地寻找，没有呼唤，没有对旁人的问询，对儿子爱得引人有度；她明白，痛苦只能自己咀嚼消化，别人代替不了的；于是她来找我、又不想让我发觉，只要见我还好好的在这园子里，她就悄悄地转身回去；儿子总是独自跑到地坛去，母亲能做的只是目送、只是寻找，没有抱怨、没有祈求，因为她不是那种光会疼爱儿子而不懂理解儿子的母亲。为了表现这一点，文中几处用了一个平平常常、但特别打动人心的动词，那就是“知道”：她知道我心里的苦闷，知道不该阻止我出去走走，知道我要是老待在家里结果会更糟；但她又担心我一个人在那荒僻的园子里整天都想些什么；我那时脾气坏到极点，经常是发了疯一样地离开家，从那园子里回来又中了魔似的什么话都不说；母亲知道有些事不该问，便犹犹豫豫地想问、而终于不敢问，因为她自己心里也没有答案；她料想，我不会愿意她跟我一同去，所以她从未这样要求过；她知道得给我一点独处的时间，得有这样一段过程。这里的“知道”是一个特别有分量的动词：很多母亲疼爱孩子，但不知道自己的孩子；一位母亲对孩子的“知道”就是懂，就是理解，就是设身处地地站在孩子的角度去考虑问题，而唯独不考虑自己。母亲因为知道，所以包容，包容我那暴怒无常的坏脾气；因为知道，所以无言，无言地看着我摇车拐出小院。当然，母亲也有不知道，她不知道想要儿子重新站起来的过程得要多久，和这过程的尽头究竟是什么？这不知道的背后是母亲的痛苦、焦虑与忍耐。而与母亲的知道和不知道相对的，是我的不知道：我不知道她已经找了多久、还要找多久，我不知道为什么我决意不喊她，我甚至不知道被她惦念。正是在知道与不知道的强烈对比中，才会有母亲过世后作者无尽的愧疚、痛悔和遗憾。由此可以总结出母亲的形象特点：作者的母亲是一位疼爱、而且能够理解儿子，沉静、理性、意志坚韧的母亲。等到作者知道的时候，母亲已经不在了，他感到难以自抑的悲痛，于是，他又摇着轮椅来到这古园，他反复地想，为什么母亲不能再等两年？母亲盼望他找到的路是什么？他抱怨上天的不公，他反复想着同一件事，母亲已经不在了；正是在这反反复复的追思和推想中，母亲的苦难与伟大在他心中鲜明起来，而母亲那艰难的命运、坚忍的意志和毫不张扬的爱，在他心中愈加深刻，从而使他对母爱、对人生有了更深的体会，对生活、对未来有了更深的思考。文中还写到作者与作家朋友谈到学写作的最初动机时，进行了两者之间的对比，通过对比，突出了母爱的伟大，也突出了自己母亲苦难的命运，加深了作者痛楚、自责、思念的情感。第五段，那些苍凉的文字来自心灵深处，没有经历过痛苦的人，是写不出这样凝重苍凉的文字的，也永远感受不到在那苍凉的底色下汩汩滚动的热流。这部分将地坛、母亲与我的人生历程交织在一起：多年来，我头一次意识到，这园中不单是处处都有过我的车辙，有过我的车辙的地方，也都有过母亲的脚印。我们怎么来理解脚印、车辙、我、地坛以及母亲的关系？处处的脚印，也就是处处的关爱与牵挂，暗示出我的成长处处都离不开母亲的启发，就如同是地坛给予作者的生命启示一样；可以说正是母亲的这种活法，解答了他人应该怎样生活、怎样面对命运、怎样面对苦难的问题，使他在逆境中坚强起来。至此地坛的形象与母亲的形象合二为一：厚重、博大、宽容、隐忍；地坛是作者的精神家园，她等待我，以荒芜但并不衰败的形象启发我；人可以残废，但不能颓废，要学会在绝望中看到希望，勇敢地选择活下去；母亲是作者心灵的港湾，她执着的目送和寻找，给我无限的心灵慰藉；想使母亲骄傲的信念支撑作者在写作的道路上昂然前行。**收束**：《我与地坛》与前几篇写景抒情散文不同，它更多的是记叙作者的人生经历和心路历程，带有自传、自省、自述的意味；文章语言凝练生动、充满诗意，写景但不是对景物的客观描摹，更多的是将景物与自己的感受结合起来，写景中夹杂着叙事、抒情和议论，表达自己对人生、世界的看法，因此文章充满了哲学意味。史铁生在乐观的根据一文中写道，生命分为两种，一种叫做有限的身在，一种叫做无限的心魂；他在《我与地坛》中呈现出来的生命状态，已经超越了有限的身在，达到了无限的心魂；我们从史铁生身上看到的不是身体的残疾，而是精神的圆满，不是对苦难的哀痛，而是对命运的感恩，不是生命的禁锢，而是灵魂的自由；地狱和天堂都在人间，地狱和天堂是人对生命以及对他人的不同态度罢了；其实，既不是地坛的帮助，也不是上天的功劳，而是史铁生自己改变了态度，对生命、对他人，都有一份感恩之心、热爱之情，于是，他从黑暗走向了光明。", "vtech": [["母亲形象怎么答", "只用极少的语言描写、更多用动作描写：送与寻找——母亲想送又不敢送，只能目送；作者有事折回时母亲仍站在原地、还是送我走时的姿势，眼睛依然望着我拐出小院去的那处墙角，并且对我的回来一时没有反应；寻找——母亲视力不好，端着眼镜在寻找海上的一条船，步履茫然又急迫，没有呼唤、没有问询；“知道”——他知道我心里的苦闷，知道不该阻止我出去走走，知道我要是老待在家里结果会更糟；母亲因为知道所以包容、因为知道所以无言。"], ["“知道”与“不知道”怎么答", "母亲的知道是懂、是理解、是设身处地站在孩子角度考虑问题，而唯独不考虑自己；母亲也有不知道——她不知道想要儿子重新站起来的过程得要多久、这过程的尽头究竟是什么，不知道的背后是母亲的痛苦、焦虑与忍耐；与母亲的知道和不知道相对的，是我的不知道——我不知道她已经找了多久、还要找多久，我不知道为什么我决意不喊她，我甚至不知道被她惦念；正是在知道与不知道的强烈对比中，才会有母亲过世后作者无尽的愧疚、痛悔和遗憾。"], ["地坛三处景物描写怎么答", "第一处在第三自然段，第二处在第五自然段（园子里小生命的顽强生命力），第三处在第七自然段；作者运用情景交融、情理结合的方法，古老又充满生机，展现自然景物的永恒，体现作者对生命的思考，也显示高超的语言表现力；写景不是对景物的客观描摹，更多是将景物与自己的感受结合起来，写景中夹杂叙事、抒情和议论，表达自己对人生、世界的看法，文章充满哲学意味。"], ["向死而生怎么理解", "作者在静默的氛围中学会了自己与自己的对话，深陷轮椅、空间缩小，但时间延长，于是有了更多的时间去想，想的内容是关于死的事，想过我为什么要出生；这样想了好几年，最后事情终于弄明白了：由最初的几度选择赴死到最后选择向死而生；地坛启发作者把握人生的意义，人可以残废、但不能颓废，要学会在绝望中看到希望，勇敢地选择活下去。"]], "vgaokao": []}}, "chn_c028": {"name": "赤壁赋", "sec": 3, "secTitle": "第16课", "page": null, "desc": "苏轼的文赋巅峰：主客问答、变与不变之辩，默写高频篇。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《赤壁赋》中写江水与明月哲理的句子（自其不变者而言）。", "answer": "自其不变者而观之，则物与我皆无尽也（注意「与我」顺序）"}, "pre": ["chn_c021"], "next": ["chn_c029"], "content": {"advance": {"a": "主客问答是赋体的传统形式：客的悲叹与主的开解，其实都是作者一人内心的两面——贬谪中的苦闷与自我超脱的努力。形式上的对话，是思想上的自我辩论；最终苏子的达观胜出，意味着作者完成了自我说服。这是理解本文思想的关键一招。", "kind": "self", "q": "为什么说赋中的「客」与「苏子」其实是同一个人的两面？这对理解主旨有何帮助？"}, "apply": [{"q": "本篇说理主要采用的形式是（ ）", "opts": ["以时间为序的游记笔法", "赋体的主客问答，借对话推进议论", "纯粹铺陈景物、情景交融", "照录史书记载"], "ans": 1, "why": "《赤壁赋》是文赋：以主客问答组织议论，客问苏答，道理在对答中层层推进。"}, {"q": "苏子「物与我皆无尽也」表达的是（ ）", "opts": ["消极避世、与世无争", "由水与月的变与不变悟出物我无尽，从而化解人生短暂之悲的达观", "看破红尘、决意出家", "对周瑜的嫉妒与不平"], "ans": 1, "why": "这是全篇哲理的落点：换一个角度看「变」，悲便解了。达观不是逃避，而是换视角的智慧。"}], "basics": [{"ans": 1, "opts": ["壬戌之秋，七月既望（农历十六）", "三月三日上巳节", "重阳节", "除夕"], "q": "《赤壁赋》开篇交代的时间是（ ）", "why": "「壬戌之秋，七月既望」：既望是农历十六日（望为十五），壬戌是元丰五年（1082 年）。"}, {"ans": 1, "opts": ["悲伤欲绝", "由乐转悲，再由悲转喜（达观）", "始终欢乐", "始终悲伤"], "q": "全文情感线索是（ ）", "why": "泛舟之乐—箫声之悲—问答之悟—达观之喜，四步是本文最稳的结构答案。"}], "case": {"a": "苏子的逻辑分两步：先说「变」的一面——江水东流从未停歇（逝者如斯，而未尝往也：流走的是水，看江的人却始终见江在）；再说「不变」的一面——月有盈虚而终究无消长。结论：从变看，天地一瞬都不能停留；从不变看，万物与我都没有穷尽，何必羡慕长江无穷。哀伤被视角转换化解。", "q": "苏子用水与月开解客人，分几步完成？各用一句概括。", "title": "案例：水月之辩的逻辑"}, "intro": "**苏轼**黄州时期的文赋巅峰。==先把情感曲线背下来：乐（泛舟）—悲（箫声）—悟（水月之辩）—喜（达观而眠）。==文言考点密集：通假（一词「属」通「嘱」在练习中常见）、词类活用、默写高频句五组。", "learn": [{"h": "叙事段：乐与悲的转换", "p": "开篇「壬戌之秋，七月既望」，泛舟赤壁之下，清风、水光、诵诗、饮酒，是极乐；客人一曲洞箫「如怨如慕，如泣如诉」，情感急转直下。客的悲叹词是全篇的题眼材料：「哀吾生之须臾，羡长江之无穷」——人生太短，江水太长。==结构意识：乐是铺垫，悲是问题，悟是答案。=="}, {"h": "议论段：变与不变", "p": "苏子的开解是全篇的哲学核心：「逝者如斯，而未尝往也；盈虚者如彼，而卒莫消长也。」再推出结论：「自其变者而观之，则天地曾不能以一瞬；自其不变者而观之，则物与我皆无尽也，而又何羡乎！」最后落到生活态度：「惟江上之清风，与山间之明月…取之无禁，用之不竭」——无主之物可以共适，心安即是归处。"}, {"h": "默写与字词", "p": "高频默写：①清风徐来，水波不兴 ②纵一苇之所如，凌万顷之茫然 ③寄蜉蝣于天地，渺沧海之一粟 ④哀吾生之须臾，羡长江之无穷 ⑤物与我皆无尽也。易错字：「愀然」的「愀」读 qiǎo 不要写成「秋然」；「匏樽」的「匏」读 páo；「桂棹」的「棹」读 zhào 是船桨；「扁舟」的「扁」读 piān 是小舟义；「山川相缪」的「缪」读 liáo 通「缭」，缠绕。词类活用例：「西望夏口，东望武昌」西、东为名词作状语；「侣鱼虾而友麋鹿」侣、友为意动用法。"}], "pitfalls": ["默写五大易错字：愀（qiǎo）、匏（páo）、棹（zhào）、扁（piān）、缪（liáo）；「须臾」的「臾」不要误写成「欤」。", "把主客问答误读成两个真实人物的争论，丢掉自我开解的内在性。", "情感曲线答成乐—悲收尾：必须答到由悲转悟、达观而喜这一层。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 25, "t": "赤壁赋·登泰山记", "dur": "24:41", "from": "名师课堂", "vtop": ["本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集P26），后续补。", "全文五段：第一段作者与友人夜游赤壁的情景；第二段作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段客对人生短促无常的感慨；第四段苏子针对客之人生短促无常的感慨表达自己的见解；第五段客听闻作者观点后转悲为喜、开怀畅饮。", "写景、抒情、说理完美融合、运用自如：写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然。"], "vsum": "本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集 P26），后续补。开场：黄州的赤壁因苏东坡闻名；今天我们学习的赤壁赋中的赤壁，是指湖北黄州的赤壁，俗称赤壁，但是它是否真的就是三国古战场的赤壁，却说法不一；为什么在苏轼前后赤壁赋和赤壁怀古的描绘中如此气势辉煌、波澜壮阔呢？**学习目标**：一、分析和把握文章观察景物的角度和表现景物的艺术手法。**全文五段大意**：第一段，作者与友人夜游赤壁的情景；第二段，作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段，客对人生短促无常的感慨；第四段，苏子针对客之人生短促无常的感慨表达自己的见解；第五段，客听闻作者观点后转悲为喜、开怀畅饮。**第一段**：壬戌之秋，七月既望，苏先生同客人乘船在赤壁之下游玩，清风缓缓吹来，江面平静没有波澜，举起酒杯劝客人饮酒，诵明月之诗、歌窈窕之章；一会儿月亮从东山上升起，在斗牛之间徘徊，白茫茫的水汽笼罩着江面，波光连着天空，任凭小船飘去、越过那茫茫的江面，多么辽阔啊，像是凌空驾风而行、不知将停留在何处，多么飘逸啊，好像脱离尘世、升入仙境；他们泛舟于赤壁之下，沐清风白露、赏月色天光，兴致生发，信口吟出《诗经·陈风·月出》中“月出皎兮，佼人僚兮，舒窈纠兮，劳心悄兮”的名句，月亮皎洁升起、如同俏丽佳人。接下来写作者所见的月出之景：月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光，似对游人极为依恋；在皎洁的月光照耀下，白茫茫的雾气笼罩江面，天光水色连成一片，正所谓秋水共长天一色，开阔的景象使人心胸舒畅、无拘无束；临万顷之茫然，乘着一叶扁舟，飘飘乎如遗世独立、羽化而登仙。**第二段**：作者饮酒乐甚，扣舷而歌，客人中有吹洞箫的，依照歌曲的声调和节拍吹箫伴奏，箫声呜呜，像是怨恨又像是私慕，像是哭泣又像是倾诉；同时上文诵明月之诗、歌窈窕之章的内容也得到了具体化；由此可见，怀美人而不见，苏子本有些失落和哀伤，又有客吹洞箫为作者的歌声伴奏，箫声凄婉哀怨，如怨如慕、如泣如诉，余音袅袅、不绝如缕；使深谷中的蛟龙听了起舞，使独处孤舟的嫠妇听了落泪，也使苏子的感情陡转。**第三段**：苏子悄然，正襟危坐而问客，何为其然也？客人说：向西望是夏口，向东望是武昌，山水环绕一片苍翠，这不是曹孟德被周瑜围困的地方吗？方其破荆州、下江陵，顺流而东也，舳舻千里、旌旗蔽空，酾酒临江、横槊赋诗，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属；寄蜉蝣于天地，渺沧海之一粟；哀吾生之须臾，羡长江之无穷；挟飞仙以遨游，抱明月而长终；知不可乎骤得，托遗响于悲风。此段由赴赤壁的自然景物转而赴赤壁的历史古迹，主人以“何为其然也”设问，客人以赤壁的历史古迹作答，文理转折自然。接下来讲客人感慨的深层原因：连曹操这类英雄人物也只是显赫一时，因而反观自己生命短暂，羡慕江水涌流不竭，渴望与神仙遨游、与明月同存。**第四段**：苏子说，客亦知夫水与月乎？为江上之清风与山间之明月，再说天地之间万物各有主人；只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也，而吾与子之所共适；苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色。**第五段**：客人高兴地笑了，洗净杯子重新斟酒，菜肴和果品已经吃完了，杯盘凌乱地放着，大家互相枕着垫着睡在船中，不知不觉已经天亮了；这一段写大家在舟中饮酒尽欢、恣意畅饮，竟不知天色将明，此处再写游赏之乐，与开头照应，再次将读者引入忘怀得失、超然物外的境界。**艺术特色**：这篇作品写景、抒情、说理完美融合、运用自如，写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然；仁者乐山、智者乐水，是中国文化的传统；赤壁赋以江山风月为骨，富有层次地写了赤壁所见、历史之江月、哲理感悟之江月，体现出一种纯净出尘的美感；何满子在《赤壁赋赏析》中写道，凡是尽善的诗文，首先当然要求写景叙事生动有味，更需要写景叙事中注入作家浓郁的主观感情，才能神情飞动、气势昂然，倘若景与情交融之外，更能从物我之间及主客观的契合之间生发出哲理的意蕴，那便是上乘之作了；主客对答是赋体中传统的表现手法，也是全赋的重心所在，主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论；“渺渺兮予怀，望美人兮天一方”，作者因美人比君，可见忠君之殷切，情怀幽远。**收束**：作者借助对清风明月之美的描绘，展现思路图；作者在“哀吾生之须臾，羡长江之无穷”中流露了人生无常的消极情绪，但他并不沉沦于个人愁怀，而是主动丢开思想包袱，以江水明月作笔，从庄子的哲学中寻找人生之路；作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙，声调铿锵和谐，增强了文章的音乐美。", "vtech": [["主客问答怎么答", "主客对答是赋体中传统的表现手法，也是全赋的重心所在；主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论。"], ["“月出”与“望美人兮天一方”怎么答", "月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光似对游人极为依恋；作者因美人比君，可见忠君之殷切，情怀幽远。"], ["苏子怎么反驳“人生短促”", "苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色；天地之间万物各有主人，只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也。"], ["语言与音乐美怎么答", "作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；声调铿锵和谐，增强了文章的音乐美；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙。"]], "vgaokao": []}}, "chn_c029": {"name": "登泰山记", "sec": 3, "secTitle": "第16课", "page": null, "desc": "姚鼐的冬日登山小记：日出一段是全文华彩，易错字最冷僻。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "《登泰山记》中「稍见云中白若____数十立者」，空格填什么？", "answer": "樗蒱（chū pú，古代博戏用具，此处形容云中露出的山峰形状）"}, "pre": ["chn_c028"], "next": [], "content": {"advance": {"a": "日出最详，因为它是登山的目的与全篇的情感高点；观日出一段又用云海、五采、红光层层造势，写出自然之壮美，寄托作者对新生与光明的向往。其余路途、石刻只作交代，详略由「是否有助于主题」决定——这正是游记取舍的法则。", "kind": "self", "q": "全文为何独详日出一段？其余部分为何从略？"}, "apply": [{"ans": 1, "opts": ["看到雪觉得冷", "以雪光映照天色之明、城郭之清，渲染清晨登临的奇景；「烛」是名词用作动词，照亮之意", "蜡烛点满了山", "比喻太阳是蜡烛"], "q": "「苍山负雪，明烛天南」中「烛」的用法与景象是（ ）", "why": "词类活用题：烛，名词作动词；意思先行，活用是壳。"}, {"ans": 1, "opts": ["按作者情感由低到高排列", "沿登山路线移步换景：泰安—中谷—中岭—西谷—山巅—日观亭，空间推进即文章顺序", "按时间打乱叙述", "先果后因的倒叙"], "q": "本文的游踪顺序是（ ）", "why": "游记的骨架就是路线；答结构题先把途经点按序报出来。"}], "basics": [{"ans": 1, "opts": ["泰山", "华山", "衡山", "嵩山"], "q": "文中「日观峰」是（ ）的主峰观日处。", "why": "日观峰是泰山观日出的著名地点，姚鼐登的是泰山，写作时值乾隆三十九年冬。"}, {"ans": 0, "opts": ["姚鼐", "苏轼", "袁宏道", "徐霞客"], "q": "《登泰山记》的作者是清代桐城派的（ ）", "why": "姚鼐是桐城派代表作家，文风简洁峻洁，与本篇的短峭笔法正相合。"}], "case": {"a": "先用云海垫场：足下皆云、云中露出如樗蒱般的山峰；再写天象变化：云端一线异色、须臾成五采；最后日出本体：正赤如丹、下有红光动摇承托。顺序是先环境、再光影、后太阳本体，由远及近、由衬到主。", "q": "日出一段，作者写了哪三层景象？按出现顺序概括。", "title": "案例：日出三层"}, "intro": "**姚鼐**的游记小品，清代桐城派的代表作。==结构是登山路线图，华彩是日出一段。==这篇的冷僻字最要命：徂徕、樗蒱、罅、偻——默写填空专挑它们设题。", "learn": [{"h": "游踪：路线的骨架", "p": "全文按行踪推进：乾隆三十九年十二月自京师出发—历齐河、长清—至泰安—由南麓入，经中谷、越中岭、循西谷—至山巅—宿日观亭等日出—写泰山石刻与山色而收束。==游记阅读法：先把路线点连成线，再看作者在每个点上停留的笔墨多少——停留最久处即全文重心。=="}, {"h": "日出：全文的华彩", "p": "写法层进：先云海（亭东自足下皆云漫），云中白峰如樗蒱；再异色（极天云一线异色，须臾成五采）；终见日出（日上，正赤如丹，下有红光动摇承之）。用字极俭而画面极足，是桐城派「简洁峻洁」的样本。「回视日观以西峰，或得日，或否，绛皓驳色，而皆若偻」以群峰的俯就之态反衬日出之胜。"}, {"h": "字词冷点清单", "p": "读音释义：「汶水」wèn；「徂徕」cú lái，山名；「樗蒱」chū pú，古代博戏之具，此处喻云中白峰之形；「石罅」xià，石头的裂缝；「偻」lǚ，脊背弯曲，此处写山峰低俯之态；「磴」dèng，石级。词类活用：「明烛天南」的烛为名词作动词（照亮）；「苍山负雪」的负是背负。古今异义：「或得日，或否」的「或」是有的（峰）的意思。"}], "pitfalls": ["默写冷点字：樗蒱、徂徕、罅、偻四词错一字整句零分。", "把「或得日」的「或」按现代义解成或者，它是「有的」的意思。", "作者归属记错：姚鼐，清代桐城派，不要记到袁宏道（明代公安派）名下。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 25, "t": "赤壁赋·登泰山记", "dur": "24:41", "from": "名师课堂", "vtop": ["本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集P26），后续补。", "全文五段：第一段作者与友人夜游赤壁的情景；第二段作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段客对人生短促无常的感慨；第四段苏子针对客之人生短促无常的感慨表达自己的见解；第五段客听闻作者观点后转悲为喜、开怀畅饮。", "写景、抒情、说理完美融合、运用自如：写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然。"], "vsum": "本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集 P26），后续补。开场：黄州的赤壁因苏东坡闻名；今天我们学习的赤壁赋中的赤壁，是指湖北黄州的赤壁，俗称赤壁，但是它是否真的就是三国古战场的赤壁，却说法不一；为什么在苏轼前后赤壁赋和赤壁怀古的描绘中如此气势辉煌、波澜壮阔呢？**学习目标**：一、分析和把握文章观察景物的角度和表现景物的艺术手法。**全文五段大意**：第一段，作者与友人夜游赤壁的情景；第二段，作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段，客对人生短促无常的感慨；第四段，苏子针对客之人生短促无常的感慨表达自己的见解；第五段，客听闻作者观点后转悲为喜、开怀畅饮。**第一段**：壬戌之秋，七月既望，苏先生同客人乘船在赤壁之下游玩，清风缓缓吹来，江面平静没有波澜，举起酒杯劝客人饮酒，诵明月之诗、歌窈窕之章；一会儿月亮从东山上升起，在斗牛之间徘徊，白茫茫的水汽笼罩着江面，波光连着天空，任凭小船飘去、越过那茫茫的江面，多么辽阔啊，像是凌空驾风而行、不知将停留在何处，多么飘逸啊，好像脱离尘世、升入仙境；他们泛舟于赤壁之下，沐清风白露、赏月色天光，兴致生发，信口吟出《诗经·陈风·月出》中“月出皎兮，佼人僚兮，舒窈纠兮，劳心悄兮”的名句，月亮皎洁升起、如同俏丽佳人。接下来写作者所见的月出之景：月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光，似对游人极为依恋；在皎洁的月光照耀下，白茫茫的雾气笼罩江面，天光水色连成一片，正所谓秋水共长天一色，开阔的景象使人心胸舒畅、无拘无束；临万顷之茫然，乘着一叶扁舟，飘飘乎如遗世独立、羽化而登仙。**第二段**：作者饮酒乐甚，扣舷而歌，客人中有吹洞箫的，依照歌曲的声调和节拍吹箫伴奏，箫声呜呜，像是怨恨又像是私慕，像是哭泣又像是倾诉；同时上文诵明月之诗、歌窈窕之章的内容也得到了具体化；由此可见，怀美人而不见，苏子本有些失落和哀伤，又有客吹洞箫为作者的歌声伴奏，箫声凄婉哀怨，如怨如慕、如泣如诉，余音袅袅、不绝如缕；使深谷中的蛟龙听了起舞，使独处孤舟的嫠妇听了落泪，也使苏子的感情陡转。**第三段**：苏子悄然，正襟危坐而问客，何为其然也？客人说：向西望是夏口，向东望是武昌，山水环绕一片苍翠，这不是曹孟德被周瑜围困的地方吗？方其破荆州、下江陵，顺流而东也，舳舻千里、旌旗蔽空，酾酒临江、横槊赋诗，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属；寄蜉蝣于天地，渺沧海之一粟；哀吾生之须臾，羡长江之无穷；挟飞仙以遨游，抱明月而长终；知不可乎骤得，托遗响于悲风。此段由赴赤壁的自然景物转而赴赤壁的历史古迹，主人以“何为其然也”设问，客人以赤壁的历史古迹作答，文理转折自然。接下来讲客人感慨的深层原因：连曹操这类英雄人物也只是显赫一时，因而反观自己生命短暂，羡慕江水涌流不竭，渴望与神仙遨游、与明月同存。**第四段**：苏子说，客亦知夫水与月乎？为江上之清风与山间之明月，再说天地之间万物各有主人；只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也，而吾与子之所共适；苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色。**第五段**：客人高兴地笑了，洗净杯子重新斟酒，菜肴和果品已经吃完了，杯盘凌乱地放着，大家互相枕着垫着睡在船中，不知不觉已经天亮了；这一段写大家在舟中饮酒尽欢、恣意畅饮，竟不知天色将明，此处再写游赏之乐，与开头照应，再次将读者引入忘怀得失、超然物外的境界。**艺术特色**：这篇作品写景、抒情、说理完美融合、运用自如，写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然；仁者乐山、智者乐水，是中国文化的传统；赤壁赋以江山风月为骨，富有层次地写了赤壁所见、历史之江月、哲理感悟之江月，体现出一种纯净出尘的美感；何满子在《赤壁赋赏析》中写道，凡是尽善的诗文，首先当然要求写景叙事生动有味，更需要写景叙事中注入作家浓郁的主观感情，才能神情飞动、气势昂然，倘若景与情交融之外，更能从物我之间及主客观的契合之间生发出哲理的意蕴，那便是上乘之作了；主客对答是赋体中传统的表现手法，也是全赋的重心所在，主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论；“渺渺兮予怀，望美人兮天一方”，作者因美人比君，可见忠君之殷切，情怀幽远。**收束**：作者借助对清风明月之美的描绘，展现思路图；作者在“哀吾生之须臾，羡长江之无穷”中流露了人生无常的消极情绪，但他并不沉沦于个人愁怀，而是主动丢开思想包袱，以江水明月作笔，从庄子的哲学中寻找人生之路；作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙，声调铿锵和谐，增强了文章的音乐美。", "vtech": [["主客问答怎么答", "主客对答是赋体中传统的表现手法，也是全赋的重心所在；主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论。"], ["“月出”与“望美人兮天一方”怎么答", "月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光似对游人极为依恋；作者因美人比君，可见忠君之殷切，情怀幽远。"], ["苏子怎么反驳“人生短促”", "苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色；天地之间万物各有主人，只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也。"], ["语言与音乐美怎么答", "作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；声调铿锵和谐，增强了文章的音乐美；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙。"]], "vgaokao": []}}, "chn_c030": {"name": "词语积累与词语解释", "sec": 1, "secTitle": "第八单元 词语积累与词语解释", "page": 125, "desc": "语言文字运用的地基：积累、古今词义、辨析与使用三项活动。", "criteria": ["能说清本单元活动的目标与流程", "能制定可执行的记录或调查方案", "能独立完成一次访谈提纲或记录稿", "能写出结构完整的报告或展示稿", "能结合本地实例做汇报并讲清依据"], "diag": null, "pre": [], "next": [], "content": {"advance": {"a": "有联系：古今异义源于词义的历史演变——有的是词义扩大（如河，古专指黄河，今泛指河流），有的是缩小（如妻子，古指妻与子，今指妻），有的是转移与感情色彩变化。理解联系，才能解释为什么同一个词在文言与现代汉语里意思不同。", "kind": "self", "q": "活动二讲「古今词义的联系与区别」。举一例说明词义演变的类型，并指出它与古今异义现象的联系。"}, "apply": [{"ans": 1, "opts": ["意思完全相同", "古义含妻与子女两人，今义只指妻子，属于词义缩小", "今义更大", "与词义无关"], "q": "「妻子」在《桃花源记》中指妻子儿女，与现代汉语只指配偶相比，属于词义的（ ）", "why": "词义范围由大变小即词义缩小；反过来如「河」由专名变泛称是词义扩大。"}, {"ans": 0, "opts": ["指小路、田间小路", "指交通大道", "指街道", "指桥梁"], "q": "成语「阡陌交通」中「交通」与「阡陌」连用时，正确理解是：阡陌指田间小路，则「交通」应释为（ ）", "why": "此句出自《桃花源记》：「阡陌交通，鸡犬相闻」——交通是交错相通，不可按现代的运输义理解，是高频古今异义考点。"}], "basics": [{"ans": 1, "opts": ["一个词只有一个意思", "一个词有多个义项的现象", "词语的读音变化", "偏旁的变化"], "q": "「一词多义」指的是（ ）", "why": "一词多义是汉语词汇的基本现象，辨析时须把义项放回语境里选。"}, {"ans": 1, "opts": ["与语境无关，看字典第一个义项", "结合语境、词性与搭配推断", "只看字形", "凭第一印象猜"], "q": "辨析同音同形词（如「意思」的几种用法）最可靠的方法是（ ）", "why": "语言文字运用题的底层方法：语境定意，离开语境谈词义必然出错。"}], "case": {"a": "走：古义多为跑（如走马观花的走、《石壕吏》三男邺城戍老妪力虽衰请从吏夜归的走指赶路逃跑语境），今义为步行。行：古义多为行走、步行，今义扩大为可以、行列、行业等，又有动词做义。两者古今发生了意义的对调与扩大：古之走≈今之跑，古之行≈今之走。", "q": "「走」与「行」各举一例说明其古今义的变化。", "title": "案例：走与行的对调"}, "intro": "第八单元是全书的语言工具箱，没有课文，只有三项学习活动。==它对应高考的**语言文字运用**板块：词汇积累、古今词义、辨析与使用——全是选择题里的常驻题型。==", "learn": [{"h": "活动一：丰富词语积累", "p": "积累的三个方法：积累要归类——按主题（家国、自然、心境）、按语体（书面、典籍）、按感情色彩分类建卡；积累要用活——把新词放进自己的句子里造句，而不是抄在摘抄本里吃灰；积累要溯源——查清成语的出处与本义，如「差强人意」本是尚能使人满意，不是「不满意」。==语言文字运用题答错，多半不是不会，而是积累的词全躺在笔记本里没有活过。=="}, {"h": "活动二：古今词义的联系与区别", "p": "词义演变四类型必记：**扩大**（河：专指黄河→泛指河流）、**缩小**（妻子：妻与子→妻）、**转移**（涕：眼泪→鼻涕）、**感情色彩变化**（卑鄙：地位低、见识浅→品质恶劣，褒贬转移）。文言文翻译题里古今异义是固定失分点，与第六、七单元的文言课文互为表里：读文言时每遇熟词先停一下——最熟的词最容易翻车。"}, {"h": "活动三：词义辨析与使用", "p": "近义词辨析三把尺：**理性义**（词义核心差别，如「爱护」与「爱戴」对象不同）、**色彩**（褒贬与语体，如「成果」褒义、「结果」中性、「后果」贬义）、**搭配**（习惯组合，如「发扬」作风、「发挥」作用）。做题顺序：先排色彩不对的，再排搭配不合的，最后抠理性义的细微差别。"}], "pitfalls": ["「差强人意」误用成不满意：它表示大体上还能使人满意，是肯定句里的词。", "成语望文生义：如「首当其冲」是首先受冲击，不是首先冲锋；「文不加点」是写文章一气呵成，不是没有标点。", "古今异义凭现代义硬套：如「交通」在古文中是交错相通，「妻子」含儿女。"]}, "video": {"bvid": "BV1JB4y1G7kF", "p": 28, "t": "词语积累与词语解释", "dur": "80:01", "from": "名师课堂", "vtop": ["本课由三讲拼成：丰富词语积累、词语解释（一词多义与成语古今词义）、词语运用（语境与语体色彩），三讲讲全了，没有缺口。", "积累词语的方法：抓住一个中心点，或语音或语义或语法，以点带面展开联想、触类旁通，就会形成一个词语的家族群；这样做不仅有益于词语积累，还更有助于记忆理解。", "一词多义看似纷繁复杂，其实也有规律可循：一个词的各个意义并不是孤立的，其间存在着各种联系，分析意义间的相互联系，往往就抓住了理解多义词的线索。"], "vsum": "本课由三讲拼成（合集 P28、P29、P30），三讲讲全了，没有缺口。**第一讲：丰富词语积累**。开场：今天我们共同来学习普通高中教科书语文必修上册第八单元第一课，丰富词语积累；说话写文章离不开词语，如同盖房子需要砖石一样，词和短语就是语言表达的砖石，我们需要做生活中的有心人，平时多读多记，积累尽可能丰富的词语，形成自己的词语库；词语库充实了才有选择的余地，才能更好地发挥语言的表现力。**学习目标**：一、多角度归类词语，让积累更加有效；二、学会将词语分类并用不同方法积累词语；三、探索词语尤其是成语中蕴含的文化现象，培养对词语的理解感悟与审美能力；四、学会用不同方法积累词语，培养对汉语文化的热爱之情；从小学到中学我们一直都在积累词语，但很多同学积累词语的途径并未建构积累词语的有效方法，我们共同建构积累词语的方法，更为高效地丰富词语积累。汉语中的词语数量是巨大的，因此我们可以从词语的家族或者系统出发：我们可以通过共同的语素借助联想积累词语；词语常通过语义上的各种关系，或者说这些词义构成了特定的语义场，因此我们可以借助词语的语义关系积累词语；汉语词语的种类数量非常大，但词语在整个词汇系统中不是孤立存在的，他们往往通过语音、语义或者语法等方面的某些共同点形成集合体，构成词语的系统和家族；所以我们在积累词语时，抓住一个中心点，或语音或语义或语法，以点带面展开联想、触类旁通，就会形成一个词语的家族群；这样做不仅有益于词语积累，还更有助于我们记忆理解。下面，我们一起走进俗语家族，丰富俗语积累，让语言多姿多彩；下面请同学们查阅工具书；因此我们可以通过积累俗语来丰富我们的词语。随着社会生活各方面的变化，新词语在不断涌现，为汉语增添了鲜活的生命力，积累词语不能不关注新词语；新词语是词汇中的动态系统，词汇同语音、语法比较起来，与社会生活的关系更加直接，社会生活的发展变化都会很快地反映到词汇中，使得一些旧词语逐渐消失，而很多新词语又不断在交际场合和传播媒体中出现；词语的新旧只能相对而言，不同时期都会有那个时期的新词语，某个时期的新词语也不可能永远是新词语；至于如何界定新词语，处在这个过程中的词语，或者说产生不足二十年的词语都可以算是新词语；新词语的产生主要有三个来源；下面请同学们谈谈对以下新词语含义的理解；我们可以梳理出新词语产生的途径；下面请同学们回顾本节课所谈到的新词语，看新词语具有哪些特点和作用：新颖性是新词语表现出来的基本特点，幽默性是新词语的优异特征，新词语具有衍生能产性这一特性，能批量生产新词语，并使其所生产的新词语形成词语族；由“打工族”的“族”构成了追星族、月光族、啃老族等，一个新词语的出现便带动产生了一个词族、词群或一批词语，从而使新词语的产生体现出新词语的能产性；所以新词语一旦形成便受到了无数人追捧，特别是从网络或者从方言中吸收的新词语，像 2014 年的新词语“蛮拼的”和“点赞”，甚至出现在了 2015 年国家主席习近平的新年贺词中；因此，我们每个人要密切注意到语言的发展动态，辩证地看待新词语，准确理解和恰当运用好新词语，从而使我们的言语表述更加准确、生动、形象，更具有时代性和现代感。**第二讲：一词多义与成语古今词义**。古诗文时要注意结合语境仔细甄别、正确理解，例如“绝”：率妻子邑人来此绝境，“绝”是僻远的意思；齐山溢水、天下独绝，“绝”是独一无二的意思；至于下水相邻、严肃阻绝，“绝”是阻断隔绝的意思；会当临绝顶、一览众山小，“绝”是极的意思；大雪三日、湖中人鸟声俱绝，“绝”是断绝的意思；又如“信”：与朋友交而不信乎，“信”是诚信守信；愿陛下亲之信之，“信”是信任相信；海客谈瀛洲、烟涛微茫信难求，“信”是确实、的确；低眉信手续续弹、说尽心中无限事，“信”是任凭随意。一词多义看似纷繁复杂，其实也有规律可循：一个词的各个意义并不是孤立的，其间存在着各种联系，分析意义间的相互联系，往往就抓住了理解多义词的线索；要分析意义间的相互联系，我们首先要明确词的本义和引申义；一个词当它有两个以上意义的时候，其中应该有一个是本义，另外还有一个或一些是引申义，所谓引申义，是从本意引申出来的，即从本意产生出另外一个或几个与之有关联的意义；例如“向”本义是向北的窗户，由向北的窗户这个本意，引申为朝着或对着。首先我们谈一谈词义引申的两种方式：第一种方式是由一个意义向各个不同方面引申，我们称之为辐射式引申，例如“节”字，它的本意是竹节，由这个本意产生出下列引申义：一、用于树木则指木结；二、用于动物则指关节；三、用于时日，则指节气；四、用于音乐，则为节奏；五、用于社会政治，则为法度；六、用于道德方面，则为节操；七、用于动作，则为节制、节省；这种引申方式很灵活，同一个词可以从不同角度联想，因而就有各种不同角度的引申，例如“唱”本意是领唱，由领的意义引申为带头、倡导，由唱的意义引申为歌唱；例如“书”本义是写，引申为装订成册的著作，引申为用于陈述正式见解的文体，引申为书信。第二种方式是由本义引申为甲义、又由甲义引申为乙义，这样一环套一环的引申，称之为链条式引申，例如“要”，它是“腰”的本字，由此引申出下列意义：一、中间；二、半路拦截；三、要挟；四、求得；五、需要；如果画成图就是“要”引申为中间，由中间引申为半路拦截，由半路拦截引申为要挟，由要挟引申为求得，由求得引申为需要；这种引申的特点是，其中一个意义只和它临近的两个意义有直接联系，而与其他意义差得较远，以“要”为例，“需要”是现代汉语中常用的意义，它和“腰”的意义乍看起来是毫无关系的，但只要我们找到它们之间的中间环节，就能清楚地看到其间词义引申发展的脉络；反过来说，有些词或字古今意义之间看不出任何关系，也可能是我们还没有找到中间环节的缘故；这两种引申方式不是截然分开的，例如“要”除了上述引申以外，还可以从别的角度引出别的意义；又如“闻”，本意是听见，由听说引申为接受、由听说引申为传布、由听说引申为有名、著称；词义引申的一般规律，通常是由具体到抽象、由个别到一般、由实词到虚词，例如“道”本意是道路，引申为抽象的途径、方法，又引申为学说、道理。现代汉语中的成语和一词多义还保留着古义；尤其是从古代沿用而来的成语，也要注意成语中古今词义不同的现象；成语中有些词：一、词义的转移，如“骄傲自大”的“骄”本义是马高六尺，后指骄傲；二、词义引申，如“顾名思义”的“顾”本意为回头看，后来引申为看，再引申为探望、拜访、照顾等多义；三、词义的缩小和扩大，如“五谷丰登”的“谷”本意是庄稼和粮食的总称，现在专指稻谷，词义缩小了；四、词义加深，如“怅恨久之”的“恨”本意是遗憾、不满足，现在表示仇恨，古今词义相比程度加深了；我们在学习使用成语的时候要避免因望文生义而以今释古，例如“把邻国当作大水坑、把本国洪水排泄到那里去，比喻把灾祸推给别人”，此处属于望文生义；“在语文老师的严格要求下，我逐渐改正了文不加点的毛病”——“文不加点”是文章一气呵成、无需修改，形容文思敏捷、写作技巧纯熟，“点”是改正修改的意思，此处属于望文生义；“此文打着科学的幌子，实际上宣传的是封建迷信，这样一篇不刊之论，竟然公开刊登在一家省级大报纸上，真是令人反感”——“不刊之论”比喻不能改动或不可磨灭的言论，用来形容文章或言辞的精准得当、正确无误，如果将其理解为“刊登”，就属于望文生义了。反馈与评价：指出下面词语词义变化的情况并解析，如“菜”古义专指蔬菜、现泛指一切菜肴包括肉类；“汤”古义专指热水、开水，现指热水开水、食物煮熟后所得的汤汁、烹调后汁液特别多的副食、汤药；“河”古义专指黄河、现泛指河流。**第三讲：词语运用——语境与语体色彩**。下面我们结合作家作品中对词语的修改和锤炼的范例；在具体的语境中使用词语；然而一旦它与特定的语境相联系，练习和使用词语要有语境意识，在具体的语境中理解和运用语言；一些中性词在上下文语境中也带上了感情色彩，其感情色彩在特定语境中也发生了转换；在特定的语境下，请大家阅读下面的便条。下面我们以《溜索》和《普通人家》两篇附有地域特色的小说为例，探究两篇小说在词语选用上的语体特点，体会其中表现出的语言风格：《溜索》中“出、峡、行”等都是单音节词，具有凝练的文言词特点；“可还些”“不消”运用文言的单音节词来表达，有一种古白化的味道，使这种对白极为减省；“小”活用动词，写出人物沿溜索滑向对岸的动态，颇有画面感，多用短句、少用词藻修饰，也使得描写简洁而富有表现力。《普通人家》中“拴贼寇”“心尖子”“废叶子”“眼珠子”“命根子”“拍花子”等词语，有明显的口语特征，准确传神地表现出劳动人民生动活泼的形象，赋予地方特色和生活气息；“人配衣裳马配鞍”“好狗不挡道”“捅了马蜂窝”“千里搭长篷、没有不散的筵席”等丰富的民间俗语的运用，体现出小说将口语与古典熔于一炉的独特的语言风格，既简洁凝练又生动形象。在小说、戏剧等文学作品中，作家常常利用词语的语体色彩描写人物语言、塑造人物形象，例如鲁迅的《孔乙己》中有如下的段落：孔乙己睁大眼睛说，你怎么这样凭空污人清白？什么清白？我前天亲眼见你偷了何家的书，吊着打；孔乙己便涨红了脸，额上的青筋条条绽出，争辩道，窃书不能算偷，窃书，读书人的事能算偷吗？接连便是难懂的话，什么君子固穷，什么者乎之类，引得众人都哄笑起来，店内外充满了快活的空气；明确：“偷”是口语，是短衣帮们使用的词语，“窃”是书面语，是读书人才使用的词语，何况窃的是书，是读书人的事，是不能与偷相提并论的；在众人看来这是诡辩、狡辩，在孔乙己却是他维护自己尊严所做的迂腐可怜的努力；孔乙己所用的文言词语与其所处环境格格不入，与他自身的境遇也形成冲突，反而成为这一人物的标志，也成为我们解读孔乙己的一把钥匙。范例：《镜花缘》中有一回写孙话旧保咬文、讲迂谈、辅如嚼字，里面有一段故事：旁边走过一个酒保，面上戴着眼镜、手中拿着折扇，斯斯文文走来向着三人打躬陪笑道，三位先生光临，莫非饮酒乎？亦用菜乎？敢请吩咐；林之洋道，你是酒保，你脸上戴着眼镜，你绝不配，你还满嘴通文，这是甚意？刚才俺同那些生童讲话，倒不见他有甚通文，谁知酒保通起文来，真是正经半吊子、半吊子正经；你可晓得俺最猴急，耐不惯你这通文；有酒有菜只管快快拿来；明确：日常对话讲究生动活泼、晓畅明快，这里的酒保却用了一连串的书面语词，酸腐难耐，作者借词讽刺了酒保的假斯文形象。根据刚才老师的讲解，我们知道，口语通俗易懂、书面语形象典雅，那么大家试一试，能不能给以下日常口语中的新词或者流行语找到匹配的古诗文？例如“时间是把杀猪刀”，我们可以找到“最是人间留不住，朱颜辞镜花辞树”；“素颜，清水出芙蓉，天然去雕饰”；那么大家看，以下几句有没有合适的古诗文匹配呢？“颜值爆表，众里嫣然通一顾，人间颜色如尘土”；“说得好有道理，我竟无言以对，此中有真意，欲辨已忘言”；“宝宝心里苦，但宝宝不说，如此寒心，隐忍不言，心好累，形容枯槁，心如死灰”；“世界那么大，我想去看看，天高地阔，欲望无边”。", "vtech": [["词义引申两种方式怎么答", "第一种是由一个意义向各个不同方面引申，称之为辐射式引申，例如“节”本意是竹节，由这个本意产生出木结、关节、节气、节奏、法度、节操、节制等引申义；第二种是由本义引申为甲义、又由甲义引申为乙义，这样一环套一环的引申，称之为链条式引申，例如“要”本义是腰，引申为中间、由中间引申为半路拦截、由半路拦截引申为要挟、由要挟引申为求得、由求得引申为需要；这两种引申方式不是截然分开的。"], ["成语古今词义怎么辨", "成语中有些词古今词义不同，要注意：一、词义的转移，如“骄傲自大”的“骄”本义是马高六尺；二、词义引申，如“顾名思义”的“顾”本意为回头看，后来引申为看、再引申为探望、拜访、照顾等多义；三、词义的缩小和扩大，如“五谷丰登”的“谷”本意是庄稼和粮食的总称，现在专指稻谷，词义缩小了；四、词义加深，如“怅恨久之”的“恨”本意是遗憾、不满足，现在表示仇恨，古今词义相比程度加深了；学习使用成语时要避免望文生义、以今释古。"], ["语境意识怎么答", "练习和使用词语要有语境意识，在具体的语境中理解和运用语言；一些中性词在上下文语境中也带上了感情色彩，其感情色彩在特定语境中也发生了转换；古诗文时要注意结合语境仔细甄别、正确理解，例如“绝”在不同句子里分别是横渡、僻远、独一无二、阻断隔绝、极、断绝的意思。"], ["语体色彩怎么答", "在小说、戏剧等文学作品中，作家常常利用词语的语体色彩描写人物语言、塑造人物形象：《溜索》多用单音节词，具有凝练的文言词特点，又用口语对白；《普通人家》多用“拴贼寇”“心尖子”“命根子”“拍花子”等口语词和“人配衣裳马配鞍”“好狗不挡道”“捅了马蜂窝”等民间俗语，体现出口语与古典熔于一炉的独特语言风格；孔乙己所用的文言词语与其所处环境格格不入，反而成为这一人物的标志，也成为解读孔乙己的一把钥匙。"]], "vgaokao": []}}, "chn_c031": {"name": "静女·涉江采芙蓉", "sec": 1, "secTitle": "古诗词诵读", "page": 139, "desc": "《诗经》的爱情小诗与《古诗十九首》的游子思乡：诵读篇目抓情感与名句。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《涉江采芙蓉》的最后两句。", "answer": "同心而离居，忧伤以终老。"}, "pre": ["chn_c009"], "next": ["chn_c032"], "content": {"advance": {"a": "有其现实基础：古人交通不便、通讯不达，离别即是长久的隔绝，所以思乡怀人成了古典诗歌最核心的母题之一。《涉江采芙蓉》中采花赠远的徒劳，正是这种隔绝感的产物——花可采而人不在，动作越轻，思念越重。", "kind": "self", "q": "《涉江采芙蓉》的思乡与今天的思念有何不同？结合古人的交通条件说说。"}, "apply": [{"ans": 1, "opts": ["只为写景", "采花赠远落空——动作起而情止，以乐景写哀情的反衬", "说明芙蓉好看", "交代季节"], "q": "「采之欲遗谁？所思在远道」两句的作用是（ ）", "why": "起句欢愉、转句落空，是本诗的情感枢纽；以动作的徒劳写思念的深切。"}, {"ans": 1, "opts": ["埋怨姑娘迟到", "半责怪半欢喜，写出男子既焦急又欣喜的复杂心理，正是爱情小诗的生动处", "男子很生气", "写约会地点"], "q": "「爱而不见，搔首踟蹰」写的是（ ）", "why": "情态题：动作（搔首、踟蹰）即心理的外化，读情先读动作。"}], "basics": [{"ans": 1, "opts": ["辞赋选集", "古代诗歌总集，收录东汉末年文人五言诗十九首", "唐代诗集", "词集"], "q": "《古诗十九首》是（ ）", "why": "它是东汉末年文人五言诗的选辑，被誉为五言之冠冕，《涉江采芙蓉》即其一。"}, {"ans": 1, "opts": ["眼泪", "赠送", "遗产", "丢失"], "q": "「采之欲遗谁」中「遗」的意思是（ ）", "why": "遗读 wèi，赠予；这是古今/多音多义的双考点字。"}], "case": {"a": "结构对照：上四句采花设问（乐事起笔），下四句望乡叹老（悲情收束）。转折点在「所思在远道」——人不在眼前，采花的意义瞬间落空，随后还顾、长路、离居、终老层层加重。与《静女》的明快形成节奏对照：一喜一悲，正是诵读单元的编排心意。", "q": "把《涉江采芙蓉》按情感分成两部分，并指出转折句。", "title": "案例：情感两段式"}, "intro": "诵读单元先读两首抒情短诗：《诗经》的**《静女》**写约会，《古诗十九首》的**《涉江采芙蓉》**写思乡。==一喜一悲，正好练两种读法：从动作读心理、从采花读落空。==", "learn": [{"h": "静女：约会小品里的动作戏", "p": "《静女》出自《诗经·邶风》。全诗三章：男子赴约，姑娘却「爱而不见」——躲了起来，男子「搔首踟蹰」，急得抓头徘徊；姑娘现身，赠他彤管（红色管萧）；又赠他牧场归来的荑（初生白茅）。收束一句最见情趣：「匪女之为美，美人之贻」——不是草美，是送草的人美。==读《诗经》小诗，先把人物动作排成戏，再谈情感。=="}, {"h": "涉江采芙蓉：采而不得的思念", "p": "起笔是乐事：涉江采芙蓉，兰泽多芳草；一转折：「采之欲遗谁？所思在远道。」花采到了，人却不在——动作的徒劳就是全诗的情感机关。后四句望乡、长路、离居、终老，语气一路下沉。手法上是以乐景写哀情、**情景反衬**；语言上质朴到近乎口语，却被评为《古诗十九首》中最深情的篇章之一。"}, {"h": "易错字与文化点", "p": "《静女》易错字：「俟我于城隅」的「俟」读 sì 是等待；「搔首踟蹰」的「踟蹰」读 chí chú；「彤管有炜」的「炜」读 wěi 是光彩；「自牧归荑」的「荑」读 yí；「洵美且异」的「洵」读 xún 是确实。《涉江》：「遗」读 wèi 不读 yí；「忧伤以终老」的老指终生，不是年老。"}], "pitfalls": ["「遗」读 wèi（赠送），按 yí 读会把整句意思读反。", "《静女》的「爱而不见」误解为不爱了：爱通「薆」，是隐藏的意思。", "把《古诗十九首》的作者写成某个具体诗人：它是东汉文人群体的佚名作品集。"]}, "video": {"bvid": "BV1mCqkYPEYr", "p": 1, "t": "古诗词诵读四首", "dur": "57:49", "from": "王老师", "vtop": ["本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。", "李煜词分前期后期：前期写宫廷享乐，后期写物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念。", "《涉江采芙蓉》用平浅质朴的文字表现深厚的感情，是古诗十九首的风格；古诗十九首标志着五言诗已经达到了成熟的阶段，刘勰称其为“五言之冠冕”，钟嵘称其“天衣无缝，一字千金”。"], "vsum": "本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。**第一首：李煜《虞美人》**。开场：同学们好，王老师带你学语文；他生于七夕、卒于七夕，他是一位君王，更是一位伟大的词人；大家说，他是谁呢？对，他就是南唐后主李煜；这节课我们就走进被称为亡国君王、绝代词人的李煜，学习他的代表作《虞美人》。**李煜简介**：李煜原名从嘉、字重光，他是五代十国时期南唐的最后一任帝王，在位十五年，史称南唐后主或者说李后主；史书记载，李煜为人仁孝、善属文、擅长写文章，工书画、也擅长书法绘画；凤额龙睛、一目重瞳子，凤额大概就是天庭饱满，龙睛就是眼睛里边有两个瞳孔，其实这是眼睛发生的病变，但是苍颉、虞舜、项羽都是重瞳子，所以古代相术就认为重瞳意味着吉祥与富贵、是帝王的象征，所以可以说李煜天生就有帝王之相；可是李煜本人却没有称帝之心，只想做一个富贵闲人，而且李煜是南唐宗主李璟的第六个儿子，所以正常情况来说也轮不到他做皇帝；可惜的是李弘冀和他的叔叔李景遂争夺王位的继承权，后来李弘冀当上太子之后就毒杀了他的叔叔李景遂，然后南唐宗主李璟因为李弘冀残害自己的亲叔叔，就废了李弘冀的太子职位；所以李煜被迫做了南唐的皇帝，而且十几年之后，南唐就灭亡了。**词风分期**：前期则描写了宫廷享乐，后期则描写了物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念等等。**写作背景**：南唐只能延续纳贡的政策、一再委屈求全，但是这也没有能够阻止宋兵围城的步伐；975 年，南唐在与宋的交战中不敌、最终亡国，李煜肉袒出降，非常屈辱啊；他不甘心南唐的灭亡。**赏词**：下面我们就一起来赏析一下李煜的这首绝笔之作《虞美人》：春花秋月何时了，往事知多少？小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁，恰似一江春水向东流。春花秋月什么时候才能停止呢？我们看这个春花秋月：春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君，要忍受无尽的屈辱；所以一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光。小楼昨夜又东风：小楼昨夜又迎来了东风；这个“又”字表现了作者怎样的情感呢？再看这个故国：故国指的是南唐故都金陵，这个国指的是国都金陵，就是现在的南京；故国不堪回首月明中，遥望南唐的故都呢。雕栏玉砌应犹在，只是朱颜改：这个“砌”我们注意啊，是台阶的意思，雕栏玉砌就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜；就形成了鲜明的对比，物是人非的悲愁之感悠然而生；那么除了对比，还运用了什么艺术手法呢？这是作者的想象，此时此刻李煜的思绪回到了南唐的故宫。问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁，来比喻愁、说愁思，愁思之多、愁思之绵长，写出了愁思的多、深重和绵长，而且用有形的水来比喻抽象的无形的愁，我们说这个愁是无形的呀、是抽象的呀，我们怎么来写呢？没有办法形容；多少愁啊，像一江春水一样的愁；用一个设问就加倍地突出了这个“愁”字；亡国之恨。不变的是春花秋月，永恒的春花秋月。**第二首：《古诗十九首·涉江采芙蓉》**。我们先来了解一下《古诗十九首》：《古诗十九首》是《十九首诗》的统称，由汉代文人创作，并且被南朝的萧统选录编入《文选》；我们今天要学的《涉江采芙蓉》是这十九首诗中的一首；这十九首诗都是五言抒情诗，这些诗我们既不知道作者是谁，也没有题目，所以我们习惯上以首句作为标题，笼统地称它们为古诗；所以我们就知道了《涉江采芙蓉》这首诗，第一句一定是“涉江采芙蓉”，以首句作为标题；古诗十九首在艺术上继承了诗经和楚词的传统，并且吸收了汉乐府的营养，从而创造出一种独特的艺术风格：用什么艺术风格呢？用平浅质朴的文字表现深厚的感情；这些个文字都是非常的浅显的、非常质朴的，但是都能够打动你，因为它表现的情感特别的真挚、深厚；古诗十九首的出现，标志着五言诗已经达到了成熟的阶段；历代文人对古诗十九首的评价都非常的高，比如说刘勰在《文心雕龙》中称古诗十九首是“五言之冠冕”，第一的、最高的、最好的；钟嵘的《诗品》说古诗十九首“天衣无缝，一字千金”；明代的王世贞称它是“千古五言之祖”；那么这些个评价可以说都是非常高的，也就是说古诗十九首的艺术成就真的是非常的高。下面我们再来看一下古诗十九首所在的这本书，萧统的《文选》：《文选》也叫昭明文选，它是我国最早的一部各类文学作品的选集，收录了秦汉以来的文学作品，它是由南朝梁武帝萧衍的长子萧统组织文人编写而成的；因为萧统死后谥号叫昭明，后来人们就称他为昭明太子，那么所以他所主编的这部作品选集就被称为昭明文选；萧统从性情上来说，对父母至孝、这是一个纯孝之人，然后他还是一个非常仁厚善良的人，他对待他身边的人、对待大臣、对待百姓都是非常仁厚的，同时萧统还是一个特别聪慧的人，据说他看书是数行俱下、就能够一下子看好几行，而且过目不忘；然而遗憾的是，英年早逝，三十岁就去世了；所幸的是他留下了这本《昭明文选》，也算是不幸中的一点安慰吧。下面我们就一起来看一下这首《涉江采芙蓉》，有两个读音需要注意，一个是“采之欲遗谁”的“遗”，一个是“还顾望旧乡”的“还”。下面我们就来赏析一下这首诗：涉江采芙蓉，兰泽多芳草；“涉”是渡水、过江的意思，渡过江水去采摘芙蓉，芙蓉就是荷花；兰泽就是生有兰草的水泽；有芙蓉、有兰泽、有芳草，就是抒情主人公涉江去采摘芙蓉的情景；如果这个抒情主人公他有心情去采摘芙蓉，芙蓉、兰泽、芳草这些都是用来表达情感的意象。为什么要采芙蓉，送给远方的人而不是采其他的东西呢？芙蓉又有什么特别之处呢？芙蓉又称荷花、莲花：周敦颐写道，“出淤泥而不染，濯清涟而不妖”，所以在这里，这个芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说，“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里，芙蓉是美丽的佳人之花；所以在这里，这个芙蓉是纯洁的爱情之花；李清照的《如梦令》中也写到了芙蓉；所以说这首诗也以芙蓉、以荷花作为意象来描写。同心而离居，忧伤以终老。收尾：咱们就讲到这里，最后咱们连接高考，看一下这些个情景填空，咱们能不能填上，看一下答案；好了，《涉江采芙蓉》咱们就讲到这儿。", "vtech": [["“春花秋月”怎么答", "春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君要忍受无尽的屈辱，一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光；不变的是春花秋月，永恒的春花秋月。"], ["“问君能有几多愁”怎么答", "问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁——愁思之多、愁思之绵长、愁思之深重和绵长，而且用有形的水来比喻抽象的无形的愁；用一个设问就加倍地突出了这个“愁”字；多少愁啊，像一江春水一样的愁。"], ["对比与想象怎么答", "雕栏玉砌应犹在、只是朱颜改，就形成了鲜明的对比，物是人非的悲愁之感悠然而生；除了对比还运用了想象，此时此刻李煜的思绪回到了南唐的故宫；“雕栏玉砌”就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜。"], ["为什么采芙蓉怎么答", "芙蓉又称荷花、莲花：周敦颐写道“出淤泥而不染，濯清涟而不妖”，所以在这里芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里芙蓉是美丽的佳人之花；所以在这里芙蓉是纯洁的爱情之花；这首诗也以芙蓉、以荷花作为意象来描写。"]], "vgaokao": []}}, "chn_c032": {"name": "虞美人·鹊桥仙", "sec": 1, "secTitle": "古诗词诵读", "page": 141, "desc": "李煜的亡国之愁与秦观的爱情名篇：「一江春水」与「两情久长」。", "criteria": ["能准确背诵默写本篇名句且不写错字", "能说清本篇的体裁常识、结构与关键手法", "能独立做对基础题（字词、常识、名句填写）", "能独立做对应用题（手法赏析、语句翻译）", "能独立完成综合鉴赏题并写清答题要点"], "diag": {"question": "默写：《鹊桥仙》中被后人传诵的爱情名句。", "answer": "两情若是久长时，又岂在朝朝暮暮。"}, "pre": ["chn_c031"], "next": [], "content": {"advance": {"a": "表面是写给世人的爱情誓言，实则是秦观词风的代表：把七夕的悲剧传说翻成乐观语——别人写相思之苦，他写相知之久。反常的立意让它从众多七夕词中跳出来，成为千古名句。这与他贬谪生涯中的达观一面互为表里。", "kind": "self", "q": "七夕词多写离别之苦，《鹊桥仙》为何反成千古名篇？谈谈它立意上的翻新。"}, "apply": [{"ans": 1, "opts": ["用一句话直说愁很多", "以水喻愁：江水无穷、东流不返，把抽象的愁写成可量、可视、不可遏止的流动之物", "愁像石头很重", "愁像天上的云"], "q": "「问君能有几多愁，恰似一江春水向东流」的比喻妙处是（ ）", "why": "设问加比喻：愁的量化（几多→一江）、方向（向东流→不可回头）全在里面，是以水喻愁的最高范本。"}, {"ans": 1, "opts": ["只有相逢的一夜", "胜却人间无数次的相守——一夜之真胜过无数之俗，把聚少离多的常态翻成精神长久的非常态", "两人决定不再相见", "牛郎织女很伤心"], "q": "「金风玉露一相逢，便胜却人间无数」的意思是（ ）", "why": "这是全词立意的转折句：以质取胜，是下文「两情久长」的逻辑前提。"}], "basics": [{"ans": 1, "opts": ["苏轼", "李煜", "柳永", "秦观"], "q": "《虞美人·春花秋月何时了》的作者是南唐后主（ ）", "why": "李煜，南唐后主，亡国后词风由宫廷享乐转为亡国之痛，成就反而更高。"}, {"ans": 0, "opts": ["秦观", "苏轼", "贺铸", "周邦彦"], "q": "《鹊桥仙·纤云弄巧》的作者是婉约词人（ ）", "why": "秦观是婉约派代表（苏门四学士之一），词风清丽含蓄。"}], "case": {"a": "上片写情的质地：纤云、飞星、银汉写相逢之境，金风玉露一句把一夜相逢的价值推到胜却无数——先肯定相聚之贵。下片翻出主旨：柔情佳期如水如梦本该伤感，词人却说只要两情久长，又何必在乎朝朝暮暮的形影相守——把空间的阻隔让位给时间的长久。上片之贵与下片之久首尾相衔，名句由此落地。", "q": "为《鹊桥仙》上下片各写一句主旨，并说明两句的衔接关系。", "title": "案例：上下片衔接"}, "intro": "诵读收官两首词：**李煜**的《虞美人》写亡国之愁，**秦观**的《鹊桥仙》写七夕之爱。==一首以水喻愁，一首以久翻新——两句话都是千古名句，都进了高考默写表。==", "learn": [{"h": "虞美人：以水喻愁的祖本", "p": "李煜被俘入宋后之作（相传作于其生日宴后的感怀）。上片追问：春花秋月何时了，往事知多少——好时光勾起亡国记忆；「雕栏玉砌应犹在，只是朱颜改」物是人非。下片设问收束：「问君能有几多愁？恰似一江春水向东流。」==以水喻愁的三个要点：有量（一江）、有向（东流不回）、有势（绵绵不绝）——默写题与鉴赏题都在这三点里。=="}, {"h": "鹊桥仙：七夕词的立意翻新", "p": "牛郎织女的故事本来是悲剧，秦观却写：相逢一夜的质量，胜过世间无数庸常的相守；两情若是长久，又何必计较朝朝暮暮的厮守。立意层层递进：一夜之贵—相知之深—长久之许。这是婉约词中难得的明朗语，高考默写与作文引用都极爱这句。"}, {"h": "两首对照读", "p": "同为诵读篇目，一悲一达：李煜的愁不可解（江水东流，愁亦不止），秦观的爱可超越（距离阻不断久长之情）。对照记情感出口：愁向时间流逝处去，爱向精神长久处立。若作文需要「面对失去」的素材，李煜在前；需要「面对距离」的素材，秦观在后。"}], "pitfalls": ["默写错字：「雕栏玉砌」的「砌」读 qì；「银汉迢迢」的「迢」读 tiáo 不要写成「招」。", "《鹊桥仙》把「朝朝暮暮」的主语弄反：它说的是不必在意形式上的朝夕相处，不是鼓励不见面。", "李煜身份记错：他是南唐后主（词人皇帝），不是唐朝皇帝。"]}, "video": {"bvid": "BV1mCqkYPEYr", "p": 1, "t": "古诗词诵读四首", "dur": "57:49", "from": "王老师", "vtop": ["本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。", "李煜词分前期后期：前期写宫廷享乐，后期写物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念。", "《涉江采芙蓉》用平浅质朴的文字表现深厚的感情，是古诗十九首的风格；古诗十九首标志着五言诗已经达到了成熟的阶段，刘勰称其为“五言之冠冕”，钟嵘称其“天衣无缝，一字千金”。"], "vsum": "本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。**第一首：李煜《虞美人》**。开场：同学们好，王老师带你学语文；他生于七夕、卒于七夕，他是一位君王，更是一位伟大的词人；大家说，他是谁呢？对，他就是南唐后主李煜；这节课我们就走进被称为亡国君王、绝代词人的李煜，学习他的代表作《虞美人》。**李煜简介**：李煜原名从嘉、字重光，他是五代十国时期南唐的最后一任帝王，在位十五年，史称南唐后主或者说李后主；史书记载，李煜为人仁孝、善属文、擅长写文章，工书画、也擅长书法绘画；凤额龙睛、一目重瞳子，凤额大概就是天庭饱满，龙睛就是眼睛里边有两个瞳孔，其实这是眼睛发生的病变，但是苍颉、虞舜、项羽都是重瞳子，所以古代相术就认为重瞳意味着吉祥与富贵、是帝王的象征，所以可以说李煜天生就有帝王之相；可是李煜本人却没有称帝之心，只想做一个富贵闲人，而且李煜是南唐宗主李璟的第六个儿子，所以正常情况来说也轮不到他做皇帝；可惜的是李弘冀和他的叔叔李景遂争夺王位的继承权，后来李弘冀当上太子之后就毒杀了他的叔叔李景遂，然后南唐宗主李璟因为李弘冀残害自己的亲叔叔，就废了李弘冀的太子职位；所以李煜被迫做了南唐的皇帝，而且十几年之后，南唐就灭亡了。**词风分期**：前期则描写了宫廷享乐，后期则描写了物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念等等。**写作背景**：南唐只能延续纳贡的政策、一再委屈求全，但是这也没有能够阻止宋兵围城的步伐；975 年，南唐在与宋的交战中不敌、最终亡国，李煜肉袒出降，非常屈辱啊；他不甘心南唐的灭亡。**赏词**：下面我们就一起来赏析一下李煜的这首绝笔之作《虞美人》：春花秋月何时了，往事知多少？小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁，恰似一江春水向东流。春花秋月什么时候才能停止呢？我们看这个春花秋月：春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君，要忍受无尽的屈辱；所以一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光。小楼昨夜又东风：小楼昨夜又迎来了东风；这个“又”字表现了作者怎样的情感呢？再看这个故国：故国指的是南唐故都金陵，这个国指的是国都金陵，就是现在的南京；故国不堪回首月明中，遥望南唐的故都呢。雕栏玉砌应犹在，只是朱颜改：这个“砌”我们注意啊，是台阶的意思，雕栏玉砌就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜；就形成了鲜明的对比，物是人非的悲愁之感悠然而生；那么除了对比，还运用了什么艺术手法呢？这是作者的想象，此时此刻李煜的思绪回到了南唐的故宫。问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁，来比喻愁、说愁思，愁思之多、愁思之绵长，写出了愁思的多、深重和绵长，而且用有形的水来比喻抽象的无形的愁，我们说这个愁是无形的呀、是抽象的呀，我们怎么来写呢？没有办法形容；多少愁啊，像一江春水一样的愁；用一个设问就加倍地突出了这个“愁”字；亡国之恨。不变的是春花秋月，永恒的春花秋月。**第二首：《古诗十九首·涉江采芙蓉》**。我们先来了解一下《古诗十九首》：《古诗十九首》是《十九首诗》的统称，由汉代文人创作，并且被南朝的萧统选录编入《文选》；我们今天要学的《涉江采芙蓉》是这十九首诗中的一首；这十九首诗都是五言抒情诗，这些诗我们既不知道作者是谁，也没有题目，所以我们习惯上以首句作为标题，笼统地称它们为古诗；所以我们就知道了《涉江采芙蓉》这首诗，第一句一定是“涉江采芙蓉”，以首句作为标题；古诗十九首在艺术上继承了诗经和楚词的传统，并且吸收了汉乐府的营养，从而创造出一种独特的艺术风格：用什么艺术风格呢？用平浅质朴的文字表现深厚的感情；这些个文字都是非常的浅显的、非常质朴的，但是都能够打动你，因为它表现的情感特别的真挚、深厚；古诗十九首的出现，标志着五言诗已经达到了成熟的阶段；历代文人对古诗十九首的评价都非常的高，比如说刘勰在《文心雕龙》中称古诗十九首是“五言之冠冕”，第一的、最高的、最好的；钟嵘的《诗品》说古诗十九首“天衣无缝，一字千金”；明代的王世贞称它是“千古五言之祖”；那么这些个评价可以说都是非常高的，也就是说古诗十九首的艺术成就真的是非常的高。下面我们再来看一下古诗十九首所在的这本书，萧统的《文选》：《文选》也叫昭明文选，它是我国最早的一部各类文学作品的选集，收录了秦汉以来的文学作品，它是由南朝梁武帝萧衍的长子萧统组织文人编写而成的；因为萧统死后谥号叫昭明，后来人们就称他为昭明太子，那么所以他所主编的这部作品选集就被称为昭明文选；萧统从性情上来说，对父母至孝、这是一个纯孝之人，然后他还是一个非常仁厚善良的人，他对待他身边的人、对待大臣、对待百姓都是非常仁厚的，同时萧统还是一个特别聪慧的人，据说他看书是数行俱下、就能够一下子看好几行，而且过目不忘；然而遗憾的是，英年早逝，三十岁就去世了；所幸的是他留下了这本《昭明文选》，也算是不幸中的一点安慰吧。下面我们就一起来看一下这首《涉江采芙蓉》，有两个读音需要注意，一个是“采之欲遗谁”的“遗”，一个是“还顾望旧乡”的“还”。下面我们就来赏析一下这首诗：涉江采芙蓉，兰泽多芳草；“涉”是渡水、过江的意思，渡过江水去采摘芙蓉，芙蓉就是荷花；兰泽就是生有兰草的水泽；有芙蓉、有兰泽、有芳草，就是抒情主人公涉江去采摘芙蓉的情景；如果这个抒情主人公他有心情去采摘芙蓉，芙蓉、兰泽、芳草这些都是用来表达情感的意象。为什么要采芙蓉，送给远方的人而不是采其他的东西呢？芙蓉又有什么特别之处呢？芙蓉又称荷花、莲花：周敦颐写道，“出淤泥而不染，濯清涟而不妖”，所以在这里，这个芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说，“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里，芙蓉是美丽的佳人之花；所以在这里，这个芙蓉是纯洁的爱情之花；李清照的《如梦令》中也写到了芙蓉；所以说这首诗也以芙蓉、以荷花作为意象来描写。同心而离居，忧伤以终老。收尾：咱们就讲到这里，最后咱们连接高考，看一下这些个情景填空，咱们能不能填上，看一下答案；好了，《涉江采芙蓉》咱们就讲到这儿。", "vtech": [["“春花秋月”怎么答", "春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君要忍受无尽的屈辱，一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光；不变的是春花秋月，永恒的春花秋月。"], ["“问君能有几多愁”怎么答", "问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁——愁思之多、愁思之绵长、愁思之深重和绵长，而且用有形的水来比喻抽象的无形的愁；用一个设问就加倍地突出了这个“愁”字；多少愁啊，像一江春水一样的愁。"], ["对比与想象怎么答", "雕栏玉砌应犹在、只是朱颜改，就形成了鲜明的对比，物是人非的悲愁之感悠然而生；除了对比还运用了想象，此时此刻李煜的思绪回到了南唐的故宫；“雕栏玉砌”就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜。"], ["为什么采芙蓉怎么答", "芙蓉又称荷花、莲花：周敦颐写道“出淤泥而不染，濯清涟而不妖”，所以在这里芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里芙蓉是美丽的佳人之花；所以在这里芙蓉是纯洁的爱情之花；这首诗也以芙蓉、以荷花作为意象来描写。"]], "vgaokao": []}}}, "units": {"u_chn_1": {"id": "u_chn_1", "name": "沁园春·长沙", "secs": "第1课", "pageFrom": 2, "pageTo": 3, "members": ["chn_c001"], "video": {"bvid": "BV1JB4y1G7kF", "p": 1, "t": "沁园春·长沙", "dur": "26:47", "from": "名师课堂", "vtop": ["“独立”不能改成“站立”：倒装前置强调“独立”，写出诗人身处险境仍坦荡从容、胸怀天下的中流砥柱气概。", "意象是融入作者主观情感的客观物象，上片“看”字领起万山、层林、漫江、百舸、鹰、鱼，远近高低多角度写秋景。", "下片首句“携来百侣曾游”是过片，承上启下；“中流击水，浪遏飞舟”回答了上片“谁主沉浮”：主宰国家命运的是以天下为己任的青年革命者。"], "vsum": "本课学毛泽东青年时代写的词《沁园春·长沙》。开场先看毛泽东年少时写的两首诗，感受他一往无前的斗争精神和天下有我的伟人情怀：一首是《七绝·改西乡隆盛诗赠父亲》，“孩儿立志出乡关，学不成名誓不还。埋骨何须桑梓地，人生无处不青山”；另一首是《七绝·咏蛙》，“独坐池塘如虎踞，绿荫树下养精神。春来我不先开口，哪个虫儿敢作声”。这就是奋斗的青春该有的样子。这首词写于**1925年**，当时革命运动正蓬勃发展，五卅运动和省港大罢工相继爆发，毛泽东直接领导了湖南的农民运动；同时国共两党的统一战线已经确立，国民革命政府已在广州正式成立。这年深秋，毛泽东去广州主持农民运动讲习所，在长沙停留期间重游橘子洲，面对湘江上的自然秋景，联想到当时的革命形势，便写下了这首词。赏析诗词从三个方面入手：一从**内容**方面入手，读懂这首词写了什么；二从**写作手法**入手，明确这首词是如何写的，写作手法一般包含描写手法、修辞手法和抒情方式三方面；三从**情感**入手，读懂作者为什么写这首词、要表达什么情感。先赏上片，上片主要写景。首句“**独立寒秋，湘江北去，橘子洲头**”，正常语序应该是“寒秋独立橘子洲头，湘江北去”，分别点明了时间、地点和特定环境。“独立寒秋”从语法上看采用了**倒装**，倒装的目的在于强调“独立”。“独立”这个词能不能改成“站立”呢？显然不能。当时湖南军阀赵恒惕命令湘潭县团防局逮捕毛泽东就地正法，毛泽东得到消息后趁着月色扮成乡下郎中，坐轿子回到了韶山，秘密来到了赵恒惕的眼皮底下长沙。诗人身处险境，却能独立寒秋，表现了他的坦荡和从容，更有迎风独立、俯视天下、胸怀大志的形象，体现了诗人充当中流砥柱、顶天立地的气概。同时把“独立”前置增强了表现力：用一个特写镜头把人物从景中推出，凸显了抒情主人公卓然而立的形象，激发了读者的联想与想象。柳宗元“独钓寒江雪”表达了被贬的落寞与独善其身的清高，与革命伟人胸怀天下的傲岸不群是不可同日而语的。欣赏完“独立寒秋图”，继续欣赏“湘江秋景图”。欣赏之前先学一个重要概念——**意象**：意象指诗歌中融入了作者主观情感的客观物象，是作者内在的思想情感与外在的客观物象的统一。这幅图景由“**看**”字领起，“看”字统领的意象有远山、层林、漫江、百舸、鹰击长空的鹰、畅游水中的鱼。先看远景：作者远眺群山，“**万山红遍**”，写出了群山起伏叠嶂之态，气象雄阔、视野开阔、大气磅礴；“遍”写出了红之广，一个数词一个副词，虽不是什么华丽的词藻，却通过红叶写出了秋天的壮观，红色枫叶在秋阳的照耀下红得似火、辉煌灿烂，突出了壮阔之美。“**层林尽染**”：“层”写出了树木随山势起伏而远近上下变化的形态；“尽”形容秋天的树叶全部变红，具有很强的画面感；“**染**”运用**拟人**的手法，写出了枫叶的颜色由淡变深的动态，且充满了意趣。王实甫在《西厢记》中有“**晓来谁染霜林醉，总是离人泪**”的名句，一个“染”字就把一片枫林仿佛人工染成的一样的壮美景色描绘出来。南宋的张炎在《疏影·咏红叶》中写红叶，寄寓着作为南宋遗民在南宋灭亡后面对异族的残暴统治依然保持爱国赤诚忠贞之心，彰显了亡国遗民蔑视卑躬屈膝的新贵的高尚气节。同样面对黑暗的社会现实，张炎展现了不卑不亢的民族气节，而毛泽东则通过壮丽之景透露出自信乐观的豪情。随着镜头的拉近，作者静观“**漫江碧透**”：“漫”是满的意思，不是取一朵浪花、一轮涟漪，而是放眼湘江整体，写出了江水漫溢之状；“透”写出了江水的清澈；“碧”是青绿色，既写出了江水的清澈，又赋予生命的力度，勃发着生命的光彩。“漫山红遍，漫江碧透”，红碧两色都赋予生命的力度，勃发着生命的光彩，一派勃然生机、欣欣向荣；而且红碧两色的对比度很强，红在碧的映衬下愈显其红，碧在红的映衬下愈显其绿，红枫绿水、交相辉映、色彩流光、鲜艳夺目。古代诗人的写景诗中也非常注意景色颜色的搭配，杜甫诗句“山青花欲燃”也是以青红二色描写出青山的壮美。“**百舸争流**”：“百”写出了船只的众多；“争”写出了江面上千帆竞发、争先恐后的热闹场面，不仅是数量多、热闹，且写出一种生机活力，与整体诗意相合。老师把这句与屈原《九歌》里同样写千帆竞渡的句子进行对比：屈原那句为纪念我国第一位爱国诗人屈原，用竞渡来消解心中的愁绪，多一份悲壮，蕴含着人们对他的无限缅怀；毛泽东的诗中却张扬着不甘人后的竞争气势。随着镜头的变幻，作者仰观应天、俯瞰于地：“**鹰击长空**”这句中“击”是否可以改为“飞”？是不行的。“击”本来应该是人发出的动作，有搏击的意味，更能把雄鹰振翅奋飞、迅猛有力地搏击长空的矫健勇猛的雄姿描绘出来，写出雄鹰振翅翱翔的自由，如此有力、如此傲然，天地之间只见这一只只雄鹰。“**鱼翔浅底**”：“翔”一般用来形容鸟儿，鱼儿在水中应该是游动的，为什么用“翔”呢？“浅底”并非真的水浅，而是清澈见底、水浅得看得见底，蓝天倒映在碧水中，看上去鱼好像在天空中游动，好像飞翔一样，不用扇动翅膀而飞，生动地写出了鱼在水中自由自在、轻松自如的神态。“翔”使整个画面活化了。再深入一层，还可理解为：鱼在水中游是眼前之景，在空中翔可以理解为心中之景，因为比海洋还辽阔的是天空，在天空翱翔的鱼更加自由。这句词是在化用《诗经·大雅·旱麓》“鸢飞戾天，鱼跃于渊”的基础上进行的不着痕迹的化用，赋予了客观事物强烈的感情色彩，更好地表现了那种彻底追求自由的状态。“**万类霜天竞自由**”由眼前景扩展到世间万物，并做了哲理性升华，“竞”有力地突出了在寒秋严霜下万物蓬勃旺盛的生命力，让读者感受到诗人对大自然的无限热爱和由衷赞美。既然世间万物都在秋光中过着自由自在的生活，在秋光中获得了自由生存，那么作为万物之灵的人类，特别是被压迫被剥削的人民，不是更应该竞自由吗？这实际上是对被压迫人民的号召和呼唤。秋天是草木变衰的季节，也是一般人容易伤怀的时候。刘禹锡《秋词》说“**自古逢秋悲寂寥，我言秋日胜春朝**”，自从宋玉悲秋，历代文人皆生悲意，秋天落在纸面上只是一颗凄清的泪滴而已。然而秋天又是守成与革新的试金石：秋天对旧有之物进行否定，对新生之物加以肯定，大凡守成恋旧的人常会因秋气扫除旧物而感慨盛世变衰，而立志改造社会的革命者对秋天的除旧布新予以热烈的欢呼。毛泽东是伟大的革命家，他所进行的改变中国几千年历史的革命是一场划时代的大革命，他热爱秋天，在所有的词作中多次欢呼秋天、赞美秋天，如“**一年一度秋风劲，不似春光，胜似春光**”“**万木霜天红烂漫**”“**六盘山上高峰，红旗漫卷西风**”。在本词中，诗人呈现在我们眼前的是一幅绚丽蓬勃、充满生机的瑰丽图景，诗人对秋天的礼赞更是达到了如火如荼的地步。品读上片最后一句“**怅寥廓，问苍茫大地，谁主沉浮**”：“怅”是诗意不畅、怅惘，这里用来表达由深思而引发的激昂慷慨的心绪；词人面对生机勃勃的大自然和广阔的宇宙，面对着在大自然和宇宙中竞自由的万物，思绪万千、深沉地思索。他想到了祖国的命运和革命的未来，禁不住向苍茫大地发问，谁来主宰国家的命运、掌握民族的前途，提出革命领导权的问题。“问”有力发千钧之势，是屈原笔下的《天问》，意在告诉我们天将降大任于斯人也，直接表现了诗人博大的胸襟和气魄。上片作者独立湘江，描绘了一幅生机盎然、色彩绚丽壮美的秋景图，并借景抒情，发出了“谁主沉浮”的感叹，直接表现了诗人博大的胸襟和气魄。面对上片提出的问题，下片是如何回答的呢？下面一起分析下片。首先具体研习“峥嵘岁月图”：“**携来百侣曾游，忆往昔峥嵘岁月稠**”在全文的结构中起什么样的作用呢？一般分上下两片的词，其下片首句又称**过片**，在词中起承接过渡的作用，因此填词时非常注意过片。本词上片写独立寒秋、故地重游而看到了景色，自然而然地想到以前同学携手来游的情景，于是过渡到对往昔生活及同学少年的回忆中，在此过渡非常自然，衔接也是非常巧妙。上片讲到“百舸争流”，数词“百”写出了船之众多，同样这里的“百侣”突出同学少年的人数之多、气势之大；“携”有带领的意思，彰显领导本色。橘子洲是青年毛泽东与同学战友常来游览的旧地，旧地重游，回忆浮现。“峥嵘”原指山势险峻，这里是不平凡、不寻常的意思；“稠”指多，“峥嵘岁月稠”指不寻常的日子很多。毛泽东在长沙生活、学习、从事革命期间，国内外发生了许多重大事件：辛亥革命、第一次世界大战、俄国十月革命、五四运动、中国共产党的成立等，都是影响世界形势的巨大变革，这样的岁月如历史群山中耸立的一座又一座的峥嵘的高峰。“**恰同学少年，风华正茂；书生意气，挥斥方遒**”四句，激昂顿挫、节奏鲜明，活化出一群青年革命家的英姿俊彩：正值青春年少的同学们意气风发、才华横溢、激情奔放、革命斗志昂扬。1914年，毛泽东进入湖南省第一师范读书，结识了一批胸怀革命大志的学友，经常在湘江岸边、岳麓山中、橘子洲头聚会，在蓬勃发展的革命形势的激励下，他们纵谈革命理想、满腔热情，正如汹涌的湘江浪涛奔腾无阻。“**指点江山，激扬文字，粪土当年万户侯**”艺术地概括了这群青年革命家的实践活动：毛泽东曾在长沙组织起湖南学生联合会和新民学会，开办了工人夜校，宣传革命真理；他们评论国家大事，写出了一篇篇激扬文字。毛泽东在《湘江评论》中豪迈地宣称：军阀不要怕，官僚不要怕，资本家不要怕，把军阀官僚看得同粪土一般。“粪土”在这里是**意动用法**，是“以……为粪土”的意思；“万户侯”本指十万户的封侯者，这里借指大军阀大官僚。回忆峥嵘岁月，流露出对往事的无限怀念，表现了他和革命战友们以天下为己任、蔑视反动派、改造旧世界的革命战斗豪情，同时也说明年轻的革命家完全可以主宰中国的命运，完全有能力打碎旧的国家机器，创造一个崭新的世界。现在继续学习“中流击水图”：“**曾记否，到中流击水，浪遏飞舟**”。当年，作者曾和蔡和森等数十名战友同学，在上水和下水的时候到湘江游泳，坚持不懈，直到隆冬季节，以此来锤炼自己的意志和胆识。现在，作者独立于橘子洲头，回忆起当时的情景，不禁向同学和战友亲切发问。这一句既写出了当时的情景，其中又暗含了勉励之意。“遏”传神之极，掷地可作金石之声，使我们仿佛看到了他们激昂的神态，好似听到了他们的豪言壮语，形象地表达了一代革命青年的凌云壮志。关于“中流击水，浪遏飞舟”，有两种不同的理解：一种解释为“击水”为游泳，在激流中奋力划水，掀起了浪花，甚至阻挡了飞速前进的船舶；另一种解释为“中流击水”即中流砥柱的转化，祖逖中流击楫而誓曰“祖逖不能清中原而复济者，有如大江”，后来“中流击楫”就成了立志复兴祖国的代名词，在这里表示诗人要在时代的潮流里乘风破浪、勇往直前、立志振兴中华的豪情壮志。无论是“到中流击水”还是“中流击楫”，本身都是带有抗争的意味，它实际上是青年革命家峥嵘岁月的艺术缩影。如果把中国革命看作是一条长河，那么这群中流击水者正是长河中的弄潮儿，他们的大无畏精神激起了震天动地的湘江浪涛。这些青年是真正的风流人物，这样的人不主沉浮，谁又能主宰沉浮呢？诗人巧妙地借用“中流击水，浪遏飞舟”的图景，回答了“谁主沉浮”的问题，形象地表达了诗人以天下为己任、蔑视反动统治者、改造旧中国的壮志豪情。这首词上片描绘了一幅多姿多彩、生机勃勃的湘江秋景图，并借景抒情，提出了“苍茫大地，谁主沉浮”的问题；下片回忆了往昔的峥嵘岁月，表现了诗人和战友们为了改造旧中国英勇无畏的革命精神和壮志豪情，形象含蓄地给出了“谁主沉浮”的答案：主宰国家命运的，是以天下为己任、蔑视反动统治者、敢于改造旧世界的青年革命者。全词气势豪迈、激情奔放，洋溢着诗人的青春热情，体现了诗人的伟大抱负。这首词的豪迈气势从何而来？作者是如何表现的呢？首先是**意象美**：由于立意昂扬向上，所以所选取的意象也是生机勃勃的景物，选取的意象广大高远；其次在景物的摄取上采用**多方观照、广角摄影**的手法，多角度、多层面地展示秋光：万山层林是远景，漫江百舸是近景，鹰击仰视、鱼翔俯视，远近高低一览无余；其三在景物的着色上注重**色彩的映衬**搭配，选取红、碧二色；其次是语言极富有表现力，精选**动词**形象入化，数词“万”“百”凸显豪放诗风，“万”“百”突出了宏大壮阔、力学上的崇高美感，给人以强烈的视觉震撼，彰显诗人豁达的胸襟，在毛泽东的其他诗词中用“万”“千”“百”等数词营造一种豪放开阔的氛围已成为他的风格，例如“红军不怕远征难，万水千山只等闲”“北国风光，千里冰封，万里雪飘”；形容词和副词的使用准确到位；其五在景物状态的描写上**动静结合**：山红水绿是静态美，鹰是搏击长空、鱼是漫游浅底、船是竞相争流、水是滔滔北去，体现了动态美，在作者的笔下，秋天不再是生命渐趋衰弱，恰恰相反，那是一个充满了生机的辉煌世界；其六是**景中含情、情景交融**：作者以情驭景，依据自己的主观情志去选择驾驭景物，词中的景物是作者主观能动化了的景物，融入了作者的感情色彩和思想意识，透过这幅壮丽飞动的秋景图，我们读到了它博大的胸襟、崇高的风范。上片写景，景中有情，无论是树叶经霜变红、似染过的万山，还是湘江水中百舸争流的场面，或是搏击长空的雄鹰和水中自在来往的游鱼，都是融入作者情感的景物；下片有叙述、有议论，也结合着抒情，在作者回忆往昔生活的时候，注入颂扬当代英雄的斗志豪情。通过这首词的学习，我们不仅感受到了青年时期的毛泽东以天下为己任、改造旧世界、创造新天地的战斗精神，也学习了鉴赏诗词的方法。练习：比较《沁园春·长沙》和马致远的《天净沙·秋思》“枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯”在意象的选取和表达的情感上有何不同。意象选取不同：《沁园春·长沙》选取远山、层林、漫江、百舸、搏击长空的鹰、畅游水中的鱼等具有壮丽特点的意象；《天净沙·秋思》选取枯藤、老树、昏鸦、西风等具有凄清悲凉特点的意象。表达情感的不同：《沁园春·长沙》表现革命青年以天下为己任、改造旧世界、创造新天地的精神；《天净沙·秋思》充分表现了断肠人浪迹天涯的浓烈的思乡之情。课后作业：再读《沁园春·长沙》，以“诗歌里的青春”为主题，撰写读后感。毛泽东创作这首词时正当而立之年，正是这青年时代树立的雄心壮志和百折不挠、乐观奋进的精神气概成就了一代伟人。青春是什么？青春是生命力最旺盛的年代，充满着豪情，洋溢着乐观，朝气蓬勃，意气风发，斗志昂扬。无奋斗，不青春。老师衷心地希望同学们在自己的青春岁月中都能自觉地磨练意志，塑造完善的人格，像当年的毛泽东那样，到中流击水，浪遏飞舟，书写出壮阔的人生篇章。", "vtech": [["“独立”与倒装：强调什么", "正常语序是“寒秋独立橘子洲头”，把“独立”前置是倒装，目的在强调“独立”；“独立”不能换成“站立”：诗人当时正被军阀下令逮捕，身处险境仍独立寒秋，写出坦荡从容、胸怀天下的中流砥柱气概；对比柳宗元“独钓寒江雪”的被贬落寞与独善其身的清高。"], ["意象与“看”字领起", "意象是融入作者主观情感的客观物象；上片“看”字统领万山、层林、漫江、百舸、鹰、鱼六组意象；做题信号：先找领字，再按远近高低列意象，最后说意象背后的情感，别只罗列景物。"], ["动词最见功力：染、击、翔、遏", "“染”是拟人，写枫叶颜色由淡变深的动态；“击”不能换“飞”，“击”有搏击的意味，写出雄鹰振翅奋飞的矫健勇猛；“翔”本写鸟，写鱼显得轻松自如、如在空中飞翔；“遏”传神之极，写浪花阻住飞舟，掷地可作金石之声。"], ["过片与“谁主沉浮”的回答", "下片首句“携来百侣曾游”是过片，承接上片写景、过渡到回忆往昔；“中流击水，浪遏飞舟”有两种理解（击水游泳／中流击楫立志复兴），都含抗争意味，是对上片“谁主沉浮”的回答：主宰国家命运的是以天下为己任的青年革命者。"]], "vgaokao": []}}, "u_chn_2": {"id": "u_chn_2", "name": "诗歌四首", "secs": "第2课", "pageFrom": 4, "pageTo": 11, "members": ["chn_c002", "chn_c003"], "video": {"bvid": "BV1JB4y1G7kF", "p": 2, "t": "诗歌四首", "dur": "25:40", "from": "名师课堂", "vtop": ["《立在地球边上放号》里“力”的特点是壮丽、伟大、不可阻挡，破坏一切又创造一切，充满艺术之美，象征五四时代狂飙突进的精神。", "《峨日朵雪峰之侧》的张力有五个方面：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义，再加上抒情的节制。", "雄鹰、雪豹象征力量、自由、英雄，蜘蛛象征弱小卑微；能坚守高度的不是强大而是弱小——这是《峨日朵雪峰之侧》的主旨。"], "vsum": "本课学第二课的两首现代诗：《立在地球边上放号》和《峨日朵雪峰之侧》。通过比较分析，了解现代诗语言的发展和变化，体会现代诗的诗歌艺术。先学郭沫若的《立在地球边上放号》。作者郭沫若，原名郭开真，四川乐山人，现代文学家、诗人、历史学家。1919年五四运动爆发，他投身新文化运动；1921年发表第一本新诗集《女神》，洋溢着强烈的浪漫主义气息，是中国新诗的奠基之作，郭沫若也因此成为中国新诗的重要奠基人之一；同年他又与郁达夫等人一同创立创造社，成为文学革命的主要阵地；他后来还是中国科学院首任院长。这首诗写于五四新文学时期：当时在思想启蒙的时代主题下倡导文学革命，主张平易抒情、新鲜活泼、明了通俗的国民文学；语言形式上扬弃文言文、提倡白话文写作——1917年《新青年》先刊出胡适的八首白话诗，后来又发表刘半农、沈尹默的白话诗；1918年《新青年》发表鲁迅的白话小说《狂人日记》；稍后郭沫若发表《女神》中的大量诗篇，这些都是这场革命的最初业绩。《立在地球边上放号》就发表于这一时期，诗歌以澎湃的激情赞颂了大自然的神力，洋溢着破旧立新的勇猛革命精神。郭沫若自己说：“个人的郁积，民族的郁积，在这时找到喷火口，也找到喷火的方式。我在那时差不多是狂了。”这些五四初期的新诗，在意象、语言、表现手法上都和古典诗歌迥然不同，虽然还显得生涩、平实，但要知道，打破两千年的文言文传统、第一次用白话文写诗，在当时需要多么勇敢的尝试。赏析这首诗从三个方面入手。一是新奇而主观化的意象：诗中的云海、北冰洋、太平洋、洪涛，展现了大自然宏伟壮丽的图景，是古典诗歌中从未出现的；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作和自然意象融合，使得意象成为生命的化身，渗透着诗人强烈的主观精神，所以称之为主观化的意象，这与古典诗歌的意象是不同的。二是狂飙突进的精神：诗中用雄奇、瑰丽、气势磅礴的意象，最终指向一种“力”。这种力有什么特点？从天空的云海到最极端的北冰洋，是壮丽的；竟然能把地球推倒，是前所未有而伟大的；滚滚而来，不可阻挡；破坏一切，又能创造一切；还能创造艺术之美，表现在形态、声响、韵律这些方面。这种力象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明，表现出一种积极进取、勇敢创造的昂扬精神，和热烈追求、摧毁旧世界的勇气与坚定。这种精神是古典诗歌中不曾出现的。三是自由的语言形式：句式上不再有字数限制，而是灵活多变，随着情感变化而变化，使得诗作显得自由奔放；自由的句式不意味着随意搭配，现代诗也讲究内在的韵律——本首诗的长句子由三个韵律单位构成，形成了诗歌的韵律感，读起来有音乐感，这是诗歌区别于散文必不可少的要素之一；“不断的毁坏，不断的创造，不断的努力”这些短句子由动词短语或名词短语排比组成，排比句式增强了诗歌的节奏感和气势；用词方面，白话文口语化的用词通俗易懂、适合传播，在动词、形容词、副词的使用上改变了文言文大多使用单音节词的特点，广泛使用双音节词，符合白话汉语的表达习惯；同时本首诗增加了语气词的使用，“啊”“哟”这些语气词直接抒情，如同词语间的粘合剂，加上后表达感情的效果更强烈。以上这些语言的变化表明，现代诗采用白话文，在句式、词语、抒情等方面都对文言文是一种突破，发展了汉语言的形式，为汉语表达开拓了新的维度。经过了六七十年，到当代，现代诗在语言上愈发取得明显的发展：诗歌文本容量增大，语言技巧性增强，给人以更多的玩味和思考。下面以本课另外一首诗《峨日朵雪峰之侧》为例，谈谈当代诗歌的特点。先了解诗人昌耀：原名王昌耀，湖南桃源人，诗人；1950年参军，曾参加抗美援朝；1955年去青海工作，后调任作协青海分会专业作家。昌耀在苦难深重的生活重压之下，将感悟和激情融于凝重、壮美的意象之中，诗歌中体现了饱经沧桑的情怀、古老开阔的西部人文背景和博大的生命意识，在当代中国诗坛具有重要的地位。峨日朵雪峰是祁连山脉的一座无名山，山顶终年积雪；这首诗写于特殊的年代，诗人遭受了不公正的待遇，但是坎坷的命运与艰苦的生活磨练了诗人的意志，更砥砺了诗人的思想。赏析这首诗主要从诗歌张力的角度入手。所谓张力，是现代诗分析绕不过去的术语。罗吉·福勒说：一般而论，凡是存在着对立而又相互联系的力量、冲动或意义的地方，都存在着张力。在现代诗中，一切相互对峙而又相互作用的意象、情感、修辞、语词，都可产生张力，使得诗歌形成一个有机统一体。简单说，张力就是现代诗中那些矛盾又融合的因素。在古典诗歌中，王籍《入若耶溪》“蝉噪林逾静，鸟鸣山更幽”就是张力诗学的典范：蝉噪、鸟鸣是动，林静、山幽是静，动静之间语意背离、形成两极，但两极间的相互作用却相反相成，营造出一个动中有静的新意境；清代诗论家吴乔由此进一步发挥，动中有静正是诗的绝诣所在。在《峨日朵雪峰之侧》中，张力体现在五个方面。第一，语言的跳跃性。诗歌的第一句“这是我此刻仅能征服的高度了”，凝练而突兀。现代诗的语言和散文截然不同，不需要层层渲染铺垫，只展示最核心的意识的一刹那，体现了语言的非连续性和跳跃性，给人想象的空间。“此刻”这个时间词具有暗示性：此前是否已经尽力陆续征服了很多高度，此后会不会有新的高度，我的目标是不是不停地征服新的高度——这些问题带来了稳稳丰富的解读空间。这就是现代诗的语言，凝练集中但绝不缺少丰富，词语表面的意义和内涵的意义之间存在一种张力。第二，词语的张力。“我小心地探出前额，惊异于薄壁那边，朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海”——这里太阳的“彷徨许久”与“决然跃入”形成一组矛盾；“我的指关节，楔钉一样，楔入巨石的罅隙。血滴，从撕裂的千层掌鞋底渗出”——人物的动作“楔入”与“撕裂”形成对比，对比的效果是打破了语言的静止状态，形成一幅动态的画面。第三，意象对比带来的张力。落日、滑坡的山体，是一组下坠的力量；而此时的攀登者，指关节楔入石缝，是一个坚守者、占据者，这构成一组矛盾，让人联想到现实中有很多让人下滑的力量，但坚守者自有自己的高度要坚持，哪怕这高度是自己仅能达到的，也要用尽全力，体现了人在自然和生活面前的尊严。小小的指关节和巨石、血滴和千层岩，这是渺小与巨大的对比，让人联想到每一寸的坚持要付出多么巨大的努力，甚至牺牲。现代诗的意象之间构成矛盾与对比，目的是让读者由外在形象思考精神内涵，给予读者开阔的想象空间。古典诗歌也有意象的对比，例如杜甫“无边落木萧萧下，不尽长江滚滚来”，落叶的渺小与长江的无穷、落叶飘落的细微声与长江奔涌的浪涛声都构成对比；但是传统诗歌意象的对比是平面的，目的是构成一幅有机的画面，以对自然景色绘声绘色的描摹、渲染意境为目的；而现代诗意象的对比是立体的、由外而内，目的是形成丰富的想象空间和内涵层次，不仅从自然，还深入到人生、精神、哲理角度给人启发。第四，意象叠加与减少带来的张力。“朝向峨日朵之雪彷徨许久的太阳，正决然跃入一片引力无穷的山海。山体不时滑坡，引动棕色深渊自上而下的一派消融，响着向远方远去的喊杀声”——这里突出雪山严酷特点的意象，太阳、山海、深渊不停叠加，而消融、喊杀声的声音也在叠加，意象与音响的叠加构成一组外部的力量；而对“我”的刻画则做了减法，只定格在指关节、血滴这样触目惊心的意象上，显示出内部力量的痛苦。内外力量都在拉扯着攀登者下滑，但他却仍在坚守，体现了攀登者的坚毅。意象的组合方式，在古典诗歌甚至早期新诗中，大多是并列的形式，如“枯藤老树昏鸦，小桥流水人家”，再如《立在地球边上放号》中太平洋、北冰洋、云海等意象的并列；还有一种组合方式是从不同角度进行排列，如杜甫“风急天高猿啸哀，渚清沙白鸟飞回”，融合了动静、远近、高低、视听等不同的描写角度；这种传统的意象组合都是线性的，而现代诗通过对意象的叠加和减少，使得诗歌的文本展现出立体般的层次，拓展了语言的维度。第五，比喻带来的暗示意义形成张力。“真渴望有一只雄鹰或雪豹与我为伍”——在陡峭的岩壁上，攀登者渴望成为雪山的雄鹰或雪豹，但“但有一只小得可怜的蜘蛛，与我一同默想着这大自然赐予的快慰”。雄鹰和雪豹是力量、速度、自由、英雄、王者的象征，而蜘蛛象征着弱小、卑微、平凡。人们总是渴望在现实中拥有自由、无拘束、潇洒伶俐的状态，但真正的情况是我们不过是一个卑微弱小的存在，这就带来了反讽的效果，是诗人的自嘲——这一层是比喻带来的表面含义。仔细再读诗歌最后几句：在陡峭的岩壁上，唯一能领略自然之美的是谁呢？只有我和这只弱小的蜘蛛，也就象征着坚守高度的不是强大、不是自由、不是速度，甚至不是英雄和王者，而是弱小。这是比喻带来的暗示意义，也是诗人想传达的诗歌主旨。寒冷陡峭的雪山之侧，光明的太阳落山了，山体正在无法阻挡地下滑；而攀登者忍受着痛苦，如楔钉一样楔入石缝，冷静而坚持。在巨大的雪山背景上，它的渺小就如同一只小小的蜘蛛，这幅画面正象征着在现实的巨浪中，能坚守自持的恰恰是卑微而平凡的人。在理智的叙说与冷静的描述中，有诗人对坚守者的歌颂与赞美。古典诗歌的比喻，本体和喻体之间的距离愈远，想象空间愈广；而现代诗歌不应停留在从本体到喻体的线性描述，而应该产生第三种暗示意义。例如辛弃疾“马作的卢飞快，弓如霹雳弦惊”，霹雳用来形容发弓射箭的速度之快之准，从弓到快准的特点、再到喻体霹雳，比喻是这样线性的表达；而《峨日朵雪峰之侧》也有线性比喻，从坚守者到弱小、平凡的特点、再到蜘蛛，但还有内在的暗示意义：尽管弱小而平凡，却在坚守高度——这一哲理性思考。再看诗人情感发生了怎样的变化。诗歌开头“我小心地探出前额”，紧张而小心翼翼；在不停下滑的深渊面前，“我”坚守住岩壁，指关节楔入石缝，给人一种紧绷之感；而后来觉察到愿望落空，只有蜘蛛陪伴自己，流露出幽默和自嘲；到最后与蜘蛛一同默想大自然赐予的快慰，这里体现了冷静、认同和默契，也体现了诗人达到自己的高度后豁达的心智和洒脱的情怀。古典诗歌“诗言志”的传统决定了抒情是古典诗的主要目的，或者借景抒情，或者直抒胸臆，或者情景交融，情是古诗的内核；而现代诗的抒情是节制的，表面的冷静叙述之下，内在流动着巨大的情感激流，这种情感的变化和流动不是喷涌而出，而是通过语言的技巧和意象的组合实现——这就是情感之流要规范进语言形式的河道之中。通过以上分析可以发现，当代诗歌在意象的组合方式、词语的跳跃性和对比、比喻的多重含义、抒情的节制等方面，都体现了现代诗语言的张力。经过汉语几十年的发展，相较五四时期的新诗，现代诗的语言不断寻找新的表现方式、不断尝试新的手法和技巧，经历了从情感的书写到哲理的思索，这些都表现出现代汉语语言形式的发展；现代诗作为一种独立的文学样式，也渐渐发展出对其进行研究的现代诗学。课堂反馈有两道题：第一题，诗中表现的五四时期狂飙突进的精神具体为一种“力”，这种力有什么特点？答案是这种力是壮丽的、伟大的、不可阻挡的，破坏一切又创造一切，充满艺术之美。第二题，《峨日朵雪峰之侧》体现出来的现代诗的张力特点有哪些方面？答案是现代诗的张力主要表现在意象的组合方式（包括意象对比、意象叠加或减少）、词语的跳跃性和对比、比喻的多重含义，以及抒情的节制。课后作业：请同学们在以下现代诗中任选一首，从词语、意象组合、情感等方面试作赏析。", "vtech": [["主观化的意象：新诗与古典诗的分水岭", "云海、北冰洋、太平洋、洪涛是古典诗歌中从未出现的新意象；“无限的太平洋提起它全身的力量来，要把地球推倒”——人的动作与自然意象融合，意象成为生命的化身，渗透着诗人强烈的主观精神；做题信号：问新诗与古典诗意象有何不同，先答意象新、再答意象主观化。"], ["“力”的特点与象征：五四狂飙突进的精神", "这种力是壮丽的、伟大的、不可阻挡的，破坏一切又能创造一切，还能创造艺术之美（形态、声响、韵律）；它象征着五四时代狂飙突进的精神：毁坏旧世界、旧社会、旧文化，创造崭新的一切、崭新的文明；答题时五个特点要答全，别只写“破坏旧世界”。"], ["张力的五个方面", "《峨日朵雪峰之侧》的张力体现在：语言的跳跃性、词语的对比、意象对比、意象叠加与减少、比喻的多重含义；再加抒情的节制；问“张力体现在哪些方面”就按这五点答，别把古典的“动中有静”当成现代诗的张力。"], ["比喻要读出第三种暗示意义", "雄鹰、雪豹象征力量、速度、自由、英雄、王者，蜘蛛象征弱小、卑微、平凡；表面含义是诗人的自嘲，暗示意义是：能坚守高度的不是强大而是弱小；古典比喻是从本体到喻体的线性描述，现代诗的比喻还要读出内在的暗示意义，别只停在“蜘蛛像攀登者一样弱小”这一层。"]], "vgaokao": []}}, "u_chn_3": {"id": "u_chn_3", "name": "小说两篇", "secs": "第3课", "pageFrom": 12, "pageTo": 28, "members": ["chn_c004", "chn_c005"], "video": {"bvid": "BV1JB4y1G7kF", "p": 4, "t": "小说两篇（百合花/哦，香雪）", "dur": "26:14", "from": "名师课堂", "vtop": ["《百合花》以小见大：不写大战场面，只写借被子、缝破洞、献被子三个生活片段，表现纯洁深厚的军民之情和战友之情。", "衣服上的破洞四次出现是全篇最重要的细节：34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞，串联情节、刻画人物、升华主题。", "百合花被子是象征：百合花清丽、纯洁、淡雅，既是新媳妇也是小通讯员高尚纯洁心灵的象征，军民之情和战友之情都像百合花一样纯洁美好。"], "vsum": "先说清楚一点：这节 P4 的视频只讲了第一篇《百合花》，第二篇《哦，香雪》这节课里一个字都没讲到——按选片登记，《哦，香雪》在合集的 P5，另有讲解。下面是这节课实际讲的内容，全部是《百合花》。\n\n开场先说战争在大家印象里是什么样：不是双方对垒的刀光剑影，就是战后的断壁残垣。但有的作家能抛开战争的血泪，从别样的角度凸显生命的美好，《百合花》就是这样一部作品。\n\n先介绍作者**茹志娟**，当代著名女作家，创作以短篇小说见长，笔调**清新俊逸**，情节单纯明了，细节丰富传神，善于从较小的角度反映时代本质。1950年起陆续在报刊发表短篇小说和特写，后来出版了《高高的白杨树》《静静的产院》《百合花》等短篇集。文学评论家**茅盾**称赞说，《百合花》风格清新俊逸，是一篇**结构谨严、没有闲笔**的短篇小说，同时又富于抒情诗的风味，是他最近读过的几十篇小说中最使他满意、最使他感动的一篇。\n\n再看写作背景：小说里的人物和事件并非来自真人真事，但描写的战斗以及战斗的时间、地点是真实的。1946年中秋节，战斗打响，茹志娟在前线包扎所做战勤工作，第一个工作就是去借被子；战斗开始后，她负责记录牺牲战士的姓名、单位，在这个过程中不禁设想他们的家庭亲友、生前的愿望、心中的秘密，当时的情景和想法她一直没有忘记。\n\n常见的战争题材作品有两种类型：一种以塑造人物形象为主，通过战争事件、战役过程和战斗场面的描写，着重刻画人物的思想性格；另一种以反映战争事件为主，通过人物和故事情节的描写，形象地阐释某一重大军事行动、军事思想、军事原则和战略战术。而《百合花》**另辟蹊径**，描写战争状态下的生活片段，格外让人心动。\n\n还要先弄清小说这种文体：小说以**塑造人物形象为中心**，通过故事情节的叙述和环境的描写，反映社会与个人生活。一篇优秀的小说往往必须具备三个要素：**生动的人物形象**、**完整的故事情节**和**人物活动的具体环境**，其中人物形象又是主要因素。\n\n进入文章，先梳理情节。主要人物有三个：小说中的“我”、**小通讯员**、**新媳妇**。情节分四段：**开端**是第1段到第23段，通讯员送我去前沿包扎所；**发展**是第24段到第43段，我和通讯员到百姓家借被子；**高潮**是第44段到第57段，新媳妇为通讯员缝衣服；**结局**是第58段到第59段，新媳妇把百合花被子献出来、盖在通讯员的遗体上。\n\n本篇小说最重要的手法是**细节描写**。细节是指人物、景物、事件等表现对象富有特色的细小环节，细节描写只抓住生活中的细微而又具体的典型情节，加以生动细致的描绘，具体渗透在对人物、景物或场面的描写之中。课文里最典型的是通讯员衣服上的破洞，先后写了四次：第34段，借被子出门，衣服挂在门钩上，肩膀处撕下一片布，“口子撕得不小”；第43段，通讯员回部队，人已走远，还看见肩上撕挂下来的布片在风里一飘一飘；第53段，通讯员牺牲后，军装的肩头上露着那个大洞，一片布还挂在那里；第56段，新媳妇拿着针，“细细地，密密地缝着那个破洞”。四次破洞的作用要从三个角度答：结构上，第一次做铺垫、照应后文缝破洞，第二次承上启下、为后文埋下伏笔，第三次把情节推向高潮、印证牺牲，第四次照应前文、与在新媳妇家划破衣服相映衬；人物上，写出通讯员的朴实、腼腆、执拗和新媳妇的友善、热情，也写出通讯员的天真质朴和回部队时的乐观；主题上，体现**军民鱼水情**，使革命情义得到升华。\n\n小说塑造人物主要运用了哪些描写手法、表现了人物什么性格特征，要分人物记。写“我”，主要运用**心理描写**、**语言描写**、**动作描写**：比如我打趣通讯员“人家走路都没出一滴汗”，“为了我跟他说话，却害他出了这一头大汗”，“这都怪我了”，写出我的幽默、爱开玩笑；面对伤员，“我不能解除他们任何痛苦”，只能带着妇女们给伤员擦洗、喂饭，写出我的细心与无奈。写小通讯员，主要运用**细节描写**、**动作描写**、**神态描写**、**语言描写**：枪筒里稀疏地插了几根树枝，表现他对生活的热爱；借了被子“却高低不肯，撂下被子就走”，表现他的执拗；“他飞红了脸，更加扭怩起来，两只手不停地数摸着皮腰带上的扣眼”，表现他的腼腆；听到要把被子送回去，“他突然站住脚，呆了一会儿说：那，那我们送回去吧”，表现他的憨厚朴实；临走摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说：给你开饭了，说完就脚不点地地走了”，表现他关爱同志。写新媳妇，主要运用**肖像描写**、**动作描写**、**神态描写**：“这媳妇长得很好看，高高的鼻梁，弯弯的眉，而且一头蓬松松的刘海”，凸显其美丽；“好像在掂量我刚才那些话的分量”，转身进去抱被子了，体现其善良和对小战士朴素浓烈的阶级感情；“那媳妇一面笑着，一面赶忙找针拿线，要给他缝上”，表现其友善热情；“依然拿着针，细细地，密密地缝着那个破洞”，“低下头还是一针一针地缝”，表现出品德高尚、勇敢坚强。\n\n除了三位主要人物，小说还刻画了**担架员**的形象，用的手法是**侧面描写**。文章结尾第53到54段，担架员把通讯员抬上门板，还围在床边不肯走；这时通讯员叫大家快趴下，自己一下子扑在了那个东西上。通过担架员的语言，侧面烘托出通讯员英勇无畏的英雄壮举，显出其革命精神的伟大。\n\n把人物刻画的方法总结一下：**正面描写**又称直接描写，指描写人物的语言、行动、肖像、神态、心理来表现人物性格特征，包括概括介绍、肖像描写、神态描写、语言描写、动作描写、细节描写、心理描写；**侧面描写**又称间接描写，即通过其他人物的言行间接写主人公。\n\n再看本文的语言和手法。《百合花》的语言，不论叙述、描写还是对话，都给人一种自然、**清新**、柔和优美的感觉，把一个流血牺牲的战斗故事写得充满诗意，特别是人物语言个性鲜明、生动传神。赏析句子要会抓点：比如“我眼前出现了一片绿雾似的竹海中间，一条窄窄的石级山道，盘旋而上，一个肩膀宽宽的小伙，肩上垫了一块老蓝布，扛了几只青竹，竹梢长长地拖在他后面，挂打着石级哗哗作响”——这句既有环境描写，又有人物的细节描写，既有蓝绿之色，又有哗哗之音，**视听结合**，描绘出竹海中小通讯员劳作的场景。再比如我和小通讯员的对话：“你多大了？”“十九。”“参加革命几年了？”“一年。”“你怎么参加革命的？”“大军北撤时，我自己跟来的。”这段话介绍了通讯员的出身、年龄，又揭示了他舍己救人的阶级基础和思想基础，表现了他的思想觉悟和自觉的革命要求。\n\n本文还突出使用**对比手法**，有两处必会：一是能射出杀人子弹的枪筒里，插着象征自然与和平的树枝与野菊花，这本身就是一个鲜明的对比，让我们在无言中感受**战争与和平的剧烈冲突**——战争是残酷的，但生活是美好的，战争中不可避免会有流血，但在小通讯员身上却能看到生活的一抹亮色；二是通讯员牺牲后，新媳妇与医生、我的态度不同：借被子时的腼腆与局促、临走时的狼狈模样还记忆犹新，舍己救人的英勇无畏又挽在眼前，新媳妇的情感由原先的疼爱变为当下的痛惜，医生和我还能够用理性的眼光去看待小通讯员的死亡，但新媳妇不能——她劈手夺下被子，一针一线，密密地缝着破洞，这是情感与理智的鲜明对比，是**情感对死亡的战胜**。\n\n再看行文构思。小说情节的叙述方式主要有五种：**顺序**，按时间、空间顺序来写，情节发展脉络分明、层次清晰；**倒叙**，不按时间先后顺序，而是把某些发生在后的情节或结局先行提出，然后再按顺序叙述下去，造成悬念、引人入胜；**插叙**，在叙述主要事件的过程中，插入另一与之有关的事件，然后再接上原来的事件写，对主要情节或中心事件做必要补充说明，使情节更加完整、结构更加严密、内容更加充实丰满；**补叙**，在叙述主要事件的过程中插入另一与之有关的事件，然后再接上原来的事件写，对上文内容加以补充解释，对下文做某些交代，照应上下文；**平叙**，只叙述两件或多件同时发生的事，使头绪清楚、照应得体。《百合花》全文以时间为顺序，以**“我”的所见所闻为线索**展开情节，以“我”为视点娓娓动听地叙述故事、栩栩如生地描绘人物，并从“我”的感情变化中逐步完成人物性格的塑造，使故事显得更为真实。\n\n最后看文章的主题，也就是百合花被子的象征意义。大自然中的百合花具备**清丽、纯洁、淡雅**的特点，小说中的白色百合最为常见，其花语为纯洁、清新，对应着文中的军民鱼水情。与百合花被子相关的情节主要有两处：第一处在第26段到第41段，通讯员和我去借被子，在我的帮助下，从新媳妇家借来了百合花被子；第二处在第58段到第59段，新媳妇把被子盖在通讯员的遗体上。这两处情节在结构上推动小说情节的发展，使得结构严谨；为刻画人物性格服务，照应人性之美，暗示人物心灵的纯洁与精神的高尚，表现出革命军民鱼水情。再说百合花和新媳妇之间的关系：新媳妇娴静、淳朴、善良、纯真，具有如百合花一样美丽的**人性美**，所以百合花正是人物纯真、美好心灵的象征。而百合花不仅仅是新媳妇心灵和性格的象征，也象征着小通讯员高贵的品格。百合花作为文章情感的载体，象征着人物的高贵品格，不仅仅是两位主人公，从小说中的“我”到文章中的担架员、医生、卫生员、通讯干部、村中妇女等等，处处表现出人民群众对革命的理解与支持。题目“百合花”本身也有讲究：百合花色泽文雅、香气清幽、白净纯洁，题目用的手法是**借代**，借印有百合花的被子来指代；更重要的是，作者赋予了它丰富的象征意义——小通讯员和新媳妇都有百合花一样高尚纯洁美好的心灵，军民之间的感情也像百合花一样纯洁、高尚、美好，战士和战士之间的情感也像百合花一样纯洁、高尚、美好。一句话，百合花象征着**人性美**、**性格美**，百合花是一首青春赞歌。\n\n课的最后总结选材特点：作者没有直接描绘战争场面，而是通过生活场景切入战争时代；作者通过连姓名都没有的三个人物之间的关系，谱写了一曲“**没有爱情的爱情牧歌**”——在通讯员和“我”之间，作者让我对通讯员建立起一种比同志、同乡更为亲切的感情；维系在通讯员和新媳妇之间的关系纽带，同样也是一种圣洁美好的感情，正如被子的百合花图案一样纯洁。这是一种青春的气息，一份革命的情意。常见的战争题材文章都是描绘战争场景，但本文选材上却从小处着眼、**以小见大**，表现主题：小说选取了革命战争时期人民斗争生活中的一朵小小的浪花，刻画了有着和百合花一样纯洁高尚、美好心灵的小通讯员和新媳妇形象，表现了纯洁深厚的**军民之情**和**战友之情**，传达了高尚的人情美和人性美。\n\n课后的反馈与评价也值得过一遍：小说主要刻画了小通讯员和新媳妇这两个人物形象，运用了细节描写、语言描写、肖像描写、神态描写和动作描写，分别表现了小通讯员热爱生活、执拗、腼腆、朴实、关爱同志的性格特点，和新媳妇美丽、善良、友善、热情、品德高尚、勇敢坚强的性格特点。练习题里有四道：一是字音字形，根据拼音写汉字：破毡帽、扭怩、踌躇、幼稚；二是刻画人物手法，“我”劝新媳妇不要缝了，她却瞟了我一眼，“还是一针一针地缝”，点拨要从新媳妇对通讯员的崇敬和愧疚上考虑——新媳妇是在缝进她的一片深情，瞟我一眼，是对我不理解她的内心表示不满；三是动作描写，“劈手”一词表现了新媳妇怎样的态度——先理解词的意思，再放在语境中考虑：劈手写出了新媳妇用自己的新被子为通讯员入殓时的果断、坚毅、不容商量的态度；四是细节描写，小说中两次写到馒头，第42段通讯员摸出两个馒头，“朝我扬了扬，顺手放在路边石头上，说，给你开饭了”，第57段通讯员牺牲后，我无意中摸到身边两个干硬的馒头——结构上前后照应，第一次为后文通讯员牺牲时身上带着干硬的馒头埋下伏笔，第二次照应前文；人物上突出了通讯员关爱同志的性格特点，烘托了他高尚的人格情操和与我深厚的革命情谊；主题上突出了我当时内心的伤痛和不舍，使文章的悲剧性更加突出，使读者产生强烈的共鸣，突出通讯员的献身精神。课后作业有三项：复习刻画人物的手法，了解手法的作用；体悟《百合花》中感人至深的青春情怀和人性之美；新媳妇将自己的新被子盖在牺牲的通讯员身上时没有说话，揣摩其心理，写一段话，写出此时她的心理所想。", "vtech": [["细节描写：破洞四次，作用分三层", "课文先后四次写通讯员衣服上的破洞（34段挂破、43段布片飘、53段牺牲后露大洞、56段新媳妇缝破洞）。考试要从结构、人物、主题三方面答：结构上铺垫、照应、承上启下、推向高潮；人物上写出通讯员的朴实腼腆执拗和新媳妇的友善热情；主题上升华军民鱼水情。只答“刻画人物”不完整。"], ["正面描写 vs 侧面描写", "正面（直接）描写：语言、行动、肖像、神态、心理、细节，如写新媳妇的肖像、写通讯员的神态。侧面（间接）描写：通过其他人物的言行间接写主人公，如担架员的语言侧面烘托通讯员英勇无畏。看到“通过别人写主人公”就认侧面描写，别写成正面。"], ["对比手法两处必会", "一是枪筒里插树枝野菊花，对比能射出杀人子弹的枪筒——战争与和平的剧烈冲突，战争残酷但生活美好；二是通讯员牺牲后新媳妇“劈手夺下被子、一针一线密密地缝”，对比医生和我的理性克制——情感对死亡的战胜。"], ["叙述顺序与线索", "全文以时间为顺序，以“我”的所见所闻为线索，以“我”为视点叙述。叙述方式有顺序、倒叙、插叙、补叙、平叙五种，别把插叙和补叙混了：插叙是插入另一有关事件再接回原文，对主要情节做必要补充；补叙是对上文补充解释、对下文做交代、照应上下文。"]], "vgaokao": []}}, "u_chn_4": {"id": "u_chn_4", "name": "新闻三篇", "secs": "第4课", "pageFrom": 32, "pageTo": 50, "members": ["chn_c006", "chn_c007"], "video": {"bvid": "BV1JB4y1G7kF", "p": 7, "t": "新闻三篇（喜看稻菽千重浪）", "dur": "27:10", "from": "名师课堂", "vtop": ["人物通讯以人物的新近行动为新闻，重在表现人物的品质、性格和精神面貌，通过个别显示一般、通过平凡突出伟大，达到揭示时代特征、感染教育读者的目的。", "《喜看稻菽千重浪》四部分四个小标题：曾记否，到中流击水（1961年发现天然杂交稻株）／创新是科学家的灵魂和本质／事实是科学家的空气／饥饿的威胁在退却——小标题就是语段的核心内容。", "读人物通讯抓四点：吸引人的故事、打动人的细节、个性化的语言、影响人的思想线；过程线是经历与事件，思想线是作者提炼的中心思想。"], "vsum": "本课讲第二单元“劳动光荣”里的《喜看稻菽千重浪》。先说清楚：这节视频只细讲这一篇人物通讯，单元里另外两篇自读通讯《探界者钟扬》和《心有一团火，温暖众人心》课上只布置了自读填表和细节分析的任务，没有逐篇细讲。\n\n开场先交代篇目：《喜看稻菽千重浪》是沈英甲写的人物通讯，发表在《科技日报》2001年2月22日，写的是首届**国家最高科学技术奖**获得者**袁隆平**。本课的学习目标有三条：一是学会阅读人物通讯，把握报道的立场，提升**媒介素养**；二是学会分析通讯的**报道角度**，理解**事实与观点**的关系；三是深入体会**劳动最光荣、劳动最伟大**的思想，培养创新的意识与勇气，形成正确的劳动观念。老师先引了一句普利策新闻奖作品序言里的话：新闻之所以重要，那就是人——写人、影响人。人物通讯在通讯家族里数量占比比较大，研究并掌握它的写作方法，是时代赋予新闻记者的神圣使命。\n\n先明晰概念：**人物通讯以人物的新近行动为新闻**，重在表现人物的品质、性格和精神面貌，**通过个别显示一般，通过平凡突出伟大**，达到揭示时代特征、感染并且教育读者的目的。人物通讯肩负着反映社会主流价值观和国家宣传导向、传播文化与价值的责任。\n\n接下来从题目入手分析。主标题“喜看稻菽千重浪”出自毛泽东的《七律·到韶山》：“喜看稻菽千重浪，遍地英雄下夕烟”。这首诗回顾韶山人民的革命历史，描绘人民公社社员通过热情劳动喜获丰收，赞扬革命人民艰苦卓绝的战斗精神。作者借用诗句为袁隆平作记：一个“喜”字，写出了袁隆平通过不断探索、收获良田稻香的喜悦；“稻”指的是**天然杂交水稻**，“千重浪”营造了开阔意境，既有风吹稻浪的滚滚金黄，又有一望无际的辽阔千里，也让人联想起袁隆平在田间地头育种耕耘的汗水。题目精准生动、富有诗意。副标题“首届国家最高科学技术奖获得者袁隆平”明确交代了人物通讯的写作对象，补充说明主标题的内容。\n\n正文一共分为四个部分，分别由四个小标题引领：**“曾记否，到中流击水”“创新是科学家的灵魂和本质”“事实是科学家的空气”“饥饿的威胁在退却”**。小标题既是语段的标题，同样也是语段的核心内容，拿到文章要对它们足够重视。\n\n第一部分“曾记否，到中流击水”出自毛泽东《沁园春·长沙》“曾记否，到中流击水，浪遏飞舟”，作者用这样有气魄的句子回顾袁隆平的研究历程。这部分是对过去时间段生活内容的回顾：1961年，31岁的袁隆平发现了**天然杂交稻株**，那份激动与喜悦以及这一发现的重大意义。文章不仅写了杂交水稻研究起始阶段的欣喜、期待、失望、思索及发现，还以中国人“**民以食为天**”的观念以及当年普遍发生的饥饿作为社会背景，写了青年袁隆平作为科学工作者要用农业科技战胜饥饿的使命感和责任心，凸显他在研究过程中表现出的**敏于发现、勇于探索**的科学素养。结构上，以“袁隆平的发现注定要成为世界农业上的经典事例”收束，强调这一发现的重大意义，也揭示科研探索过程的艰辛，并引起下文——袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战。\n\n第二部分“创新是科学家的灵魂和本质”揭示这部分内容的主旨：主要写袁隆平面对水稻杂种优势利用这道世界性难题所表现出的敢于挑战的勇气和信心，突出他作为科学家**勇于创新**的精神品格。值得注意的是，这部分里作者写道，袁隆平“从而拉开了我国水稻杂种优势利用的序幕，开创了水稻研究的新纪元”，对袁隆平的成果给予了高度评价；并通过写袁隆平对“中国有中国的有利条件”的分析，显示了他对祖国的热爱以及对制度、道路和文化的自信。\n\n第三部分“事实是科学家的空气”开头先以典型细节写袁隆平对中国亿万农民的深厚感情及为农民造福的追求；在此基础上写他针对不顾农民利益、无视事实驳斥杂交水稻的观点，以平和的语气、无可辩驳的事实以及具体的数据进行回复，充分否定了不实观点，以事实捍卫了科学的尊严。这部分不仅强调了袁隆平作为科学家**实事求是**的态度和捍卫真理的科学精神，还写出了他在论辩中表现的平和个性。\n\n第四部分“饥饿的威胁在退却”开头以袁隆平谈他的梦这个典型细节写起，引出袁隆平对杂交水稻育种的**战略设想**，表现他不断进取的精神以及培育**超级杂交稻**、让杂交稻走向世界的远大目标。在这部分里，作者不仅写出了袁隆平的成就，还强调了两点：一是袁隆平不仅对“谁来养活中国”的疑问做出了有说服力的回答，而且使饥饿的威胁在退却，引导我们走向一个营养充足的世界；二是作为有世界影响力的中国科学家，袁隆平正在引导一场**新的绿色革命**。\n\n纵观全文的时间线：1961年发现天然杂交稻株、确定研究方向，到1964年发现**天然雄性不育株**、开创研究新纪元，从1982年针对否定三系法的观点发表文章、用事实捍卫真理，到1986年提出杂交水稻育种战略设想并付诸实践。从袁隆平身上可以看到的精神品质有：**重视实践、探索规律、勇于挑战、坚持创新、捍卫真理、实事求是、勇于担当、造福民众**。更看到一个坚守了60年的信念，看到了起点的坚定、当下的坚持与未来的期许。\n\n把握了文章写了什么，接下来要透过文本挖掘人物通讯怎么写。采写人物通讯是为了通过人的思想、人的精神面貌去教育人、感染人：光写事迹不写思想，人物是平面的；写了思想，人才有了灵魂、生命，才能有感染他人的力量。人物通讯的写作媒介是真切的实践活动，但隐含在活动背后的，是作者借助各种技巧将思想融入写作，赋予人物立体鲜活的生命力。具体有四点写法。\n\n第一，**抓住吸引人的故事**。人物通讯如何做到故事化？首先要正确选取能够表现人物特点的故事情节，其次要设法增强故事或情节的跌宕起伏、悬念吸引力。但人物通讯故事化有一条底线：**人物故事必须是真实的，不能艺术化**，否则就失去了新闻的真实性，人物通讯就变成小说了。作者笔下的袁隆平故事，叙述并不繁复冗杂，而是抓住典型时间节点的典型特征加以重点描绘：只写袁隆平作为国家最高科学技术奖获得者这一身份，写出杂交水稻之父与杂交水稻的交集部分，重点突出、画面集中、条理清晰，让读者跟随作者的视野、袁隆平的脚步，感受杂交水稻培育之路的坎坷与辛劳。\n\n第二，**打造动人的细节**。细节常被称作**新闻的细胞、通讯的血肉**，是人物生活中最真实、最具特色的精华部分，是新闻的活力所在。形象、真实、可信地表现人物，就是要让细节说话。文章里的三个典型细节句值得细品。其一，“袁隆平眯起双眼，出神地打量着这几百亩大的实验田，然后跨过水渠，迈步走进田间，他蹲下身子，翻看着土壤”——抓住“眯起”“出神地打量”等一系列动词，生动准确地写出袁隆平面对实验田的专注、仔细；借助“跨过、迈步走近、蹲下、翻看”这一串熟练的动作描写，更凸显他是一个真正的实践派科学家，所有科学研究都是自己深入田间地头亲自完成，流畅熟练、毫不马虎，埋头苦干的质朴品质展露无遗。其二，“泥腿子专家，泥腿子院士”——作者以自己跟在袁隆平身后走下稻田时产生的瞬间错觉，写出袁隆平给人的巨大反差的两个印象：杰出的科学家与地道的湖南农民；“挽起裤腿走下稻田，是人们从播种到收获季节见到的袁隆平最标准的形象”一句作答：袁隆平绝对是专家，也是名副其实的院士，但更是土地的儿子、百姓爱戴的国家栋梁。“泥腿子”**一语双关**，既是袁隆平扎根泥土、耕耘土地的写照，也是他专注农业的最好象征。其三，“突然，他那敏锐的目光停留在了一兜形态特异、鹤立鸡群的水稻植株上，他屏住呼吸，伸出双手，欣喜地抚摸着那可爱的稻穗，激动得几乎要喊出声来”——神态与动作描写传神地表现了袁隆平发现杂交水稻植株时的专业、小心翼翼与爱不释手；“几乎”这个程度副词写出了他激动与喜悦的程度，涌动欲出、理性克制。其四，“他头顶烈日，脚踩淤泥，弯腰驼背，去寻找这种天然雄性不育株，已经第十四天了”——“头顶烈日、脚踩淤泥、弯腰驼背”三个四字词语叠加却不用标点隔开，朗读时缩短词语之间的停顿，显现出一种一气呵成的阅读状态，让人感受到袁隆平寻找时的忘我精神、不顾一切、无法阻挡；时间词“十四天”和“马上”“终于”这些典型副词，处处透露寻找的艰难、得到的惊喜、成功的来之不易。\n\n第三，**体现个性化的语言**。语言使人物更生动。人物语言要合乎所写人物的年龄、身份、职业等，要逼真、口语化，还要合乎人物所处的特定环境、特定时期、特定心情和说话对象，做到恰如其分、恰到好处、贴切自然、生动传神。文章第四部分捕捉了袁隆平的语言：“袁隆平是一位世界级的伟大科学家，同时也是一个凡人，当然要做梦。他高兴地回答，他曾经梦见水稻长得像高粱那么高，稻穗像扫帚那么大。”作为凡人，袁隆平也会做梦；作为世界级的伟大科学家，他的梦和他所热爱的事业息息相关。这段语言描写生动形象，夸张比喻的运用突出了袁隆平对粮食丰收的最大期许：杂交稻又高又大，还能真正解决更多人的饥饿问题，让饥饿逐渐退却——如此悲天悯人的情怀、如此造福百姓的社会担当，借助袁隆平的语言传递着动人的力量。这就是他的**“禾下乘凉梦”**。\n\n第四，**抓住影响人的思想线**。人物通讯有两条线：一条是**过程线**，一条是**思想线**。过程线是人物生活的经历或事件发展的过程，是事物的表面现象；思想线则是作者根据人物事迹所提炼出的中心思想，贯穿于人物的典型事迹中，反映事物的本质意义。找思想线要看议论句。第一部分里有这样的句子：“袁隆平对真理的发现，使他不可避免地要向国际知名的权威和他们的权威结论发起挑战”，从中可以读出袁隆平的坚韧个性与不屈品质，感受到一个伟大的科学家不惧困难的勇气和敢于攀登的执着。第二部分里：“他根据自己的实践，以科学家的胆识和眼光断定，杂交水稻研究具有光辉的前景，他决心义无反顾地坚持研究”——作者直接把科学家的胆识和眼光写出来，和后文“义无反顾的坚持”形成呼应。还有一句议论：“在理论与事实发生矛盾时，袁隆平的态度是尊重权威，但不崇拜权威，不能跟在权威后面亦步亦趋，不敢越雷池一步，他不迷信权威的每一个观点”——这里作者直接提出观点：袁隆平对权威的尊重和对真理的坚持。这与后文的句子也形成呼应：“**科学家是真理的使者，是事实的追随者**。袁隆平坚信实践能发现事实、发现真理，并能验证真理。所有的科学家都将真理奉为圭臬，他们总是将事实真相作为自己不断探寻的目标，在发现事实、发现真理、验证真理中推动人类的不断发展与进步。”因此，总有一些时候，袁隆平作为伟大的科学家站了出来：凡是涉及不顾农民利益、无视事实的事，他都能挺身而出、毫不含糊地阐明事实；至于是不是要担风险，袁隆平在所不惜。就这样，袁隆平捍卫了事实，也捍卫了真理。最后，作者引述的内容更加值得深思：美国学者唐·帕尔伯格在《走向丰衣足食的世界》一书中写道，袁隆平使饥饿的威胁在退却，正引导我们走向一个营养充足的世界；袁隆平是世界上最有影响的中国科学家之一，他正在引导一场新的绿色革命。这是世界对袁隆平的高度评价，也反映出他不仅仅是中国的“泥腿子院士”，更是为世界发展做出卓越贡献的中国科学家。**科学没有国界，大爱无疆**。\n\n课的最后回顾阅读人物通讯的方法：一要抓住吸引人的故事，二要抓住打动人的细节，三要抓住个性化的语言，四要抓住影响人的思想线。学以致用：请同学们仿照本课对细节内容的筛选过程，自读《探界者钟扬》并填写表格——表格有时代身份、典型事件、精神品质三个填写角度：钟扬的第一个时代身份是英雄少年，典型事件是考入中科大少年班、对植物学产生浓厚兴趣、旁听五大课程、做好植物学知识储备，精神品质是雷厉风行、追求梦想、敢想敢做；第二个时代身份是种子达人，典型事件是在西藏收集种子、努力建设来自世界各地的种子宝库、采集种子获得的快乐惊喜与存在的风险，精神品质是执着追求、献身科学；第三个时代身份是科学队长，典型事件是热心科普工作，精神品质是胸怀人类、不辞辛劳；第四个时代身份是接棒导师，典型事件是接过转导师的学生、为学生量身规划、鼓励少数民族地区学生报考自己的研究生，精神品质是热爱教育、关爱学生；第五个时代身份是生命延续先锋，典型事件是研究长寿基因、超负荷工作，精神品质是敢为人先、不懈奉献。再仿照本课对细节内容的分析理解，自读《心有一团火，温暖众人心》，找出表现张秉贵全心全意为人民服务精神品质的细节并加以分析：文章运用语言、神态和心理描写，表现张秉贵面对无端发火的女顾客，不是以冷对冷，而是以热对冷、变冷为热；他站在顾客的立场、为顾客着想，用优质服务、耐心和善带给顾客温暖和慰藉，展现的是对为人民服务宗旨的完全彻底，是一个服务工作者的责任心，是一个平凡劳动者伟大的精神世界。\n\n课后作业有两项：一是阅读第27届中国新闻奖一等奖作品《折翼海天》，通过分析典型事件和细节描写把握人物精神；二是观赏第29届中国新闻奖一等奖获奖作品《见证》，理解事实与观点的关系、把握报道的立场。课堂上还朗读了一段德国媒体的报道：2020年9月7日，袁隆平迎来自己的90岁生日，德国电视一台网站报道称，中国的一位科学英雄迎来自己的90岁生日，他的伟大功绩是培育出了比普通水稻更高产的新水稻品种；袁隆平让中国人从几十年前开始就能吃饱肚子、不必再忍饥挨饿；无论过去还是现在，让全世界的人都吃饱饭是这位科学家的伟大目标，在中国这一目标已基本实现；如今杂交水稻种植面积占全国水稻种植总面积的50%以上；袁隆平和他的团队自上世纪60年代以来一直在培育能大幅提升产量的特殊水稻品种；上世纪我们的研究目标是培育高产水稻，如今随着人民生活水平的显著提高，目标不仅是高产，还要注重高质量；袁隆平领导的研究中心近年来致力于培育耐盐碱杂交水稻品种；90岁的袁隆平说自己仍在参与工作，没有固定的工作时间，想工作时就去办公室，不工作的时候待在家里看电视或打排球、有时也出去旅游，但即便不在全天工作，每天也要去看看自己的水稻。课程最后用一段对袁隆平的颁奖词收束：袁隆平，毕生梦想消除饥饿，他是一位真正的耕耘者；当他还是一个乡村教师的时候，已经具有颠覆世界权威的胆识；当他名满天下的时候，却仍然只是专注于田畴，淡泊名利；一介农夫，播洒智慧，收获富足；他毕生的梦想，就是让所有的人远离饥饿。喜看稻菽千重浪，最是风流袁隆平。", "vtech": [["小标题就是语段的核心", "拿到文章先看小标题：四个小标题对应四个部分——1961年发现天然杂交稻株、敢于创新挑战权威、用事实捍卫真理、袁隆平的梦与超级杂交稻战略设想；答结构题先列小标题，再按时间线展开。"], ["细节描写三处必考点", "“眯起双眼、出神地打量、跨过、蹲下、翻看”一串动词写袁隆平专注田间、埋头苦干的实践派本色；“泥腿子”一语双关，既是扎根泥土的写照，也是专注农业的象征；“头顶烈日、脚踩淤泥、弯腰驼背”连用四字词、不加标点，一气呵成写出寻找雄性不育株十四天的执着。"], ["人物通讯的两条线", "过程线是人物生活的经历或事件发展的过程（表面现象），思想线是作者根据人物事迹提炼的中心思想（本质意义）；找思想线看议论句，如“向国际知名的权威发起挑战”“尊重权威但不崇拜权威”“科学家是真理的使者”。"], ["故事化的底线是真实", "人物通讯要抓住吸引人的故事、增强情节的跌宕与悬念，但故事必须是真实的，不能艺术化，否则就失去了新闻的真实性，人物通讯就变成小说了。"]], "vgaokao": []}}, "u_chn_5": {"id": "u_chn_5", "name": "以工匠精神雕琢时代品质", "secs": "第5课", "pageFrom": 51, "pageTo": 52, "members": ["chn_c008"], "video": {"bvid": "BV1JB4y1G7kF", "p": 8, "t": "以工匠精神雕琢时代品质", "dur": "26:47", "from": "名师课堂", "vtop": ["工匠精神的内涵是四句话：炉火纯青的技术、专心如一的热爱、臻于至善的追求、不改初衷的境界——出自第四自然段，顺序别记乱。", "新闻评论由论点、论据、论证三要素组成，特点是政策性、针对性、准确性；主要表现方法是夹叙夹议、以理以情。", "四种论证方法要会认：引证法、对比论证、类比论证、假设论证——“倘若没有……怎能有……”就是假设论证。"], "vsum": "本课学第一单元第5课《以工匠精神雕琢时代品质》，是一篇新闻评论，作者李斌。开场先引习近平同志的话：要弘扬工匠精神，精心打磨每一个零部件，生产优质的产品。只有打造更多精品、塑造更多中国品牌，中国经济才能进入质量效益时代，中国制造业才能在做大做强中跻身世界前列。接着老师抛出三个问题：什么是工匠精神？自动化程度越来越高的现代社会，传统社会孕育的工匠精神还有没有坚守的必要？如果有，我们应该怎样践行？这三个问题关乎如何认识劳动的意义和价值，带着问题学完全文。\n\n先补知识点。**新闻评论**是媒体编辑部或作者对新近发生的有价值的新闻事件和有普遍意义的紧迫问题，运用分析和综合的方法，就事论理、就实论虚，有着鲜明针对性和指导性的一种新闻文体，是社论、评论、评论员文章、短评、编者按、专栏评论和评述等的总称，属于论说文的范畴。简单说，新闻评论就是对有价值的新闻事实和社会现象发表意见、以指导实践的文体。新闻评论由**论点、论据、论证**三个要素组成，特点是政策性、针对性、准确性；要求立意新颖，在有限的篇幅里靠独特的见解吸引读者；论述精当、文采斐然；主要面向广大群众。它的主要表现方法是**夹叙夹议**——对一件事发表看法，既要写事又要写看法；**以理以情**——在理性评判和分析时，又动之以情。写作的基本思路分四步：引述材料摆出现象，从现象中提取论述的观点，分析论证观点、联系实际、紧紧围绕论点运用各种论证方法论证，总结全文、提出倡议。\n\n再看写作背景。现代科技时代，工匠似乎已经远离我们，但实现中华民族伟大复兴的中国梦，不仅需要大批科学技术专家，同时也需要千千万万的能工巧匠。更重要的是，工匠精神作为一种优秀的职业道德文化，它的传承和发展契合了时代发展的需要，具有重要的时代价值与广泛的社会意义。2017年的政府工作报告提出，大力弘扬工匠精神，厚植工匠文化，恪尽职业操守，崇尚精益求精，完善激励机制，培育众多中国工匠，打造更多享誉世界的中国品牌，推动中国经济发展进入质量时代。我国是技能人才大国，也是制造业大国，制造业在国民经济中的地位和作用举足轻重，当前正处在从工业大国向工业强国迈进的关键时期，培育和弘扬严谨认真、精益求精、追求完美的工匠精神，对于建设制造强国具有重要意义。作者李斌，女，汉族，1954年10月出生，辽宁抚顺人，1981年6月入党，1974年7月参加工作，研究生学历，经济学博士，研究员。\n\n整体阅读先读一则材料：故宫“男神”王津。故宫博物院的钟表收藏居世界首位，现存1500多件钟表，除了产自本国，还有来自英国、法国、瑞士等国的珍品，不仅报时准确、造型精美，而且融绘画、雕塑、工艺、天文、音乐、机械、科技于一体，代表着18至20世纪初世界钟表制造精湛技艺的最高成就。钟表修复技术是故宫里唯一绵延下来、没有断层的**非物质文化遗产**，已传承了三百多年。王津是国家级非物质文化遗产“古钟表修复技艺”第三代传承人，41年待在一间仅60平方米的工作室里，日复一日、年复一年干同一件事。要真正喜爱才能耐得住寂寞，因为喜欢就能干一辈子。自央视纪录片《我在故宫修文物》热播后，镜头中工作专注、执着内敛、气质儒雅的王津被网友封为“故宫男神”，也让文物修复师这个冷门职业广为人知。宫廷钟表都是特制的，一般只生产一个或一对，大多是孤品，没有配件可换，修复必须遵循不改变文物原状的原则，技艺必须由师父手把手教徒弟、口传身授，再通过修复每一件文物钟表遇到的不同类型问题，不断学习和积累方法与经验，代代传承。一件待修的钟表运来，先拍照记录，制定修复方案，再拆解、清洗、补配、组装、调试，直至运转正常，最后进库保存。从1981年上手修复第一件钟算起，经王津修复成功的故宫钟表已超过200座，故宫钟表馆中陈列的120多件钟表中，约三分之一都是他修复的。而每让一只故宫古钟表转动，都要花费几个月甚至一年的功夫。与其他文物修缮不同，钟表修复的独特之处在于不仅要恢复走时功能，更重要的是恢复表演功能才叫修好了。令王津印象最深刻、修复得最满意的文物，是一件铜镀金魔术人钟，钟内部有超过一千个零部件、七套系统、五套机械联动，被故宫认为世界上最难修复的钟表之一，王津与团队耗时一年多集中修理，才最终将其表演功能重现于世，此钟后来远赴荷兰展出半年，让世界为之惊艳。读完材料再想：像王津师傅一样，工匠精神要有一流的技术，更要有一颗热爱的心、一种耐得住寂寞的境界。\n\n课文是怎样高屋建瓴地概括工匠精神内涵的呢？重点读第四自然段：**工匠精神**的内涵是**炉火纯青的技术**、**专心如一的热爱**、**臻于至善的追求**、**不改初衷的境界**。工匠精神蕴藏的既有格物致知、正心诚意的生命哲学，又有超然达观的人生信念。细读两句重要的话：第一句“将一门技术掌握到炉火纯青、绝技在身，但工匠精神的内涵远不限于此”——意思是工匠精神首先要掌握一门炉火纯青的技术，这已经不是一件容易的事，但是只有技术还不够，还要有技术之外的精神品质。第二句“我们不必人人成为工匠，却可以人人成为工匠精神的践行者”——意思是并非人人都能做到心思巧妙、技术精湛、造诣高深，但我们都应该追求并实践工匠精神，体现了作者对工匠精神的推崇和倡导。\n\n再读文本理清思路。中心话题是工匠精神的时代特征，开篇从时代特点和企业打造金字招牌的角度引出话题，紧扣时代品质，具有很强的现实性。文章分三部分：第一部分是第一自然段，提出工匠精神的话题；第二部分是第二至四自然段，论述工匠精神的内涵，其中第二自然段论述“匠”的时代内涵及工匠精神对个人、企业和国家的作用与意义；第三部分是第五自然段，从个人与时代的关系角度总结全文。\n\n论证方法有四种。一是**引证法**：文中多处引用，如引用企业家的话写出工匠精神在当代的意义，引用《说文解字》里对“匠”的记载写出“匠”古已有之、然后写出其演变，引用鲁迅的话在此基础上再深入论证，从不同角度分析论述，使文章更有说服力、观点更加深入人心。二是**对比论证**：如“工匠精神从来都不是什么雕虫小技，而是一种改变世界的现实力量”，边破边立，写出了工匠精神的作用。三是**类比论证**：如第一段“像手工匠人一样雕琢记忆、打造产品，企业才有金字招牌，产品才能经受住用户最挑剔眼光的检验”，将手工匠人和企业进行类比，写出了企业拥有工匠精神的重要性。四是**假设论证**：如第四段中“倘若没有发自肺腑、专心如一的热爱，怎能有废寝忘食、尽心竭力的付出；没有臻于至善、超今贯古的追求，怎能有出类拔萃、巧夺天工的卓越；没有冰心一片、不改初衷的境界，怎能有雷打不动、脚踏实地的笃行”，假设论证写出了工匠精神的内涵。\n\n语言特色是**整散结合**、生动形象、富有说服力。文章是时评，却没有枯燥说教的感觉，生动形象、绚丽多彩，主要是因为语言生动、整散结合。第一段用了“高精尖”等具有时代特点的新词，使人们容易接受和理解；第二段用“气质雍容、活力涌流”来写企业，使企业拥有了人的特点，生动地写出了拥有工匠精神对企业的意义；第三、四、五段运用排比句式，起到增强气势、调节音律的作用，增强了读者的阅读兴趣，使观点更加鲜明突出、更具有说服力。此外，本文运用大量成语，言简意赅，掷地有声。\n\n拓展延伸：类似王津师傅这样体现工匠精神的事例还有哪些？一是高凤林，为火箭焊接心脏的人。焊接技术千变万化，为火箭发动机焊接更不是一般人能胜任的。三十多年来，高凤林先后参与北斗导航、嫦娥探月、载人航天等国家重点工程，以及长征五号新一代运载火箭的研制工作，一次次攻克发动机喷管焊接技术世界级难关，出色完成亚洲最大的全箭振动试验塔的焊接攻关，修复苏制图-154飞机发动机，还被丁肇中教授钦点，成功解决反物质探测器项目难题。他吃饭时拿筷子、喝水时端着盛满水的杯子练稳定性，休息时举着铁块练耐力，冒着高温观察铁水的流动规律，为了保障一次大型科学实验的顺利完成，他的双手至今还留有被严重烫伤的疤痕；为了攻克国家某重点攻关项目，近半年的时间，他天天趴在冰冷的产品上，关节麻木了，他甚至被戏称为“和产品结婚的人”。二是顾秋亮，深海“蛟龙”守护者。“蛟龙”号载人潜水器是目前世界上潜水最深的载人潜水器，其研制难度不亚于航天工程，在这个高精尖的重大技术攻关中，有一个普通钳工技师的身影，他就是顾秋亮，中国船舶重工集团公司第七〇二研究所水下工程研究开发部职工，“蛟龙”号载人潜水器首席装配钳工技师。作为首席装配钳工技师，工作中面对技术难题是常有的事，而每次顾秋亮都能见招拆招，靠的就是工作40余年来养成的螺丝钉精神。他爱琢磨、善钻研，喜欢啃工作中的硬骨头，凡是交给他的活，他总是绞尽脑汁，想着如何改进安装方法和工具、提高安装精度、确保高质量地完成安装任务，正是凭着这股爱钻研的劲儿，顾秋亮练就了较强的创新和解决技术难题的技能，出色完成了各项高技术、高难度、高水平的工程安装调试任务。三是宁允展，高铁上的“中国精度”。宁允展是南车青岛四方机车车辆股份有限公司车辆钳工高级技师、高铁首席研磨师，国内第一位从事高铁转向架定位销研磨的工人，也是这道工序最高技能水平的代表，他研磨的定位销已经创造了连续十年无次品的纪录。转向架是高速动车组九大关键技术之一，转向架上有个定位销是关键中的关键，高速动车组在运行时速达200多公里的情况下，定位销和轮对节点必须有75%以上的接触面、间隙小于0.05毫米，否则会直接影响行车安全。宁允展的工作就是确保这个间隙小于0.05毫米，他的风动砂轮纯手工研磨操作法将研磨效率提高了一倍多，接触面的贴合率也从原来的75%提高到了90%以上，他发明的精加工表面缺陷焊修方法，修复精度最高可达到0.01毫米，相当于一根细头发丝的五分之一。他执着于创新研究，主持了多项课题攻关，发明了多种工装，其中有两项通过专利审查、获得了国家专利，每年为公司节约创效近三百万元。四是张东伟，80后造船工匠。张东伟是个80后，但手里的活儿却让老师傅们竖起大拇指。LNG船是国际上公认的高技术、高难度、高附加值的“三高”船舶，作为LNG船核心的维护系统，焊接是重中之重，维护系统使用的殷瓦钢大部分为0.7毫米厚，殷瓦钢焊接犹如在钢板上绣花，对操作人员的技术、耐心和责任心要求非常高。面对肩上的重担，张东伟不断磨练自己的心性、培养专注度、潜心研究焊接工艺，为了攻破技术难关，他与技术人员放弃休息时间、日夜埋头图纸堆中、潜心钻研技术，最终他主持的实验取得成功，得到专利方的认可并用于LNG船实船生产，收到良好成效。张东伟是中国广大造船工匠的杰出代表，他用自己火红的青春，谱写了一曲执着于国家海洋装备建设的奉献之歌。\n\n最后回到我们自己：我们也拥有火红的青春，应该如何践行工匠精神呢？首先要努力学习文化知识，知识是工匠精神的力量源泉，“问渠那得清如许，为有源头活水来”。其次要有严谨的态度，态度决定一切，在我们的学习和生活中起着举足轻重的作用，一个人只有用严谨的态度对待一切学习活动，才能以严格的标准要求自己、深刻地理解和牢固地掌握各类文化知识，才能认认真真、一丝不苟地做好日常生活中的每一件事，为成功打下基础。再次要学会持之以恒，“事业千古事，非一朝一夕之功”，学习或者工作，要像工匠求艺那样，一定要耐得住寂寞、稳得住心神、经得住诱惑，要有滚石上山的勇气和气魄，少一些急功近利，多一些真抓实干，一步一步推进，一点一点积累，实现量变到质变的跨越，那么即使铺满荆棘的道路也会变得平坦。\n\n总结全文：从本质上讲，工匠精神是一种职业精神，它是职业道德、职业能力、职业品质的体现，是从业者的一种职业价值取向和行为表现。在新的时代，弘扬和践行工匠精神，需深入把握其基本内涵、当代价值与培育途径。工匠精神是时代的呼唤，也是社会主义核心价值观题中应有之义，培育工匠精神、弘扬工匠精神，这绝不仅限于物质生产，还需要全社会各行各业驱除浮躁，培育和弘扬精益求精、一丝不苟、追求卓越、爱岗敬业的品格，从而提供高品质产品和高水准服务。课后作业有两个：一是结合本单元人物通讯篇目，基于其呈现的事实，任选一篇、自选角度进行评论，写一篇三百字左右的小评论；二是思考中学生如何践行工匠精神，将所思写成一篇五百字左右的作文。结尾寄语：同学们，我们已经踏上实现中华民族伟大复兴的征程，要让蓝图变现实、让梦想成真，需要一砖一瓦的接力，需要每时每刻的努力，无论在哪个岗位上，我们都要做一名专注的工匠，让我们只争朝夕、不负韶华，为梦想而战，让人生绽放光彩。", "vtech": [["新闻评论的定义一句话", "对有价值的新闻事实和社会现象发表意见、以指导实践的论说文；看到“就事论理、就实论虚”就想到新闻评论，别和一般议论文搞混。"], ["工匠精神内涵四句话按顺序记", "炉火纯青的技术→专心如一的热爱→臻于至善的追求→不改初衷的境界；技术、热爱、追求、境界层层递进，第四自然段原话。"], ["四种论证方法看标志词", "引证法看引用（企业家的话、《说文解字》、鲁迅的话）；对比论证看“不是……而是……”；类比论证看“像……一样”；假设论证看“倘若没有……怎能有……”。"], ["写作思路四步", "引述材料摆现象→从现象中提取观点→分析论证联系实际→总结全文提出倡议；问“本文写作思路”就按这四步答。"]], "vgaokao": []}}, "u_chn_6": {"id": "u_chn_6", "name": "诗经两首", "secs": "第6课", "pageFrom": 53, "pageTo": 54, "members": ["chn_c009"], "video": {"bvid": "BV1JB4y1G7kF", "p": 9, "t": "诗经两首（芣苢/插秧歌）", "dur": "26:15", "from": "名师课堂", "vtop": ["《芣苢》六个动词分三组：采、有是概略叙述；掇、捋是具体描写（一颗颗、一把把）；袺、襭是用衣襟兜取——动词变化写出芣苢越采越多，劳动过程层层推进。", "《芣苢》重章叠句：三章十二句，除六个动词外其余诗句不断重复，产生简单明快、往复回环的音乐节奏，契合采摘劳动轻快的动作节拍。", "《插秧歌》“唤”与“不答”：有人唤农人吃早饭歇一歇，农人低头折腰只不答——看似答非所问，实则传神：秧根未牢、田未插完，庄稼才是农家人的命根；鉴赏要捕捉这种刹那间的意趣之美。"], "vsum": "本课是必修上册第二单元第6课，讲两首写古代劳动的诗：《诗经》里的《芣苢》和南宋杨万里的《插秧歌》。单元主题是劳动，前面几课讲的是新时代的劳动者和工匠精神，这节课走进古代人民的劳动场景，感受劳动的美好与欢乐，体会劳动的崇高与美丽。\n\n先回顾《诗经》的文学常识：《诗经》是我国第一部诗歌总集，共收录从西周初年到春秋中叶的诗歌305篇，先秦时称《诗》或《诗三百》，汉代被尊为经典，称《诗经》并沿用至今。形式上以四言为主，多数隔句用韵，章法上讲究重章叠句、反复咏唱。内容上分风、雅、颂三部分：风是各诸侯国的土风歌谣，大多是民歌，又分十五国风；雅是西周王畿地区的正声雅乐，分小雅（用于贵族宴享）和大雅（用于诸侯朝会）；颂是统治阶级宗庙祭祀的舞曲歌词，分周颂、鲁颂、商颂。艺术手法主要是赋、比、兴：赋是直接铺陈叙述，比是比喻，兴是先言他物以引出所咏之物。\n\n第一首是《芣苢》，出自《诗经·周南》。《芣苢》就是车前草。全诗三章十二句：“采采芣苢，薄言采之。采采芣苢，薄言有之……”先跟老师准确诵读全诗，把握节奏。注释要记牢：“薄言”是发语词，没有实在意义；“采”就是采摘，“有”是取得、获得，“掇”是一颗颗地摘取，“捋”是从茎上成把地取下，“袺”是提起衣襟兜东西，“襭”是把衣襟掖在腰带上兜东西。六个动词可以分三组：采、有是概略叙述采集劳动；掇、捋是对摘取动作的具体描写，一颗颗、一把把，写得真切生动；袺、襭是对用衣襟兜取的描写。动词的变化写出了劳动的实际操作过程，芣苢越采越多，把劳动细节细腻地描绘出来，展现了一幅三五成群的田家妇女在平原旷野、风和日丽中边唱边采的集体劳动场景。\n\n清代姚际恒在《诗经通论》里说，《芣苢》三章，每章四句，每二句只换一字——全诗只有六个动词不断变化，其余诗句不断重复。这种重章叠句的写法在不断重叠中产生了简单明快、往复回环的音乐节奏，正好契合采摘芣苢劳动的轻快动作节拍，表现出歌声中的喜悦之情。文化知识补充：采集芣苢是古老的习俗，按《毛传》的说法，芣苢就是车前草，相传吃了芣苢能受胎生子、解难产，所以周南女子怀着繁衍种族、祈求神灵赐福的愿望，三五成群愉快地劳作——她们摘着芣苢、唱着芣苢，心里荡漾着虔诚与激情。这首产生于自然与生命的乐章，是有着浓厚生活气息的劳动之歌。\n\n第二首是南宋杨万里的《插秧歌》。先认识诗人：杨万里，字廷秀，号诚斋，吉州吉水人，与陆游、尤袤、范成大并称“中兴四大家”，诗作达4200余首，在宋代仅次于陆游。他善于巧妙摄取自然景物的特征和动态，语言平易浅近、自然活泼，善于熔炼俗语、口语入诗，幽默诙谐，形成独具特色的诚斋体。这首《插秧歌》作于淳熙六年（1179年），杨万里由常州卸任返回吉州故里，途经衢州时看到农人插秧的场景，有感而作。\n\n全诗八句：“田夫抛秧田妇接，小儿拔秧大儿插。笠是兜鍪蓑是甲，雨从头上湿到甲。唤取朝餐歇半霎，低头折腰只不答。秧根未牢莳未匝，照管鹅儿与除鸭。”注释记牢：“抛秧”是插秧前把秧苗从秧田拔出、捆成小捆扔进稻田；“兜鍪”是古代战士戴的头盔；“甲”是铠甲；“半霎”是极短的时间；“莳”是移栽种植；“匝”是布满、遍及；“照管”在这里是提防的意思。\n\n逐句赏析：一二句“田夫抛秧田妇接，小儿拔秧大儿插”，从田夫、田妇、小儿、大儿可知插秧是全家总动员，“抛、接、拔、插”四个动词把全家的劳作真切地表现出来，大家各有分工、相互配合、井然有序，一气呵成，渲染出一家人齐心协力、其乐融融的劳动氛围。三四句“笠是兜鍪蓑是甲，雨从头上湿到甲”，把农人的斗笠比作头盔、蓑衣比作铠甲，写出农人如兵士一般在农田中冒雨插秧，有如在天地之中奋勇战斗，说明插秧时节性强，即便下雨农人也不停止劳作；接着笔锋一转，农人虽然带盔披甲，却还是被雨水淋得从头湿到甲，一句通俗浅白，农人的艰辛跃然纸上。五六句“唤取朝餐歇半霎，低头折腰只不答”，有人招呼农人吃早饭、歇一歇，可农人仍然弯腰干活，没有回答；七八句“秧根未牢莳未匝，照管鹅儿与除鸭”给出答案：秧苗刚种下去还不牢，这块田还没插完秧，还要看管好饲养的鹅和鸭，提防它们来捣乱。最后两句看似答非所问，实则传神地反映了农事生产的劳身和劳心。诗人用“唤”和“不答”描写农家夫妇的对话和对话时的情态，为我们开辟了一条鉴赏文学作品的路径：捕捉刹那间的意趣之美——“唤”与“不答”之间存在逻辑上的悖论，在文学审美上却是美的；吃饭不重要，庄稼才是农家人的命根，这种认知是我们民族所共有的。\n\n两首诗还要放在一起比较。先比较唐代李绅的《悯农》和杨万里的《插秧歌》：同样写古代农人的劳动生活，侧重点不同——李绅“锄禾日当午，汗滴禾下土”，描绘劳动的辛苦，对劳动人民充满同情；杨万里侧重表现劳动人民的紧张繁忙、齐心协力、勤劳，抱着欣赏的态度客观表现劳动场面，流露出诗人对劳动和劳动者的赞美。再比较《芣苢》和《插秧歌》本身：都是描写古代劳动场景、关注普通劳动者，但表现形式和描写角度不同——《芣苢》句式整齐、节奏明朗轻快，以一系列动词的变换和重章叠句的写法，自然流露出劳动的喜悦；《插秧歌》运用民歌手法，选取日常劳动场景，善用口语，显白流畅，富于生活情趣，字里行间洋溢着吃苦耐劳、勤奋乐观的精神。劳动者特写也不同：《芣苢》塑造的是先秦时期采摘芣苢的劳动妇女，特写采集、收取、收成的动作，描绘三五成群妇女集体劳动的场景，表现出劳动者喜悦的心情；《插秧歌》塑造的是南宋时期参加插秧的一家四口，特写抛、接、拔、插的具体动作，描绘呼唤农人吃早饭的插曲，传神地表现农事生产的劳身和劳心，表现农人吃苦耐劳、勤劳乐观的优秀品质。\n\n课堂反馈三道题：第一题考《芣苢》的赏析，不恰当的一项是B项——“采采”的叠唱有着采集野菜的急促感，这种表述不正确，应该是音乐美感；重章叠句产生的是简单明快、往复回环的音乐节奏，切合采摘劳动轻快的动作节拍。第二题考《插秧歌》的逐句评析：一二句写热火朝天的劳动场面，抛、接、拔、插四个动词准确具体，又暗示分工明确；三四句点明雨中抢插的情形，以盔甲防护之人，雨水仍然从头上流入、沾湿肩膀，领会春雨之密、之急、之大；五六句写劳作的忘我程度，家人送饭让歇一会儿却无人答话，连抬头看一眼的功夫也没有，写出抢插的紧张程度；七八句运用口语化的语言，随意写取天赋的肢体动作和对答语言，写出全家其乐融融的画面，使读者有身临其境之感。第三题考《诗经·秦风·无衣》中重章叠句的表达效果：全诗三章，采用重章叠唱的形式，每章句数、字数相等，但结构的相同并不意味着简单的机械重复，而是在不断递进中有所发展——每章首二句以豪迈的语气表现奋起从军、慷慨相助的精神，“同袍、同泽、同裳”深重地表现出大敌当前战友们克服困难、团结互助的精神；每章的三四句写他们一听到君王要发兵的命令，便急忙修整武器、磨砺兵刃、整装待发，“修我戈矛、修我矛戟、修我甲兵”正反映出摩拳擦掌、积极奋战的高昂战斗热情；每章的末句“同仇、偕作、偕行”写共同的仇恨与共同奋起奔赴战场，表现出团结一心、同仇敌忾、誓死保卫疆土的义愤。这种重章叠句的形式与舞蹈的节奏起落、回环往复紧密结合，构成诗中主旋律的是一股战斗的激情，激情的起伏跌宕自然形成乐曲的节奏与舞蹈动作。\n\n课后作业：阅读北宋苏辙的《文氏外孙入村收麦》，选择恰当的角度，比较《芣苢》《插秧歌》《文氏外孙入村收麦》三首诗的异同。本课学习的古诗都是描写劳动的，从中可以感受到劳动的欢乐与情趣，要自觉地在实践中感悟劳动之美，自觉继承和发扬中华民族尊重劳动、热爱劳动的美德。", "vtech": [["《芣苢》六个动词分三组", "采、有是概略叙述采集劳动；掇、捋是对摘取动作的具体描写（一颗颗、一把把）；袺、襭是对用衣襟兜取的描写；动词变化体现劳动实际操作过程，芣苢越采越多。"], ["重章叠句的表达效果", "三章十二句，除动词外其余诗句不断重复，在重叠中产生简单明快、往复回环的音乐节奏，契合劳动轻快的动作节拍；《秦风·无衣》同理，三章递进：首二句同袍/同泽/同裳写团结互助，三四句修我戈矛/矛戟/甲兵写整装待发，末句同仇/偕作/偕行写同仇敌忾。"], ["《插秧歌》的动词与比喻", "抛、接、拔、插四个动词写全家总动员、各有分工；笠是兜鍪、蓑是甲，把农人穿戴比作兵士的头盔铠甲，写出雨中抢插的紧张与奋勇；雨从头上湿到甲，通俗浅白，农人的艰辛跃然纸上。"], ["两首诗对比：同情与赞美", "李绅《悯农》锄禾日当午、汗滴禾下土，侧重写劳动的辛苦，对劳动者充满同情；杨万里《插秧歌》侧重写劳动的紧张繁忙、齐心协力，抱欣赏态度，赞美劳动和劳动者；《芣苢》句式整齐、重章叠句显音乐美，《插秧歌》善用口语、民歌手法显自然新鲜的意趣。"]], "vgaokao": []}}, "u_chn_7": {"id": "u_chn_7", "name": "短歌行·归园田居", "secs": "第7课", "pageFrom": 58, "pageTo": 59, "members": ["chn_c010", "chn_c011"], "video": {"bvid": "BV1JB4y1G7kF", "p": 11, "t": "短歌行·归园田居", "dur": "25:48", "from": "名师课堂", "vtop": ["诗眼是“忧”，曹操三忧：人生短暂、求贤不得、功业未就——三者相连：有建功立业、一统天下的壮志，才会感到人生短暂，更要抓紧时间延揽天下人才。", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“纵我不往，子宁不嗣音”的省略是含蓄提醒：就算我没去找你们，你们为什么不主动来投奔我呢？", "“周公吐哺，天下归心”：周公洗头、吃饭时贤士来见，握着湿发、吐出口中食物就出来见客——诗人以周公自比，表明像周公一样热切殷勤待贤才、渴望求贤以统一天下。"], "vsum": "本课是必修上册第三单元“生命的诗意”第7课。先说明一点：这个视频只讲《短歌行》一首，同课的陶渊明《归园田居》不在这个视频里，它在合集的下一页 P12，学完这首再去看 P12，不要以为这一课就讲完了。\n\n学诗先讲方法：赏析诗词有一个非常重要的解读方法，叫**知人论世**，最早由孟子提出——“颂其诗，读其书，不知其人，可乎？是以论其世也”。意思是只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容。这节课就用这个方法走进作者、解读全诗。\n\n先认识作者。曹操，字孟德，是三国时期杰出的政治家、军事家、文学家。陈寿在《三国志》里评价他是“**非常之人，超世之杰**”。作为政治家，他外定武功、内兴文学，知人善察、**唯才是举**；作为军事家，他指挥了**官渡之战**，逐步统一了中国北方；作为文学家，他是**建安文学**的开创者和组织者。他的诗歌语言质朴、感情深沉、格调苍凉悲壮，被誉为**建安风骨**（也称魏晋风骨）：建安时期的作品真实反映了现实的动乱和人民的苦难，抒发了建功立业的理想和积极进取的精神，同时流露出人生短暂、壮志难酬的悲凉忧怨，意境宏大，具有鲜明的时代特征和个性特征。他用**乐府古题**写实事，继承了汉乐府“感于哀乐，缘事而发”的现实主义精神。乐府诗有长歌和短歌之分，叶嘉莹教授认为一般根据歌声的长短而定：长歌比较热烈奔放，短歌节奏短促、低回短唱，适合抒发内心的忧愁和苦闷——这首诗作者是否也要抒发内心的忧愁和苦闷呢？带着这个问题往下学。\n\n写作背景有不同的说法，不可轻信其一。《三国演义》第48回写曹操平定北方后率百万雄师与孙权决战，月明之夜在大江之上置酒宴月，酒酣时取槊立于船头慷慨而歌，歌词就是这首《短歌行》；苏轼的《前赤壁赋》也说此诗作于赤壁大战前夕（“方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗”）。但这些都是小说家言和文学家的想象推测，缺乏可信的史料依据，还不能作出准确的结论。毫无疑问的是，曹操把他英雄的气质、诗人的才情和霸主的野心都集中表现在了这首诗中。\n\n全诗可分为**八章，每章四句**。先找**诗眼**：哪个字最能体现全诗的感情？是“**忧**”。“诗言志，歌永言”——曹操为何而忧，又是如何抒发这种情感的呢？\n\n第一二章：对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧？唯有杜康。“对”和“当”都是面对的意思，对酒当歌就是面对着酒与歌，即饮酒听歌。面前有酒有歌，作者情绪激动起来，就会想到这对酒当歌的美好快乐日子能有多少，眼前的快乐更反衬出人生无常的哀叹，于是发出“人生几何”的感叹——让人想起《左传·襄公八年》的“**俟河之清，人寿几何**”：黄河水清象征天下太平，可人寿有限，哪等得到那一天？开头两句就表现了诗人对于生命短促和人生无常的哀叹。“譬如朝露，去日苦多”用**比喻**：人生就像早晨的露水，太阳一出就晒干了。汉乐府《薤露歌》说“薤上露，何易晞。露晞明朝更复落，人死一去何时归”——草叶上的露水干了，明天早晨还会落上新的露水，而人死了以后就再也不会回来了。“朝露”这个意象在古诗文中有特定的含义，就是生命短促。“慨当以慷”：慷慨是形容感情激动的样子，“当以”没有实在意义。接下来的“唯有杜康”：杜康相传是最早造酒的人，这里用**借代**的修辞手法，以杜康代酒。借代能使表达形象生动、重点突出、简洁精炼。中国文人历来与酒有着不解之缘：范仲淹“浊酒一杯家万里”表达思乡之情，王维“劝君更尽一杯酒，西出阳关无故人”表达送别之情，杜甫晚年穷困潦倒却还感叹“艰难苦恨繁霜鬓，潦倒新停浊酒杯”，李白“五花马，千金裘，呼儿将出换美酒，与尔同销万古愁”“抽刀断水水更流，举杯消愁愁更愁”——借杯中酒浇胸中块垒，一直是中国知识分子的精神寄托方式。\n\n第一二章乍读起来似乎情调消沉，其实不然。诗人生逢乱世，目睹百姓颠沛流离，渴望建功立业而未得，不能不产生苦闷和感慨；但这种苦闷和感慨，只有对事业和感情执着的人、只有不满现实而又积极要求改变现实的人才可能产生。所以诗人的苦闷和感慨正是英雄人物的苦闷和感慨，是烈士的一种悲心，自有它的积极意义——全诗蕴含着应及时努力的思想。诗人一方面抒发个人之情，感叹时间过得太快、恐怕来不及有所作为，另一方面也是在巧妙地感染广大贤才：人生就像朝露那样容易消失，岁月已经流逝了很多，应该赶快拿定主意，到他那里施展抱负。这样积极的目的用低沉的调子来发端，固然表明诗人确有他的愁思，说得真切；但也唯有通过这样的调子，才更能打开处于下层、多方艰难、又急于寻找出路的贤才的心扉。\n\n第三四章：青青子衿，悠悠我心。但为君故，沉吟至今。“青青子衿，悠悠我心”语出《诗经·郑风·子衿》，原写姑娘思念情人，这里用来比喻渴望得到贤才。“子”是对对方的尊称，“青衿”指周代读书人青色交领的服装，“悠悠”是长远的样子，形容思虑连绵不断。诗人这里引用《诗经》中的诗句，还说自己一直低低地吟诵它，实在太巧妙了。但更重要的是他所省略的原诗中的两句——“**纵我不往，子宁不嗣音**”：虽然我不能去找你，你为什么不主动给我音信？诗人由于事实上不可能一个一个去找那些贤才，所以用这种含蓄的方法提醒他们：就算我没去找你们，你们为什么不主动来投奔我呢？由这层含而不露的意思可以看出，他求才的用心十分真诚，的确具有感人的力量。“但为君故，沉吟至今”：这里指思念和倾慕贤人。“君”在《诗经》中可能指一个具体的人，而在这里则具有了广泛的意义——在当时凡是读到曹操此诗的贤士，都可以自认为就是曹操渴求的对象，正因为这样，此诗流传开去才会起到巨大的社会作用。紧接着，作者又引用了《诗经·小雅·鹿鸣》中的四句——“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”，描写宾主欢宴的情景：鹿鸣本是周代朝廷宴请宾客的诗，鹿喜欢群居，每当找到了艾蒿，便悠悠地呼唤着同伴相聚而食；这里用来表达招纳贤才的热情，意思是只要你们到我这里来，我一定会待以嘉宾之礼，我们能够欢快融洽地相处并合作。三四两章从表面看，曹操自己的话只有“但为君故，沉吟至今”两句，但他通过用典婉转而清晰地吐露了自己的情意：第三章写他求贤而不得的日夜思慕，第四章写他求贤既得后设宴欢迎的情景，两相对照，表达了**求贤若渴**之情。加上青青之色、悠悠之声，诗中有声有色，顿觉词彩鲜艳、音韵悠扬。\n\n第五六章：明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈讌，心念旧恩。“明明如月，何时可掇”有两种理解：一种把“掇”当作拾取、摘取的意思——诗人奇想天外，明朗的月亮什么时候才能把它摘到手呢？后来李白“欲上青天揽明月”的诗句应由此脱胎；这两句写得非常精彩，除了显示诗人不失赤子之心、想上九天揽月之外，还运用了比喻的修辞手法，将人才比作月亮，把寻求贤士生动地比作无法揽取的明月，是那样的渴望而不可及。另一种解释把“掇”当作同“辍”、停止的意思——皓月当空运转永不停止，而我的求贤之心也不会停止。两种解释都合理，无论是“掇”还是“辍”，这四句都道出了作者深深的忧虑：忧贤才不得。“越陌度阡”：陌、阡都是田间小路，南北叫阡、东西叫陌，这里引用《风俗通》里的古谚；“枉用相存”：枉是屈驾的意思，用是以，相存是问候、探望，合起来是屈驾来访；“契阔谈讌”：契阔是久别重逢，谈讌是谈心宴饮，合起来是久别重逢、欢聚畅谈；“心念旧恩”指往日的情意。当贤才们跨越乡间的小路、长途跋涉，一个个屈尊前来探望作者时，彼此就像久别重逢的好友，谈心宴饮、诉说往日的情谊，诗人又因贤才远道而来归附自己而喜不自胜。五六两章一忧一喜，忽忧忽喜的矛盾心理把求贤过程中的悲喜情状曲折有致地表现出来，充分表现了诗人思贤若渴的主题。五六两章也是对前四章的强调和照应：前四章主要讲了两个意思——忧人生短暂、为求贤而愁，又表示要待贤以礼，这是全诗的两个主旋律；五六两章就是这两个主旋律的复线和变奏，“明明如月，何时可掇，忧从中来，不可断绝”是照应第一二章，“越陌度阡，枉用相存，契阔谈讌，心念旧恩”是照应第三四章。表面看来五六两章与前四章重复，但实际上由于主旋律的复现和变奏，使全诗更有一扬一抑、反复咏叹之致，加强了抒情的意味。\n\n第七八章是全诗的关键，也是艺术感染力最强的地方。先看第七章：月明星稀，乌鹊南飞。绕树三匝，何枝可依？明月皎洁、夜星稀疏，乌鹊向南飞去，围着树木绕来绕去，不知哪个枝干可以依附。这可能就是写眼前的实景。中国古人常说“**良禽择木而栖，良臣择主而事**”：一只好的鸟不会随便栖落在一个污秽肮脏的地方，它一定会选择一棵好的树作为栖息之所；传说中的凤凰更是非梧桐不栖。在这里，作者运用比喻的手法，用乌鹊比喻贤才，用“绕树三匝，何枝可依”比喻贤士们在三国鼎立的局面下无所侍从的情形。诗人启发他们不要三心二意，要善于择木而栖，赶紧到自己这一边来。这四句生动地刻画了那些犹豫彷徨者的处境与心情，然而诗人不仅丝毫没有指责，反而在浓郁的诗意中透露出对这些人的关心和同情。同时，由于汉末大乱、北方人口大量迁移，这首诗除了可能含有诗人在另一首乐府诗《蒿里行》中所表现的征故怀乡之感，也可能含有慨叹人民流离失所的情感。我们不仅能感受到诗人渴求贤才的心情，而且还能够从中感觉到当时社会的氛围。再看结尾：山不厌高，海不厌深。周公吐哺，天下归心。“山不厌高，海不厌深”仿用《管子·形势解》里的话——“海不辞水，故能成其大；山不辞土，故能成其高；明主不厌人，故能成其众”：海从来不拒绝水，所有的水都流到海里，所以海才会这么大；山从来不拒绝土石，所有的土石都可以落在山上，所以山才会那么高；明主从不拒绝归附他的人，所有的人都来投奔他，所以他才拥有很大的力量。诗人用这两句比喻贤才多多益善。下面“周公吐哺”又是一个典故：周公是周武王的弟弟、周成王的叔叔，武王死后成王年幼，周公辅政，平息了武庚的叛乱，并且制作礼乐，使天下大治，被后代称为圣贤的典范；周公的儿子伯禽受封于鲁，周公说他在辅政的时候从来不敢怠慢前来求见的贤士，如果在洗头发的时候有人来见他，他来不及把头发梳好，握着湿头发就出来见客，如果在吃饭的时候有人来见他，他来不及嚼完口中的食物，就把食物吐出来、出去见客，就这样他还唯恐疏漏了国中的贤人。这里借用这个典故表示自己会像周公一样热切殷勤地接待贤才，突出地表现了诗人求贤的心愿。最后四句画龙点睛，明明白白地披肝沥胆，希望人才都来归顺，点明此诗的主题；同时作者以周公自比，表明自己渴望求贤以统一天下的宏图大志。曹操的这种宏图大志值得充分肯定：三国时期军阀割据、战祸连年，生产力遭到了极大的破坏，人民饱尝流离的痛苦、面临死亡的威胁，中原地区尤为严重，曹操的《蒿里行》对此有过真实的写照——“白骨露于野，千里无鸡鸣。生民百遗一，念之断人肠。”那时人心思定，要求尽快结束纷争的局面，是大势所趋、势在必行，曹操正是顺应时代的潮流，肩负起完成统一大业的英雄。\n\n学完这首诗，总结一下：曹操为何而忧？他所忧的是**人生短暂、求贤不得、功业未就**。这三者之间有何内在的联系呢？正因为诗人有建功立业、一统天下的壮志，所以才会想到人生短暂，更应当抓紧时间延揽天下人才，及早尽快建功立业。这首诗的艺术特色主要有两点：一是**运用典故**、合理引用和化用，例如“青青子衿，悠悠我心”是引用《诗经》的诗句，将女子对情人的相思之情变成了诗人对贤才的思慕；“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”也是引用《诗经》的诗句，意在表达诗人期待贤者的热忱；再如“周公吐哺，天下归心”，化用《史记·鲁周公世家》中周公的事迹，诗人以周公自比，表达求贤建业的雄心。用典的好处在于能用极精简的语言表达丰富的思想，可以丰富诗歌的内容、强化诗歌的内涵。二是**妙用比喻**：用朝露比喻人生的短暂，用“明明如月，何时可掇”将贤才比作高空的明月、渴望而不可及，又用“月明星稀，乌鹊南飞。绕树三匝，何枝可依”中乌鸦难以择枝的情景比喻贤才无所依托，还用“山不厌高，海不厌深”比喻贤才越多越好。最后是反馈与评价三道题：第一题，“青青子衿，悠悠我心”表达了作者对贤才的思慕；第二题，“山不厌高，海不厌深”表现了作者渴望多招纳贤才；第三题，课堂讨论清人吴淇“纯是一片求才意思”的评价——你同意“求才”一说吗？老师认为可以同意：这首诗是曹操诗歌中具有代表性的杰出之作，全诗通过对时光易逝、贤才难得的再三咏叹，抒发了自己求贤若渴的感情，表现出统一天下的雄心壮志和自强不息的进取精神。", "vtech": [["知人论世：读诗先读人", "孟子提出的方法：颂其诗、读其书，不知其人可乎？是以论其世也——只有了解作者的生活思想和写作的时代背景，才能客观准确地把握作品的思想内容；本课就用这个方法走进曹操、解读全诗。"], ["用典：化用《诗经》与周公典故", "“青青子衿，悠悠我心”化用《诗经·郑风·子衿》，把女子对情人的相思变成对贤才的思慕；“呦呦鹿鸣，食野之苹”化用《诗经·小雅·鹿鸣》，写宾主欢宴、待贤以礼；“周公吐哺，天下归心”化用《史记·鲁周公世家》，以周公自比。用典能用极精简的语言表达丰富的思想、丰富诗歌内容、强化诗歌内涵。"], ["比喻：朝露、明月、乌鹊、山海", "“譬如朝露”比喻人生短暂；“明明如月，何时可掇”把贤才比作高空的明月，寻求贤士比作无法揽取的明月；“月明星稀，乌鹊南飞。绕树三匝，何枝可依”比喻贤才无所依托、犹豫彷徨；“山不厌高，海不厌深”比喻贤才多多益善。"], ["借代与“忧”的三重结构", "“唯有杜康”以杜康代酒，是借代；全诗两个主旋律是忧人生短暂、为求贤而愁，第五六章是主旋律的复现与变奏，“明明如月”照应第一二章，“越陌度阡”照应第三四章，一扬一抑、反复咏叹。"]], "vgaokao": []}}, "u_chn_8": {"id": "u_chn_8", "name": "李杜白三篇", "secs": "第8课", "pageFrom": 60, "pageTo": 64, "members": ["chn_c012", "chn_c013", "chn_c014"], "video": {"bvid": "BV1JB4y1G7kF", "p": 13, "t": "李杜白三篇", "dur": "25:23", "from": "名师课堂", "vtop": ["“梦游”是贯穿全诗的主线：梦前（海客谈瀛洲至对此欲倒东南倾）、梦中（我欲因之梦吴越至仙之人兮列如麻）、梦后（忽魂悸以魄动至篇末），做题先按三段切分再找手法。", "全诗主旨落在结尾“安能摧眉折腰事权贵，使我不得开心颜”：追求个性解放、蔑视权贵，前面所有瑰丽梦境都是为这一句铺垫。", "浪漫主义两大招：神奇的想象（民间传说、神话、梦境）加 大胆的夸张（天姥之高、仙人盛会），夸张总与具体事物结合、自然不露痕迹。"], "vsum": "本课只讲《梦游天姥吟留别》一篇。《登高》《琵琶行》不在本视频内，在合集 P14（cid 818559059），后续补。开场先定李白的地位：诗仙，继屈原之后又一位伟大的浪漫主义诗人，杜甫说他的诗是“笔落惊风雨，诗成泣鬼神”。本课三个目标：一是**知人论世**，把握诗歌内涵、理解李白的精神境界；二是诵读涵咏，品味诗中神奇瑰丽的诗境、认识李白豪迈飘逸的诗风；三是体察李白对社会与人生的思考。先**解题**：“吟”本指吟咏、作诗，后来成为乐府歌行体的一种诗体名称；“留别”是临行前留下这首诗向朋友话别；全题的意思就是用梦游天姥的诗向朋友话别，别名《梦游天姥山别东鲁诸公》。旧诗分古体和近体，唐人把新出现的格律诗叫近体诗，把唐以前较少格律限制的叫古体诗，《梦游天姥吟留别》是古体诗。接着落实读音和特殊句式，圈出天姥、瀛洲、渌水、澹澹、霹雳等易读错的字。再把握全诗脉络：**“梦游”是贯穿全诗的主线**，开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，从“忽魂悸以魄动”到篇末是梦后。本诗最突出的特点是浪漫主义的艺术特色，即神奇的想象和大胆的夸张：想象有来源于民间传说的（如仙境的种种细节），也有出于诗人个性爱好的（如“湖月照我影，送我至剡溪”，跟“举杯邀明月，对影成三人”一样，是把月看成最亲密的朋友）；夸张不是简单的放大，而是融合着诗人的感情，如开头写天姥山横空出世的雄姿，里面就含着诗人对天姥山的景仰和向往。**写作背景**：李白字太白，号青莲居士，一生最重要的活动在开元盛世，怀着济苍生、安社稷的政治理想，希望有一番作为。天宝二年因朋友吴筠推荐被唐玄宗召入长安，做了翰林供奉，这时他已 42 岁。本想借此施展才能，却只得了一个侍从闲职，没有被重用，又因一身傲骨不肯与权贵同流合污、得罪了权贵，在长安仅住了一年多就被赐金放还，政治上的失败使他心情苦闷，也让他看清了封建统治者的荒淫腐朽。被排挤出长安的第二年，即天宝四年，李白准备由东鲁南游吴越，行前写了这首向朋友表明自己心志的诗。李白诗歌的浪漫主义手法有三点：一是善于凭借想象，以主观现客观，现实事物、自然景观、神话传说、历史典故、梦中幻境无不成为想象的媒介，常借助想象超越时空，把现实与梦境、自然界与人类社会交织一体；二是把**拟人与比喻**巧妙结合，以情寓物、将物比人；三是抓住事物某一特点，在生活真实的基础上大胆想象夸张，夸张得自然不露痕迹、大胆又真实可信，有时还把夸张与鲜明对比结合，通过加大艺术反差加强效果。李白最擅长的体裁是七言歌行和绝句，七言歌行大开大合、跳跃跌宕，开头常突兀如狂飙骤起，中间形象转换疏忽、往往省略过渡照应，结尾都在感情高潮处戛然而止。**整体阅读**：抓住梦游主线，先读梦前。诗人借“海客谈瀛洲”衬托天姥山，瀛洲是海上仙山，写它也是为天姥山拢上一层神秘浪漫的色彩；接着着力写天姥山的高大，用的是夸张和对比。明朝王思任说天姥不过一小山峰，诗人竟写得如此气势巍峨——其实真正的天姥山并不高大，李白是用夸张、对比等手法描绘自己心中的天姥山，所谓“**一切景语皆情语**”，诗人的浪漫笔墨正是源自豪放胸襟。梦中分三幅画面：**月夜渡湖、著屐登山、仙人盛会**。诗人“一夜飞度镜湖月，湖月照我影，送我至剡溪”，渡过镜湖在月的映照下来到剡溪；“谢公宿处今尚在，渌水荡漾清猿啼”，相传南朝谢灵运到浙江永嘉任太守，喜遨游山水，伐木取径开辟了通往天姥的古道；诗人“脚著谢公屐，身登青云梯”，立在前人开拓的古道上展开想象。登山所见：“半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝”，所闻：“熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟”——连深林、层巅都能栗、能惊，烟、水、青云都满含幽郁，与诗人的情感融成一体。忽然“列缺霹雳，丘峦崩摧。洞天石扉，訇然中开”，梦境推向高潮：“青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。虎鼓瑟兮鸾回车，仙之人兮列如麻。”金台银台与日月交相辉映，仙人列队迎接诗人，这是全诗写景最辉煌灿烂的一段，也是人世间生活的反映：里面既有长期漫游经历过的万壑千山的印象、古代传说和屈原诗歌的启发，也有长安宫廷生活的记忆，全靠浪漫主义的非凡想象凝聚在一起。**梦后**只有七句：“忽魂悸以魄动，恍惊起而长嗟。惟觉时之枕席，失向来之烟霞。”梦已尽而思无穷，结尾落在“**安能摧眉折腰事权贵，使我不得开心颜**”——这才是全诗的主旨：诗人追求个性解放、蔑视权贵。老师提醒两点：一是“吟”多有悲愁慨叹之意；二是解读作品要了解作家的思想，李白既怀有儒家兼善天下的抱负，也有道家逍遥自在的情怀，表面看这是一首游仙诗，主体是神仙世界的描写，但他向往这个世界正是因为厌恶眼前黑暗的现实世界。全诗特点有二：一是构思上富有浪漫主义色彩，突破了一般送别诗惜别伤离的老套，借留别表明自己蔑视权贵的政治态度，围绕一场由先的梦幻来构思，直到最后才落到蔑视权贵的主旨上，给幻想的驰骋开拓了广阔领域；二是句法上以七言为基调，交错运用四言、五言、六言、九言的句子，灵活多样却浑然一体，因为全诗有一条感情发展的脉络贯穿，诗句随感情起落而有长有短、节拍有急有缓。课堂小结引王思任的话：天姥攀缘入李白之梦，李白一做梦便吟诗，一吟诗就使得天姥山与天台山不分伯仲——李白写的是梦游，是用浪漫的艺术抒发对理想人生的热烈追求。课后作业：充满感情地诵读梦后部分，其中“安能摧眉折腰事权贵，使我不得开心颜”连读三遍；专题延伸推荐阅读《品中国文人·李白》。", "vtech": [["梦游三段怎么切", "先找梦的边界：开头到“对此欲倒东南倾”是梦前，“我欲因之梦吴越”到“仙之人兮列如麻”是梦中，“忽魂悸以魄动”起是梦后；结构题、思路题先报三段再展开，别从头平铺直叙。"], ["夸张题的答法：先还原再说效果", "天姥山其实并不高大，李白用夸张、对比写心中之山；答题先说“诗人用夸张写……”，再说突出了什么、表达了什么感情，缺了还原那一步就只剩套话。"], ["“安能摧眉折腰”为什么是主旨", "结尾两句是全诗唯一的直接表态，前面梦境越瑰丽、反衬现实越黑暗；问主旨、问情感就落在这两句上，答“追求个性解放、蔑视权贵”，再回扣梦境铺垫。"], ["古体诗的句式怎么答", "本诗以七言为基调，交错四言、五言、六言、九言，长短句随感情起落而变化；考句式就答“句式灵活多变、浑然一体”，别只说“七言古诗”四个字。"]], "vgaokao": []}}, "u_chn_9": {"id": "u_chn_9", "name": "宋词三首", "secs": "第9课", "pageFrom": 65, "pageTo": 68, "members": ["chn_c015", "chn_c016", "chn_c017"], "video": {"bvid": "BV1JB4y1G7kF", "p": 15, "t": "宋词三首", "dur": "57:12", "from": "名师课堂", "vtop": ["念奴娇的豪放有三点：描绘壮丽之景（大江东去、乱石穿空、惊涛拍岸、卷起千堆雪，夸张加比喻）、刻画豪迈之人（周瑜羽扇纶巾、谈笑间樯橹灰飞烟灭，儒将风度）、表现壮志难酬又能自我解脱的放达（故国神游、多情应笑我、人生如梦、一尊还酹江月）。", "永遇乐全靠典故推进：孙权（千古江山、英雄无觅）、刘裕（斜阳草树、气吞万里如虎）、刘义隆（元嘉草草、封狼居胥、赢得仓皇北顾）、拓跋焘（佛狸祠下、一片神鸦社鼓）、廉颇（凭谁问、廉颇老矣、尚能饭否），每个典故先讲史实再讲用意，考典故题就按这个顺序答。", "两首词都是怀古抒怀，但词风不同：苏词潇洒疏朗、旷达超脱，不平之意最后能参悟平复；辛词多用典故、充满奋勇抗敌的热情与报国无门的悲哀，慷慨悲壮。"], "vsum": "本课由两段视频拼成：前 26 分钟是名师课堂讲《念奴娇·赤壁怀古》和《永遇乐·京口北固亭怀古》，后 31 分钟是语文老师倪文韬逐句精讲《声声慢》。三首词全讲到了，没有缺口。开场先定本课三个目标：一是鉴赏《念奴娇》雄浑壮阔的意境、分析周瑜形象、体会词人壮志难酬的情感、了解豪放风格；二是掌握《永遇乐》中典故的含义及作用、赏析其豪放风格；三是对比分析两首词，体会思想情感和艺术手法的异同。先讲《念奴娇》。**苏轼生平**：字子瞻，号东坡居士，眉州眉山人，北宋著名文学家、唐宋八大家之一。嘉祐二年进士，宋神宗时在杭州、密州、徐州、湖州等地任职，元丰三年因乌台诗案被贬为黄州团练副使；宋哲宗即位后任礼部郎中、翰林学士等职，又出知杭州、颍州、扬州、定州等地；晚年因新党执政被贬惠州、儋州，宋徽宗时获大赦北还、途中病逝常州。《念奴娇·赤壁怀古》写于宋神宗元丰五年七月，正是苏轼被贬黄州期间，抱负遭遇重挫、人身行动受限、内心极度彷徨苦闷，试图通过踏寻古迹、咏怀古人实现精神突围。**豪放特征**从四个方面赏析。写景句“乱石穿空”三句是现场写景：写山石用“穿”，写浪涛用“拍”，写出景物的动态美，表现山之奇峭高峻、水之汹涌澎湃；“卷起千堆雪”以雪比喻波涛，“千堆”是数量上的夸张，更写出波涛的气势；几种物象作用于视觉、听觉，视听结合，呈现出一个有声有色、富有动感、豪放壮阔的画面。人物塑造：“羽扇纶巾”写周瑜手持羽扇、头戴纶巾，通过描写人物典型装束塑造他的儒将形象；“谈笑间”写他指挥若定、从容不迫的大将风度；“樯橹灰飞烟灭”写强大的敌人在周瑜面前不堪一击，既写出辉煌战功，也写出潇洒风度、沉着性格。塑造人物还用了**衬托**：正衬如用“千古风流人物”“一时多少豪杰”陪衬周郎，反衬如以雄姿英发的周郎反衬早生华发的词人自我。周瑜 24 岁为将，人称周郎，性情温厚、精通音乐，34 岁与 28 岁的诸葛亮统帅孙刘联军，在赤壁大战中用火攻把 54 岁的曹操打得一败涂地，这样的人物在苏轼眼中当然值得向往。情感部分：上片写景开篇，感慨“江山如画，一时多少豪杰”，表现对时光流逝的感慨；下片“遥想公瑾当年，小乔初嫁了，雄姿英发”是咏史，写风流人物、战功卓越，表达对英雄豪杰的仰慕赞颂；结尾“故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月”转入抒怀：“故国神游”即神游故国，“多情应笑我”即应笑我多情，都是倒装；想到周瑜 34 岁便建立惊天动地的功业，而自己却贬谪在此、头发早白，相形之下无限感慨；头发变白是由于多情、不能忘情于世事，而这种自作多情仔细想来又可笑，于是“人生如梦”，不如借酒浇愁——“酹”是把酒倒在地上表示祭奠，这里却指对月敬酒，如李白月下独酌“举杯邀明月”之意，所邀乃江中月影，在地不在天。内容上这首词表现了作者用世与避世、入世与出世思想之间的矛盾，这是封建社会知识分子的普遍矛盾：没有机会为国为民做出一番事业，就只有在无可奈何的心情下寻求解脱。**豪放特征总结三点**：一是描绘壮丽之景，“大江东去”“乱石穿空”“卷起千堆雪”运用夸张、比喻，呈现广阔景致、宏大气魄；二是刻画豪迈之人，肯定周瑜在赤壁之战中的关键作用，赞颂其才华功勋，塑造指挥若定、从容不迫的儒将形象；三是表现词人壮志难酬又能自我解脱的放达，生不逢时、空有一腔抱负，壮志难酬不如在江月下举杯逍遥，在失落中找到了解脱。最后回顾念奴娇写景、咏史、抒情如何融为一体：先写山之奇峭、水之汹涌澎湃，联想江山如画、一时多少豪杰，为后文咏史刻画周瑜、续写赤壁之战场景做铺垫，同时表现对时光流逝的感慨；下片咏史抒情，回想周瑜指挥赤壁之战的场景，表达仰慕赞颂，再由周瑜想到自身，抒发壮志难酬之叹，同时寻求内心解脱。再讲《永遇乐》。**辛弃疾生平**：字幼安，号稼轩，历城人，南宋词人，出生时中原已为金兵所占，21 岁参加抗金义军，与党怀英齐名北方、号称“辛党”，青年时参与耿京起义、擒杀叛徒张安国回归南宋，献《美芹十论》等，历任江西、湖北、湖南转运使、安抚使等职，一生力主抗金，提出的抗金建议很少被采纳，还遭到主和派打压、长期落职闲居；其词艺术风格多样、以豪放为主，与苏轼并称“苏辛”。本词是辛弃疾 65 岁登临镇江北固亭所作，时为南宋开禧元年秋，当时韩侂胄把持朝政大权，企图用北伐中原来提高自己的声誉，于嘉泰三年启用闲居的抗金派代表辛弃疾，先任命为绍兴知府、浙东安抚使，次年调任镇江知府；镇江古名京口，素来是军事重镇，南宋时处于抗金前线。韩侂胄抗金的主张符合辛弃疾收复失地的一贯志愿，但韩侂胄在军事上准备并不充分，辛弃疾忧心忡忡，登临北固亭时览景有感。**以点入词是本词一大特色**，五个典故逐个讲。“千古江山，英雄无觅孙仲谋处”刻画孙权：词题为京口北固亭怀古，一开头就从镇江的历史人物孙权说起，孙权是三国时吴国皇帝，在南京建都、打垮北方的曹操、保卫了国家；如今江山如故却无处寻找像孙权那样的英雄，惋惜之余暗含无人可用的愤懑。“斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎”刻画刘裕：寄奴是南朝宋武帝刘裕的小字，刘裕在京口起兵讨伐桓玄、平定叛乱；斜阳照着草丛树木与普通街道，人们说刘裕曾在这里住过，回想当年他指挥强劲精良的兵马、气势如猛虎；从回顾刘裕生平揭示出寒门庶族、低微出身并不妨碍英雄建功立业，表达对古代英雄的赞叹，也暗含以英雄业绩鼓励鞭策自己、抗敌救国的心情。“元嘉草草，封狼居胥，赢得仓皇北顾”刻画刘义隆：元嘉是南朝宋文帝的年号，宋文帝刘义隆是刘裕的儿子，不能继承父业、好大喜功，听信王玄谟的北伐之策、打无准备之仗，结果一败涂地；“封狼居胥”讲汉朝霍去病战胜匈奴、在狼居胥山举行祭天大礼的故事，宋文帝听了王玄谟的大话、对臣下说“闻王玄谟言，使人有封狼居胥意”；词人借此表达对当时执政者急功近利、主张用兵而不做充分准备的警告。“可堪回首，佛狸祠下，一片神鸦社鼓”刻画拓跋焘：拓跋焘小字佛狸，属鲜卑族，击败刘宋军队后率追兵直达长江北岸的瓜步山、在山上建立行宫，就是后来的佛狸祠；当地老百姓年年在佛狸祠下迎神赛会，神鸦是吃祭品的乌鸦、社鼓是祭神的鼓声；词人感叹往事怎忍再回顾，如今佛狸祠香火正盛，而江北各地沦陷已久，不迅速谋求恢复的话，民众安于异族统治、忘记自己是宋氏臣民，借此提醒人们不要忘记江北仍处在金人铁蹄之下、不要忘记收复故土，表达对南宋统治者苟安、不思收复失地的悲愤。“凭谁问：廉颇老矣，尚能饭否”刻画廉颇：又谁来问廉颇将军老了、饭量还好吗？廉颇虽老还想为赵王所用，在赵王使者面前一顿吃了一斗米做的饭、十斤肉，又披甲上马表示自己尚有余勇；诗人联想自己，并不如廉颇老迈、却没有人来过问，这里运用典故、以廉颇自比，表示仍能为国效力，同时抒发报国无门、壮志难酬之愤。有人批评辛弃疾的词“掉书袋”，岳飞的孙子岳珂说“用事多是这首词的毛病”，这是不恰当的批评：这首词所用的故事除了末尾廉颇一事以外，都是有关镇江的史实，眼前风光是京口怀古这个题目应有的内容，且都和词的思想感情密切相连；就艺术手法论，围绕作品的思想内容使用许多史事，以加强作品的说服力和感染力，在词里是不多见的，这正是这首词的长处。**对比鉴赏**：用典上，苏词以精细笔墨集中塑造儒雅倜傥、击败强曹的青年将领周瑜，渲染其显赫功业、横溢才华时又巧妙点染他温文尔雅的风度和幸福美满的婚姻，以一个特写镜头“谈笑间，樯橹灰飞烟灭”现出军事统帅风度翩翩、气宇轩昂、运筹帷幄、指挥若定的儒将风范；辛词上片写孙权、刘裕两人，不像苏词那样亲比于人物的音容笑貌、神情风采，而是侧重于史实的铺叙，下片写刘义隆急于求成、仓促北伐，只落得仓皇北顾的下场，沉重追溯惨痛的历史教训，道古以讽今、告诫当政者谨慎用兵、免蹈前车之辙，末尾廉颇渴望为国出力、却报国无门，词人以己自比。借景抒情上，念奴娇集中写景、浓墨重彩，“乱石”写形状之雄奇、“惊涛”写声音之汹涌、“卷起千堆雪”写色彩之磅礴，绘出一幅雄浑壮丽的江山图；永遇乐没有纯粹的景物描写，景物描写有机穿插在史实叙述中、次第出现，都是淡笔勾勒，开篇景物大至江山、小至舞榭歌台、斜阳草树，浅墨淡彩、不着点缀，纯客观的轻描淡写，意在暗示事过境迁、物是人非。词风上，苏词偏于潇洒疏朗、旷达超脱，词中的不平之意最后能通过对人生的参悟逐渐平复，因而读到乐观旷达；辛词喜欢用典，充满奋勇抗敌的热情和报国无门的悲哀，给人慷慨悲壮之感。相同点是境界开阔、感情豪放，都借古人抒怀。最后一段是倪文韬讲《声声慢》。先逐句讲字面意思：开篇“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”是七组十四个叠字连用，非常打破常规，历来诗论家词论家都赞叹“精妙出奇”；“寻寻觅觅”展现似乎在寻找什么的彷徨、空虚、迷茫的心理状态，“冷冷清清”既是外部环境的凄清，也是体感上的冷表达内心世界的清冷，“凄”有寒冷、悲伤、静寂三种意思，“惨”是程度极深的悲伤、“戚”是忧愁悲哀，三个字意思相近、通过叠词连在一起，把感伤忧愁的情绪渲染得非常浓烈。“乍暖还寒时候，最难将息”：“将息”是调养、休息的意思，乍暖还寒的时节最难将息，因为气温不稳定、很容易生病；“乍暖还寒”究竟是什么时候？课下注解给的是忽冷忽热、天气变化无常，一般指由冬入春（“乍”是刚刚、起初，“还”是又回到：刚刚天气热起来、又回到了寒冷，就是春寒），但本词后面有“雁过也”“满地黄花堆积”，黄花是秋天开的菊花、大雁秋冬南飞，似乎更像由秋入冬；不过大雁春天北归时也能看到，春天也有迎春花这样的黄花，所以由秋入冬还是由冬入春都可以，不必死抠。字面意思讲完（约 37 分钟）进入两个重点：一是**内容情感层面**，这首词当然表现的是愁情（“这次第，怎一个愁字了得”），但究竟是怎样的愁、愁从何而来、愁到了什么程度，值得仔细玩味；这是李清照的晚期作品，正是作者最为抑郁痛苦的时期，要了解这愁从何而来、自然要考察李清照的人生经历——她出生在和平年代，年轻时婚姻美满、生活安逸，父亲李格非是礼部员外郎、后做吏部侍郎，公公是宰相赵挺之，夫妻二人都是高干子弟，曾经度过一段非常安逸美满的生活，一个经历过盛世再进入乱世的人，那种生命体验与出生在乱世的人完全不同；二是**创作技巧层面**，重点分析开篇十四个叠字：从声调看，平声昂扬、去声分明、入声短促，如“寻寻觅觅”第二声、第四声、阳平到去声，阳平有升起的感觉；“凄凄”后边的“凄”都是擦音，念的时候给人哽咽的感觉；这十四个字不仅在声调上一扬顿挫、不流于呆板繁复，而且能暗示情绪流动的状态。李清照填词对声律要求极其严格，这正是她“词别是一家”的词学观。课末老师预告下期讲《窦娥冤》。", "vtech": [["典故题三步答法", "先说典故讲的是谁、什么事（如刘义隆元嘉北伐、封狼居胥），再说词人借它说什么（告诫当政者谨慎用兵），最后落到情感（忧愤、讽谏）；只讲故事不讲用意，等于白写。"], ["对比鉴赏先列不同再说相同", "用典不同（苏词集中写一人、辛词连用五典）、写景不同（苏词浓墨重彩、辛词淡笔勾勒）、词风不同（旷达超脱 vs 慷慨悲壮）；相同点是境界开阔、感情豪放、都借古人抒怀。"], ["“故国神游，多情应笑我”怎么断句讲", "故国神游即神游故国，多情应笑我即应笑我多情，都是倒装；情感是联想自身、壮志难酬，又转念以江月举杯求解脱，答题要把“感慨—解脱”两层都说到。"], ["叠字题抓声音和情绪", "声声慢开篇七组十四个叠字连用，寻寻觅觅写彷徨迷茫、冷冷清清写内外清冷、凄凄惨惨戚戚把悲愁渲染到极致；再看声调，平声昂扬、去声分明、入声短促、擦音哽咽，声音本身就在传情绪。"]], "vgaokao": []}}, "u_chn_10": {"id": "u_chn_10", "name": "家乡文化生活", "secs": "第四单元", "pageFrom": 71, "pageTo": 78, "members": ["chn_c018"], "video": {"bvid": "BV1JB4y1G7kF", "p": 17, "t": "家乡文化生活", "dur": "26:30", "from": "名师课堂", "vtop": ["本单元是学习活动单元，没有课文精讲：三个活动是记录家乡的人和物、家乡文化生活现状调查、参与家乡文化建设，从调查访谈到提建议，层层递进。", "访谈是活动一的核心方法：流程是定目的、定时间进度、选代表性对象、定形式设计问题；问题要紧扣目的、清晰具体、层层深入；访谈时熟悉问题、用对谈方式、善于追问，访谈者不分享自己的观点倾向、要忠实记录。", "调查报告与建议书是两项输出：调查报告要包括教材列出的一般要素、也可加图表目录致谢附录；建议书格式与一般书信大体相同，标题可写“关于某某某的建议书”，中学生写建议书要用委婉的建议语气、不能是说教或命令语气。"], "vsum": "本课是“家乡文化生活”单元的导读课，没有课文精讲，讲的是本单元要做的三件事怎么做。开场先定家乡文化的地位：家乡文化既是中国文化的主要组成部分，又是个体精神生活的重要依托，它并不是抽象的存在——家乡的各色人物、各类人文和自然景观、独特的风俗习惯和历史文化，都承载着丰富的情感与记忆。**单元目标四点**：一是思考家乡文化生活与自我成长之间的关系，形成关注和参与当代文化生活的意识，培养家国情怀；二是了解访谈的基本概念和特点，掌握有关访谈的基本知识、方法、程序和技巧，提高在具体情境下的语言文字运用能力；三是阅读有关调查研究、乡土风俗等方面的文章，帮助完成本单元要求的学习活动，提升理性思维能力和审美鉴赏能力，学会灵活运用常见工具书和网络、根据一定的目的查阅所需信息资料、快速定位信息；四是学会从现象中提炼有价值的典型问题，形成专题研究意识，根据事实说话、学会论证说理、学会分析书面材料、掌握研究方法，了解调查报告应包括的一般要素并完成调查报告写作，培养理性思考、深入认识问题的能力。**三个学习活动各有侧重**：第一个活动“记录家乡的人和物”，面向日常生活、梳理值得记下的人和物素材，从熟悉的场景中激活记忆、凝练认识、感受家乡的底蕴；第二个活动“家乡文化生活现状调查”，从人际关系、道德风尚、文物古迹的保护、文化生活的方式等不同主题展开调查研究，在某一个专题方向深入了解、感受家乡的变化；第三个活动“参与家乡文化建设”，从风俗习惯、邻里关系、生活方式、文化环境等方面思考可以改进的地方，这是语文学习的课外延伸，也是当代同学应该担负的责任。第一个活动侧重通过调查访谈深入了解家乡的人、物、历史、习俗等，第二个活动侧重通过访谈和调查了解家乡文化生活现象、辩证思考文化发展与个人、社会的关系，第三个活动侧重在掌握大量一手材料后提出丰富家乡文化生活的建议，在这一学习活动过程中提升语文素养、培养热爱家乡进而热爱祖国的感情。**活动一：记录家乡的人和物**，核心方法是访谈。访谈是一种交谈活动，以口头形式围绕特定目的、根据被询问者的答复搜集客观的、不带偏见的事实材料，以准确地说明问题；面对复杂问题时运用访谈的方法，遴选不同方面的各具代表性的人物，可以了解不同类型的材料，就有一定的灵活性和覆盖性。访谈前要了解关于访谈的一般知识、知道怎样进行访谈，分四部分讲。**一、访谈的一般流程**：确定访谈的目的、功能以及理由；确定访谈的时间及进度；选择有代表性的访谈对象；确定访谈形式、设计问题。例如记录家乡人物，可以从家庭几代人、同学和朋友中选择相应的代表性人物；确定访谈对象后在访谈开始前做好充分准备，例如了解访谈对象的情况、制作访谈问题表、准备录音或摄像器材等等。**二、访谈问题的设计**：问题设计要紧扣访谈目的，清晰具体、简单明白、便于回答，具体明确、层层深入；提问的方式、用词的选择、问题的范围要适合被访者的知识水平和习惯；如有可能，也可以事先发给访谈对象访问题纲，让访谈对象提前做好准备。**三、必要的访谈技巧**：访谈前熟悉访谈问题，这样不用照着读出来，用对谈的方式可以让受访者更好地参与进来；访谈时要根据访谈对象的特点，通过一定的话题切入拉近距离，让氛围变得轻松、适于交流，与受访者加强了解和沟通，营造友善的谈话氛围、建立良好的访谈人际关系；抓住时机、灵活呈现问题，旁敲侧击、善于提问与追问，将谈话引向深入；对非语言信息保持敏感、适当回应，使访谈顺利进行；访谈者不需要向受访者分享你的个人经历或观点倾向，这会影响访谈所获得的信息；要能忠实准确地记录访谈内容。**四、访谈后要根据一定的结构完成初始研究资料的整理**。**活动二：家乡文化生活现状调查**。地方文化可以反映在各个方面，例如某地代表性的建筑、街道，甚至一草一木、一砖一瓦、一人一物，都可以是家乡文化的反映；发展家乡文化可以提升同学们的主人翁意识、增强归属感、维系良好的人际关系、提高文化生活质量。调查社区文化生活现状，下面的题目可供参考：一是家乡文化遗产保护传承情况调查，二是家乡群众性业余文化活动调查，三是家乡图书室藏书与借阅情况调查，四是家乡商家招牌体现的商业文化调查，五是家乡文化习俗生活方式的变化调查。调查前要规划调查路线、确定调查重点；调查时要认真观察、做好记录，尽可能详尽地留下第一手材料，包括影像资料，要注意准确记录各种信息的来源。**调查要有问题意识**：家乡文化生活并非静态的存在，随着社会的发展会呈现出哪些变化？原因是什么？每个人的想法可能不同。如何形成理性全面的认识，需要在调研观察中发现典型现象，在对现象的审视中提出问题，针对具体问题搜集材料、分析问题、梳理材料、研讨有关文化现象，增强对问题的深入认识。具体到语言文字任务，要通过多种渠道获得信息、初步形成研究资料：通过自己的观察搜集材料，以调查访谈的方式获得典型个案，通过各类报刊、利用图书馆和网络进行文献阅读，从有关部门获得数据，汇聚各个角度的信息、形成较为全面的研究资料，然后才能运用学到的知识，对有关现象与成因做出推理、解释、判断、得出结论。调查大多会包括一系列的任务，为了很好地完成这一学习活动，需要制定一个初步的调研计划：一般来说科研工作者的研究计划会涉及研究目的、价值、预设、文献综述、路径、内容以及可能遇到的问题与应对策略等，这里不需要那么系统，研究的过程就是发现、提出问题、分析、解决问题的过程，这份调研计划可以定位为任务计划书，目的是让我们据此开展一系列具体的学习活动，促使我们去思考要调查什么、有哪些渠道可以获得材料、如何判断这些材料有效有用、怎样分析这些材料、需要多少同学做什么事、各自的分工是什么、时间节点又是什么，同学们要在一到两周的时间完成这个学习任务；当代文化参与的特点是将语文学习和日常生活联系起来，制定计划时可以课内课外相结合。家乡不仅是生活的场所，也是文化熏陶的场所：你家乡的文化生活状况如何？那里的文化设施是否齐全？使用情况如何？人们日常都开展哪些活动？有没有图书阅览室？是否经常开展读书活动？开展调查时可以以小组为单位，通过访谈、考察等方式了解家乡的文化生活现状；汇报展示时可以以调查报告的方式，也可以制作成演示文稿。调查报告呈现的是同学们自己搜集到的研究材料，搜集材料的方法与路径包括调查、访谈、阅读所获等，以及分析这些材料之后的研究发现；报告中需要对具体案例进行剖析，对家乡文化生活的一些典型现象，应结合调查、访谈、观察、阅读等所得进行分析。**调查报告应包括的一般要素**教材上已经列出，同学们撰写调查报告时以上要素要尽量齐备，但并不一定要照搬，必要的话也可以通过课堂交流研讨等环节，将研究内容、研究结论中的具体要点提炼出来成为标题，并在报告中具体展开阐释；调查报告也可以加入图表、目录、致谢语、附录等其他内容。**活动三：参与家乡文化建设**。了解家乡的文化生活、参与家乡的文化建设，是语文学习的课外延伸，也是当代同学们应该担负的责任；在对家乡文化生活现状调查的基础上，也许同学们会发现一些可以改进和改善的地方，不妨做一些操练、提一些可行性建议，教材上有一些活动提示，可以选择某项开展活动。**关于建议书**：建议书的格式和一般书信大体相同，标题可以只写“建议书”三个字，有时为了突出建议的具体内容，还可以写“关于某某某的建议书”，题目要写在第一行的中间、字体要大；建议书的对象可以是家乡的相关部门，要注意语言表达的得体，因为写作者的身份是中学生，所以在表达中不能是说教语气、更不能是命令语气，应是委婉的建议语气；对部门的建议可以是理性分析为主，要陈述建议的内容、建议的理由、实施的步骤和可行性，要有依据，切记不能根据个人好恶提建议。每个学习活动后同学们都可以设置交流与研讨的环节，以多种方式展示学习收获：班级展示采用幻灯片配讲解的形式，校园展示采用图片配文字的形式，网络展示则可以建立公众号、采用文字图片视频加音频的形式等等；在展示的同时整理自己的思路，但更重要的是相互借鉴启发，在交流与研讨中深化对问题的认识。如果是小组交流，各小组要注意确定发言人、记录者，发言要有一定的组织纪律，组内交流先达成共识，各组发言时要避免发言无序、更要避免不必要的争论。同学们要将自己的观点通过语言准确地表达出来，让别人能理解，这种说的素养包括思维的逻辑性、语言的组织能力、参与讨论的风度等。对很多同学而言，当众发言及其组织语言是相当困难的，大多数同学平时也很少会有意识地将其作为学习内容；发言时听众是我们的同学，无需紧张，目的是让同学们听明白，而不是赶紧说完完成任务；发言前要先做准备，先撰写发言提纲，可以用若干关键词来提示，说话时要清楚和缓、注意节奏与停顿，重要的观点可以借助加重语气、必要的重复等方式予以强调；别人发言时要认真聆听，不能随便打断，能够听出别人说话的重点、问题，才能合理有效地吸收他人意见、互相借鉴、共同提高。**活动举例：写家乡风物志**。我们生活的家乡，各种风光景物、风俗物产，这些风物往往承载家乡的历史、文化，寄托了人们对家乡的情思；为这些风物写一个风物志，是同学们了解家乡文化、积极参与家乡文化建设的重要方式；冲破挖掘这些风物的文化内涵，可以更深入地理解当代文化，也有利于同学们在真实情境中提升语文素养。学习活动一：掌握家乡风物志撰写所需要的相关知识。一是风物志知识学习：风物志的概念——“志”是记录的意思，是古代记叙事物、抒发感情的一种文体，所谓风物志是指对家乡风光景物、风俗物产的介绍；撰写对象选取基本原则——应该选取反映本地历史、体现本地风土民情、对本地文化生活有重要影响的自然景物、建筑、物产、风俗等；写作对象选取定向——小组讨论本地有哪些适合写入家乡风物志的风物，确定写作具体对象并明确选取理由，初步确定所写的主要话题。二是学习访谈设计：访谈准备——先查阅资料、了解所写风物的基本情况，寻找了解该风物的人员、进行访谈、设计访谈问题；访谈方案设计——先了解访谈对象，进入正式访谈前先通过互相寒暄、自我介绍、真诚求教等方式拉近与被访者的心理距离，然后进入访谈主题；采访问题直接明确、切记空泛，围绕访谈目的进行；通过提问引导被采访者，保证访谈方向不偏离；可以请被采访者陈述事实、介绍信息、发表看法，也可以请被采访者讲述细节，必要时可以与被采访者展开讨论，但不宜喧宾夺主、更不宜与被采访者发生争论；访谈问题设计举例——请问您在本地生活了多久，在您的印象中家乡人的习俗是否有变化，如果有、变化的原因是什么；听说您是这里的老住户，对这里的情况特别了解，您能给我们讲讲这座石桥当年是怎么立起来的、有哪些故事。三是学习如何实施访谈：从简单问题入手、启发调查对象充分发表自己的看法；访谈中提出问题应具体明确，避免笼统、含糊不清；控制话题、避免谈话离题太远；交流中要注意倾听受访人的看法，随时给予积极回应；最重要问题可以用不同方式重复提问，重复对方关于此问题的回答、看其是否肯定此说法；访谈结束后要及时整理访谈记录、整合访谈内容。学习活动二：针对本校学情，利用学校和同学们所在村镇、社区资源开展家乡风物志写作活动。任务动员、领会活动目的：一是增进对家乡风光景物、风俗物产的了解，二是训练写作风物介绍文字、家乡风物志的能力，三是深入了解家乡、村镇和社区，提升参与家乡文化建设的能力；在教师指导下进行课堂讨论，搜集、列举本地各类家乡风物，制作家乡风物名录——明确列入风物名录的原则：本地著名的自然景物、建筑、物产、风俗，具有本地特色、可以作为本地标志，有历史积淀或反映本地最新变化的事物；分小组讨论、确定本小组撰写风物志的具体风物，明确写作内容、确定具体风物，研讨采访方案与内容。学习活动三：在教师指导下明确访谈思路与技巧。了解风物志内容获取途径：根据提纲方案的内容，在网络上查阅相关材料、获取调研访谈线索；采访与风物有关的人员，包括相关风物的管理人员、久居本地的居民等；查阅本地地方志等材料。了解风物志主要内容：该风物的特点，该风物的历史沿革、传说故事，该风物名称的内涵，家乡风物体现的乡土情感；访谈问题举例——以本地中学某棵纪念树为例：这棵树是哪年种植的，当年是因为什么事情种植的；您还记得当年种树时的场景吗；这棵树从种植到现在发生过哪些有意义的事情。学习活动四：以小组为单位开展访谈、为写作做准备。确定采访名单，访谈名单举例以当地学校的中外友谊树为例：采访学校校长与老教师，采访当年参与种树的老校友，采访现在的同学对这棵树的感受；拟定调研访谈程序与方案：根据所写风物确定关键词、上网搜索资料，确定调研、访谈和查阅资料的方向，根据调研与资料查阅成果确定访谈内容，整理资料、编制资料目录，以某学校中外友谊树所需资料为例，所查资料目录包括本地地方志中的中外交流资料、学校的校史特别是国际交流资料、植树当年的中外交流事件记录、当年植树的当事人回忆录、该友谊树相关学校的信息、植树之后学校与相关联谊学校的交流记录；开展访谈，考虑到不熟悉本地区的人的阅读需要，全篇结尾处要有对被访谈者的感谢，并附相关图片。交流展示家乡风物志：在学校网站建立专栏，在家乡风物处粘贴二维码、扫码后可供来访者阅读，班内交流。可供参考的活动方向（提示下面提供的一系列活动任务，可以任选一个展开调查；家乡在外地的同学，可以自动把下面涉及有关的内容换成自己家乡的内容）：一是人物——注意采访人物的生平、主要事迹、贡献和影响等；二是建筑——历史、现状、故事、建筑特色等；三是风景；四是风物——来源、特点、文化价值等；五是风俗、生活方式；六是家乡的历史、文化遗产；七是建议书。学习资源包括《俗世奇人》《毛泽东与调查研究》《胡同文化》、调查报告的一般结构、撰写调查报告应注意的问题、弘扬传统文化、半量现代生活：济南市历城区民间伴奏队伍调查报告、纪录片《五大道》等。课堂小结：通过本课的学习，同学们应形成关注和参与当代文化生活的意识，培养家国情怀，了解访谈的基本概念和特点，提高在具体情境下的语言文字运用能力。", "vtech": [["访谈问题怎么设计", "紧扣访谈目的、清晰具体、简单明白、便于回答，层层深入；提问方式、用词、问题范围要适合被访者的知识水平和习惯；有条件可事先发给访谈对象问题提纲，让对方提前准备。"], ["调查报告的要素怎么凑齐", "按教材列出的一般要素尽量齐备、不必照搬；先把研究内容、研究结论的具体要点提炼出来做标题、再展开；也可加入图表、目录、致谢语、附录；报告里要对典型案例做剖析。"], ["建议书语气怎么把握", "对象是家乡相关部门，写作者是中学生，语言要得体：委婉的建议语气，不能是说教语气、更不能是命令语气；内容要有建议内容、建议理由、实施步骤和可行性，切记不能凭个人好恶提建议。"], ["风物志选题怎么定", "选反映本地历史、体现本地风土民情、对本地文化生活有重要影响的自然景物、建筑、物产、风俗；先列风物名录（本地著名、有本地特色、有历史积淀或反映最新变化），再定具体风物和采访方案。"]], "vgaokao": []}}, "u_chn_11": {"id": "u_chn_11", "name": "乡土中国（整本书阅读）", "secs": "第五单元", "pageFrom": 79, "pageTo": 79, "members": ["chn_c019"], "video": {"bvid": "BV1JB4y1G7kF", "p": 18, "t": "乡土中国（整本书阅读）", "dur": "26:13", "from": "名师课堂", "vtop": ["整本书阅读建议共四点：先粗后细逐步推进、抓住核心概念、创作思维导图把握知识体系、品读文章感受写作特色；先按这四点搭阅读框架，再进正文。", "粗读三点：读序言后记了解写作背景和目的（二十世纪四十年代后期，费孝通在西南联大等校讲授乡村社会学课程，整理授课内容写成十四篇文章）、浏览目录大体了解内容和章节结构、浏览正文快速跳读形成整体感知；细读注重概念、材料、论证、推理。", "差序格局是核心概念：由亲属关系和地缘关系决定的有差等的次序关系，与西洋社会的团体格局相对；作者用生活经验、历史事实、民间俗语、《红楼梦》情节、《论语》《大学》名言等材料论证，用了比喻、事实、道理、对比论证，由具体事实概括出一般理论是归纳推理。"], "vsum": "本课是《乡土中国》整本书阅读的导读课：先介绍作者费孝通，再给四点阅读建议，最后留两个练习并附参考答案。开场先定这本书的地位：《乡土中国》是一部经典的社会学著作，作者费孝通以实地调查为基础，研究中国乡村社会的特点，提出许多具有启发性和影响力的观点。**作者费孝通**：江苏吴江人，社会学家、人类学家、民族学家、社会活动家，早年赴英留学，1938 年学成回国，曾任西南联大教授、清华大学教授、中国社会科学院社会学研究所所长等职，长期从事社会学、社会人类学的教学和研究工作，主要著作有《江村经济》《禄村农田》《生育制度》《乡土中国》等，其中《乡土中国》是最为脍炙人口的一本。《乡土中国》是一部社科类学术著作，同学们之前很少接触学术著作、不知应该如何着手阅读，老师给出四点阅读建议。**阅读建议第一点：先粗后细，逐步推进**。粗读指的是粗读，细指的是细读，阅读社会科学论著最好将粗读与细读结合起来，先粗读后细读。粗读主要包括三点。第一，在阅读书的正文内容之前，先阅读书的序言后记，来了解作者的写作背景和写作目的：二十世纪四十年代后期，费孝通在西南联大等校讲授乡村社会学课程，他不喜欢用现有的教材，而是独立思考和探索，将自己的研究成果分享给学生，后来应《世纪评论》之约，费孝通将授课内容进行整理，写成分期连载的十四篇文章；阅读序言和后记还可以了解此书的写作目的，是要探讨中国乡村社会的特点，回答作为中国基层社会的乡土社会究竟是个什么样的社会这个问题。第二，浏览目录，大体了解著作的基本内容和章节结构：社科类著作的目录一般都比较明晰，主要的观点往往会出现在章节标题中，阅读目录中的章节标题就能对全书的内容和结构有粗略的了解；《乡土中国》除了重刊序言和后记之外，包括十四篇文章，分别是《乡土本色》《文字下乡》《再论文字下乡》《差序格局》《维系着私人的道德》《家族》《男女有别》《礼治秩序》《无讼》《无为政治》《长老统治》《血缘和地缘》《名实的分离》《从欲望到需要》；阅读目录中的文章标题，再结合在序言和后记中了解到的研究背景、研究目的等内容，可以大致断定本书的主要内容是谈论中国乡土社会的特点，涉及文字的使用、社会结构、道德观念、传统感情、宗法制度、社会变迁等方面的内容；初次读目录，你可能对其中一些题目的含义不太理解、存有疑问，这是很正常的，这样你阅读正文的时候就带着这些疑问去阅读，在阅读中解决疑惑。第三，浏览正文、快速跳读，对全书形成初步的整体感知：在浏览正文时可以留意每个章节的开头和结尾，以及每个段落的开头和结尾，那里往往会出现观点；看到阐述观点或定义概念的句子，顺手勾画下来；其他部分可以一目十行、自行跳读，知其大意即可。以上讲的是粗读，通过粗读形成对全书的第一印象，有了第一印象就会产生对这本书的疑问点和兴趣点，也就产生了阅读期待，带着这样的期待去阅读会有更好的阅读效果。在粗读之后再自行细读：细读是指对文章进行精细深入的阅读，注重概念、材料、论证、推理等要素，深入思考、不断提炼。以《差序格局》这一篇为例说一说细读需要注意的方面：首先关注作者提出的概念，在这一章节中作者提出的核心概念是**差序格局**，用它来指称中国传统社会结构的格局，差序格局是指由亲属关系和地缘关系所决定的有差等的次序关系；作者为了更好地说明差序格局，举出另一个可与之构成对比的概念，就是**团体格局**，团体格局是用来指称西洋社会结构格局的概念。其次注意区分观点与材料，看一看作者是如何用材料来支撑观点的：在《差序格局》这篇文章中，费孝通运用了丰富的材料，包括生活经验、历史事实、民间俗语、《红楼梦》中的情节、《论语》《大学》中的名言；在细读文章的时候，需要弄明白作者为何使用这些材料，他用这些材料验证了什么样的观点。再次关注作者是如何论证观点的、他使用了什么样的论证方法：在《差序格局》这篇文章中，作者运用了比喻论证、事实论证、道理论证、对比论证等论证方法来论证自己的观点。最后注意分析作者是如何进行逻辑推理的：在差序格局中，作者由一系列具体的事实概括出中国传统社会结构的格局是差序格局这一结论，这种由一系列具体的事实概括出一般理论的推理方法是**归纳**的推理方法。运用细读的方法去阅读，能够让我们更好地把握作者的观点和论述的逻辑。**阅读建议第二点：抓住核心概念，找出概念间的联系**。学术著作往往会提出一些重要的概念，然后从理论上进行阐释，阅读《乡土中国》要特别关注其中的重要概念，如礼俗社会、差序格局、无讼、无为政治等；费孝通先生在《乡土中国》的序言里说，搞清楚我所谓乡土社会这个概念，就可以帮助我们去理解具体的中国社会，概念在这个意义上是我们认识事物的工具，理解书中的核心概念、找到作者认识事物解决问题的工具，就等于掌握了阅读学术类著作的钥匙，借助这把钥匙就能够把握全书的主要内容、理解其学术研究的价值。那么应该怎样抓住和理解核心概念呢？第一，留意目录中的核心概念：《乡土中国》的目录包含一些核心概念，如差序格局、无讼等等，在读目录时可以留心记下这些核心概念，把它们抓住。第二，在阅读正文时也要实时留意概念，碰到概念先区分它是一般概念还是核心概念，如果是核心概念，要将它勾画下来，并且思考这个概念是在什么样的语境中提出来的、它的内涵是什么、作者是如何围绕它展开论述的。第三，在对比中理解核心概念：在《乡土中国》这本书中，作者提出许多用来指称乡土社会的概念，并且往往同时提出指称其他社会的对应概念，比如作者分别用差序格局和团体格局这两个概念来分别表示乡土社会结构和西洋社会结构的格局，在两者的对比中，每个概念各自的内涵就更加清晰了；在理解某一个核心概念时，就可以尝试找到与它构成对比的另一个概念，在比较中更好地理解每一个概念；教材上有一个《乡土中国》概念对比表，同学们可以利用这个表格，梳理作者用来指称乡土社会的概念和与之相对应的指称其他社会的概念，并结合作者的论述理解这些概念的含义。第四，注意理解概念之间的联系：《乡土中国》中的很多概念都具有紧密的关联，例如差序格局和维系着私人的道德这两个概念就具有紧密的联系，用作者的话说就是，在差序格局中，社会关系是逐渐从一个一个人推出去的，是私人联系的增加，社会范围是一根根私人联系所构成的网络，因之我们传统社会里所有的社会道德也只在私人联系中发生意义，道德观念是依社会格局而决定的，有差序格局这样的社会结构格局，就自然会有维系着私人的道德；如果能将书中重要概念之间的联系弄清楚，就能更好地理解这本书的知识体系。第五，有时也会遇到一些不容易理解的概念，在这种情况下可以反复阅读、联系上下文用心推敲它的含义，或者查阅一些资料，如词典、百科全书等，促进对概念的理解；面对一些比较抽象的概念，也可以调动自己的生活经验和知识，积极思考、促进对著作的理解。**阅读建议第三点：创作思维导图，把握知识体系**。《乡土中国》的正文包括 14 篇文章，作者在每一篇文章都提出了一些观点，而这 14 篇文章又相互关联、构成一个完整的知识体系；在阅读每一篇文章之后应该想一想，作者在这篇文章中阐述了怎样的内容；在阅读全书之后也应该想一想，这些文章分别讲到乡土社会哪些方面的特点，它们之间有何联系；可以将思考结果用思维导图的形式呈现出来：读完每一篇文章时，尝试画一个思维导图来概括这一篇文章的主要内容；如果认为某几篇文章的联系非常紧密、它们是在讲一个问题的不同方面，也可以尝试用一个思维导图去概括这几篇文章的主要内容；当阅读完整本书时，回顾之前画过的思维导图，利用这些思维导图去思考、分析全书各篇文章的联系，进一步尝试画一个总的思维导图来概括整本书的内容。举一个例子说明：《乡土中国》的第二篇和第三篇文章分别是《文字下乡》和《再论文字下乡》，阅读这两篇之后发现这两篇都是在讲乡土社会的语言文字使用情况，并且从不同角度来阐述为何乡土社会有语言而无文字，所以可以将这两篇归拢到一起，画一个思维导图来理清作者的论证思路：作者先由“乡下人在城里人的眼里是愚的”谈起，原因是乡下人不识字，但不识字其实是知识问题、不是智力问题，不识字并不是愚的表现；乡下多文盲，是因为乡下本来无需文字，这和乡土社会的本质有关——文字的发生是在人和人传情达意受到空间和时间阻隔的情境里，乡土社会的人是在熟人里长大的，他们是一个面对面的社群，在面对面的社群里有话可以当面说明白、无需借助文字；此外，乡下生活是同一方式的反复重演，乡下人身处于熟悉的社会中、过着定型的生活，就个人而言，生活经验用记忆和语言来保存就足够了，无需文字，就社会而言，语言足够传递世代间的经验，也无需文字，所以乡下人不识字，不是因为愚，而是因为他们没有使用文字的需要；作者进一步指出，中国社会乡土性的基层发生了变化，才能更好地推行文字下乡。借助这样一个思维导图，抓住了作者的主要观点、理清了作者的论证思路，将原文的内容化繁为简。画思维导图时需要注意：首先应该独立完成，思维导图创作的过程就是个人对这本书再阅读、再思考、再总结的过程，应该独立完成，而不要满足于现成的答案；别人的思维导图可以参考、借鉴，以此来优化自己的思维导图，但不应用别人的思考来代替自己的思考；此外，在阅读《乡土中国》时，会发现作者在每一篇中都提出了一些关键概念、阐明了一些观点，为了将概念解释得更清晰、让观点更加具有说服力，作者使用了大量的材料，例如民俗调查的案例、历史事实、生活经验、经典著作原文、民间俗语等，当画思维导图时，只需要呈现关键的概念、主要的观点即可，不必涉及材料；再有，在画思维导图时，应该尽量用准确、凝练的语言去概括作者的观点。**阅读建议第四点：品读文章，感受写作特色**。《乡土中国》是一部学术著作，读起来却并不觉得枯燥难懂，而是感觉它非常通俗自然、生动有趣，具有很强的可读性；阅读这本书，除了可以拓展视野、了解一些社会学的知识之外，还可以从文章品读的角度入手，感受作者的写作特色，从中借鉴一些写作方面的经验。第一是论点鲜明：《乡土中国》的每一篇文章都集中解决一个问题，而且文章的标题往往就是作者观点的凝练表达，例如读到“差序格局”这个标题，就能够明确这篇文章的主要论点是乡土社会的结构是差序格局，读到“无讼”这个标题，就能够明确这篇文章的主要论点是乡土社会维持秩序的理想手段是教化而不是诉讼，等等。第二是事例丰富而贴切：作者使用了大量的事例，并且这些事例都能够很好地验证作者的论点，例如在《礼治秩序》一文中，作者提到抗战时期自己在乡下的经历，孩子啼哭不止、自己找不到医生而请教房东老太太，老太太利用生活经验顺利地解决了问题，这个事例能够很好地论证作者的观点——乡土社会的生活很少变动，后人可以用前人的生活经验来解决很多问题，所以乡土社会里的人敬畏传统、主动地服膺于传统；作者运用贴切的事例，使读者更容易理解他的观点，也使观点更有说服力。第三是善用旧典翻出新意：在这本书中，作者也用了不少传统典籍文献，并且以新的视角、新的思路去解读他们，来验证自己的观点，例如在《维系着私人的道德》一文中，作者运用了《论语》中孔子对“人”的不同解释，指出《论语》中“人”这个观念并没有非常确定的解释，人其实是一系列私人间道德要素的总和，这表明在乡土社会的差序格局中没有超乎私人关系的道德观念；作者善于将旧典翻出新意、将旧典纳入到自己的论述体系之中，使人读到之后往往眼前一亮。第四是比喻巧妙：《乡土中国》里有不少巧妙的比喻，例如在《差序格局》一文中，作者将西洋社会的团体格局比喻成捆柴，将乡土社会的差序格局比喻成石头丢在水面上的一圈圈波纹；在《无讼》这篇文章中，作者用足球比赛来比喻礼治秩序的性质，这些比喻都十分形象，是对抽象理论的生动说明。第五是善于对比：作者在文中经常对比乡土社会与现代社会、乡土社会与西洋社会的诸多不同，这种对比展现了作者开阔的视野与宏观的思考，也使读者更加容易理解不同社会类型的特点。第六是语言通俗自然：《乡土中国》是一部学术著作，读来却并不感到枯燥和艰涩，作者用通俗易懂、朴实自然的语言，向读者阐明一个个抽象的概念和理论，这展现了作者深厚的学术素养和不凡的语言功力。以上就是给同学们提供的《乡土中国》整本书阅读建议，希望这些建议能够帮助你更好地展开阅读，也希望同学们在读书的过程中积累学术著作阅读的经验、形成适合自己的读书方法、养成良好的阅读习惯。课末两个练习：一是阅读学术著作要先粗读后细读，那么粗读和细读分别指什么；二是阅读《乡土中国》要关注核心概念，那么我们应该怎样抓住和理解核心概念呢。第一题参考答案：粗读主要包括三点——阅读序言后记，了解作者的写作背景和写作目的；浏览目录，大体了解著作的基本内容和章节结构；浏览正文、快速跳读，对全书形成初步的整体感知。细读是指对文章进行精细深入的阅读，注重概念、材料、论证、推理等要素，深入思考、不断提炼。第二题参考答案：留意目录中的核心概念；勾画正文中的核心概念，思考其产生的语境、内涵，以及作者如何围绕它展开论述；在对比中理解核心概念；理解概念之间的联系；反复阅读、查阅资料、联系经验，促进理解。", "vtech": [["核心概念怎么抓", "五法：留意目录中的核心概念；在正文里勾画核心概念、想它在什么语境提出、内涵是什么、作者如何围绕它展开论述；在对比中理解（如差序格局 vs 团体格局）；理解概念之间的联系（如差序格局与维系着私人的道德）；难懂的概念反复读、查词典百科、联系生活经验。"], ["思维导图怎么画", "每读完一篇文章画一个导图概括主要内容；联系紧密的几篇（如《文字下乡》《再论文字下乡》）合画一个；读完整本书再画总导图；导图只呈现关键概念和主要观点、不必涉及材料；独立完成、不用别人的思考代替自己的思考。"], ["细读一篇怎么下手", "以《差序格局》为例：先抓核心概念（差序格局及其对比概念团体格局），再区分观点与材料（看作者用什么材料支撑观点），再看论证方法（比喻、事实、道理、对比），最后看逻辑推理（由具体事实概括出一般理论是归纳推理）。"], ["写作特色六点怎么答", "论点鲜明（标题往往就是观点的凝练表达）、事例丰富而贴切、旧典翻出新意（《论语》中“人”的不同解释）、比喻巧妙（团体格局如捆柴、差序格局如水波纹、礼治秩序如足球比赛）、善于对比、语言通俗自然。"]], "vgaokao": []}}, "u_chn_12": {"id": "u_chn_12", "name": "劝学·师说", "secs": "第10课", "pageFrom": 83, "pageTo": 84, "members": ["chn_c020", "chn_c021"], "video": {"bvid": "BV1JB4y1G7kF", "p": 19, "t": "劝学·师说", "dur": "69:13", "from": "名师课堂", "vtop": ["劝学中心论点是“学不可以已”：第一段讲学习的意义（青出于蓝、冰寒于水、木直中绳輮以为轮、金就砺则利，学习提高智能、改造品性），第二段讲学习的作用（登高而招、顺风而呼、假舆马、假舟楫，借助外物事半功倍），第三段讲学习的方法与态度（积累、坚持、专一）。", "师说中心论点是“师者，所以传道受业解惑也”：第一段提出中心论点并从两个角度阐述，第二段用对比论证（古之圣人 vs 今之众人、巫医乐师百工之人 vs 士大夫、句读之不知 vs 惑之不解）层层深入，第三段以李蟠为例，末段交代写作缘起。", "两篇都是说理文但路子不同：劝学通篇比喻论证（青、冰、木、金、登高、顺风、假舆马、假舟楫、积土成山、锲而不舍、蚓无爪牙之利），师说以对比论证为主、兼用引用论证；背诵与默写都要落实文言实词、通假字、词类活用、特殊句式。"], "vsum": "本课由两段视频拼成：前 25 分钟是名师课堂讲《劝学》，后 44 分钟是黄姨语文逐句精讲《师说》。两篇都讲全了，没有缺口。先讲《劝学》。开场走进作者：荀子，名况，字卿，赵国人；散文说理透彻，后人编为《荀子》，其中绝大部分是荀子的作品，其余为荀子弟子记录的荀子言论和思想观点；荀子在教育目的上与先秦儒者保持一致，即通过教育来培养士、君子、圣人，认为人的知识、道德不是天赋予的，而是经过后天教育、学习逐渐培养的；他写《劝学》就是为了勉励人们积善成德、成为君子，《劝学》是《荀子》中的第一篇。接着对本课重点文言知识进行总结：借助字源示意的办法学习两个重要的文言实词，再过通假字、特殊句式，然后借助书下注释翻译全文。**品读感悟**：第一自然段，作者借在学问上有修养的人提出“学不可以已”的观点，“君子”指有学问有修养的人；作者从学习的意义分析，有条理有层次、论述严密。第二段末句“君子博学而日参省乎己，则知明而行无过矣”是前文几组比喻得出的结论，从这一点看，荀子劝学是劝人们首先要学习做人。第三段作者连用“登高而招，顺风而呼，假舆马，假舟楫”四个比喻，从见、闻、陆、水等方面阐明在实际生活中利用和借助外界条件所起的重要作用——善假于物。第四段共有三个层次：第一层论述学习要积累，作者先正面论述，从积土、积水推论到积善，正面论述积累的作用，说明学习上的成就是不断积累起来的，接着又用“不积跬步，不积小流”两个比喻，从反面说明如果不积累就不能达到远大目标；第二层论述学习要持之以恒，先用骐骥与驽马对比，坚持不懈才是学好的关键，进一步说明只有坚持不懈、持之以恒才会有所成就；第三层论述学习要专一，作者用蚓和蟹两个比喻正反对照，说明做到积累和坚持不懈后还要专一。第一段的五个比喻（青取之于蓝而青于蓝、冰水为之而寒于水、木直中绳輮以为轮、金就砺则利）论述了学习的意义在于能提高人的智能、改造人的品性，使人智慧明达、不犯过错，学习的重要性被提升到了新的高度，学习是人类不断进步的阶梯。课末思考：本文的中心论点是什么——“学不可以已”。再讲《师说》。开场先讲作者韩愈与背景知识：韩愈是唐代古文运动的倡导者，所谓古文运动首先是文学上的一种改革；写作背景是当时士大夫耻于从师、师道不振，韩愈写《师说》抨击这种风气。逐句精讲第一段：“师者，所以传道受业解惑也”——老师是用来传授道理、教授学业、解答疑难的人，“所以”有两个固定意思，一是“用来”，二是“……的原因”；“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；“生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之”；“吾师道也，夫庸知其年之先后生于吾乎？是故无贵无贱，无长无少，道之所存，师之所存也”。讲到“耻学于师”与通假字，再讲“圣人无常师”与“巫医乐师百工之人，不耻相师”，以及“六艺经传皆通习之”中的“六艺经传”就是解释经的书。**中心论点与结构**：第一段提出中心论点并从两个角度阐述中心论点；第二段用对比论证——古之圣人其出人也远矣，犹且从师而问焉，今之众人其下圣人也亦远矣，而耻学于师；再拿巫医乐师百工之人与士大夫之族对比，句读之不知、惑之不解，小学而大遗；对比有横比和纵比，三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论；第三段以李蟠为例；最后引用论证收束。知识点总结后讲特殊句式：状语后置（如《曹刿论战》“战于长勺”，翻译过来就是“于长勺战”，即在长勺作战，介宾做状语、还后置了，所以叫状语后置）、省略句（如《桃花源记》“见渔人”，省略了主语“村民”，古文的原则是能省就省），并提醒学习古文最懵的就是省略，要多读几遍。全文收束：像《劝学》还有《师说》这些文章都很简单，老师不停地讲为什么要讲《劝学》、为什么要讲《师说》，都是在鼓励大家去学习——劝学是鼓励大家学习，师说是叫大家一定要端正自己求学的态度，把这些文章放在一起给大家讲，也是想让大家真真正正地意识到学习的重要性，因为学习可以改变你的命运，你不学习、你的命运就这样了，但是你学习之后一切皆有可能。", "vtech": [["劝学比喻题怎么答", "先认比喻本体和喻体：青取之于蓝而青于蓝（学习提高）、冰水为之而寒于水、木直中绳輮以为轮（改造品性）、金就砺则利；登高而招、顺风而呼、假舆马、假舟楫（善假于物）；积土成山、积水成渊、积善成德、不积跬步（积累）、骐骥一跃、驽马十驾、锲而不舍、金石可镂（坚持）、蚓无爪牙之利、蟹六跪而二螯（专一）；答题先点比喻、再说论证了什么。"], ["师说对比论证三组怎么分", "纵比：古之圣人其出人也远矣，犹且从师而问焉；今之众人其下圣人也亦远矣，而耻学于师；横比：巫医乐师百工之人不耻相师，士大夫之族耻相师；句读之不知、惑之不解，小学而大遗；三组对比一层层深入，得出圣人之所以为圣、愚人之所以为愚的结论。"], ["文言知识四件套怎么落实", "通假字、词类活用、古今异义、特殊句式四件套每篇先过一遍再进文本：如“受”通“授”、句读之不知是宾语前置、战于长勺是状语后置、见渔人是省略句；默写只考名句，先把主旨句写对。"], ["两篇主旨句怎么背", "劝学背“学不可以已”与“君子博学而日参省乎己，则知明而行无过矣”；师说背“师者，所以传道受业解惑也”与“人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣”；默写只考名句，先把这两句写对。"]], "vgaokao": []}}, "u_chn_13": {"id": "u_chn_13", "name": "反对党八股（节选）", "secs": "第11课", "pageFrom": 85, "pageTo": 87, "members": ["chn_c022"], "video": {"bvid": "BV1Lu411H7GG", "p": 1, "t": "反对党八股（节选）", "dur": "26:00", "from": "小熊图书", "vtop": ["党八股是党内某些人写的文章，如同八股文：八股文连字数都有限制，考生只能按题目字数敷衍成文，写出来的文章没有内容、只讲形式，是文字的游戏；党八股就是党内的这种不良文风，毛泽东持反对态度。", "本文写于1942年延安整风时期：整风三个方面是反对主观主义、反对宗派主义、反对党八股；全文分五个部分——总说反对党八股的必要性、分析党八股的历史根源和阶级根源、列举党八股的罪状并深刻剖析、提出打倒党八股的办法、照应开头号召彻底打倒党八股；本课选讲第三部分（八大罪状）。", "本视频只讲了前三条罪状：第一条空话连篇、言之无物；第二条装腔作势、借以吓人；第三条无的放矢、不看对象；第四至第八条老师说下节课继续讲，不在本视频内。"], "vsum": "本课讲《反对党八股》（节选），但只讲了八大罪状中的前三条：第四至第八条老师说下节课继续讲，不在本视频内。开场先讲八股文：这种八股文连字数都有限制，考生只能够按照题目的字数敷衍成文，所以最后写出来的文章是没有内容、只讲形式的文章，是文字的游戏；党内也出现了类似八股文的现象，所以伟大的领袖毛泽东就需要反对党八股。学习目标有三：学习作者的论证方法（列举、比喻等论证方法，表达方式也是论证方法的一个扩展），学习作者在写作时生动活泼的语言风格，从内容上了解不良文风的具体表现；还要掌握论点、论据、论证三要素。**作者与定义**：作者是毛泽东；党八股指的是党内某些人所写的文章，就如同八股文，所以被毛泽东称为党八股；对此党八股，毛泽东持反对的态度。**写作背景**：本文是毛泽东 1942 年在延安整风运动中写的文章；当时整风有三个方面，一个是反对主观主义，一个是反对宗派主义，而第三个就是反对党八股；争取抗日战争的最后胜利，这是当时的社会背景。**全文共分为五个部分**：第一部分是总说反对党八股的必要性；第二部分是详细地分析党八股的历史根源和阶级根源；第三部分就列举了党八股的罪状，对党八股进行全面而深刻的剖析；第四部分提出打倒党八股的办法；第五部分照应开头，号召人们彻底打倒党八股。**本课选讲第三部分，即党八股的罪状**。选文又分三部分：第一部分概括党八股的八大罪状，引出下文对八大罪状的具体分析和批判；第二部分从党八股的第一条罪状一直到第二条、第三条、第四条、第五条罪状，第六、七、八条到此处来了一个总结；第三部分总结前文的阐述，反对党八股、树立马克思列宁主义新文风的重要意义。接着逐条讲罪状。**第一罪状：空话连篇，言之无物**。**第二罪状：装腔作势，借以吓人**。主观主义和宗派主义表现在党八股式的文章和演说里面，却深怕人家不懂，非常胆怯，于是就靠装样子吓人，以为这一下人家就闭口了、自己就可以得胜回朝了；这里分析了第二条罪状产生的原因，就是想要吓唬别人、让别人不敢说话，深刻揭示了写这种文章的人表面上很厉害、实际上内心是空虚的心理状态；“得胜回朝”原指取得胜利归来，此处用来写党八股装腔作势、吓过别人后自以为是、自以为成功、自欺欺人的心理状态，这里用词是反语，反语能够达到辛辣尖锐讽刺的效果，加引号表示反语、否定和讽刺的效果。整个段落的论证思路是：先摆出第二大罪状，并且来分析它的原因和危害——作者先在和空话连篇的比较中摆出第二重罪状，说他简直是无赖，接着分析他产生的原因，即是主观主义、宗派主义，并非真理，最后指出他的危害，即不能反映真理、而是妨碍了真理；行文思路是先摆出罪状、分析问题，最后指出危害；同时作者结合党内斗争的历史教训进一步分析他的危害：首先指出了“残酷斗争”和“无情打击”这两种手段，尖锐地分析了错误地应用这两种手段的原因，及没有分析清楚该针对什么样的对象，所以来装腔作势、借以吓人，最后进一步指出吓人战术的危害及其本质，以吃饭这样的事情来做比喻，明确指出共产党要靠马克思列宁主义的真理、靠实事求是才能够吃饭，表明自己鲜明的立场、得出结论，才能够正面阐明观点。**第三罪状：无的放矢，不看对象**。“的”指的是靶心，即没有把心去放箭、不看对象，这就是他们写文章存在的问题；这一段主要论述做宣传工作必须要有“的”，“的”指的是群众，必须要联系实际，这也是一个“的”；开篇举了“工人”两个字的写法，从反面批评某些做宣传工作的同志没有“的”、脱离了“的”、脱离了实际的做法，又从正面指出共产党员如果真想做宣传就要看对象；接着通过分析那些不看对象的人的心理，揭示这一党八股调的主观主义思想实质，并创造性地运用“对牛弹琴”这一成语，对无的放矢、不看对象的党八股给予讽刺和严厉的批判；最后用“射箭要看靶子，弹琴要看听众，交朋友要互相知心”这样的大众常识来做比喻，从正面说明做宣传工作必须要联系实际、要有调查的对象、要联系实际，从而进行调查研究分析，这才是正确的做法。课末小结：老师已经讲了三条罪状，大家先消化，下一节课继续讲党八股的第四条罪状，看看下面的四、五、六、七、八到底是什么样的罪状、作者又想表达什么。", "vtech": [["罪状段落的论证思路怎么答", "先摆出罪状，再分析它产生的原因（主观主义、宗派主义），最后指出它的危害（不能反映真理、反而妨碍真理）；答题按“摆罪状—析原因—指危害”三步走，别只抄罪状名字。"], ["反语和比喻怎么辨", "“得胜回朝”原指取得胜利归来，这里写党八股装腔作势吓过别人后自以为成功、自欺欺人，是反语、加引号表示否定和讽刺；“吃饭”比喻共产党要靠马克思列宁主义的真理、靠实事求是才能够吃饭；“射箭要看靶子、弹琴要看听众、交朋友要互相知心”是大众常识作比喻，正面说明做宣传工作必须联系实际。"], ["无的放矢的“的”指什么", "“的”指的是靶心：没有把心去放箭、不看对象；做宣传工作必须要有“的”，“的”就是群众、就是实际；开篇举“工人”两个字的写法，从反面批评某些做宣传工作的同志脱离了“的”、脱离了实际。"], ["八大罪状只记住前三条够不够", "不够：考试若问八大罪状，要知道本视频只讲了前三条（空话连篇、装腔作势、无的放矢），后五条在下节视频；先把前三条的罪状名、表现、原因、危害背熟，再补后五条。"]], "vgaokao": []}}, "u_chn_14": {"id": "u_chn_14", "name": "拿来主义", "secs": "第12课", "pageFrom": 88, "pageTo": 93, "members": ["chn_c023"], "video": {"bvid": "BV1JB4y1G7kF", "p": 20, "t": "拿来主义", "dur": "27:19", "from": "名师课堂", "vtop": ["全文分两部分：第一部分1–7段破，先破闭关主义、送去主义，再破送来主义，层层剥落各种文化现象、从而引出中心；第二部分8–10段立，集中阐释拿来主义的主张。", "中心论点是“我们要运用脑髓，放出眼光，自己来拿”，三个关键词：运用脑髓（独立思考、分辨是非）、放出眼光（既开阔宽广、又深刻独到）、自己来拿（敢拿、会拿）。", "杂文特点：结合现实、针砭时弊，提出观点不是主要目的、有现实针对性才是写作原则；作者不是一上来就提出中心论点，而是层层剥落各种文化现象从而引出中心，这是杂文和一般议论文结构有区别的地方。"], "vsum": "本课讲鲁迅《拿来主义》，全文讲全了，没有缺口。开场：今天我们来学习第十二课，鲁迅先生的《拿来主义》；在这篇文章中，鲁迅先生提出，运用脑髓，放出眼光，自己来拿。**作者介绍**：鲁迅，原名周树人，鲁迅是他发表《狂人日记》时所用的笔名，也是他影响最为广泛的笔名；鲁迅曾把杂文分为社会批判和文明批判，所强调的正是杂文的批评与批判的特点，顺次翻开鲁迅的十多本杂文集，就可以看一部不停息的批判；鲁迅杂文所显示的这种不屈不挠、战则不止的不屈精神，从根本上有别于传统士大夫的中庸之道，集中体现了鲁迅其人其文的现实性与反叛性。**写作背景**：鲁迅针对当时种种社会文化现象，深思熟虑后提出拿来主义。**第一部分 1–7 段**，先破后立：鲁迅曾说，杂文家批评一个人或一种社会现象、文化思潮，常加以简括的名称，虽只寥寥数字，却需要明确的判断力和表现的才能；这篇《拿来主义》用的也是这样的简括法，把当时对待外来文化的种种错误态度概括为闭关主义、送去主义、送来主义，再确立拿来主义的观点。第一段提出闭关主义和送去主义：在清政府奉行闭关主义的锁国政策下，闭关主义的本质就是排外，而危害则是清政府的丧权辱国，比喻成碰了一串钉子，暗含着讽刺的意味；接着论述送去主义，鲁迅敏锐地注意到，只送不拿、只输出不输入，这是一种媚外行径。第二段提出拿来的主张，这里需要大家注意，文章批判的锋芒不是对着几位艺术家，而是针对媚外的国民党当局及其反动文人。第三段指出，送去主义者盲目自大，送去主义的危害在于对文化只是自我陶醉、而不思变革进取，长此以往，丧失主动权，只能被动接受别人的残羹冷炙。四五六段集中分析送去和送来的关系：第四段揭示了送来的真实面目，即“抛给”——鲁迅一语中的，不要误解为抛来的东西，这是抛给的，说得文雅些，可以称之为送来；请大家比较一下抛来与抛给的感情色彩，抛来是个中性词，没有轻蔑侮辱的意味，不过是自己不要的东西扔出来罢了，而抛给犹如送来之物，含有轻蔑和鄙视，更多了强迫和不怀好意；鲁迅先生说，对送来的东西不想举出实例，其实这背后也是有现实的针对性，1933 年，国民政府和美国签署了棉麦借款协定，购买美国的小麦、面粉和棉花，美国借此向中国倾销了大量物资；所以第五段再次强调了送去之外还得拿来；为了进一步阐述送去与拿来的关系，文章没有直接论述，而是在第六段对送来继续列举事实、揭示本质：先有英国的鸦片，德国的废枪炮，后有法国的香粉，美国的电影，日本的印着“完全国货”的各种小东西；大家可以思考，这些外国势力送来的东西有什么特点：既有毒害国民身体的毒品，也有不能使用的军事武器，还有日用品，更有文化和思想的输出，可以说覆盖了社会生活和精神的方方面面；这是抛给的，是强制接受并且不允许选择，不同于主动的拿来，实际上是一种经济倾销、文化扩张；在鸦片战争以来的历史上，是西方殖民者军事、政治、经济侵略的伴随物；通过分析送来的本质，鲁迅先生启发我们认识送去与送来的关系：如果只是一味地送去，本质上是一种文化保守主义，最终会导致外国势力无孔不入的侵略和渗透，也就是送来；必须在送去之外奉行拿来主义，与外国在经济、技术、文化上进行双向交流；此外，第六段还直接揭示了送来的危害，连清醒的青年们也对洋货发生了恐怖，这就表明被动接受送来的东西，一方面处于被侵略的地位，另一方面也导致社会对西方文化的全面排斥和恐惧；一味送去的保守主义和媚外行径不可取，而盲目排外的主张也不可取；所以我们要运用脑髓，放出眼光，自己来拿，于是第七段就提出了拿来主义的宗旨。第一部分为了阐明中心论点拿来主义，运用了驳论和立论相结合的论证方法：第一段批判闭关主义和送去主义，用讽刺的语言暗中指出各自的本质；第二段提出拿来，有破有立；第三段借指出送去主义的危害引出送来及抛给；第五段再次明确拿来的必要性；第六段进一步指出送来的本质和危害；第七段明确拿来的宗旨；由此可以体察到鲁迅先生的思路。本文提出了拿来主义的主张，杂文的一个特点即结合现实、针砭时弊，第一部分鲁迅先生针对当时种种社会文化现象，深思熟虑后提出拿来主义；提出观点不是杂文的主要目的，有现实针对性才是杂文的写作原则；所以读这篇文章，我们发现作者并不是一上来就提出中心论点，而是层层剥落各种文化现象，从而引出中心，这也是杂文和一般议论文结构有区别的地方。“我们要运用脑髓，放出眼光，自己来拿”，这是对拿来主义的概括，也是本文的中心论点，这里有三个关键词：运用脑髓、放出眼光、自己来拿；其二，放出眼光，既开阔宽广、又深刻独到。**第二部分 8–10 段**，集中阐释了拿来主义的主张：第八段以大宅子比喻外来文化，展开形象化论述；对待大宅子的三种态度，一是孱头，害怕继承、拒绝借鉴，二是勃然大怒、放一把火烧光的昏蛋，三是欣欣然接受一切的废物；第九段一上来就从正面具体而形象地阐明了拿来主义的原则和方法，“占有”呼应了第八段的“首先是不管三七二十一，拿来”，即敢拿；挑选呼应运用脑髓、放出眼光、自己来拿，即会拿；敢拿和会拿是拿来主义的两个重要内涵；鱼翅是文化中精华的部分；用鸦片比喻有利有弊的部分；用烟枪烟灯和姨太太比喻完全的糟粕；拿来主义凝结了三重内涵：沉着、勇猛、有辨别、不自私。**现实意义与收束**：运用脑髓、放出眼光、自己来拿，就是一个既要敢拿、又要会拿的创新的过程；创新需要有眼光、有魄力，既能分辨、又不要丢掉文化自主性，既要广泛接纳、又要有文化自信；沉着、勇猛、有辨别、不自私，这就是真正能面对世界、理直气壮与世界对话、向世界学习、同时宣传自己文化的心态；即使到今天，鲁迅先生的拿来主义仍然具有现实意义；在文艺成为新文艺的过程中，鲁迅先生敏锐地发现，没有拿来的人不能自成为新人；在民族新文化形成的过程中，既要冲破传统、向西方学习科学和物质文明，又要保持警惕、吸取西方的教训、重视传统文化的传承和重建；而其中最有价值的，鲁迅先生提醒我们，不要忘记根底在人，在人的解放和民族精神的重建，也就是培养新人；这是和鲁迅先生的启蒙思想和改造国民性的观念一脉相承的；由此也启发当下的我们思考，发扬我们的民族文化、树立文化自信，重要的是培养有眼光、有辨别、有创新、不自私的人才。**总结**：借课堂反馈的题目共同进行总结：一、用富有画面感的构思，借助比喻，把深奥的道理说得通俗易懂，用大宅子比喻外来文化，用孱头、昏蛋、废物比喻对待外来文化三种不同的态度，用鱼翅、鸦片、烟枪和烟灯、姨太太比喻外来文化中不同的组成部分；二、用幽默犀利、讽刺性强的语言，鲜明地表达自己的观点态度，例如“只有烟灯和烟枪，虽然形式和印度、波斯、阿拉伯的烟具都不同，却可以算是一种国粹”——国粹原指传统文化中的精华，这里是反语，暗含着讽刺意味，指文化中应该抛弃的部分。", "vtech": [["孱头、昏蛋、废物怎么答", "对待外来文化的三种态度：孱头是害怕继承、拒绝借鉴，昏蛋是勃然大怒、放一把火烧光，废物是欣欣然接受一切；三者都不对，拿来主义是沉着、勇猛、有辨别、不自私。"], ["鱼翅、鸦片、烟枪烟灯、姨太太怎么答", "用鱼翅比喻文化中精华的部分；用鸦片比喻有利有弊的部分；用烟枪烟灯和姨太太比喻完全的糟粕；只有烟灯和烟枪，虽然形式和印度、波斯、阿拉伯的烟具都不同，却可以算是一种国粹——国粹原指传统文化中的精华，这里是反语，暗含讽刺意味，指文化中应该抛弃的部分。"], ["抛来与抛给怎么辨", "抛来是个中性词，没有轻蔑侮辱的意味，不过是自己不要的东西扔出来罢了；抛给犹如送来之物，含有轻蔑和鄙视，更多了强迫和不怀好意；送来的东西是抛给的、强制接受并且不允许选择，不同于主动的拿来，实际上是一种经济倾销、文化扩张。"], ["送去与送来什么关系", "只是一味地送去，本质上是一种文化保守主义，最终会导致外国势力无孔不入的侵略和渗透，也就是送来；必须在送去之外奉行拿来主义，与外国在经济、技术、文化上进行双向交流；被动接受送来的东西，一方面处于被侵略的地位，另一方面也导致社会对西方文化的全面排斥和恐惧——一味送去的保守主义和媚外行径不可取，盲目排外的主张也不可取。"]], "vgaokao": []}}, "u_chn_15": {"id": "u_chn_15", "name": "读书两篇", "secs": "第13课", "pageFrom": 94, "pageTo": 99, "members": ["chn_c024"], "video": {"bvid": "BV1H14y1H7aA", "p": 1, "t": "读书两篇", "dur": "47:53", "from": "项仁军名师工作室", "vtop": ["本课精讲王佐良《上图书馆》，黑塞《读书：目的和前提》在比较阅读与课堂延伸中对照讲：两篇都与读书有关，但论述内容不同——黑塞讲阅读经典是获得真正教养的最重要途径、提出正确的读书观；王佐良写自己在不同图书馆读书的几段经历，讲读书之乐。", "上图书馆之乐分四种：文华中学图书馆的启蒙之乐、清华大学进入新世界之乐、飘摇中获得宁静之乐、感悟知识理性伟大力量之乐；开头引用名言引出“上图书馆之乐”，结尾引用阿尔比斯的台词说明人类创造了知识理性那种伟大的力量和高贵的理性。", "健康的阅读观三问：为什么读书（获得鲜活的知识、意识和理解，由此获得满足和幸福；启示思考、获得意义、增强自我意识）、读什么书（能引起共鸣的书、真正的杰作，而不是报纸或粗浅的流行文字）、如何读书（专注态度、花力气下功夫、认识自己、不盲从不教条、培养有教养的人格）。"], "vsum": "本课精讲王佐良《上图书馆》，黑塞《读书：目的和前提》在比较阅读与课堂延伸中对照讲，两篇都讲到了，没有缺口。开场先定本课：今天学习这个单元的最后一课《上图书馆》，学习目标是品味王佐良的读书经历，品味读书场景的描写，品读分析王佐良的读书观。**作者王佐良**：正统教育出身，作为中国莎士比亚学会成员、翻译研究会成员，留学牛津大学攻读英国文学研究生，回国以后在中国莎士比亚学会任职；其读书经历与上大学、参加工作都与文化、图书馆相关。先落实字音：教义、音训、高耸、苍穹、白炽、赤灯、见习、复复等第一组字音要注意。**第一段到第三自然段**引用名言引出“上图书馆之乐”这个标题，然后写作者上图书馆的经历。**第一部分 4–5 自然段**写中学阶段上图书馆：作者上的是文华中学，写的是文华中学图书馆；接着写上大学的时候：清华大学图书馆，说的是清华图书馆；然后是牛津大学的博德林图书馆，博德林就是牛津大学图书馆；后来又到大英博物馆的图书馆去读书的情况；最后一句说上图书馆也有其奇趣。第十自然段点出“上图书馆之乐”。随后梳理作者不同阶段的读书选择和读书的感受与思考，养成看英文杂志的习惯。**上图书馆之乐分写四种**：文华中学图书馆的启蒙之乐，清华大学进入新世界之乐，飘摇中获得宁静之乐，感悟知识理性伟大力量之乐；概括第三自然段“上图书馆之乐”分写的就是这四种乐。接着进入研读阶段，把握观点和论证方法、文中开头与结尾：结尾直接引用阿尔比斯的台词，说明人类创造了知识理性那种伟大的力量和高贵的理性。表格梳理：上图书馆之乐有什么——启蒙之乐、进入新世界之乐、知识理性高尚伟大力量之乐等，对自身的影响从哪些角度写——在进出自己上图书馆的经历时，多次写到了自己因受到外界影响而产生不同的心情。由此做一个探究：有人认为读书就应该是家事、国事、天下事事事关心，也有人认为读书就应该是心无旁骛、两耳不闻窗外事、一心只读圣贤书，你怎样看待这一问题？答案是读圣贤书与关心窗外事并不矛盾：读圣贤书要专心致志、心无旁骛，闲暇时就了解社会、浏览新闻、把握时代的脉搏，天文地理、政治、各地风土人情、民俗特色，逐一品味这一道道文化的大餐，把读圣贤书与关心窗外事结合起来，让圣贤书的理论开启我们的智慧、引领我们去深刻认识社会，练就我们的思维、培养我们的能力，然后以我们的能力再去丰富圣贤的理论，让圣贤之书发扬光大、代代传承；既要家事国事天下事事事关心，还要参加社会、国家的建设。**整合拓展：比较阅读**。《读书：目的和前提》与《上图书馆》这两篇文章都与读书有关，他们论述的内容有什么不同？《读书：目的和前提》主要论述阅读经典是获得真正教养的最重要的途径之一，并阐明阅读经典著作的重要意义，提出正确的读书观，比如“书中自有颜如玉，书中自有黄金屋”那是东方的读书观点；而《上图书馆》写作者在不同图书馆读书的几段经历，从而表明读书之后这个乐有启蒙之乐、进入新世界之乐、飘摇中获得宁静之乐、感悟知识理性伟大力量之乐。两篇文章的相同点：都是按时间顺序记叙，都写到了自己不同时期读到的书籍和自己的感受与收获；不同点：《读书：目的和前提》描写自己的感受和收获比较详细具体，《上图书馆》在叙述中还写到了各个图书馆的建筑华美等特点。**课堂延伸**：黑塞第一篇中说到“红房子”，第一次是阿尔卑斯南面的芬芳的红房子，第二次是正如白昼、春夜和夜晚之间，我的人生、旅行欲望和安家愿望之间渐渐消逝；如果有一个中心，所有的例子是从这个中心发现了两端摆动，那时生活是多么的不同，但是我生活没有这样的一个中心，没有这样的中心就是把我变成另一个模样的，不是我的事情，这是神奇的事情，谁要寻找神奇、谁要把他引来、谁要帮助他，他就逃避谁；其实作者说我的事情是漂浮在许多紧张对立的矛盾之间，并且做好了精神准备，如果奇迹突然降临到我头上，我的事情是不满并忍受着动荡不安；然后绿色花园中的红房子，我对你已经有过体验，可我不想再次体验；第七段说我还会走许多弯路、将还讲失望许多，有许多愿望，但到头来仍然会使我失望，总有一天一切都显示它的意义；那矛盾消失的地方，是涅槃境界，还是可爱的眷念的群星，还向我放射出明亮的光。根据整篇文章的阅读，阐释“红房子”的两层意思：第一层是实质的，红色房子和舒适的现实生活；第二层是象征，实现理想以及愿望，是象征手法。文章第八段画线句子应该怎样理解：矛盾消失的地方，是指人生不停追求的渴望和对安宁生活向往之间的这种矛盾得到解决的境界，矛盾消失了，那可爱的眷念的群星还向我放射出明亮的光，是指到达一个理想境界、实现一个愿望之后，人又会产生新的愿望、永远不会满足。在语言表达方面有什么特色：首先用了比较丰富的修辞，比如第一自然段的比喻、第四段的反复、第六段的排比，这都是高考必考的修辞，比喻、反复、排比增加了文章的表现力；从表达方式来说，通常说四种表达方式——叙述、议论、抒情和说明，本文用了叙述中的描写、议论和抒情，灵活多变、相辅相成；人称使用方面角度转换自由，第一段和第六段用了第二人称“你”，与红房子面对面交流、便于抒发作者的感情，第一、第二、第三人称都有，这是本文在语言表达方面的特色。**观念性阅读**：第一篇黑塞创作大约在一战前后，强权主义已经开始甚嚣尘上，所以文中会有为数众多的年轻人似乎觉得舍弃愉快的生活而埋头读书是既可笑又不值得的，这是一种事实性关联；王佐良主动外国文学及翻译，因此上图书馆的经历也主要围绕着英美文化等杂志和书籍展开，文章中也会有莎士比亚《哈姆雷特》的台词引用，无处不显示着外国文化的学术底蕴，这与当时的作者背景、经历是一致的；第二是观点性的关联：黑塞对于人性人格拥有非常深刻的思考和探索，他坚持提倡通过读书来提高修养、达到心灵和个性的自我完善；而王佐良在武昌文华中学、西南联大（清华大学）、牛津大学读研留学，养成了良好的读书习惯，拥有了深厚的学术功底，最终在外国文学翻译上有如此卓著的建树。**学生任务：健康的阅读观**。通过两位作家的两篇文章、两位作家的经历出发，你认为应该具备怎样的健康的阅读观呢？第一个问题是为什么要读书：要获得鲜活的知识、意识和理解，由此获得满足和幸福，还要启示我们思考、并获得意义、增强自我意识，就是自我阅读、个性和人格，追求真正的修养；第二个问题是读什么书：读能引起共鸣的书、真正的杰作，而不是报纸或者粗浅的流行文字；第三个问题是如何读书：专注态度、花力气下功夫、认识自己、不盲从不教条、培养有教养的人格。最后说一说随笔这种问题的魅力：随笔在结构上行文缜密而不失活泼，结构自由而不失严谨；形式上可以不受体裁的限制，灵活多变、不拘一格，可以观景抒情、也可以读书看报谈感想，一事一议、也可以同类事物综合议论，篇幅长短由内容而定；内容上获得文化知识、发表学术观点、评论世态人情，启人心智、引人深思、富有理趣，是随笔的突出特色。", "vtech": [["比较阅读怎么答", "先找相同点：两篇都在时间顺序记叙，都写了自己不同时期读到的书籍和感受收获；再找不同点：《读书：目的和前提》描写感受收获比较详细具体，《上图书馆》还写了各个图书馆的建筑华美等特点；最后落到关联性：事实性关联（黑塞一战前后、王佐良英美文化背景）与观点关联性（黑塞通过读书提高修养、达到心灵和人格自我完善；王佐良为外国文学翻译做出贡献）。"], ["“红房子”两层意思怎么答", "第一层是实质的：红色房子和舒适的现实生活；第二层是象征：实现理想以及愿望，是象征手法；第八段画线句“矛盾消失的地方……可爱的眷念的群星还向我放射出明亮的光”指人生不停追求的渴望和对安宁生活向往之间的矛盾得到解决的境界，愿望实现后人又会产生新的愿望、永远不会满足。"], ["语言特色三方面怎么答", "修辞：第一自然段的比喻、第四段的反复、第六段的排比，都是高考必考的修辞，增加了文章表现力；表达方式：叙述、议论、抒情和说明四种，本文用了叙述中的描写、议论和抒情，灵活多变、相辅相成；人称使用：第一段和第六段用了第二人称“你”，与红房子面对面交流、便于抒发作者感情，第一、第二、第三人称转换自由。"], ["随笔的特点怎么答", "结构上行文缜密而不失活泼，结构自由而不失严谨；形式上可以不受体裁限制、灵活多变、不拘一格，可以观景抒情、也可以读书看报谈感想，一事一议、也可以同类事物综合议论，篇幅长短由内容而定；内容上获得文化知识、发表学术观点、评论世态人情，启人心智、引人深思、富有理趣。"]], "vgaokao": []}}, "u_chn_16": {"id": "u_chn_16", "name": "故都的秋·荷塘月色", "secs": "第14课", "pageFrom": null, "pageTo": null, "members": ["chn_c025", "chn_c026"], "video": {"bvid": "BV1JB4y1G7kF", "p": 22, "t": "故都的秋·荷塘月色", "dur": "26:52", "from": "名师课堂", "vtop": ["本课只讲《故都的秋》，《荷塘月色》不在本视频内，在合集P23（cid 818559469），后续补。", "文章结构：开头以感叹句抒发对秋的总体感觉、又荡开一笔拿江南之秋与北方之秋比较；三到十一段细腻描绘故都清秋景色；最后三段议论抒情收尾，再次将北方之秋与南方之秋比较，表达对故都之秋的深切怀念。", "五幅秋景图都取自北平普通老百姓的日常生活场景：破屋晨光、落蕊、秋蝉、秋雨、秋果；景物多半是冷色调的，写出清、静、悲凉——既是客观景物特点的描写和总结，又是作者内心的感受。"], "vsum": "本课只讲《故都的秋》一篇。《荷塘月色》不在本视频内，在合集 P23（cid 818559469），后续补。开场：今天学习必修上册第 24 课《故都的秋》。**作者简介**：郁达夫，中央人民政府追认为革命烈士。**写作背景与题目**：“故都”两个字指明描写的地点，不说北平而说故都，含有深切的眷念之意；“故都”与“古都”结合在一起，古都二字意味着北平不再是垂拱天下的政治中心；读出作者心中对这座历史名城的真爱赞叹以及深情的眷恋和向往。**文章结构十分精巧**：文章开头和结尾都以北国之秋和江南之秋做对比，中间细腻描绘故都的清秋景色，最后以议论和抒情收尾。文章开头就以一句感叹句抒发作者对于秋的总体感觉，也为全文奠定了基调；然而作者并没有沿着这个感觉往下陷，而是荡开一笔，将江南的秋拿来与北方的秋做比较，出现了北国之秋的浓烈、酣畅。那么到哪里去寻觅故都最有代表性的秋景呢？文章的三到十一段就是对故都的秋的细致描写，这些描写也是最能体现作家审美情趣的地方：他不写故都的皇家宫殿园林，也不写远近郊区众多优美的自然风光，顶多就是一笔带过——在南方每年到了秋天，总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，那些景致虽然也代表了故都的特色，但似乎离日常生活很遥远；他关注的更多是北平普通老百姓的日常生活场景。作者笔下的故都清秋主要集中在以下几种景致：住在人家一间破屋里，早晨起来看到碧绿的天色，听到鸽子的飞声，静静地对着喇叭花，疏疏落落的尖细且长的秋草；槐树的落蕊，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉，地上扫过之后留下的印记、灰土上留下的一条条扫帚的丝纹，看起来既觉得细腻、又觉得清闲，人意之下并且还觉得有点落寞；秋蝉，衰弱的残声，简直像是家家户户都养在家里的家虫；秋雨，稀里哗啦，一层秋雨一层凉，穿着很厚的青布单衣或夹袄的都市闲人，缓慢悠闲的声调；生长在屋角、墙头、茅房边上、枣树门口的枣子树，枣子、柿子、葡萄。从以上的事物可以看出，作者所描绘的都是故都普通人家日常的生活场景，是老百姓的日常生活环境，既不稀奇、也不富贵，但带着一股老北京所特有的悠闲、自如，又有一点落寞的感觉。这些景物的选区多半是冷色调的：房子是破屋，牵牛花以蓝色或白色者为佳，紫黑色次之，淡红色最下；不写长在树上的生气勃勃的槐花，而是已经落到地上快要干枯的花蕊，以及人们很少注意到的扫帚的痕迹。这些描写给人的感觉是不是特别的来得清、来得静、来得悲凉？这里的清、静、悲凉既是对客观景物特点的描写和总结，又是作者内心的感受；可以说，从寻常景象、甚至破败景象中看出、体验出美，正是郁达夫所独有的审美体验；这些细腻而独特的感受，显得淡而略显忧郁的情调，只有郁达夫这样一位传统且对孤独有真挚眷恋的读书人才能体验得到，也才能表现得这样细腻而深知。**文章最后三段是议论和抒情**：文章指出，无论是传统的文人学士，还是外国的诗人，都有很多关于秋的歌颂与悲叹，写秋的名篇特别多，因此得出结论——有感觉的动物、有情趣的人类，对于秋总是一样的能特别引起深沉、幽远、严厉、萧索的感触来的，而最能代表秋的深味的，就是这北国的秋天了；本章最后再次将北方的秋与南方的秋作比较，进一步表达了作者对故都之秋的深切怀念。在写景状物方面，本文极其精彩，而且包含作者的深情，情景完美交融，值得仔细体会、揣摩：如早晨起来，泡一碗浓茶，向院子一坐，你也能看得到很高很高的碧绿的天色，听得到青天下驯鸽的飞声，从槐树叶底朝东细数着一丝一丝漏下来的日光，或在破壁腰中静对着像喇叭似的牵牛花的蓝朵，自然而然地也能感觉到十分的秋意——这里写了视觉形象、听觉形象，景物写得非常细致，如一丝一丝漏下来的日光、像喇叭似的牵牛花的蓝朵，也写了观景赏景的心态动作如静对，给人以悠闲、惬意的感觉；又如北国的槐树，也是一种能使人联想起秋来的点缀，像花而又不是花的那一种落蕊，早晨起来会铺得满地，脚踏上去声音也没有、气味也没有，只能感出一点点极微细极柔软的触觉——这里写了视觉形象、触觉形象，花铺满地写视觉形象，脚踏花地是触觉感受，写触觉仿佛能拨动读者最微妙的感觉，给读者以逼真的感受；这里寂静无人，可以独自徘徊，静静享受与自然交融的情趣。**语言上也特别见功力**：文中有许多整齐的语句，排比句也很多，具有工整雅致之美，抒情味很浓厚，朗读起来又具有音韵之美，显示出作者很强的语言驾驭能力；“却特别的来得清、来得静、来得悲凉”三个短语精妙地概括了全文的意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾，语势舒缓，为文章整体抒情定下基础；“总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”这些描写性的名词短语，一个短语就是一幅画面，展现出生动的美景，成为故都的秋的美妙意境的重要组成部分，引人遐想，作者神往之情溢于言表。文章最后一段的语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语进去，运用“稀饭”“摸摸”“黄瓜”“大蟹”等词语，这些话语本来是缺乏诗意的，用在这充满古典的高雅趣味的文章中，是要冒不和谐的风险的，但是郁达夫却在这里构成了和谐的统一，这是因为他的情感亮点就是把大雅和大俗融为一体。**审美情趣方面**：秋天，无论在什么地方的秋天，总是好的，可是啊，北国的秋却特别的来得清、来得静、来得悲凉；郁达夫欣赏的正是这样一种萧瑟悲凉之美，因此文中所展示的是冷色调的牵牛花、已经落在地上的槐花的落蕊、疏疏落落的秋草等带有着衰败意味的景物，这些正体现了传统文人的审美情趣与审美追求。“不逢北国之秋已将近十余年了，在南方每年到了秋天总要想起陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声”——审美是一种情感和感觉，文学的审美，一般化的情感和感觉是很难感染读者的，关键在于要有特点；当时的北平是一座大城市，是政治、经济、文化、教育的中心，一般知识分子久违了这个大城市，怀念什么呢？是那里的行人熙来攘往的街道吗？是那里的繁华商场吗？是那里的大学校园吗？是那里的名胜古迹吗？如果怀念这些东西，不是很能表现郁达夫知识分子的情趣吗？但是，如果他怀念的就是这些五光十色、热热闹闹的场景，就没有他的文化修养和与众不同的个性了；陶然亭的芦花、钓鱼台的柳影、西山的虫唱、玉泉的夜月、潭柘寺的钟声，没有大城市的商业繁华，也没有生活的喧嚣闹腾，相反，他所选中的芦花非常朴素，从形状到色彩几乎没有什么花的特点；是不是北平就没有比芦花更为鲜艳的花呢？当然有，西山的红叶、公园中的菊花就是鲜艳夺目的，但是都被郁达夫的记忆筛选掉了；他所选中的公园不是游人如织的圣地，而是比较幽静的陶然亭，就是在这比较安静的公园中，他所钟情的恰恰又平淡得只剩下柳条的影子；西山的虫唱，有的是野趣，与其说是大都市的，不如说是乡村的；潭柘寺的钟声，给人的联想是古老、宁静而幽远；在大城市的喧嚣中，没有宁静的心情是感受不到的；郁达夫所营造的孤独之美，在于超越了大城市的喧嚣。课末讨论：前四幅秋景图体现了清、静、悲凉的特点，容易理解，而最后一幅图画代表着丰收、代表着喜悦，是否与全文基调相悖？并不相悖：作者在这段中说道，像橄榄又像鸽蛋似的这枣子颗，在小椭圆形的细叶中间显出淡绿微黄的颜色的时候，正是秋的全盛时期；但之后紧接着说，等枣树叶落、枣子红完，西北风就要起来了，北方就是沙尘灰土的世界，在反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅能看到秋的衰败、更能看到秋的丰收，体现了作者细致、全面的感知力和审美力。", "vtech": [["五幅秋景图怎么背", "按顺序记：破屋晨光（碧绿的天色、鸽子飞声、喇叭花、秋草）、落蕊（槐树落蕊、脚踏上去声音也没有、气味也没有、只能感出一点点极微细极柔软的触觉）、秋蝉（衰弱的残声、家家户户都养在家里的家虫）、秋雨（一层秋雨一层凉、都市闲人缓慢悠闲的声调）、秋果（枣子、柿子、葡萄）；考写景就按这五幅图的顺序答。"], ["“清、静、悲凉”怎么答", "“来得清、来得静、来得悲凉”三个短语精妙概括全文意旨，既有递进的气势、又有一扬顿挫的声韵之美，先用两个单音节词、又以一个双音节词结尾；答题要说清既是客观景物特点、又是作者内心感受，从寻常甚至破败景象中看出美、体验出美，正是郁达夫独有的审美体验。"], ["秋果图与基调相悖吗", "不相悖：枣子红时是秋的全盛时期，但之后紧接着说等枣树叶落、枣子红完、西北风就要起来了，北方就是沙尘灰土的世界，反衬之后依然是萧索与悲凉；作者对秋的感受是全面的、整体的，不仅看到秋的衰败、更能看到秋的丰收，体现细致全面的感知力和审美力。"], ["语言特色大雅大俗怎么答", "文章最后一段语言既有古典诗文的典雅、又有现代白话文的通俗：郁达夫把秋写得这么有诗意，赋予一系列诗意的高雅话语，然而不时又穿插一些平民的俗语（稀饭、摸摸、黄瓜、大蟹等），这些话语本来缺乏诗意，用在充满古典高雅趣味的文章中是要冒不和谐风险的，但郁达夫却构成和谐统一，因为他的情感亮点就是把大雅和大俗融为一体。"]], "vgaokao": []}}, "u_chn_17": {"id": "u_chn_17", "name": "我与地坛（节选）", "secs": "第15课", "pageFrom": null, "pageTo": null, "members": ["chn_c027"], "video": {"bvid": "BV1JB4y1G7kF", "p": 24, "t": "我与地坛（节选）", "dur": "27:14", "from": "名师课堂", "vtop": ["全文在作者与假想对象地坛的对话中展开，有两条线：一是作家与地坛非同寻常的亲情关系，二是作家对地坛中几个人物的观察、描写和思索；地坛是作者的精神家园，母亲是他的生命家园。", "地坛三处景物描写（第三、第五、第七自然段）用情景交融、情理结合的方法写：古园历尽沧桑的建筑和景物有着看尽繁华后的平静，连野草荒藤也都茂盛得自在坦荡，抚慰作者内心的痛苦、缓解迷茫的心绪，暗示生命的启示。", "母亲的形象靠动作写：目送、寻找、“知道”；母亲疼爱而且能够理解儿子，沉静、理性、意志坚韧；车辙与脚印合二为一——园中处处都有过我的车辙，有过我的车辙的地方也都有过母亲的脚印，我的成长处处离不开母亲的启发。"], "vsum": "本课讲《我与地坛》（节选），地坛与母亲两部分都讲全了，没有缺口。开场：今天就让我们带着这样的问题，沿着一道道轮椅的痕迹，走进地坛，去探索文学世界里的人生答案。学习目标之一是体会作者对生命的思考及对母亲的怀念之情，激发对生命和生活的热爱。**走近作者**：史铁生的写作与他的生命完全同构在了一起，在自己的写作之夜，他用残缺的身体说出了最为健全而丰满的思想；他体验到的是生命的苦难，表达出的却是存在的明朗和欢乐。**《我与地坛》是史铁生散文的代表作，写于 1989 年**：从他的腿残疾到写此文的漫长岁月中的大部分时间，他都是在地坛中度过的；地坛却于风吹雨打中，史铁生觉得他和地坛冥冥之中有一种缘分——他在找不到工作、找不到路、忽然间几乎什么都找不到了的情形下走进地坛。**全文在作者与假想对象地坛的对话中展开**：其一是作家与地坛的那种非同寻常的亲情关系，其二是作家对地坛中的几个人物的观察、描写和思索。作者从自己为何踏进这座古园写起，写了地坛四百多年的等待，与我冥冥之中的到来；作者在第二自然段说，地坛离我家很近，或者说我家离地坛很近，二者的变化实质上表现了作者的心路历程。21 岁时突至的残疾，使他人生道路急转直下；地坛对于作者来说是一种慰藉。**三处景物描写**：作者运用情景交融、情理结合的方法，对地坛进行了三处景物描写。第一处景物描写在第三自然段；第二处在第五自然段，写园子里小生命的顽强生命力；第三处在第七自然段。古园里历尽沧桑的建筑和景物，有着看尽繁华后的平静，连野草荒藤也都茂盛得自在坦荡，这样的景致抚慰了作者内心的痛苦，缓解了他迷茫的心绪，也使他感到生命的启示似乎在暗示给作者；在作者眼里，能够无拘无束、自由自在地飞，是多么让人艳羡的事；坐在轮椅上的史铁生，面对地坛充满生机的一切，虽有如同树上的蝉蜕一般的寂寞感；古老又充满生机，展现出自然景物的永恒，体现出作者对生命的思考，也显示了作者高超的语言表现力。**与自己对话**：作者在静默的氛围中学会了自己与自己的对话，深陷轮椅、空间缩小，但时间延长，于是有了更多的时间去想，想的内容是关于死的事，想过我为什么要出生；这样想了好几年，最后事情终于弄明白了；在这里，作者不是在讴歌死亡，而是在表达玄想或放下死亡后的轻松释然；地坛启发作者把握人生的意义；作者由最初的逃避者成长为思想者，由最初的几度选择赴死到最后选择向死而生。**另一个重要人物：作者的母亲**。如果说地坛是作者的精神家园，那母亲则是他的生命家园。这一部分是以“总是独自跑到地坛去的我，给母亲出了一个难题”开场的：这个难题就是残疾又沉默寡言的儿子总是独自地去地坛，这时本已痛苦的母亲更增加了悲伤和恐惧，却又不知道为儿子做些什么；然后围绕这个难题，作者回顾了当时自己的心路历程，以及由此而给母亲带来的烦恼痛苦。这一部分对母亲的塑造只有极少的语言描写，更多的是动作描写：在儿子陷入切肤之痛、无路可走的困境时，再多安慰的话都显得苍白，至爱无声，母亲只是默默地去做、去关注儿子的一举一动，用她宽容和隐忍的爱去温暖孩子的世界；她能做的就是送与寻找——当作者出门去地坛时，母亲想送，又不敢送，于是只能目送；当作者有事折回时，母亲仍站在原地，而且还是送我走时的姿势，她的眼睛依然望着我拐出小院去的那处墙角，并且她对我的回来竟然一时没有反应；“站”“送”“望”和“没有反应”这几个静态重词组构出一幅立体的画面，母亲的担忧、牵挂、心疼与无奈，诸多复杂的情感通过这些词语准确地表达了出来。母亲另外一个让人印象深刻的动作就是寻找：母亲的寻找是艰难的，因为她视力不好，端着眼镜像在寻找海上的一条船，与眼镜搭配的动词不是戴着、不是扶着，而是端着，可以想象母亲寻找时的极度艰难和胶着；母亲的寻找是无声的，她只是步履茫然又急迫地寻找，没有呼唤，没有对旁人的问询，对儿子爱得引人有度；她明白，痛苦只能自己咀嚼消化，别人代替不了的；于是她来找我、又不想让我发觉，只要见我还好好的在这园子里，她就悄悄地转身回去；儿子总是独自跑到地坛去，母亲能做的只是目送、只是寻找，没有抱怨、没有祈求，因为她不是那种光会疼爱儿子而不懂理解儿子的母亲。为了表现这一点，文中几处用了一个平平常常、但特别打动人心的动词，那就是“知道”：她知道我心里的苦闷，知道不该阻止我出去走走，知道我要是老待在家里结果会更糟；但她又担心我一个人在那荒僻的园子里整天都想些什么；我那时脾气坏到极点，经常是发了疯一样地离开家，从那园子里回来又中了魔似的什么话都不说；母亲知道有些事不该问，便犹犹豫豫地想问、而终于不敢问，因为她自己心里也没有答案；她料想，我不会愿意她跟我一同去，所以她从未这样要求过；她知道得给我一点独处的时间，得有这样一段过程。这里的“知道”是一个特别有分量的动词：很多母亲疼爱孩子，但不知道自己的孩子；一位母亲对孩子的“知道”就是懂，就是理解，就是设身处地地站在孩子的角度去考虑问题，而唯独不考虑自己。母亲因为知道，所以包容，包容我那暴怒无常的坏脾气；因为知道，所以无言，无言地看着我摇车拐出小院。当然，母亲也有不知道，她不知道想要儿子重新站起来的过程得要多久，和这过程的尽头究竟是什么？这不知道的背后是母亲的痛苦、焦虑与忍耐。而与母亲的知道和不知道相对的，是我的不知道：我不知道她已经找了多久、还要找多久，我不知道为什么我决意不喊她，我甚至不知道被她惦念。正是在知道与不知道的强烈对比中，才会有母亲过世后作者无尽的愧疚、痛悔和遗憾。由此可以总结出母亲的形象特点：作者的母亲是一位疼爱、而且能够理解儿子，沉静、理性、意志坚韧的母亲。等到作者知道的时候，母亲已经不在了，他感到难以自抑的悲痛，于是，他又摇着轮椅来到这古园，他反复地想，为什么母亲不能再等两年？母亲盼望他找到的路是什么？他抱怨上天的不公，他反复想着同一件事，母亲已经不在了；正是在这反反复复的追思和推想中，母亲的苦难与伟大在他心中鲜明起来，而母亲那艰难的命运、坚忍的意志和毫不张扬的爱，在他心中愈加深刻，从而使他对母爱、对人生有了更深的体会，对生活、对未来有了更深的思考。文中还写到作者与作家朋友谈到学写作的最初动机时，进行了两者之间的对比，通过对比，突出了母爱的伟大，也突出了自己母亲苦难的命运，加深了作者痛楚、自责、思念的情感。第五段，那些苍凉的文字来自心灵深处，没有经历过痛苦的人，是写不出这样凝重苍凉的文字的，也永远感受不到在那苍凉的底色下汩汩滚动的热流。这部分将地坛、母亲与我的人生历程交织在一起：多年来，我头一次意识到，这园中不单是处处都有过我的车辙，有过我的车辙的地方，也都有过母亲的脚印。我们怎么来理解脚印、车辙、我、地坛以及母亲的关系？处处的脚印，也就是处处的关爱与牵挂，暗示出我的成长处处都离不开母亲的启发，就如同是地坛给予作者的生命启示一样；可以说正是母亲的这种活法，解答了他人应该怎样生活、怎样面对命运、怎样面对苦难的问题，使他在逆境中坚强起来。至此地坛的形象与母亲的形象合二为一：厚重、博大、宽容、隐忍；地坛是作者的精神家园，她等待我，以荒芜但并不衰败的形象启发我；人可以残废，但不能颓废，要学会在绝望中看到希望，勇敢地选择活下去；母亲是作者心灵的港湾，她执着的目送和寻找，给我无限的心灵慰藉；想使母亲骄傲的信念支撑作者在写作的道路上昂然前行。**收束**：《我与地坛》与前几篇写景抒情散文不同，它更多的是记叙作者的人生经历和心路历程，带有自传、自省、自述的意味；文章语言凝练生动、充满诗意，写景但不是对景物的客观描摹，更多的是将景物与自己的感受结合起来，写景中夹杂着叙事、抒情和议论，表达自己对人生、世界的看法，因此文章充满了哲学意味。史铁生在乐观的根据一文中写道，生命分为两种，一种叫做有限的身在，一种叫做无限的心魂；他在《我与地坛》中呈现出来的生命状态，已经超越了有限的身在，达到了无限的心魂；我们从史铁生身上看到的不是身体的残疾，而是精神的圆满，不是对苦难的哀痛，而是对命运的感恩，不是生命的禁锢，而是灵魂的自由；地狱和天堂都在人间，地狱和天堂是人对生命以及对他人的不同态度罢了；其实，既不是地坛的帮助，也不是上天的功劳，而是史铁生自己改变了态度，对生命、对他人，都有一份感恩之心、热爱之情，于是，他从黑暗走向了光明。", "vtech": [["母亲形象怎么答", "只用极少的语言描写、更多用动作描写：送与寻找——母亲想送又不敢送，只能目送；作者有事折回时母亲仍站在原地、还是送我走时的姿势，眼睛依然望着我拐出小院去的那处墙角，并且对我的回来一时没有反应；寻找——母亲视力不好，端着眼镜在寻找海上的一条船，步履茫然又急迫，没有呼唤、没有问询；“知道”——他知道我心里的苦闷，知道不该阻止我出去走走，知道我要是老待在家里结果会更糟；母亲因为知道所以包容、因为知道所以无言。"], ["“知道”与“不知道”怎么答", "母亲的知道是懂、是理解、是设身处地站在孩子角度考虑问题，而唯独不考虑自己；母亲也有不知道——她不知道想要儿子重新站起来的过程得要多久、这过程的尽头究竟是什么，不知道的背后是母亲的痛苦、焦虑与忍耐；与母亲的知道和不知道相对的，是我的不知道——我不知道她已经找了多久、还要找多久，我不知道为什么我决意不喊她，我甚至不知道被她惦念；正是在知道与不知道的强烈对比中，才会有母亲过世后作者无尽的愧疚、痛悔和遗憾。"], ["地坛三处景物描写怎么答", "第一处在第三自然段，第二处在第五自然段（园子里小生命的顽强生命力），第三处在第七自然段；作者运用情景交融、情理结合的方法，古老又充满生机，展现自然景物的永恒，体现作者对生命的思考，也显示高超的语言表现力；写景不是对景物的客观描摹，更多是将景物与自己的感受结合起来，写景中夹杂叙事、抒情和议论，表达自己对人生、世界的看法，文章充满哲学意味。"], ["向死而生怎么理解", "作者在静默的氛围中学会了自己与自己的对话，深陷轮椅、空间缩小，但时间延长，于是有了更多的时间去想，想的内容是关于死的事，想过我为什么要出生；这样想了好几年，最后事情终于弄明白了：由最初的几度选择赴死到最后选择向死而生；地坛启发作者把握人生的意义，人可以残废、但不能颓废，要学会在绝望中看到希望，勇敢地选择活下去。"]], "vgaokao": []}}, "u_chn_18": {"id": "u_chn_18", "name": "赤壁赋·登泰山记", "secs": "第16课", "pageFrom": null, "pageTo": null, "members": ["chn_c028", "chn_c029"], "video": {"bvid": "BV1JB4y1G7kF", "p": 25, "t": "赤壁赋·登泰山记", "dur": "24:41", "from": "名师课堂", "vtop": ["本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集P26），后续补。", "全文五段：第一段作者与友人夜游赤壁的情景；第二段作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段客对人生短促无常的感慨；第四段苏子针对客之人生短促无常的感慨表达自己的见解；第五段客听闻作者观点后转悲为喜、开怀畅饮。", "写景、抒情、说理完美融合、运用自如：写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然。"], "vsum": "本课只讲《赤壁赋》，《登泰山记》不在本视频内（在合集 P26），后续补。开场：黄州的赤壁因苏东坡闻名；今天我们学习的赤壁赋中的赤壁，是指湖北黄州的赤壁，俗称赤壁，但是它是否真的就是三国古战场的赤壁，却说法不一；为什么在苏轼前后赤壁赋和赤壁怀古的描绘中如此气势辉煌、波澜壮阔呢？**学习目标**：一、分析和把握文章观察景物的角度和表现景物的艺术手法。**全文五段大意**：第一段，作者与友人夜游赤壁的情景；第二段，作者饮酒纵歌的快乐和客人洞箫的悲凉；第三段，客对人生短促无常的感慨；第四段，苏子针对客之人生短促无常的感慨表达自己的见解；第五段，客听闻作者观点后转悲为喜、开怀畅饮。**第一段**：壬戌之秋，七月既望，苏先生同客人乘船在赤壁之下游玩，清风缓缓吹来，江面平静没有波澜，举起酒杯劝客人饮酒，诵明月之诗、歌窈窕之章；一会儿月亮从东山上升起，在斗牛之间徘徊，白茫茫的水汽笼罩着江面，波光连着天空，任凭小船飘去、越过那茫茫的江面，多么辽阔啊，像是凌空驾风而行、不知将停留在何处，多么飘逸啊，好像脱离尘世、升入仙境；他们泛舟于赤壁之下，沐清风白露、赏月色天光，兴致生发，信口吟出《诗经·陈风·月出》中“月出皎兮，佼人僚兮，舒窈纠兮，劳心悄兮”的名句，月亮皎洁升起、如同俏丽佳人。接下来写作者所见的月出之景：月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光，似对游人极为依恋；在皎洁的月光照耀下，白茫茫的雾气笼罩江面，天光水色连成一片，正所谓秋水共长天一色，开阔的景象使人心胸舒畅、无拘无束；临万顷之茫然，乘着一叶扁舟，飘飘乎如遗世独立、羽化而登仙。**第二段**：作者饮酒乐甚，扣舷而歌，客人中有吹洞箫的，依照歌曲的声调和节拍吹箫伴奏，箫声呜呜，像是怨恨又像是私慕，像是哭泣又像是倾诉；同时上文诵明月之诗、歌窈窕之章的内容也得到了具体化；由此可见，怀美人而不见，苏子本有些失落和哀伤，又有客吹洞箫为作者的歌声伴奏，箫声凄婉哀怨，如怨如慕、如泣如诉，余音袅袅、不绝如缕；使深谷中的蛟龙听了起舞，使独处孤舟的嫠妇听了落泪，也使苏子的感情陡转。**第三段**：苏子悄然，正襟危坐而问客，何为其然也？客人说：向西望是夏口，向东望是武昌，山水环绕一片苍翠，这不是曹孟德被周瑜围困的地方吗？方其破荆州、下江陵，顺流而东也，舳舻千里、旌旗蔽空，酾酒临江、横槊赋诗，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属；寄蜉蝣于天地，渺沧海之一粟；哀吾生之须臾，羡长江之无穷；挟飞仙以遨游，抱明月而长终；知不可乎骤得，托遗响于悲风。此段由赴赤壁的自然景物转而赴赤壁的历史古迹，主人以“何为其然也”设问，客人以赤壁的历史古迹作答，文理转折自然。接下来讲客人感慨的深层原因：连曹操这类英雄人物也只是显赫一时，因而反观自己生命短暂，羡慕江水涌流不竭，渴望与神仙遨游、与明月同存。**第四段**：苏子说，客亦知夫水与月乎？为江上之清风与山间之明月，再说天地之间万物各有主人；只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也，而吾与子之所共适；苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色。**第五段**：客人高兴地笑了，洗净杯子重新斟酒，菜肴和果品已经吃完了，杯盘凌乱地放着，大家互相枕着垫着睡在船中，不知不觉已经天亮了；这一段写大家在舟中饮酒尽欢、恣意畅饮，竟不知天色将明，此处再写游赏之乐，与开头照应，再次将读者引入忘怀得失、超然物外的境界。**艺术特色**：这篇作品写景、抒情、说理完美融合、运用自如，写景时景物清爽开阔、令人神往，抒情时情思幽渺畅达、淋漓尽致，说理时将抽象道理赋予具体形象，让说理变得生动自然；仁者乐山、智者乐水，是中国文化的传统；赤壁赋以江山风月为骨，富有层次地写了赤壁所见、历史之江月、哲理感悟之江月，体现出一种纯净出尘的美感；何满子在《赤壁赋赏析》中写道，凡是尽善的诗文，首先当然要求写景叙事生动有味，更需要写景叙事中注入作家浓郁的主观感情，才能神情飞动、气势昂然，倘若景与情交融之外，更能从物我之间及主客观的契合之间生发出哲理的意蕴，那便是上乘之作了；主客对答是赋体中传统的表现手法，也是全赋的重心所在，主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论；“渺渺兮予怀，望美人兮天一方”，作者因美人比君，可见忠君之殷切，情怀幽远。**收束**：作者借助对清风明月之美的描绘，展现思路图；作者在“哀吾生之须臾，羡长江之无穷”中流露了人生无常的消极情绪，但他并不沉沦于个人愁怀，而是主动丢开思想包袱，以江水明月作笔，从庄子的哲学中寻找人生之路；作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙，声调铿锵和谐，增强了文章的音乐美。", "vtech": [["主客问答怎么答", "主客对答是赋体中传统的表现手法，也是全赋的重心所在；主与客都是作者的化身，客的观点和感情是苏轼的日常感受和苦恼，而主人苏子所说的则是他超脱的、察人与宇宙之后的哲学领悟，前者沉郁、后者达观，前者充满人事沧桑与无声叹息的感慨，后者则表现了诗人与大自然合而为一的心灵进化的境界；赤壁赋中不仅是客与作者的灵魂对话，更体现了儒道的对话，是苏轼内心两个自我的辩论。"], ["“月出”与“望美人兮天一方”怎么答", "月出于东山之上、徘徊于斗牛之间，又借用诗中月如美人的描写，引出下一段作者自作之歌“望美人兮天一方”；诗中景与眼中景圆满契合，情感自然流泻，文气一气呵成；“徘徊”二字生动形象地描绘出柔和的月光似对游人极为依恋；作者因美人比君，可见忠君之殷切，情怀幽远。"], ["苏子怎么反驳“人生短促”", "苏子继承前文客所说的江水明月，以二物继续作比，认为流去的水像这样不断地流去、永不复返，而并没有流去，意味永在流淌；又何必羡慕江水、明月和天地呢；江上清风有声、山间明月有色；天地之间万物各有主人，只有这江上的清风和山间的明月，耳得之而为声、目遇之而成色，取之无禁、用之不竭，是造物者之无尽藏也。"], ["语言与音乐美怎么答", "作者饮酒乐甚，扣舷而歌，以抒发其思美人而不得见的、畅往诗意的胸怀；声调铿锵和谐，增强了文章的音乐美；全文错落有致、挥洒自如，犹如行云流水、极尽变化，既有整饬之美、又有通达流转之妙。"]], "vgaokao": []}}, "u_chn_19": {"id": "u_chn_19", "name": "词语积累与词语解释", "secs": "第八单元", "pageFrom": 125, "pageTo": 138, "members": ["chn_c030"], "video": {"bvid": "BV1JB4y1G7kF", "p": 28, "t": "词语积累与词语解释", "dur": "80:01", "from": "名师课堂", "vtop": ["本课由三讲拼成：丰富词语积累、词语解释（一词多义与成语古今词义）、词语运用（语境与语体色彩），三讲讲全了，没有缺口。", "积累词语的方法：抓住一个中心点，或语音或语义或语法，以点带面展开联想、触类旁通，就会形成一个词语的家族群；这样做不仅有益于词语积累，还更有助于记忆理解。", "一词多义看似纷繁复杂，其实也有规律可循：一个词的各个意义并不是孤立的，其间存在着各种联系，分析意义间的相互联系，往往就抓住了理解多义词的线索。"], "vsum": "本课由三讲拼成（合集 P28、P29、P30），三讲讲全了，没有缺口。**第一讲：丰富词语积累**。开场：今天我们共同来学习普通高中教科书语文必修上册第八单元第一课，丰富词语积累；说话写文章离不开词语，如同盖房子需要砖石一样，词和短语就是语言表达的砖石，我们需要做生活中的有心人，平时多读多记，积累尽可能丰富的词语，形成自己的词语库；词语库充实了才有选择的余地，才能更好地发挥语言的表现力。**学习目标**：一、多角度归类词语，让积累更加有效；二、学会将词语分类并用不同方法积累词语；三、探索词语尤其是成语中蕴含的文化现象，培养对词语的理解感悟与审美能力；四、学会用不同方法积累词语，培养对汉语文化的热爱之情；从小学到中学我们一直都在积累词语，但很多同学积累词语的途径并未建构积累词语的有效方法，我们共同建构积累词语的方法，更为高效地丰富词语积累。汉语中的词语数量是巨大的，因此我们可以从词语的家族或者系统出发：我们可以通过共同的语素借助联想积累词语；词语常通过语义上的各种关系，或者说这些词义构成了特定的语义场，因此我们可以借助词语的语义关系积累词语；汉语词语的种类数量非常大，但词语在整个词汇系统中不是孤立存在的，他们往往通过语音、语义或者语法等方面的某些共同点形成集合体，构成词语的系统和家族；所以我们在积累词语时，抓住一个中心点，或语音或语义或语法，以点带面展开联想、触类旁通，就会形成一个词语的家族群；这样做不仅有益于词语积累，还更有助于我们记忆理解。下面，我们一起走进俗语家族，丰富俗语积累，让语言多姿多彩；下面请同学们查阅工具书；因此我们可以通过积累俗语来丰富我们的词语。随着社会生活各方面的变化，新词语在不断涌现，为汉语增添了鲜活的生命力，积累词语不能不关注新词语；新词语是词汇中的动态系统，词汇同语音、语法比较起来，与社会生活的关系更加直接，社会生活的发展变化都会很快地反映到词汇中，使得一些旧词语逐渐消失，而很多新词语又不断在交际场合和传播媒体中出现；词语的新旧只能相对而言，不同时期都会有那个时期的新词语，某个时期的新词语也不可能永远是新词语；至于如何界定新词语，处在这个过程中的词语，或者说产生不足二十年的词语都可以算是新词语；新词语的产生主要有三个来源；下面请同学们谈谈对以下新词语含义的理解；我们可以梳理出新词语产生的途径；下面请同学们回顾本节课所谈到的新词语，看新词语具有哪些特点和作用：新颖性是新词语表现出来的基本特点，幽默性是新词语的优异特征，新词语具有衍生能产性这一特性，能批量生产新词语，并使其所生产的新词语形成词语族；由“打工族”的“族”构成了追星族、月光族、啃老族等，一个新词语的出现便带动产生了一个词族、词群或一批词语，从而使新词语的产生体现出新词语的能产性；所以新词语一旦形成便受到了无数人追捧，特别是从网络或者从方言中吸收的新词语，像 2014 年的新词语“蛮拼的”和“点赞”，甚至出现在了 2015 年国家主席习近平的新年贺词中；因此，我们每个人要密切注意到语言的发展动态，辩证地看待新词语，准确理解和恰当运用好新词语，从而使我们的言语表述更加准确、生动、形象，更具有时代性和现代感。**第二讲：一词多义与成语古今词义**。古诗文时要注意结合语境仔细甄别、正确理解，例如“绝”：率妻子邑人来此绝境，“绝”是僻远的意思；齐山溢水、天下独绝，“绝”是独一无二的意思；至于下水相邻、严肃阻绝，“绝”是阻断隔绝的意思；会当临绝顶、一览众山小，“绝”是极的意思；大雪三日、湖中人鸟声俱绝，“绝”是断绝的意思；又如“信”：与朋友交而不信乎，“信”是诚信守信；愿陛下亲之信之，“信”是信任相信；海客谈瀛洲、烟涛微茫信难求，“信”是确实、的确；低眉信手续续弹、说尽心中无限事，“信”是任凭随意。一词多义看似纷繁复杂，其实也有规律可循：一个词的各个意义并不是孤立的，其间存在着各种联系，分析意义间的相互联系，往往就抓住了理解多义词的线索；要分析意义间的相互联系，我们首先要明确词的本义和引申义；一个词当它有两个以上意义的时候，其中应该有一个是本义，另外还有一个或一些是引申义，所谓引申义，是从本意引申出来的，即从本意产生出另外一个或几个与之有关联的意义；例如“向”本义是向北的窗户，由向北的窗户这个本意，引申为朝着或对着。首先我们谈一谈词义引申的两种方式：第一种方式是由一个意义向各个不同方面引申，我们称之为辐射式引申，例如“节”字，它的本意是竹节，由这个本意产生出下列引申义：一、用于树木则指木结；二、用于动物则指关节；三、用于时日，则指节气；四、用于音乐，则为节奏；五、用于社会政治，则为法度；六、用于道德方面，则为节操；七、用于动作，则为节制、节省；这种引申方式很灵活，同一个词可以从不同角度联想，因而就有各种不同角度的引申，例如“唱”本意是领唱，由领的意义引申为带头、倡导，由唱的意义引申为歌唱；例如“书”本义是写，引申为装订成册的著作，引申为用于陈述正式见解的文体，引申为书信。第二种方式是由本义引申为甲义、又由甲义引申为乙义，这样一环套一环的引申，称之为链条式引申，例如“要”，它是“腰”的本字，由此引申出下列意义：一、中间；二、半路拦截；三、要挟；四、求得；五、需要；如果画成图就是“要”引申为中间，由中间引申为半路拦截，由半路拦截引申为要挟，由要挟引申为求得，由求得引申为需要；这种引申的特点是，其中一个意义只和它临近的两个意义有直接联系，而与其他意义差得较远，以“要”为例，“需要”是现代汉语中常用的意义，它和“腰”的意义乍看起来是毫无关系的，但只要我们找到它们之间的中间环节，就能清楚地看到其间词义引申发展的脉络；反过来说，有些词或字古今意义之间看不出任何关系，也可能是我们还没有找到中间环节的缘故；这两种引申方式不是截然分开的，例如“要”除了上述引申以外，还可以从别的角度引出别的意义；又如“闻”，本意是听见，由听说引申为接受、由听说引申为传布、由听说引申为有名、著称；词义引申的一般规律，通常是由具体到抽象、由个别到一般、由实词到虚词，例如“道”本意是道路，引申为抽象的途径、方法，又引申为学说、道理。现代汉语中的成语和一词多义还保留着古义；尤其是从古代沿用而来的成语，也要注意成语中古今词义不同的现象；成语中有些词：一、词义的转移，如“骄傲自大”的“骄”本义是马高六尺，后指骄傲；二、词义引申，如“顾名思义”的“顾”本意为回头看，后来引申为看，再引申为探望、拜访、照顾等多义；三、词义的缩小和扩大，如“五谷丰登”的“谷”本意是庄稼和粮食的总称，现在专指稻谷，词义缩小了；四、词义加深，如“怅恨久之”的“恨”本意是遗憾、不满足，现在表示仇恨，古今词义相比程度加深了；我们在学习使用成语的时候要避免因望文生义而以今释古，例如“把邻国当作大水坑、把本国洪水排泄到那里去，比喻把灾祸推给别人”，此处属于望文生义；“在语文老师的严格要求下，我逐渐改正了文不加点的毛病”——“文不加点”是文章一气呵成、无需修改，形容文思敏捷、写作技巧纯熟，“点”是改正修改的意思，此处属于望文生义；“此文打着科学的幌子，实际上宣传的是封建迷信，这样一篇不刊之论，竟然公开刊登在一家省级大报纸上，真是令人反感”——“不刊之论”比喻不能改动或不可磨灭的言论，用来形容文章或言辞的精准得当、正确无误，如果将其理解为“刊登”，就属于望文生义了。反馈与评价：指出下面词语词义变化的情况并解析，如“菜”古义专指蔬菜、现泛指一切菜肴包括肉类；“汤”古义专指热水、开水，现指热水开水、食物煮熟后所得的汤汁、烹调后汁液特别多的副食、汤药；“河”古义专指黄河、现泛指河流。**第三讲：词语运用——语境与语体色彩**。下面我们结合作家作品中对词语的修改和锤炼的范例；在具体的语境中使用词语；然而一旦它与特定的语境相联系，练习和使用词语要有语境意识，在具体的语境中理解和运用语言；一些中性词在上下文语境中也带上了感情色彩，其感情色彩在特定语境中也发生了转换；在特定的语境下，请大家阅读下面的便条。下面我们以《溜索》和《普通人家》两篇附有地域特色的小说为例，探究两篇小说在词语选用上的语体特点，体会其中表现出的语言风格：《溜索》中“出、峡、行”等都是单音节词，具有凝练的文言词特点；“可还些”“不消”运用文言的单音节词来表达，有一种古白化的味道，使这种对白极为减省；“小”活用动词，写出人物沿溜索滑向对岸的动态，颇有画面感，多用短句、少用词藻修饰，也使得描写简洁而富有表现力。《普通人家》中“拴贼寇”“心尖子”“废叶子”“眼珠子”“命根子”“拍花子”等词语，有明显的口语特征，准确传神地表现出劳动人民生动活泼的形象，赋予地方特色和生活气息；“人配衣裳马配鞍”“好狗不挡道”“捅了马蜂窝”“千里搭长篷、没有不散的筵席”等丰富的民间俗语的运用，体现出小说将口语与古典熔于一炉的独特的语言风格，既简洁凝练又生动形象。在小说、戏剧等文学作品中，作家常常利用词语的语体色彩描写人物语言、塑造人物形象，例如鲁迅的《孔乙己》中有如下的段落：孔乙己睁大眼睛说，你怎么这样凭空污人清白？什么清白？我前天亲眼见你偷了何家的书，吊着打；孔乙己便涨红了脸，额上的青筋条条绽出，争辩道，窃书不能算偷，窃书，读书人的事能算偷吗？接连便是难懂的话，什么君子固穷，什么者乎之类，引得众人都哄笑起来，店内外充满了快活的空气；明确：“偷”是口语，是短衣帮们使用的词语，“窃”是书面语，是读书人才使用的词语，何况窃的是书，是读书人的事，是不能与偷相提并论的；在众人看来这是诡辩、狡辩，在孔乙己却是他维护自己尊严所做的迂腐可怜的努力；孔乙己所用的文言词语与其所处环境格格不入，与他自身的境遇也形成冲突，反而成为这一人物的标志，也成为我们解读孔乙己的一把钥匙。范例：《镜花缘》中有一回写孙话旧保咬文、讲迂谈、辅如嚼字，里面有一段故事：旁边走过一个酒保，面上戴着眼镜、手中拿着折扇，斯斯文文走来向着三人打躬陪笑道，三位先生光临，莫非饮酒乎？亦用菜乎？敢请吩咐；林之洋道，你是酒保，你脸上戴着眼镜，你绝不配，你还满嘴通文，这是甚意？刚才俺同那些生童讲话，倒不见他有甚通文，谁知酒保通起文来，真是正经半吊子、半吊子正经；你可晓得俺最猴急，耐不惯你这通文；有酒有菜只管快快拿来；明确：日常对话讲究生动活泼、晓畅明快，这里的酒保却用了一连串的书面语词，酸腐难耐，作者借词讽刺了酒保的假斯文形象。根据刚才老师的讲解，我们知道，口语通俗易懂、书面语形象典雅，那么大家试一试，能不能给以下日常口语中的新词或者流行语找到匹配的古诗文？例如“时间是把杀猪刀”，我们可以找到“最是人间留不住，朱颜辞镜花辞树”；“素颜，清水出芙蓉，天然去雕饰”；那么大家看，以下几句有没有合适的古诗文匹配呢？“颜值爆表，众里嫣然通一顾，人间颜色如尘土”；“说得好有道理，我竟无言以对，此中有真意，欲辨已忘言”；“宝宝心里苦，但宝宝不说，如此寒心，隐忍不言，心好累，形容枯槁，心如死灰”；“世界那么大，我想去看看，天高地阔，欲望无边”。", "vtech": [["词义引申两种方式怎么答", "第一种是由一个意义向各个不同方面引申，称之为辐射式引申，例如“节”本意是竹节，由这个本意产生出木结、关节、节气、节奏、法度、节操、节制等引申义；第二种是由本义引申为甲义、又由甲义引申为乙义，这样一环套一环的引申，称之为链条式引申，例如“要”本义是腰，引申为中间、由中间引申为半路拦截、由半路拦截引申为要挟、由要挟引申为求得、由求得引申为需要；这两种引申方式不是截然分开的。"], ["成语古今词义怎么辨", "成语中有些词古今词义不同，要注意：一、词义的转移，如“骄傲自大”的“骄”本义是马高六尺；二、词义引申，如“顾名思义”的“顾”本意为回头看，后来引申为看、再引申为探望、拜访、照顾等多义；三、词义的缩小和扩大，如“五谷丰登”的“谷”本意是庄稼和粮食的总称，现在专指稻谷，词义缩小了；四、词义加深，如“怅恨久之”的“恨”本意是遗憾、不满足，现在表示仇恨，古今词义相比程度加深了；学习使用成语时要避免望文生义、以今释古。"], ["语境意识怎么答", "练习和使用词语要有语境意识，在具体的语境中理解和运用语言；一些中性词在上下文语境中也带上了感情色彩，其感情色彩在特定语境中也发生了转换；古诗文时要注意结合语境仔细甄别、正确理解，例如“绝”在不同句子里分别是横渡、僻远、独一无二、阻断隔绝、极、断绝的意思。"], ["语体色彩怎么答", "在小说、戏剧等文学作品中，作家常常利用词语的语体色彩描写人物语言、塑造人物形象：《溜索》多用单音节词，具有凝练的文言词特点，又用口语对白；《普通人家》多用“拴贼寇”“心尖子”“命根子”“拍花子”等口语词和“人配衣裳马配鞍”“好狗不挡道”“捅了马蜂窝”等民间俗语，体现出口语与古典熔于一炉的独特语言风格；孔乙己所用的文言词语与其所处环境格格不入，反而成为这一人物的标志，也成为解读孔乙己的一把钥匙。"]], "vgaokao": []}}, "u_chn_20": {"id": "u_chn_20", "name": "古诗词诵读四首", "secs": "古诗词诵读", "pageFrom": 139, "pageTo": 142, "members": ["chn_c031", "chn_c032"], "video": {"bvid": "BV1mCqkYPEYr", "p": 1, "t": "古诗词诵读四首", "dur": "57:49", "from": "王老师", "vtop": ["本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。", "李煜词分前期后期：前期写宫廷享乐，后期写物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念。", "《涉江采芙蓉》用平浅质朴的文字表现深厚的感情，是古诗十九首的风格；古诗十九首标志着五言诗已经达到了成熟的阶段，刘勰称其为“五言之冠冕”，钟嵘称其“天衣无缝，一字千金”。"], "vsum": "本课只讲四首中的两首：李煜《虞美人》与《古诗十九首·涉江采芙蓉》；《静女》与《鹊桥仙》不在本视频内，后续补。**第一首：李煜《虞美人》**。开场：同学们好，王老师带你学语文；他生于七夕、卒于七夕，他是一位君王，更是一位伟大的词人；大家说，他是谁呢？对，他就是南唐后主李煜；这节课我们就走进被称为亡国君王、绝代词人的李煜，学习他的代表作《虞美人》。**李煜简介**：李煜原名从嘉、字重光，他是五代十国时期南唐的最后一任帝王，在位十五年，史称南唐后主或者说李后主；史书记载，李煜为人仁孝、善属文、擅长写文章，工书画、也擅长书法绘画；凤额龙睛、一目重瞳子，凤额大概就是天庭饱满，龙睛就是眼睛里边有两个瞳孔，其实这是眼睛发生的病变，但是苍颉、虞舜、项羽都是重瞳子，所以古代相术就认为重瞳意味着吉祥与富贵、是帝王的象征，所以可以说李煜天生就有帝王之相；可是李煜本人却没有称帝之心，只想做一个富贵闲人，而且李煜是南唐宗主李璟的第六个儿子，所以正常情况来说也轮不到他做皇帝；可惜的是李弘冀和他的叔叔李景遂争夺王位的继承权，后来李弘冀当上太子之后就毒杀了他的叔叔李景遂，然后南唐宗主李璟因为李弘冀残害自己的亲叔叔，就废了李弘冀的太子职位；所以李煜被迫做了南唐的皇帝，而且十几年之后，南唐就灭亡了。**词风分期**：前期则描写了宫廷享乐，后期则描写了物是人非、思乡之情、亡国之恨、被囚禁后的苦闷以及对昔日生活的怀念等等。**写作背景**：南唐只能延续纳贡的政策、一再委屈求全，但是这也没有能够阻止宋兵围城的步伐；975 年，南唐在与宋的交战中不敌、最终亡国，李煜肉袒出降，非常屈辱啊；他不甘心南唐的灭亡。**赏词**：下面我们就一起来赏析一下李煜的这首绝笔之作《虞美人》：春花秋月何时了，往事知多少？小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁，恰似一江春水向东流。春花秋月什么时候才能停止呢？我们看这个春花秋月：春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君，要忍受无尽的屈辱；所以一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光。小楼昨夜又东风：小楼昨夜又迎来了东风；这个“又”字表现了作者怎样的情感呢？再看这个故国：故国指的是南唐故都金陵，这个国指的是国都金陵，就是现在的南京；故国不堪回首月明中，遥望南唐的故都呢。雕栏玉砌应犹在，只是朱颜改：这个“砌”我们注意啊，是台阶的意思，雕栏玉砌就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜；就形成了鲜明的对比，物是人非的悲愁之感悠然而生；那么除了对比，还运用了什么艺术手法呢？这是作者的想象，此时此刻李煜的思绪回到了南唐的故宫。问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁，来比喻愁、说愁思，愁思之多、愁思之绵长，写出了愁思的多、深重和绵长，而且用有形的水来比喻抽象的无形的愁，我们说这个愁是无形的呀、是抽象的呀，我们怎么来写呢？没有办法形容；多少愁啊，像一江春水一样的愁；用一个设问就加倍地突出了这个“愁”字；亡国之恨。不变的是春花秋月，永恒的春花秋月。**第二首：《古诗十九首·涉江采芙蓉》**。我们先来了解一下《古诗十九首》：《古诗十九首》是《十九首诗》的统称，由汉代文人创作，并且被南朝的萧统选录编入《文选》；我们今天要学的《涉江采芙蓉》是这十九首诗中的一首；这十九首诗都是五言抒情诗，这些诗我们既不知道作者是谁，也没有题目，所以我们习惯上以首句作为标题，笼统地称它们为古诗；所以我们就知道了《涉江采芙蓉》这首诗，第一句一定是“涉江采芙蓉”，以首句作为标题；古诗十九首在艺术上继承了诗经和楚词的传统，并且吸收了汉乐府的营养，从而创造出一种独特的艺术风格：用什么艺术风格呢？用平浅质朴的文字表现深厚的感情；这些个文字都是非常的浅显的、非常质朴的，但是都能够打动你，因为它表现的情感特别的真挚、深厚；古诗十九首的出现，标志着五言诗已经达到了成熟的阶段；历代文人对古诗十九首的评价都非常的高，比如说刘勰在《文心雕龙》中称古诗十九首是“五言之冠冕”，第一的、最高的、最好的；钟嵘的《诗品》说古诗十九首“天衣无缝，一字千金”；明代的王世贞称它是“千古五言之祖”；那么这些个评价可以说都是非常高的，也就是说古诗十九首的艺术成就真的是非常的高。下面我们再来看一下古诗十九首所在的这本书，萧统的《文选》：《文选》也叫昭明文选，它是我国最早的一部各类文学作品的选集，收录了秦汉以来的文学作品，它是由南朝梁武帝萧衍的长子萧统组织文人编写而成的；因为萧统死后谥号叫昭明，后来人们就称他为昭明太子，那么所以他所主编的这部作品选集就被称为昭明文选；萧统从性情上来说，对父母至孝、这是一个纯孝之人，然后他还是一个非常仁厚善良的人，他对待他身边的人、对待大臣、对待百姓都是非常仁厚的，同时萧统还是一个特别聪慧的人，据说他看书是数行俱下、就能够一下子看好几行，而且过目不忘；然而遗憾的是，英年早逝，三十岁就去世了；所幸的是他留下了这本《昭明文选》，也算是不幸中的一点安慰吧。下面我们就一起来看一下这首《涉江采芙蓉》，有两个读音需要注意，一个是“采之欲遗谁”的“遗”，一个是“还顾望旧乡”的“还”。下面我们就来赏析一下这首诗：涉江采芙蓉，兰泽多芳草；“涉”是渡水、过江的意思，渡过江水去采摘芙蓉，芙蓉就是荷花；兰泽就是生有兰草的水泽；有芙蓉、有兰泽、有芳草，就是抒情主人公涉江去采摘芙蓉的情景；如果这个抒情主人公他有心情去采摘芙蓉，芙蓉、兰泽、芳草这些都是用来表达情感的意象。为什么要采芙蓉，送给远方的人而不是采其他的东西呢？芙蓉又有什么特别之处呢？芙蓉又称荷花、莲花：周敦颐写道，“出淤泥而不染，濯清涟而不妖”，所以在这里，这个芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说，“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里，芙蓉是美丽的佳人之花；所以在这里，这个芙蓉是纯洁的爱情之花；李清照的《如梦令》中也写到了芙蓉；所以说这首诗也以芙蓉、以荷花作为意象来描写。同心而离居，忧伤以终老。收尾：咱们就讲到这里，最后咱们连接高考，看一下这些个情景填空，咱们能不能填上，看一下答案；好了，《涉江采芙蓉》咱们就讲到这儿。", "vtech": [["“春花秋月”怎么答", "春花秋月总是和最美好的事物联系在一起，但是一个被囚禁的亡国之君要忍受无尽的屈辱，一年一度的春花秋月只是意味着这种屈辱生活的延续罢了，所以才会厌恶春花秋月的无休无尽；景是乐景春花秋月，往事指的是他在江南无数的春花秋月那些个美好的时光；不变的是春花秋月，永恒的春花秋月。"], ["“问君能有几多愁”怎么答", "问君能有几多愁，恰似一江春水向东流：这个“君”就是作者李煜的自称，“几多”就是多少；这是千古传颂的以水喻愁——愁思之多、愁思之绵长、愁思之深重和绵长，而且用有形的水来比喻抽象的无形的愁；用一个设问就加倍地突出了这个“愁”字；多少愁啊，像一江春水一样的愁。"], ["对比与想象怎么答", "雕栏玉砌应犹在、只是朱颜改，就形成了鲜明的对比，物是人非的悲愁之感悠然而生；除了对比还运用了想象，此时此刻李煜的思绪回到了南唐的故宫；“雕栏玉砌”就是雕花的栏杆和如玉石的台阶，都是非常精美的，所以用雕栏玉砌来指代远在金陵的南唐故宫，这是作者过去生活的象征，也可以指作者的容颜。"], ["为什么采芙蓉怎么答", "芙蓉又称荷花、莲花：周敦颐写道“出淤泥而不染，濯清涟而不妖”，所以在这里芙蓉是高洁的君子之花；王昌龄的《采莲曲》中说“荷叶罗裙一色裁，芙蓉向脸两边开”，所以在这里芙蓉是美丽的佳人之花；所以在这里芙蓉是纯洁的爱情之花；这首诗也以芙蓉、以荷花作为意象来描写。"]], "vgaokao": []}}}, "nodeUnit": {"chn_c001": "u_chn_1", "chn_c002": "u_chn_2", "chn_c003": "u_chn_2", "chn_c004": "u_chn_3", "chn_c005": "u_chn_3", "chn_c006": "u_chn_4", "chn_c007": "u_chn_4", "chn_c008": "u_chn_5", "chn_c009": "u_chn_6", "chn_c010": "u_chn_7", "chn_c011": "u_chn_7", "chn_c012": "u_chn_8", "chn_c013": "u_chn_8", "chn_c014": "u_chn_8", "chn_c015": "u_chn_9", "chn_c016": "u_chn_9", "chn_c017": "u_chn_9", "chn_c018": "u_chn_10", "chn_c019": "u_chn_11", "chn_c020": "u_chn_12", "chn_c021": "u_chn_12", "chn_c022": "u_chn_13", "chn_c023": "u_chn_14", "chn_c024": "u_chn_15", "chn_c025": "u_chn_16", "chn_c026": "u_chn_16", "chn_c027": "u_chn_17", "chn_c028": "u_chn_18", "chn_c029": "u_chn_18", "chn_c030": "u_chn_19", "chn_c031": "u_chn_20", "chn_c032": "u_chn_20"}};
